window.TEXTBOOK_TEXTS = {"hsk1-1":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"AI小语，你好！","pinyin":"AI Xiǎoyǔ, nǐ hǎo!","speaker":"王一飞","vi":"Chào AI Tiểu Ngữ!"},{"hanzi":"王老师，你好！","pinyin":"Wáng lǎoshī, nǐ hǎo!","speaker":"小语","vi":"Chào cô Vương!"}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong phần bối cảnh có câu \"开学第一天，在办公室里，王一飞和AI助教小语打招呼。\" (Ngày đầu tiên khai giảng, trong văn phòng, Vương Nhất Phi và trợ giảng AI Tiểu Ngữ chào hỏi nhau), nên đáp án đúng là 在办公室里.","options":["在教室里","在办公室里","在校园里","在家里"],"q":"王一飞和小语在哪里打招呼？"},{"answerIdx":0,"explanation":"Trong bài có câu 小语 nói \"王老师，你好！\" (Thầy/Cô Vương, chào thầy/cô!), nên đáp án đúng là 王老师，你好！.","options":["王老师，你好！","同学们，再见！","老师，您好！","王老师，谢谢！"],"q":"小语怎么跟王一飞打招呼？"}],"scene":"开学第一天，在办公室里，王一飞和AI助教小语打招呼。","sceneVi":"Ngày đầu tiên khai giảng, trong văn phòng, Vương Nhất Phi chào hỏi trợ giảng AI Tiểu Ngữ."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"大家好！","pinyin":"Dàjiā hǎo!","speaker":"王一飞","vi":"Chào mọi người!"},{"hanzi":"老师，您好！","pinyin":"Lǎoshī, nín hǎo!","speaker":"学生们","vi":"Chúng em chào cô ạ!"},{"hanzi":"你们好！","pinyin":"Nǐmen hǎo!","speaker":"小语","vi":"Chào các bạn!"},{"hanzi":"你好，小语！","pinyin":"Nǐ hǎo, Xiǎoyǔ!","speaker":"学生们","vi":"Chào Tiểu Ngữ!"}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu 学生们 nói \"老师，您好！\" (Em chào thầy/cô ạ!), dùng từ kính trọng 您 để chào giáo viên, nên đáp án đúng là 老师，您好！.","options":["大家好！","你们好！","老师，您好！","你好，小语！"],"q":"学生们怎么向王老师打招呼？"},{"answerIdx":1,"explanation":"Trong bài có câu thoại của 小语 là \"你们好！\" (Chào các bạn!), nên người nói câu này là 小语.","options":["王一飞","小语","学生们","白家月"],"q":"“你们好！”是谁说的话？"}],"scene":"开学第一天，课堂上，学生们学习打招呼用语。","sceneVi":"Ngày đầu tiên khai giảng, trên lớp học, các học sinh học các câu chào hỏi."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"谢谢！","pinyin":"Xièxie!","speaker":"学生们","vi":"Cảm ơn!"},{"hanzi":"不客气！","pinyin":"Bú kèqi!","speaker":"小语","vi":"Không có gì!"},{"hanzi":"同学们，再见！","pinyin":"Tóngxuémen, zàijiàn!","speaker":"王一飞","vi":"Tạm biệt các em!"},{"hanzi":"老师，再见！","pinyin":"Lǎoshī, zàijiàn!","speaker":"学生们","vi":"Tạm biệt cô ạ!"}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài có đoạn đối thoại 学生们 nói \"谢谢！\" (Cảm ơn!) và 小语 đáp lại \"不客气！\" (Không có gì!), nên đáp án đúng là 不客气！.","options":["不客气！","没关系！","同学们，再见！","你们好！"],"q":"学生们说“谢谢！”以后，小语怎么回答？"},{"answerIdx":3,"explanation":"Trong bài có câu 王一飞 nói \"同学们，再见！\" (Tạm biệt các em!), nên đáp án đúng là 同学们，再见！.","options":["老师，再见！","谢谢！","大家好！","同学们，再见！"],"q":"王一飞下课时对学生们说什么？"}],"scene":"开学第一天，课堂上，学生们学习致谢语、告别语。","sceneVi":"Ngày đầu tiên khai giảng, trên lớp học, các học sinh học câu cảm ơn và câu tạm biệt."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (绕口令)","lines":[{"hanzi":"妈种麻，我放马。","pinyin":"Mā zhòng má, wǒ fàng mǎ.","speaker":"绕口令","vi":"Mẹ trồng gai, tôi chăn ngựa."},{"hanzi":"马吃麻，妈骂马。","pinyin":"Mǎ chī má, mā mà mǎ.","speaker":"绕口令","vi":"Ngựa ăn gai, mẹ mắng ngựa."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài đọc líu lưỡi có câu \"妈种麻，我放马。\" (Mẹ trồng cây gai, tôi chăn ngựa), nên việc người mẹ làm là 种麻.","options":["放马","吃麻","种麻","打招呼"],"q":"绕口令里，妈妈在做什么？"},{"answerIdx":0,"explanation":"Trong bài có câu \"马吃麻，妈骂马。\" (Ngựa ăn cây gai, mẹ mắng ngựa), cho thấy mẹ mắng ngựa vì ngựa đã ăn cây gai mẹ trồng, nên đáp án đúng là 因为马吃了妈妈种的麻.","options":["因为马吃了妈妈种的麻","因为马没有吃麻","因为我不放马","因为妈妈不喜欢马"],"q":"为什么妈妈骂马？"}],"scene":"跟读绕口令","sceneVi":"Đọc theo câu nói líu lưỡi."}],"hsk1-2":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"请问，你叫什么名字？","pinyin":"Qǐngwèn, nǐ jiào shénme míngzi?","speaker":"王一飞","vi":"Xin hỏi, em tên là gì?"},{"hanzi":"我叫陈天中。","pinyin":"Wǒ jiào Chén Tiānzhōng.","speaker":"陈天中","vi":"Em tên là Trần Thiên Trung."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong phần bối cảnh có câu \"在教室里，王一飞在认识学生。\" (Trong lớp học, Vương Nhất Phi đang làm quen với học sinh), nên cô hỏi tên nhằm mục đích làm quen với học sinh (她想认识学生).","options":["她想认识学生","她想跟学生说再见","她认错了人","她想感谢学生"],"q":"王一飞为什么问“请问，你叫什么名字？”？"},{"answerIdx":1,"explanation":"Trong bài có câu học sinh trả lời \"我叫陈天中。\" (Em tên là Trần Thiên Trung), nên đáp án đúng là 陈天中.","options":["李文","陈天中","白家月","杨同乐"],"q":"回答王一飞的学生叫什么名字？"}],"scene":"在教室里，王一飞在认识学生。","sceneVi":"Trong phòng học, Vương Nhất Phi đang làm quen với học sinh."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"你好，安妮！","pinyin":"Nǐ hǎo, Ānnī!","speaker":"陈天中","vi":"Chào cậu, Annie!"},{"hanzi":"你好，陈天中！我不是安妮，我是白家月。","pinyin":"Nǐ hǎo, Chén Tiānzhōng! Wǒ bú shì Ānnī, wǒ shì Bái Jiāyuè.","speaker":"白家月","vi":"Chào Trần Thiên Trung! Mình không phải là Annie, mình là Bạch Gia Nguyệt."},{"hanzi":"对不起！","pinyin":"Duìbuqǐ!","speaker":"陈天中","vi":"Xin lỗi nhé!"},{"hanzi":"没关系！","pinyin":"Méi guānxi!","speaker":"白家月","vi":"Không sao đâu!"}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu 陈天中 gọi \"你好，安妮！\" và 白家月 đính chính \"我不是安妮，我是白家月。\" (Mình không phải An Ni, mình là Bạch Gia Nguyệt), nên Trần Thiên Trung xin lỗi vì đã nhận nhầm Bạch Gia Nguyệt thành An Ni.","options":["因为他迟到了","因为他不知道白家月的名字","因为他把白家月认成安妮了","因为他忘了打招呼"],"q":"陈天中为什么说“对不起！”？"},{"answerIdx":1,"explanation":"Trong bài có câu 白家月 đáp lại lời xin lỗi bằng câu \"没关系！\" (Không sao đâu!), nên đáp án đúng là 没关系！.","options":["不客气！","没关系！","谢谢！","再见！"],"q":"听到“对不起！”以后，白家月怎么回答？"}],"scene":"在校园里，陈天中和白家月打招呼时认错了人。","sceneVi":"Trong khuôn viên trường, khi chào hỏi Bạch Gia Nguyệt, Trần Thiên Trung đã nhận nhầm người."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"你好！我叫李文。","pinyin":"Nǐ hǎo! Wǒ jiào Lǐ Wén.","speaker":"李文","vi":"Chào bạn! Mình tên là Lý Văn."},{"hanzi":"你好！我叫白家月。","pinyin":"Nǐ hǎo! Wǒ jiào Bái Jiāyuè.","speaker":"白家月","vi":"Chào bạn! Mình tên là Bạch Gia Nguyệt."},{"hanzi":"很高兴认识你。","pinyin":"Hěn gāoxìng rènshi nǐ.","speaker":"李文","vi":"Rất vui được làm quen với bạn."},{"hanzi":"认识你我也很高兴。","pinyin":"Rènshi nǐ wǒ yě hěn gāoxìng.","speaker":"白家月","vi":"Làm quen với bạn mình cũng rất vui."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong phần bối cảnh có câu \"在校园里，李文和白家月第一次相遇。\" (Trong khuôn viên trường, Lý Văn và Bạch Gia Nguyệt lần đầu gặp nhau), kết hợp với phần tự giới thiệu tên và câu \"很高兴认识你。\" (Rất vui được làm quen với bạn), nên đáp án đúng là 他们刚认识，第一次见面.","options":["他们是老朋友","他们是老师和学生","他们刚认识，第一次见面","他们是哥哥和妹妹"],"q":"李文和白家月是什么关系？"},{"answerIdx":2,"explanation":"Trong bài có hai câu \"很高兴认识你。\" (Rất vui được làm quen với bạn) và \"认识你我也很高兴。\" (Quen biết bạn mình cũng rất vui), cho thấy cả Lý Văn và Bạch Gia Nguyệt đều rất vui khi quen nhau.","options":["只有李文很高兴","白家月认识李文不太高兴","李文和白家月都很高兴认识对方","李文不知道白家月叫什么名字"],"q":"关于这段对话，下面哪句话是对的？"}],"scene":"在校园里，李文和白家月第一次相遇。","sceneVi":"Trong khuôn viên trường, Lý Văn và Bạch Gia Nguyệt lần đầu tiên gặp nhau."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (绕口令)","lines":[{"hanzi":"七加一，再减一，加完减完等于几？","pinyin":"Qī jiā yī, zài jiǎn yī, jiāwán jiǎnwán děngyú jǐ?","speaker":"绕口令","vi":"Bảy cộng một, lại trừ một, cộng xong trừ xong bằng mấy?"},{"hanzi":"加完减完还是七。","pinyin":"Jiāwán jiǎnwán hái shì qī.","speaker":"绕口令","vi":"Cộng xong trừ xong vẫn là bảy."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài có câu \"七加一，再减一，加完减完等于几？\" (Bảy cộng một, rồi trừ một, cộng xong trừ xong bằng mấy?), nên thứ tự phép tính là 先加一，再减一.","options":["先加一，再减一","先减一，再加一","先加七，再减七","先加一，再加一"],"q":"绕口令里说七先做什么，再做什么？"},{"answerIdx":1,"explanation":"Trong bài có câu trả lời \"加完减完还是七。\" (Cộng xong trừ xong vẫn là bảy), nên đáp án đúng là 等于七.","options":["等于六","等于七","等于八","等于一"],"q":"七加一再减一，最后等于几？"}],"scene":"跟读绕口令","sceneVi":"Đọc theo câu nói líu lưỡi."}],"hsk1-3":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"我是中国人。","pinyin":"Wǒ shì Zhōngguó rén.","speaker":"李文","vi":"Tôi là người Trung Quốc."},{"hanzi":"我是法国人。我的中文老师也是中国人。","pinyin":"Wǒ shì Fǎguó rén. Wǒ de Zhōngwén lǎoshī yě shì Zhōngguó rén.","speaker":"白家月","vi":"Tôi là người Pháp. Giáo viên tiếng Trung của tôi cũng là người Trung Quốc."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu 白家月 nói \"我是法国人。\" (Tôi là người Pháp), nên đáp án đúng là 法国人.","options":["中国人","泰国人","法国人","美国人"],"q":"白家月是哪国人？"},{"answerIdx":1,"explanation":"Trong bài có câu \"我的中文老师也是中国人。\" (Giáo viên tiếng Trung của tôi cũng là người Trung Quốc), nên đáp án đúng là 中国人.","options":["法国人","中国人","泰国人","李文"],"q":"白家月的中文老师是哪国人？"}],"scene":"在校园里，李文和白家月第一次相遇，两人继续聊天儿。","sceneVi":"Trong khuôn viên trường, Lý Văn và Bạch Gia Nguyệt lần đầu gặp nhau, hai người tiếp tục trò chuyện."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"这是谁？","pinyin":"Zhè shì shéi?","speaker":"安妮","vi":"Đây là ai?"},{"hanzi":"这是我女朋友。","pinyin":"Zhè shì wǒ nǚpéngyou.","speaker":"陈天中","vi":"Đây là bạn gái của tôi."},{"hanzi":"你女朋友是哪国人？","pinyin":"Nǐ nǚpéngyou shì nǎ guó rén?","speaker":"安妮","vi":"Bạn gái của bạn là người nước nào?"},{"hanzi":"她也是泰国人。","pinyin":"Tā yě shì Tàiguó rén.","speaker":"陈天中","vi":"Cô ấy cũng là người Thái Lan."}],"readingQuiz":[{"answerIdx":3,"explanation":"Trong bài, khi 安妮 hỏi \"这是谁？\" (Đây là ai?), 陈天中 trả lời \"这是我女朋友。\" (Đây là bạn gái của mình), nên người trong ảnh là 陈天中的女朋友.","options":["安妮","白家月","王老师","陈天中的女朋友"],"q":"陈天中手机里的照片是谁？"},{"answerIdx":0,"explanation":"Trong bài có câu 陈天中 nói \"她也是泰国人。\" (Cô ấy cũng là người Thái Lan); từ 也 (cũng) cho thấy bản thân Trần Thiên Trung cũng là người Thái Lan, nên đáp án đúng là 陈天中也是泰国人.","options":["陈天中也是泰国人","陈天中的女朋友不是泰国人","照片里的人是安妮","陈天中不知道女朋友是哪国人"],"q":"从“她也是泰国人”这句话，我们能知道什么？"}],"scene":"在教室里，下课后，安妮在看陈天中手机里的照片。","sceneVi":"Trong phòng học, sau giờ học, An Ni đang xem ảnh trong điện thoại của Trần Thiên Trung."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"喂，一飞！","pinyin":"Wèi, Yīfēi!","speaker":"王一雪","vi":"A lô, Nhất Phi!"},{"hanzi":"姐姐！","pinyin":"Jiějie!","speaker":"王一飞","vi":"Chị ơi!"},{"hanzi":"你工作还忙吗？","pinyin":"Nǐ gōngzuò hái máng ma?","speaker":"王一雪","vi":"Công việc của em vẫn bận chứ?"},{"hanzi":"对，还很忙。你也很忙吗？","pinyin":"Duì, hái hěn máng. Nǐ yě hěn máng ma?","speaker":"王一飞","vi":"Vâng, vẫn rất bận ạ. Chị cũng rất bận phải không?"},{"hanzi":"我不太忙。我们很想你。","pinyin":"Wǒ bú tài máng. Wǒmen hěn xiǎng nǐ.","speaker":"王一雪","vi":"Chị không bận lắm. Cả nhà rất nhớ em."},{"hanzi":"我也想你们。","pinyin":"Wǒ yě xiǎng nǐmen.","speaker":"王一飞","vi":"Em cũng nhớ mọi người."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, khi Vương Nhất Tuyết hỏi \"你工作还忙吗？\" (Công việc của em vẫn bận chứ?), Vương Nhất Phi trả lời \"对，还很忙。\" (Vâng, vẫn rất bận), nên đáp án đúng là 很忙.","options":["不太忙","很忙","不工作","不忙"],"q":"王一飞现在工作怎么样？"},{"answerIdx":2,"explanation":"Trong bài có câu 王一雪 nói \"我不太忙。我们很想你。\" (Chị không bận lắm. Mọi người rất nhớ em), nên thông tin đúng là 她不太忙，而且很想王一飞.","options":["她是王一飞的妹妹","她工作很忙","她不太忙，而且很想王一飞","她不想王一飞"],"q":"关于王一雪，下面哪句话是对的？"}],"scene":"在家里，王一雪给王一飞打视频电话。","sceneVi":"Ở nhà, Vương Nhất Tuyết gọi điện thoại video cho Vương Nhất Phi."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (绕口令)","lines":[{"hanzi":"四是四，十是十。","pinyin":"Sì shì sì, shí shì shí.","speaker":"绕口令","vi":"Bốn là bốn, mười là mười."},{"hanzi":"十四是十四，四十是四十。","pinyin":"Shísì shì shísì, sìshí shì sìshí.","speaker":"绕口令","vi":"Mười bốn là mười bốn, bốn mươi là bốn mươi."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài đọc líu lưỡi chỉ nhắc đến bốn con số là \"四\" (4), \"十\" (10), \"十四\" (14) và \"四十\" (40), không có số 七 (7), nên đáp án đúng là 七.","options":["四","十","七","四十"],"q":"这个绕口令里没有下面哪个数字？"},{"answerIdx":1,"explanation":"Trong bài có câu \"十四是十四，四十是四十。\" (Mười bốn là mười bốn, bốn mươi là bốn mươi), nên đáp án đúng là 十四是十四，四十是四十.","options":["十四是四十，四十是十四","十四是十四，四十是四十","十四是四，四十是十","四是十四，十是四十"],"q":"“十四”和“四十”在这个绕口令里是怎么说的？"}],"scene":"跟读绕口令。","sceneVi":"Luyện đọc theo bài nói líu lưỡi (Tongue Twister)."}],"hsk1-4":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"一飞忙吗？","pinyin":"Yīfēi máng ma?","speaker":"刘明","vi":"Nhất Phi có bận không?"},{"hanzi":"她很忙。","pinyin":"Tā hěn máng.","speaker":"王一雪","vi":"Cô ấy rất bận."},{"hanzi":"她有多少个学生？","pinyin":"Tā yǒu duōshao gè xuéshēng?","speaker":"刘明","vi":"Cô ấy có bao nhiêu học sinh?"},{"hanzi":"她有二十个学生。","pinyin":"Tā yǒu èrshí gè xuéshēng.","speaker":"王一雪","vi":"Cô ấy có hai mươi học sinh."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu 王一雪 trả lời \"她有二十个学生。\" (Em ấy có hai mươi học sinh), nên đáp án đúng là 二十个.","options":["十二个","二十个","五个","四个"],"q":"王一飞有多少个学生？"},{"answerIdx":0,"explanation":"Trong bài, Lưu Minh mở đầu bằng câu hỏi \"一飞忙吗？\" (Nhất Phi có bận không?) và tiếp tục hỏi về số học sinh của Nhất Phi, nên hai người đang trò chuyện về 王一飞.","options":["王一飞","杨同乐","陈天中","李文"],"q":"刘明和王一雪在聊谁？"}],"scene":"在家里，刘明和王一雪在聊天儿。","sceneVi":"Ở nhà, Lưu Minh và Vương Nhất Tuyết đang trò chuyện."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"我有两个哥哥，你呢？","pinyin":"Wǒ yǒu liǎng gè gēge, nǐ ne?","speaker":"王一雪","vi":"Tôi có hai anh trai, còn bạn thì sao?"},{"hanzi":"我没有哥哥。","pinyin":"Wǒ méiyǒu gēge.","speaker":"杨同乐","vi":"Tôi không có anh trai."},{"hanzi":"你家有几口人？","pinyin":"Nǐ jiā yǒu jǐ kǒu rén?","speaker":"王一雪","vi":"Nhà bạn có mấy người?"},{"hanzi":"我家有四口人，爸爸、妈妈、妹妹和我。","pinyin":"Wǒ jiā yǒu sì kǒu rén, bàba, māma, mèimei hé wǒ.","speaker":"杨同乐","vi":"Nhà tôi có bốn người: bố, mẹ, em gái và tôi."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu 王一雪 nói \"我有两个哥哥，你呢？\" (Tôi có hai người anh trai, còn bạn thì sao?), nên đáp án đúng là 两个哥哥.","options":["没有哥哥","一个哥哥","两个哥哥","三个哥哥"],"q":"王一雪有几个哥哥？"},{"answerIdx":3,"explanation":"Trong bài có câu 杨同乐 trả lời \"我家有四口人，爸爸、妈妈、妹妹和我。\" (Nhà tôi có bốn người: bố, mẹ, em gái và tôi), nên đáp án đúng là 四口人：爸爸、妈妈、妹妹和他.","options":["三口人：爸爸、妈妈和他","四口人：爸爸、妈妈、哥哥和他","五口人：爸爸、妈妈、哥哥、妹妹和他","四口人：爸爸、妈妈、妹妹和他"],"q":"杨同乐家有几口人？都有谁？"}],"scene":"在公司里，王一雪和杨同乐休息时聊天儿。","sceneVi":"Ở công ty, Vương Nhất Tuyết và Dương Đồng Nhạc trò chuyện lúc nghỉ giải lao."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"这是您儿子吗？","pinyin":"Zhè shì nín érzi ma?","speaker":"杨同乐","vi":"Đây là con trai của chị phải không?"},{"hanzi":"是的。我有两个孩子，一个儿子，一个女儿。","pinyin":"Shì de. Wǒ yǒu liǎng gè háizi, yí gè érzi, yí gè nǚ'ér.","speaker":"王一雪","vi":"Đúng vậy. Tôi có hai người con, một con trai, một con gái."},{"hanzi":"您儿子几岁？","pinyin":"Nín érzi jǐ suì?","speaker":"杨同乐","vi":"Con trai chị mấy tuổi rồi?"},{"hanzi":"他今年五岁。","pinyin":"Tā jīnnián wǔ suì.","speaker":"王一雪","vi":"Cháu năm nay năm tuổi."},{"hanzi":"您女儿多大？","pinyin":"Nín nǚ'ér duō dà?","speaker":"杨同乐","vi":"Con gái chị bao nhiêu tuổi rồi?"},{"hanzi":"她今年十二。","pinyin":"Tā jīnnián shí'èr.","speaker":"王一雪","vi":"Cháu năm nay mười hai tuổi."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài, khi Dương Đồng Nhạc hỏi \"您儿子几岁？\" (Con trai chị mấy tuổi?), Vương Nhất Tuyết đáp \"他今年五岁。\" (Cháu năm nay năm tuổi), nên đáp án đúng là 五岁.","options":["五岁","四岁","十二岁","两岁"],"q":"王一雪的儿子今年几岁？"},{"answerIdx":2,"explanation":"Trong bài có hai câu 王一雪 nói \"我有两个孩子，一个儿子，一个女儿。\" (Tôi có hai con, một trai một gái) và \"她今年十二。\" (Cháu gái năm nay mười hai tuổi), nên đáp án đúng là 她有一个儿子和一个女儿，女儿十二岁.","options":["她只有一个儿子，没有女儿","她有两个儿子，今年都五岁","她有一个儿子和一个女儿，女儿十二岁","她的女儿五岁，儿子十二岁"],"q":"关于王一雪的孩子，下面哪句话是对的？"}],"scene":"在街上，王一雪带着儿子偶遇杨同乐。","sceneVi":"Trên đường, Vương Nhất Tuyết dắt con trai tình cờ gặp Dương Đồng Nhạc."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (短文 tổng hợp)","lines":[{"hanzi":"王一飞很忙，她有二十个学生。","pinyin":"Wáng Yīfēi hěn máng, tā yǒu èrshí gè xuéshēng.","speaker":"Đoạn văn","vi":"Vương Nhất Phi rất bận, cô ấy có hai mươi học sinh."},{"hanzi":"王一雪有两个哥哥，还有两个孩子，一个儿子，一个女儿。","pinyin":"Wáng Yīxuě yǒu liǎng gè gēge, hái yǒu liǎng gè háizi, yí gè érzi, yí gè nǚ'ér.","speaker":"Đoạn văn","vi":"Vương Nhất Tuyết có hai anh trai, còn có hai người con, một con trai và một con gái."},{"hanzi":"她的儿子今年五岁，女儿今年十二岁。","pinyin":"Tā de érzi jīnnián wǔ suì, nǚ'ér jīnnián shí'èr suì.","speaker":"Đoạn văn","vi":"Con trai của chị ấy năm nay năm tuổi, con gái năm nay mười hai tuổi."},{"hanzi":"杨同乐没有哥哥，他家有四口人：爸爸、妈妈、妹妹和他。","pinyin":"Yáng Tónglè méiyǒu gēge, tā jiā yǒu sì kǒu rén: bàba, māma, mèimei hé tā.","speaker":"Đoạn văn","vi":"Dương Đồng Nhạc không có anh trai, nhà anh ấy có bốn người: bố, mẹ, em gái và anh ấy."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong đoạn văn có câu \"王一雪有两个哥哥，还有两个孩子，一个儿子，一个女儿。\" (Vương Nhất Tuyết có hai anh trai và còn có hai người con, một trai một gái), nên đáp án đúng là 王一雪.","options":["王一飞","王一雪","杨同乐","杨同乐的妹妹"],"q":"短文里，谁既有哥哥又有孩子？"},{"answerIdx":3,"explanation":"Trong đoạn văn có câu \"杨同乐没有哥哥，他家有四口人：爸爸、妈妈、妹妹和他。\" (Dương Đồng Nhạc không có anh trai, nhà anh ấy có bốn người: bố, mẹ, em gái và anh ấy), nên đáp án đúng là 杨同乐没有哥哥，他有一个妹妹.","options":["王一飞有十二个学生","王一雪的儿子比女儿大","杨同乐有一个哥哥和一个妹妹","杨同乐没有哥哥，他有一个妹妹"],"q":"根据短文，下面哪句话是对的？"}],"scene":"短文总结第四课课文一至课文三的内容。","sceneVi":"Đoạn văn tổng hợp nội dung Bài khóa 1 đến Bài khóa 3 của Bài 4."}],"hsk1-5":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"今天几号？","pinyin":"Jīntiān jǐ hào?","speaker":"王一雪","vi":"Hôm nay ngày mấy?"},{"hanzi":"今天9月8号。","pinyin":"Jīntiān jiǔ yuè bā hào.","speaker":"刘明","vi":"Hôm nay ngày 8 tháng 9."},{"hanzi":"星期几？","pinyin":"Xīngqī jǐ?","speaker":"王一雪","vi":"Thứ mấy?"},{"hanzi":"星期日。今天我休息。","pinyin":"Xīngqīrì. Jīntiān wǒ xiūxi.","speaker":"刘明","vi":"Chủ nhật. Hôm nay tôi nghỉ."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài có câu “今天9月8号。” (Hôm nay là ngày 8 tháng 9), nên đáp án đúng là 9月8号。","options":["9月8号","9月7号","8月9号","10月8号"],"q":"今天是几月几号？"},{"answerIdx":1,"explanation":"Trong bài Lưu Minh nói “星期日。今天我休息。” (Chủ nhật. Hôm nay tôi nghỉ), nên lý do anh ấy được nghỉ là vì hôm nay là Chủ nhật (因为今天是星期日)。","options":["因为今天是星期一","因为今天是星期日","因为今天他去医院","因为今天他做饭"],"q":"今天刘明为什么休息？"}],"scene":"在家里，刘明和王一雪在聊天儿。","sceneVi":"Ở nhà, Lưu Minh và Vương Nhất Tuyết đang trò chuyện."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"你会做饭吗？","pinyin":"Nǐ huì zuò fàn ma?","speaker":"王一雪","vi":"Bạn biết nấu ăn không?"},{"hanzi":"我会做。","pinyin":"Wǒ huì zuò.","speaker":"杨同乐","vi":"Tôi biết nấu."},{"hanzi":"你会做什么？","pinyin":"Nǐ huì zuò shénme?","speaker":"王一雪","vi":"Bạn biết nấu món gì?"},{"hanzi":"我会做面条儿、饺子，也会做一些菜。星期天我也做饭。","pinyin":"Wǒ huì zuò miàntiáor, jiǎozi, yě huì zuò yìxiē cài. Xīngqītiān wǒ yě zuò fàn.","speaker":"杨同乐","vi":"Tôi biết làm mì sợi, sủi cảo, cũng biết nấu một số món ăn. Chủ nhật tôi cũng nấu cơm."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Dương Đồng Nhạc nói “我会做面条儿、饺子，也会做一些菜。” (Tôi biết làm mì sợi, sủi cảo và cũng biết nấu một ít món ăn), nên đáp án đúng là 面条儿、饺子和一些菜。","options":["水果和茶","面条儿、饺子和一些菜","米饭和咖啡","他不会做饭"],"q":"杨同乐会做什么？"},{"answerIdx":3,"explanation":"Trong bài có câu “星期天我也做饭。” (Chủ nhật tôi cũng nấu cơm), nên đáp án đúng là 星期天。","options":["星期一","星期三","星期五","星期天"],"q":"杨同乐什么时候也做饭？"}],"scene":"在公司里，王一雪和杨同乐休息时聊天儿。","sceneVi":"Ở công ty, Vương Nhất Tuyết và Dương Đồng Nhạc trò chuyện lúc nghỉ ngơi."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"同乐，下班吗？","pinyin":"Tónglè, xiàbān ma?","speaker":"王一雪","vi":"Đồng Nhạc, tan làm à?"},{"hanzi":"下班。","pinyin":"Xiàbān.","speaker":"杨同乐","vi":"Tan làm rồi."},{"hanzi":"这是你的新电脑吗？","pinyin":"Zhè shì nǐ de xīn diànnǎo ma?","speaker":"王一雪","vi":"Đây là máy tính mới của bạn à?"},{"hanzi":"是的，是我的新电脑。","pinyin":"Shì de, shì wǒ de xīn diànnǎo.","speaker":"杨同乐","vi":"Đúng vậy, là máy tính mới của tôi."},{"hanzi":"真好看！","pinyin":"Zhēn hǎokàn!","speaker":"王一雪","vi":"Đẹp thật đấy!"},{"hanzi":"我也很喜欢它。","pinyin":"Wǒ yě hěn xǐhuan tā.","speaker":"杨同乐","vi":"Tôi cũng rất thích nó."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài Vương Nhất Tuyết khen “真好看！” (Đẹp thật đấy!), nên đáp án đúng là 真好看。","options":["真好看","不好看","很小","很贵"],"q":"王一雪觉得杨同乐的新电脑怎么样？"},{"answerIdx":1,"explanation":"Trong bài Dương Đồng Nhạc nói “我也很喜欢它。” (Tôi cũng rất thích nó), nên đáp án đúng là 很喜欢。","options":["不喜欢","很喜欢","没说喜不喜欢","觉得不好看"],"q":"杨同乐喜欢这个新电脑吗？"}],"scene":"在公司里，王一雪和杨同乐下班时聊天儿。","sceneVi":"Ở công ty, Vương Nhất Tuyết và Dương Đồng Nhạc trò chuyện lúc tan làm."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (短文 tổng hợp)","lines":[{"hanzi":"今天9月8号，星期日，刘明在家里休息。","pinyin":"Jīntiān jiǔ yuè bā hào, Xīngqīrì, Liú Míng zài jiā li xiūxi.","speaker":"Đoạn văn","vi":"Hôm nay là ngày 8 tháng 9, Chủ nhật, Lưu Minh nghỉ ngơi ở nhà."},{"hanzi":"杨同乐会做面条儿、饺子，也会做一些菜，星期天他也做饭。","pinyin":"Yáng Tónglè huì zuò miàntiáor, jiǎozi, yě huì zuò yìxiē cài, Xīngqītiān tā yě zuò fàn.","speaker":"Đoạn văn","vi":"Dương Đồng Nhạc biết làm mì sợi, sủi cảo, cũng biết nấu một số món ăn, Chủ nhật anh ấy cũng nấu cơm."},{"hanzi":"下班时，王一雪和杨同乐聊天儿。","pinyin":"Xiàbān shí, Wáng Yīxuě hé Yáng Tónglè liáotiānr.","speaker":"Đoạn văn","vi":"Lúc tan làm, Vương Nhất Tuyết và Dương Đồng Nhạc trò chuyện."},{"hanzi":"杨同乐有一个新电脑，这个电脑真好看，他也很喜欢它。","pinyin":"Yáng Tónglè yǒu yí gè xīn diànnǎo, zhège diànnǎo zhēn hǎokàn, tā yě hěn xǐhuan tā.","speaker":"Đoạn văn","vi":"Dương Đồng Nhạc có một chiếc máy tính mới, chiếc máy tính này đẹp thật, anh ấy cũng rất thích nó."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong đoạn văn có câu “今天9月8号，星期日，刘明在家里休息。” (Hôm nay là Chủ nhật ngày 8 tháng 9, Lưu Minh nghỉ ngơi ở nhà), nên đáp án đúng là 刘明。","options":["王一雪","杨同乐","刘明","王一雪和杨同乐"],"q":"9月8号星期日，谁在家里休息？"},{"answerIdx":3,"explanation":"Trong đoạn văn có câu “杨同乐有一个新电脑” (Dương Đồng Nhạc có một chiếc máy tính mới), nên đáp án đúng là 新电脑。","options":["新手机","新书","新桌子","新电脑"],"q":"杨同乐有什么新东西？"}],"scene":"复习第五课的三篇课文。","sceneVi":"Tổng hợp nội dung ba bài khóa của Bài 5."}],"hsk1-6":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"家月，你的手机号是多少？","pinyin":"Jiāyuè, nǐ de shǒujīhào shì duōshao?","speaker":"李文","vi":"Gia Nguyệt, số điện thoại di động của bạn là bao nhiêu?"},{"hanzi":"我的手机号是+33 601493190。","pinyin":"Wǒ de shǒujīhào shì sān sān liù líng yāo sì jiǔ sān yāo jiǔ líng.","speaker":"白家月","vi":"Số điện thoại của tôi là +33 601493190."},{"hanzi":"我的手机号是+86 13552721160。","pinyin":"Wǒ de shǒujīhào shì bā liù yāo sān wǔ wǔ èr qī èr yāo yāo liù líng.","speaker":"李文","vi":"Số điện thoại của tôi là +86 13552721160."},{"hanzi":"好的。","pinyin":"Hǎo de.","speaker":"白家月","vi":"Được rồi."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Bạch Gia Nguyệt nói “我的手机号是+33 601493190。” (Số điện thoại di động của tôi là +33 601493190), nên đáp án đúng là +33 601493190。","options":["+86 13552721160","+33 601493190","+33 13552721160","+86 601493190"],"q":"白家月的手机号是多少？"},{"answerIdx":0,"explanation":"Trong bài, Lý Văn hỏi số điện thoại của Bạch Gia Nguyệt (“家月，你的手机号是多少？”) và cũng nói ra số điện thoại của mình (“我的手机号是+86 13552721160。”), nên đáp án đúng là 问白家月的手机号，也说了自己的手机号。","options":["问白家月的手机号，也说了自己的手机号","问白家月去不去医院","和白家月一起买东西","问白家月会做什么菜"],"q":"对话里，李文做了什么？"}],"scene":"在校园里，李文向白家月要手机号。","sceneVi":"Trong khuôn viên trường, Lý Văn hỏi xin số điện thoại di động của Bạch Gia Nguyệt."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"家月，明天你去哪儿？","pinyin":"Jiāyuè, míngtiān nǐ qù nǎr?","speaker":"陈天中","vi":"Gia Nguyệt, ngày mai bạn đi đâu?"},{"hanzi":"我想去超市买东西。","pinyin":"Wǒ xiǎng qù chāoshì mǎi dōngxi.","speaker":"白家月","vi":"Tôi muốn đi siêu thị mua đồ."},{"hanzi":"你去超市买什么？","pinyin":"Nǐ qù chāoshì mǎi shénme?","speaker":"陈天中","vi":"Bạn đi siêu thị mua gì?"},{"hanzi":"我想买些牛奶。","pinyin":"Wǒ xiǎng mǎi xiē niúnǎi.","speaker":"白家月","vi":"Tôi muốn mua một ít sữa bò."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài Trần Thiên Trung hỏi “家月，明天你去哪儿？” (Gia Nguyệt, ngày mai bạn đi đâu?) và Bạch Gia Nguyệt đáp “我想去超市买东西。” (Tôi muốn đi siêu thị mua đồ), nên đáp án đúng là 明天。","options":["今天","昨天","明天","星期天"],"q":"白家月什么时候想去超市？"},{"answerIdx":2,"explanation":"Trong bài Bạch Gia Nguyệt nói “我想买些牛奶。” (Tôi muốn mua một ít sữa bò), nên đáp án đúng là 牛奶。","options":["茶","米饭","牛奶","包子"],"q":"白家月想去超市买什么？"}],"scene":"在教室里，下课后，白家月和陈天中在聊天儿。","sceneVi":"Trong phòng học, sau giờ tan học, Bạch Gia Nguyệt và Trần Thiên Trung đang trò chuyện."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"星期天我们去哪儿吃晚饭？","pinyin":"Xīngqītiān wǒmen qù nǎr chī wǎnfàn?","speaker":"王一雪","vi":"Chủ nhật chúng ta đi đâu ăn tối?"},{"hanzi":"我还想去西安饭店。","pinyin":"Wǒ hái xiǎng qù Xī’ān Fàndiàn.","speaker":"刘明","vi":"Anh vẫn muốn đến Nhà hàng Tây An."},{"hanzi":"那边的包子非常好吃，我想吃包子。","pinyin":"Nàbiān de bāozi fēicháng hǎochī, wǒ xiǎng chī bāozi.","speaker":"刘小雪","vi":"Bánh bao ở bên đó rất ngon, con muốn ăn bánh bao."},{"hanzi":"妈妈，我想吃米饭，不想吃包子。","pinyin":"Māma, wǒ xiǎng chī mǐfàn, bù xiǎng chī bāozi.","speaker":"刘小明","vi":"Mẹ ơi, con muốn ăn cơm, không muốn ăn bánh bao."},{"hanzi":"好的。我们怎么去？","pinyin":"Hǎo de. Wǒmen zěnme qù?","speaker":"王一雪","vi":"Được thôi. Chúng ta đi bằng cách nào?"},{"hanzi":"坐出租车去。","pinyin":"Zuò chūzūchē qù.","speaker":"刘明","vi":"Đi bằng taxi."}],"readingQuiz":[{"answerIdx":3,"explanation":"Trong bài Lưu Tiểu Minh nói “妈妈，我想吃米饭，不想吃包子。” (Mẹ ơi, con muốn ăn cơm, không muốn ăn bánh bao), nên đáp án đúng là 刘小明。","options":["王一雪","刘明","刘小雪","刘小明"],"q":"谁想吃米饭，不想吃包子？"},{"answerIdx":0,"explanation":"Trong bài Lưu Minh nói “坐出租车去。” (Đi bằng xe taxi), nên đáp án đúng là 坐出租车去。","options":["坐出租车去","坐公共汽车去","走路去","坐火车去"],"q":"他们怎么去西安饭店？"}],"scene":"在家里，王一雪全家在讨论周末晚餐安排。","sceneVi":"Ở nhà, cả gia đình Vương Nhất Tuyết đang bàn kế hoạch ăn tối cuối tuần."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (短文 tổng hợp)","lines":[{"hanzi":"在校园里，白家月的手机号是+33 601493190，李文的手机号是+86 13552721160。","pinyin":"Zài xiàoyuán li, Bái Jiāyuè de shǒujīhào shì sān sān liù líng yāo sì jiǔ sān yāo jiǔ líng, Lǐ Wén de shǒujīhào shì bā liù yāo sān wǔ wǔ èr qī èr yāo yāo liù líng.","speaker":"Đoạn văn","vi":"Trong khuôn viên trường, số điện thoại di động của Bạch Gia Nguyệt là +33 601493190, số điện thoại của Lý Văn là +86 13552721160."},{"hanzi":"下课后，在教室里，白家月和陈天中聊天儿，明天白家月想去超市买些牛奶。","pinyin":"Xiàkè hòu, zài jiàoshì li, Bái Jiāyuè hé Chén Tiānzhōng liáotiānr, míngtiān Bái Jiāyuè xiǎng qù chāoshì mǎi xiē niúnǎi.","speaker":"Đoạn văn","vi":"Sau giờ tan học, trong phòng học, Bạch Gia Nguyệt và Trần Thiên Trung trò chuyện, ngày mai Bạch Gia Nguyệt muốn đi siêu thị mua một ít sữa bò."},{"hanzi":"在家里，王一雪和刘明星期天想去西安饭店吃晚饭。","pinyin":"Zài jiā li, Wáng Yīxuě hé Liú Míng Xīngqītiān xiǎng qù Xī’ān Fàndiàn chī wǎnfàn.","speaker":"Đoạn văn","vi":"Ở nhà, Vương Nhất Tuyết và Lưu Minh muốn đến Nhà hàng Tây An ăn tối vào Chủ nhật."},{"hanzi":"刘小雪想吃那边的包子，刘小明想吃米饭，他们坐出租车去。","pinyin":"Liú Xiǎoxuě xiǎng chī nàbiān de bāozi, Liú Xiǎomíng xiǎng chī mǐfàn, tāmen zuò chūzūchē qù.","speaker":"Đoạn văn","vi":"Lưu Tiểu Tuyết muốn ăn bánh bao ở bên đó, Lưu Tiểu Minh muốn ăn cơm, họ đi bằng taxi."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong đoạn văn có câu “明天白家月想去超市买些牛奶。” (Ngày mai Bạch Gia Nguyệt muốn đi siêu thị mua một ít sữa bò), nên đáp án đúng là 去超市买牛奶。","options":["去教室上课","去西安饭店吃晚饭","去超市买牛奶","在家里看书"],"q":"明天白家月想去哪儿做什么？"},{"answerIdx":0,"explanation":"Trong đoạn văn có câu “王一雪和刘明星期天想去西安饭店吃晚饭。” và “他们坐出租车去。” (Chủ nhật Vương Nhất Tuyết và Lưu Minh muốn đến Nhà hàng Tây An ăn tối và họ đi bằng taxi), nên đáp án đúng là 去西安饭店，坐出租车去。","options":["去西安饭店，坐出租车去","去超市，坐出租车去","去西安饭店，坐公共汽车去","在家里吃，不去饭店"],"q":"王一雪和家人星期天去哪儿吃晚饭，怎么去？"}],"scene":"复习第六课的三篇课文。","sceneVi":"Tổng hợp nội dung ba bài khóa của Bài 6."}],"hsk1-7":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"现在几点？","pinyin":"Xiànzài jǐ diǎn?","speaker":"白家月","vi":"Bây giờ mấy giờ rồi?"},{"hanzi":"早上八点四十。","pinyin":"Zǎoshang bā diǎn sìshí.","speaker":"安妮","vi":"8 giờ 40 phút sáng."},{"hanzi":"我上午十点十分有课。","pinyin":"Wǒ shàngwǔ shí diǎn shí fēn yǒu kè.","speaker":"白家月","vi":"10 giờ 10 phút sáng nay tôi có tiết học."},{"hanzi":"好的，我们下午两点见吧。","pinyin":"Hǎo de, wǒmen xiàwǔ liǎng diǎn jiàn ba.","speaker":"安妮","vi":"Được, chúng ta gặp nhau lúc 2 giờ chiều nhé."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài An Ni nói “早上八点四十。” (8 giờ 40 sáng), nên đáp án đúng là 早上八点四十。","options":["早上八点四十","上午十点十分","下午两点","晚上六点半"],"q":"现在是几点？"},{"answerIdx":2,"explanation":"Trong bài An Ni nói “好的，我们下午两点见吧。” (Được, chúng ta gặp nhau lúc 2 giờ chiều nhé), nên đáp án đúng là 下午两点。","options":["早上八点四十","上午十点十分","下午两点","下午四点半"],"q":"白家月和安妮几点见？"}],"scene":"白家月和安妮在打电话。","sceneVi":"Bạch Gia Nguyệt và An Ni đang gọi điện thoại."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"下午我想去电影院看电影，你去吗？","pinyin":"Xiàwǔ wǒ xiǎng qù diànyǐngyuàn kàn diànyǐng, nǐ qù ma?","speaker":"李文","vi":"Chiều nay tôi muốn đi rạp chiếu phim xem phim, bạn có đi không?"},{"hanzi":"我不想去，下午还有事。","pinyin":"Wǒ bù xiǎng qù, xiàwǔ hái yǒu shì.","speaker":"白家月","vi":"Tôi không muốn đi, chiều nay tôi vẫn còn việc."},{"hanzi":"好的。明天呢？","pinyin":"Hǎo de. Míngtiān ne?","speaker":"李文","vi":"Được rồi. Thế ngày mai thì sao?"},{"hanzi":"我明天下午两点还上课呢，四点半下课。","pinyin":"Wǒ míngtiān xiàwǔ liǎng diǎn hái shàngkè ne, sì diǎn bàn xiàkè.","speaker":"白家月","vi":"2 giờ chiều mai tôi vẫn đang học trên lớp đấy, 4 giờ rưỡi mới tan học."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Lý Văn nói “下午我想去电影院看电影” (Buổi chiều tôi muốn đi rạp chiếu phim xem phim), nên đáp án đúng là 去电影院。","options":["去超市","去电影院","去书店","去医院"],"q":"李文下午想去哪儿？"},{"answerIdx":2,"explanation":"Trong bài Bạch Gia Nguyệt nói “我明天下午两点还上课呢，四点半下课。” (Chiều mai 2 giờ tôi còn lên lớp, 4 giờ rưỡi tan học), nên đáp án đúng là 四点半。","options":["两点","三点半","四点半","六点半"],"q":"白家月明天几点下课？"}],"scene":"在校园里，李文遇到白家月。","sceneVi":"Trong khuôn viên trường, Lý Văn tình cờ gặp Bạch Gia Nguyệt."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"喂，你在哪儿呢？","pinyin":"Wèi, nǐ zài nǎr ne?","speaker":"王一雪","vi":"Alô, anh đang ở đâu thế?"},{"hanzi":"我在家里呢。","pinyin":"Wǒ zài jiā li ne.","speaker":"刘明","vi":"Anh đang ở nhà đây."},{"hanzi":"我晚上六点半下班。","pinyin":"Wǒ wǎnshang liù diǎn bàn xiàbān.","speaker":"王一雪","vi":"Tối nay 6 giờ rưỡi em tan làm."},{"hanzi":"我八点去医院上班。","pinyin":"Wǒ bā diǎn qù yīyuàn shàngbān.","speaker":"刘明","vi":"8 giờ anh đến bệnh viện làm việc."},{"hanzi":"好的，你去店里买些菜吧。","pinyin":"Hǎo de, nǐ qù diàn li mǎi xiē cài ba.","speaker":"王一雪","vi":"Được rồi, anh ra cửa hàng mua một ít rau nhé."},{"hanzi":"好，我十分钟后去。","pinyin":"Hǎo, wǒ shí fēnzhōng hòu qù.","speaker":"刘明","vi":"Được, 10 phút nữa anh đi."}],"readingQuiz":[{"answerIdx":3,"explanation":"Trong bài Lưu Minh trả lời “我在家里呢。” (Anh đang ở nhà đây), nên đáp án đúng là 在家里。","options":["在办公室","在医院","在店里","在家里"],"q":"王一雪打电话时，刘明在哪儿？"},{"answerIdx":1,"explanation":"Trong bài Vương Nhất Tuyết bảo “你去店里买些菜吧。” (Anh ra cửa hàng mua ít rau nhé) và Lưu Minh đáp “好，我十分钟后去。” (Được, 10 phút nữa anh đi), nên đáp án đúng là 去店里买菜。","options":["去医院上班","去店里买菜","去办公室找王一雪","去电影院看电影"],"q":"十分钟后，刘明去哪儿做什么？"}],"scene":"王一雪在办公室给刘明打电话。","sceneVi":"Vương Nhất Tuyết đang ở văn phòng gọi điện thoại cho Lưu Minh."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (短文 tổng hợp)","lines":[{"hanzi":"现在是早上八点四十，白家月上午十点十分有课，她和安妮下午两点见。","pinyin":"Xiànzài shì zǎoshang bā diǎn sìshí, Bái Jiāyuè shàngwǔ shí diǎn shí fēn yǒu kè, tā hé Ānnī xiàwǔ liǎng diǎn jiàn.","speaker":"Đoạn văn","vi":"Bây giờ là 8 giờ 40 sáng, Bạch Gia Nguyệt có tiết học lúc 10 giờ 10 sáng, cô ấy và An Ni gặp nhau lúc 2 giờ chiều."},{"hanzi":"下午李文想去电影院看电影，白家月不想去，她下午还有事，明天下午两点还上课，四点半下课。","pinyin":"Xiàwǔ Lǐ Wén xiǎng qù diànyǐngyuàn kàn diànyǐng, Bái Jiāyuè bù xiǎng qù, tā xiàwǔ hái yǒu shì, míngtiān xiàwǔ liǎng diǎn hái shàngkè, sì diǎn bàn xiàkè.","speaker":"Đoạn văn","vi":"Chiều nay Lý Văn muốn đi rạp chiếu phim xem phim, Bạch Gia Nguyệt không muốn đi, chiều nay cô ấy vẫn còn việc, chiều mai 2 giờ vẫn học trên lớp, 4 giờ rưỡi tan học."},{"hanzi":"王一雪晚上六点半下班，刘明在家呢，他八点去医院上班。","pinyin":"Wáng Yīxuě wǎnshang liù diǎn bàn xiàbān, Liú Míng zài jiā ne, tā bā diǎn qù yīyuàn shàngbān.","speaker":"Đoạn văn","vi":"Vương Nhất Tuyết 6 giờ rưỡi tối tan làm, Lưu Minh đang ở nhà, 8 giờ anh ấy đến bệnh viện làm việc."},{"hanzi":"刘明十分钟后去店里买些菜。","pinyin":"Liú Míng shí fēnzhōng hòu qù diàn li mǎi xiē cài.","speaker":"Đoạn văn","vi":"Mười phút nữa Lưu Minh sẽ ra cửa hàng mua một ít rau."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong đoạn văn có câu “明天下午两点还上课，四点半下课。” (Chiều mai 2 giờ còn học, 4 giờ rưỡi tan học), nên đáp án đúng là 四点半。","options":["两点","四点半","六点半","十点十分"],"q":"白家月明天下午几点下课？"},{"answerIdx":3,"explanation":"Trong đoạn văn có câu “刘明在家呢，他八点去医院上班。” (Lưu Minh đang ở nhà, 8 giờ anh ấy đến bệnh viện làm việc), nên đáp án đúng là 刘明。","options":["王一雪","白家月","李文","刘明"],"q":"谁晚上八点去医院上班？"}],"scene":"综合课文一到课文三的时间与日程。","sceneVi":"Tổng hợp thời gian và lịch trình từ Bài khóa 1 đến Bài khóa 3."}],"hsk1-8":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"房间外有一只小猫。","pinyin":"Fángjiān wài yǒu yì zhī xiǎo māo.","speaker":"白家月","vi":"Ngoài phòng có một chú mèo con."},{"hanzi":"我没看见，它在哪儿呢？","pinyin":"Wǒ méi kànjiàn, tā zài nǎr ne?","speaker":"陈天中","vi":"Tôi không thấy, nó ở đâu thế?"},{"hanzi":"它在桌子下呢。","pinyin":"Tā zài zhuōzi xià ne.","speaker":"白家月","vi":"Nó ở dưới gầm bàn đấy."},{"hanzi":"这只小猫真漂亮！","pinyin":"Zhè zhī xiǎo māo zhēn piàoliang!","speaker":"陈天中","vi":"Chú mèo con này thật xinh đẹp!"}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài Bạch Gia Nguyệt nói “房间外有一只小猫。” (Ngoài phòng có một chú mèo con) và “它在桌子下呢。” (Nó ở dưới cái bàn), nên đáp án đúng là 在房间外桌子下。","options":["在房间里","在桌子上","在房间外桌子下","在椅子上"],"q":"小猫在哪儿？"},{"answerIdx":0,"explanation":"Trong bài Trần Thiên Trung khen “这只小猫真漂亮！” (Chú mèo con này thật xinh đẹp!), nên đáp án đúng là 真漂亮。","options":["真漂亮","很大","不可爱","很胖"],"q":"陈天中觉得这只小猫怎么样？"}],"scene":"在王一飞家，白家月和陈天中来做客。","sceneVi":"Tại nhà Vương Nhất Phi, Bạch Gia Nguyệt và Trần Thiên Trung đến chơi."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"我们在哪儿见呢？","pinyin":"Wǒmen zài nǎr jiàn ne?","speaker":"白家月","vi":"Chúng ta gặp nhau ở đâu nhé?"},{"hanzi":"在学校书店前见吧。","pinyin":"Zài xuéxiào shūdiàn qián jiàn ba.","speaker":"李文","vi":"Gặp nhau ở trước hiệu sách của trường nhé."},{"hanzi":"好的。下午两点你能到吗？","pinyin":"Hǎo de. Xiàwǔ liǎng diǎn nǐ néng dào ma?","speaker":"白家月","vi":"Được rồi. 2 giờ chiều bạn có đến được không?"},{"hanzi":"我能到。我在学校吃午饭。","pinyin":"Wǒ néng dào. Wǒ zài xuéxiào chī wǔfàn.","speaker":"李文","vi":"Tôi đến được. Tôi ăn cơm trưa ở trường."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Lý Văn nói “在学校书店前见吧。” (Gặp nhau trước hiệu sách của trường nhé), nên đáp án đúng là 在学校书店前。","options":["在教室里","在学校书店前","在电影院前","在饭店里"],"q":"白家月和李文在哪儿见？"},{"answerIdx":2,"explanation":"Trong bài Lý Văn nói “我在学校吃午饭。” (Tôi ăn cơm trưa ở trường), nên đáp án đúng là 在学校。","options":["在家里","在书店里","在学校","在饭店"],"q":"李文在哪儿吃午饭？"}],"scene":"在教室里，下课后，白家月给李文打电话。","sceneVi":"Trong lớp học, sau khi tan học, Bạch Gia Nguyệt gọi điện thoại cho Lý Văn."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"小胡，还没吃饭呢？","pinyin":"Xiǎo Hú, hái méi chī fàn ne?","speaker":"刘明","vi":"Tiểu Hồ, vẫn chưa ăn cơm à?"},{"hanzi":"没吃呢。","pinyin":"Méi chī ne.","speaker":"胡医生","vi":"Vẫn chưa ăn ạ."},{"hanzi":"大医院病人多，医生非常忙。","pinyin":"Dà yīyuàn bìngrén duō, yīshēng fēicháng máng.","speaker":"刘明","vi":"Bệnh viện lớn nhiều bệnh nhân, bác sĩ vô cùng bận."},{"hanzi":"是的。我爸爸也在医院工作，他也非常忙。","pinyin":"Shì de. Wǒ bàba yě zài yīyuàn gōngzuò, tā yě fēicháng máng.","speaker":"胡医生","vi":"Đúng vậy. Bố tôi cũng làm việc ở bệnh viện, ông ấy cũng rất bận."},{"hanzi":"你家有两个医生？","pinyin":"Nǐ jiā yǒu liǎng gè yīshēng?","speaker":"刘明","vi":"Nhà cậu có hai bác sĩ à?"},{"hanzi":"对。","pinyin":"Duì.","speaker":"胡医生","vi":"Đúng ạ."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Lưu Minh nói “大医院病人多，医生非常忙。” (Bệnh viện lớn bệnh nhân đông, bác sĩ vô cùng bận rộn), nên đáp án đúng là 因为大医院病人多。","options":["因为大医院医生少","因为大医院病人多","因为医生不想吃饭","因为医生都在家里"],"q":"为什么大医院的医生非常忙？"},{"answerIdx":1,"explanation":"Trong bài Lưu Minh hỏi “你家有两个医生？” (Nhà anh có hai bác sĩ à?) và bác sĩ Hồ đáp “对。” (Đúng vậy), nên đáp án đúng là 两个。","options":["一个","两个","三个","四个"],"q":"胡医生家有几个医生？"}],"scene":"在医院里，刘明和同事胡医生在聊天儿。","sceneVi":"Trong bệnh viện, Lưu Minh và đồng nghiệp là bác sĩ Hồ đang trò chuyện."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (短文 tổng hợp)","lines":[{"hanzi":"白家月和陈天中在王一飞家做客，房间外桌子下有一只漂亮的小猫。","pinyin":"Bái Jiāyuè hé Chén Tiānzhōng zài Wáng Yīfēi jiā zuòkè, fángjiān wài zhuōzi xià yǒu yì zhī piàoliang de xiǎo māo.","speaker":"Đoạn văn","vi":"Bạch Gia Nguyệt và Trần Thiên Trung đến chơi nhà Vương Nhất Phi, ngoài phòng dưới gầm bàn có một chú mèo con xinh đẹp."},{"hanzi":"下课后，白家月和李文下午两点在学校书店前见，李文在学校吃午饭。","pinyin":"Xiàkè hòu, Bái Jiāyuè hé Lǐ Wén xiàwǔ liǎng diǎn zài xuéxiào shūdiàn qián jiàn, Lǐ Wén zài xuéxiào chī wǔfàn.","speaker":"Đoạn văn","vi":"Sau khi tan học, Bạch Gia Nguyệt và Lý Văn gặp nhau lúc 2 giờ chiều trước hiệu sách của trường, Lý Văn ăn cơm trưa ở trường."},{"hanzi":"在医院里，小胡医生还没吃饭呢，大医院病人多，医生非常忙。","pinyin":"Zài yīyuàn li, Xiǎo Hú yīshēng hái méi chī fàn ne, dà yīyuàn bìngrén duō, yīshēng fēicháng máng.","speaker":"Đoạn văn","vi":"Ở bệnh viện, bác sĩ Tiểu Hồ vẫn chưa ăn cơm, bệnh viện lớn nhiều bệnh nhân nên bác sĩ rất bận."},{"hanzi":"胡医生的爸爸也在医院工作，他家有两个医生。","pinyin":"Hú yīshēng de bàba yě zài yīyuàn gōngzuò, tā jiā yǒu liǎng gè yīshēng.","speaker":"Đoạn văn","vi":"Bố của bác sĩ Hồ cũng làm việc ở bệnh viện, nhà anh ấy có hai bác sĩ."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong đoạn văn có câu “下课后，白家月和李文下午两点在学校书店前见，李文在学校吃午饭。” (Sau giờ học, Bạch Gia Nguyệt và Lý Văn gặp nhau trước hiệu sách trường lúc 2 giờ chiều, Lý Văn ăn cơm trưa ở trường), nên đáp án đúng là 李文。","options":["白家月","陈天中","李文","小胡医生"],"q":"下午两点在学校书店前见，谁在学校吃午饭？"},{"answerIdx":3,"explanation":"Trong đoạn văn có câu “胡医生的爸爸也在医院工作” (Bố của bác sĩ Hồ cũng làm việc ở bệnh viện), nên đáp án đúng là 在医院。","options":["在学校","在书店","在公司","在医院"],"q":"胡医生的爸爸在哪儿工作？"}],"scene":"综合课文一到课文三的地点与工作情况。","sceneVi":"Tổng hợp địa điểm và công việc từ Bài khóa 1 đến Bài khóa 3."}],"hsk1-9":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"学校前边有一家电影院。","pinyin":"Xuéxiào qiánbian yǒu yì jiā diànyǐngyuàn.","speaker":"李文","vi":"Phía trước trường học có một rạp chiếu phim."},{"hanzi":"对。我们晚上去那个电影院看电影吧。","pinyin":"Duì. Wǒmen wǎnshang qù nàge diànyǐngyuàn kàn diànyǐng ba.","speaker":"白家月","vi":"Đúng vậy. Tối nay chúng ta đến rạp chiếu phim đó xem phim đi."},{"hanzi":"好！我们七点在电影院外边见，好吗？","pinyin":"Hǎo! Wǒmen qī diǎn zài diànyǐngyuàn wàibian jiàn, hǎo ma?","speaker":"李文","vi":"Được! Chúng ta gặp nhau lúc bảy giờ ở bên ngoài rạp chiếu phim nhé?"},{"hanzi":"好的，晚上七点见！","pinyin":"Hǎo de, wǎnshang qī diǎn jiàn!","speaker":"白家月","vi":"Được thôi, hẹn gặp tối nay lúc bảy giờ!"}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài, Lý Văn nói \"学校前边有一家电影院。\" (Phía trước trường học có một rạp chiếu phim.), nên đáp án đúng là 学校前边.","options":["学校前边","学校后边","学校里边","学校外边"],"q":"电影院在哪儿？"},{"answerIdx":2,"explanation":"Trong bài có câu \"我们七点在电影院外边见\" (Chúng ta gặp nhau ở bên ngoài rạp chiếu phim lúc 7 giờ nhé) và \"好的，晚上七点见！\" (Được, tối 7 giờ gặp!), nên đáp án đúng là 七点在电影院外边.","options":["六点在学校外边","七点在电影院里边","七点在电影院外边","八点在学校前边"],"q":"他们晚上几点在哪儿见？"}],"scene":"在校园里，李文和白家月在聊天儿。","sceneVi":"Trong khuôn viên trường, Lý Văn và Bạch Gia Nguyệt đang trò chuyện."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"椅子上有一本中文书，那是谁的书？","pinyin":"Yǐzi shang yǒu yì běn Zhōngwén shū, nà shì shéi de shū?","speaker":"白家月","vi":"Trên ghế có một quyển sách tiếng Trung, đó là sách của ai vậy?"},{"hanzi":"是我的书，谢谢。这是我的第二本中文书。","pinyin":"Shì wǒ de shū, xièxie. Zhè shì wǒ de dì-èr běn Zhōngwén shū.","speaker":"陈天中","vi":"Là sách của tôi, cảm ơn bạn. Đây là quyển sách tiếng Trung thứ hai của tôi."},{"hanzi":"不客气。你明天上午在哪儿？","pinyin":"Bú kèqi. Nǐ míngtiān shàngwǔ zài nǎr?","speaker":"白家月","vi":"Không có gì. Sáng mai bạn ở đâu?"},{"hanzi":"我明天上午在学校学习。","pinyin":"Wǒ míngtiān shàngwǔ zài xuéxiào xuéxí.","speaker":"陈天中","vi":"Sáng mai tôi học ở trường."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài, Bạch Gia Nguyệt hỏi \"椅子上有一本中文书，那是谁的书？\" (Trên ghế có một quyển sách tiếng Trung, đó là sách của ai?) và Trần Thiên Trung đáp \"是我的书\" (Là sách của tôi), nên đáp án đúng là 一本中文书，是陈天中的.","options":["一本中文书，是白家月的","两本中文书，是陈天中的","一本中文书，是陈天中的","一本中文书，不是陈天中的"],"q":"椅子上有什么？是谁的？"},{"answerIdx":2,"explanation":"Trong bài có câu \"我明天上午在学校学习。\" (Sáng ngày mai tôi học ở trường.), nên đáp án đúng là 在学校学习.","options":["在家里看书","在教室休息","在学校学习","去电影院看电影"],"q":"陈天中明天上午在哪儿做什么？"}],"scene":"在教室里，下课后，白家月和陈天中在对话。","sceneVi":"Trong phòng học, sau khi tan học, Bạch Gia Nguyệt và Trần Thiên Trung đang nói chuyện."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"明天星期六，你做什么？","pinyin":"Míngtiān Xīngqīliù, nǐ zuò shénme?","speaker":"王一雪","vi":"Ngày mai là thứ Bảy, bạn làm gì?"},{"hanzi":"我白天在家里读书，晚上和朋友们去外边唱歌。","pinyin":"Wǒ báitiān zài jiā li dúshū, wǎnshang hé péngyoumen qù wàibian chàng gē.","speaker":"杨同乐","vi":"Ban ngày tôi đọc sách ở nhà, buổi tối cùng bạn bè ra ngoài hát."},{"hanzi":"你唱歌很好听。","pinyin":"Nǐ chàng gē hěn hǎotīng.","speaker":"王一雪","vi":"Bạn hát rất hay."},{"hanzi":"谢谢！您星期六做什么？","pinyin":"Xièxie! Nín Xīngqīliù zuò shénme?","speaker":"杨同乐","vi":"Cảm ơn! Thứ Bảy chị làm gì?"},{"hanzi":"我在家里做饭、看电视，和孩子们、小狗玩。","pinyin":"Wǒ zài jiā li zuò fàn, kàn diànshì, hé háizimen, xiǎo gǒu wán.","speaker":"王一雪","vi":"Tôi ở nhà nấu cơm, xem tivi, chơi với các con và chú chó nhỏ."},{"hanzi":"我也有一只小狗。","pinyin":"Wǒ yě yǒu yì zhī xiǎo gǒu.","speaker":"杨同乐","vi":"Tôi cũng có một chú chó nhỏ."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Dương Đồng Nhạc nói \"我白天在家里读书，晚上和朋友们去外边唱歌。\" (Ban ngày tôi đọc sách ở nhà, buổi tối đi ra ngoài hát với bạn bè.), nên đáp án đúng là 白天在家读书，晚上去外边唱歌.","options":["白天在家做饭，晚上看电视","白天在家读书，晚上去外边唱歌","白天去外边唱歌，晚上在家读书","白天和孩子们玩，晚上和朋友吃饭"],"q":"杨同乐星期六做什么？"},{"answerIdx":0,"explanation":"Trong bài, Vương Nhất Tuyết nói ở nhà chơi với \"...小狗玩\" (chơi với chó con) và Dương Đồng Nhạc đáp \"我也有一只小狗。\" (Tôi cũng có một con chó con.), nên đáp án đúng là 都有一只小狗.","options":["都有一只小狗","都有很多孩子","都喜欢星期六在家做饭","都去外边唱歌"],"q":"王一雪和杨同乐都有什么？"}],"scene":"在办公室里，休息时，王一雪和杨同乐谈论周末生活。","sceneVi":"Trong văn phòng, vào giờ nghỉ giải lao, Vương Nhất Tuyết và Dương Đồng Nhạc trò chuyện về cuộc sống cuối tuần."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (短文 tổng hợp)","lines":[{"hanzi":"学校前边有一家电影院，李文和白家月晚上七点在电影院外边见，去那个电影院看电影。","pinyin":"Xuéxiào qiánbian yǒu yì jiā diànyǐngyuàn, Lǐ Wén hé Bái Jiāyuè wǎnshang qī diǎn zài diànyǐngyuàn wàibian jiàn, qù nàge diànyǐngyuàn kàn diànyǐng.","speaker":"Đoạn văn","vi":"Phía trước trường học có một rạp chiếu phim, tối nay lúc 7 giờ Lý Văn và Bạch Gia Nguyệt gặp nhau ở bên ngoài rạp rồi vào rạp đó xem phim."},{"hanzi":"在教室里，椅子上有一本中文书，那是陈天中的第二本中文书，他明天上午在学校学习。","pinyin":"Zài jiàoshì li, yǐzi shang yǒu yì běn Zhōngwén shū, nà shì Chén Tiānzhōng de dì-èr běn Zhōngwén shū, tā míngtiān shàngwǔ zài xuéxiào xuéxí.","speaker":"Đoạn văn","vi":"Trong phòng học, trên ghế có một quyển sách tiếng Trung, đó là quyển sách tiếng Trung thứ hai của Trần Thiên Trung, sáng mai anh ấy học ở trường."},{"hanzi":"明天星期六，杨同乐白天在家里读书，晚上和朋友们去外边唱歌。","pinyin":"Míngtiān Xīngqīliù, Yáng Tónglè báitiān zài jiā li dúshū, wǎnshang hé péngyoumen qù wàibian chàng gē.","speaker":"Đoạn văn","vi":"Ngày mai là thứ Bảy, ban ngày Dương Đồng Nhạc đọc sách ở nhà, buổi tối cùng bạn bè ra ngoài hát."},{"hanzi":"王一雪星期六在家里做饭、看电视，和孩子们、小狗玩，杨同乐也有一只小狗。","pinyin":"Wáng Yīxuě Xīngqīliù zài jiā li zuò fàn, kàn diànshì, hé háizimen, xiǎo gǒu wán, Yáng Tónglè yě yǒu yì zhī xiǎo gǒu.","speaker":"Đoạn văn","vi":"Thứ Bảy Vương Nhất Tuyết ở nhà nấu cơm, xem tivi, chơi với các con và chú chó nhỏ, Dương Đồng Nhạc cũng có một chú chó nhỏ."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu \"那是陈天中的第二本中文书，他明天上午在学校学习。\" (Đó là quyển sách tiếng Trung thứ hai của Trần Thiên Trung, sáng ngày mai anh ấy học ở trường.), nên đáp án đúng là 陈天中.","options":["李文","白家月","陈天中","杨同乐"],"q":"谁明天上午在学校学习？"},{"answerIdx":3,"explanation":"Trong bài có câu \"王一雪星期六在家里做饭、看电视，和孩子们、小狗玩\" (Thứ Bảy Vương Nhất Tuyết ở nhà nấu cơm, xem tivi, chơi với các con và chó con), nên đáp án đúng là 做饭、看电视，和孩子们、小狗玩.","options":["读书、唱歌、看电影","学习、买书、听歌","看电视、去外边唱歌","做饭、看电视，和孩子们、小狗玩"],"q":"王一雪星期六在家里做什么？"}],"scene":"总结本课三篇课文的内容。","sceneVi":"Tóm tắt nội dung ba bài khóa trong bài 9."}],"hsk1-10":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"请问，有杯子吗？","pinyin":"Qǐngwèn, yǒu bēizi ma?","speaker":"王一雪","vi":"Xin hỏi, ở đây có cốc không ạ?"},{"hanzi":"有，杯子在这边。","pinyin":"Yǒu, bēizi zài zhèbiān.","speaker":"售货员","vi":"Có ạ, cốc ở bên này."},{"hanzi":"多少钱一个？","pinyin":"Duōshao qián yí gè?","speaker":"王一雪","vi":"Bao nhiêu tiền một cái ạ?"},{"hanzi":"这些五块钱一个，那些十块钱一个。","pinyin":"Zhèxiē wǔ kuài qián yí gè, nàxiē shí kuài qián yí gè.","speaker":"售货员","vi":"Những cái này năm tệ một cái, những cái kia mười tệ một cái."},{"hanzi":"我买这个吧。","pinyin":"Wǒ mǎi zhège ba.","speaker":"王一雪","vi":"Tôi mua cái này nhé."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài, người bán hàng nói \"这些五块钱一个，那些十块钱一个。\" (Những cái này năm tệ một cái, những cái kia mười tệ một cái.), nên đáp án đúng là 这些五块，那些十块.","options":["都是五块钱一个","都是十块钱一个","这些五块，那些十块","这些十块，那些五块"],"q":"小店里的杯子多少钱一个？"},{"answerIdx":1,"explanation":"Trong bài, người bán giới thiệu \"这些五块钱一个，那些十块钱一个。\" (Những cái này 5 tệ một cái, những cái kia 10 tệ một cái.) và Vương Nhất Tuyết nói \"我买这个吧。\" (Tôi mua cái này nhé - tức loại gần chỗ cô ấy giá 5 tệ), nên đáp án đúng là 买五块钱的这个.","options":["买十块钱的那个","买五块钱的这个","她不买杯子","她买两个杯子"],"q":"王一雪买哪个杯子？"}],"scene":"在一家小店，王一雪在买杯子。","sceneVi":"Trong một cửa hàng nhỏ, Vương Nhất Tuyết đang mua cốc."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"这儿的水果真不少！","pinyin":"Zhèr de shuǐguǒ zhēn bù shǎo!","speaker":"王一雪","vi":"Hoa quả ở đây thật nhiều!"},{"hanzi":"您想买什么？","pinyin":"Nín xiǎng mǎi shénme?","speaker":"售货员","vi":"Chị muốn mua gì ạ?"},{"hanzi":"我想买两斤苹果。","pinyin":"Wǒ xiǎng mǎi liǎng jīn píngguǒ.","speaker":"王一雪","vi":"Tôi muốn mua hai cân táo."},{"hanzi":"苹果三块五一斤。这些七块二，七块钱吧。","pinyin":"Píngguǒ sān kuài wǔ yì jīn. Zhèxiē qī kuài èr, qī kuài qián ba.","speaker":"售货员","vi":"Táo ba tệ rưỡi một cân. Chỗ này bảy tệ hai hào, tính chẵn bảy tệ nhé."},{"hanzi":"好的，这儿的苹果真便宜！","pinyin":"Hǎo de, zhèr de píngguǒ zhēn piányi!","speaker":"王一雪","vi":"Vâng, táo ở đây rẻ thật đấy!"}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài, Vương Nhất Tuyết nói \"我想买两斤苹果。\" (Tôi muốn mua hai cân táo.) và người bán nói \"苹果三块五一斤。\" (Táo giá ba tệ rưỡi một cân.), nên đáp án đúng là 三块五一斤，想买两斤.","options":["三块五一斤，想买两斤","三块钱一斤，想买两斤","七块二一斤，想买一斤","三块五一斤，想买三斤"],"q":"苹果多少钱一斤？王一雪想买多少？"},{"answerIdx":1,"explanation":"Trong bài, người bán hàng nói \"这些七块二，七块钱吧。\" (Chỗ này bảy tệ hai hào, tính tròn bảy tệ nhé.), nên đáp án đúng là 七块钱.","options":["七块二","七块钱","三块五","六块钱"],"q":"这些苹果七块二，售货员说多少钱？"}],"scene":"在菜市场，王一雪在买水果。","sceneVi":"Ở chợ rau quả, Vương Nhất Tuyết đang mua hoa quả."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"这家商店衣服真多！这件一百元，怎么样？","pinyin":"Zhè jiā shāngdiàn yīfu zhēn duō! Zhè jiàn yìbǎi yuán, zěnmeyàng?","speaker":"王一雪","vi":"Cửa hàng này nhiều quần áo thật! Chiếc này một trăm tệ, anh thấy thế nào?"},{"hanzi":"好看，也不贵。","pinyin":"Hǎokàn, yě bú guì.","speaker":"刘明","vi":"Đẹp đấy, cũng không đắt."},{"hanzi":"小雪能穿，买一件吧。","pinyin":"Xiǎoxuě néng chuān, mǎi yí jiàn ba.","speaker":"王一雪","vi":"Tiểu Tuyết mặc vừa đấy, mua một chiếc nhé."},{"hanzi":"好的。小明能穿吗？","pinyin":"Hǎo de. Xiǎomíng néng chuān ma?","speaker":"刘明","vi":"Được. Tiểu Minh có mặc được không?"},{"hanzi":"不能。这些是女孩子穿的衣服，男孩子的衣服在那儿。","pinyin":"Bù néng. Zhèxiē shì nǚ háizi chuān de yīfu, nán háizi de yīfu zài nàr.","speaker":"王一雪","vi":"Không được. Đây là quần áo cho bé gái mặc, quần áo của bé trai ở đằng kia."},{"hanzi":"好的。","pinyin":"Hǎo de.","speaker":"刘明","vi":"Được rồi."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài, Vương Nhất Tuyết hỏi về chiếc áo 100 tệ \"这件一百元，怎么样？\" (Cái này 100 tệ, thấy sao?), Lưu Minh trả lời \"好看，也不贵。\" (Đẹp, cũng không đắt.), nên đáp án đúng là 好看，也不贵.","options":["不好看，很贵","好看，但是很贵","好看，也不贵","不好看，也不贵"],"q":"刘明觉得那件一百元的衣服怎么样？"},{"answerIdx":1,"explanation":"Trong bài, Vương Nhất Tuyết giải thích \"不能。这些是女孩子穿的衣服，男孩子的衣服在那儿。\" (Không được. Đây là quần áo con gái mặc, quần áo của con trai ở đằng kia.), nên đáp án đúng là 因为这些是女孩子穿的衣服.","options":["因为这些衣服太贵了","因为这些是女孩子穿的衣服","因为商店没有男孩子的衣服","因为小明不喜欢这件衣服"],"q":"为什么小明不能穿这些衣服？"}],"scene":"在商场里，刘明和王一雪在给孩子买衣服。","sceneVi":"Trong trung tâm thương mại, Lưu Minh và Vương Nhất Tuyết đang mua quần áo cho con."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (短文 tổng hợp)","lines":[{"hanzi":"在一家小店，王一雪买杯子，这些五块钱一个，那些十块钱一个，她买这个。","pinyin":"Zài yì jiā xiǎo diàn, Wáng Yīxuě mǎi bēizi, zhèxiē wǔ kuài qián yí gè, nàxiē shí kuài qián yí gè, tā mǎi zhège.","speaker":"Đoạn văn","vi":"Ở một cửa hàng nhỏ, Vương Nhất Tuyết mua cốc, những cái này năm tệ một cái, những cái kia mười tệ một cái, cô ấy mua cái này."},{"hanzi":"在菜市场，王一雪买两斤苹果，苹果三块五一斤，售货员说七块钱吧，这儿的苹果真便宜！","pinyin":"Zài càishìchǎng, Wáng Yīxuě mǎi liǎng jīn píngguǒ, píngguǒ sān kuài wǔ yì jīn, shòuhuòyuán shuō qī kuài qián ba, zhèr de píngguǒ zhēn piányi!","speaker":"Đoạn văn","vi":"Ở chợ rau quả, Vương Nhất Tuyết mua hai cân táo, táo ba tệ rưỡi một cân, người bán nói tính bảy tệ nhé, táo ở đây rẻ thật!"},{"hanzi":"在商场里，刘明和王一雪给孩子买衣服，这家商店衣服真多，有一件一百元，好看也不贵。","pinyin":"Zài shāngchǎng li, Liú Míng hé Wáng Yīxuě gěi háizi mǎi yīfu, zhè jiā shāngdiàn yīfu zhēn duō, yǒu yí jiàn yìbǎi yuán, hǎokàn yě bú guì.","speaker":"Đoạn văn","vi":"Trong trung tâm thương mại, Lưu Minh và Vương Nhất Tuyết mua quần áo cho con, cửa hàng này thật nhiều quần áo, có một chiếc giá một trăm tệ, đẹp mà cũng không đắt."},{"hanzi":"小雪能穿这件女孩子穿的衣服，男孩子的衣服在那儿。","pinyin":"Xiǎoxuě néng chuān zhè jiàn nǚ háizi chuān de yīfu, nán háizi de yīfu zài nàr.","speaker":"Đoạn văn","vi":"Tiểu Tuyết mặc được chiếc áo dành cho bé gái này, còn quần áo của bé trai ở đằng kia."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu \"在菜市场，王一雪买两斤苹果... 售货员说七块钱吧\" (Ở chợ rau, Vương Nhất Tuyết mua hai cân táo... người bán nói bảy tệ nhé), nên đáp án đúng là 在菜市场，给了七块钱.","options":["在商场，给了一百元","在小店，给了五块钱","在菜市场，给了七块钱","在菜市场，给了三块五"],"q":"王一雪在哪儿买苹果？给了多少钱？"},{"answerIdx":1,"explanation":"Trong bài có câu \"有一件一百元，好看也不贵。小雪能穿这件女孩子穿的衣服\" (Có một chiếc áo giá 100 tệ, đẹp mà không đắt. Tiểu Tuyết có thể mặc chiếc áo dành cho bé gái này), nên đáp án đúng là 小雪.","options":["小明","小雪","刘明","售货员"],"q":"商场里那件一百元的衣服，谁能穿？"}],"scene":"总结本课三篇课文的内容。","sceneVi":"Tóm tắt nội dung ba bài khóa trong bài 10."}],"hsk1-11":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"喂，李文，你什么时候能到饭店？","pinyin":"Wèi, Lǐ Wén, nǐ shénme shíhou néng dào fàndiàn?","speaker":"王一飞","vi":"A-lô, Lý Văn, khi nào bạn có thể đến nhà hàng?"},{"hanzi":"还不知道，正在找呢。它是不是在超市后边？","pinyin":"Hái bù zhīdào, zhèngzài zhǎo ne. Tā shì bu shì zài chāoshì hòubian?","speaker":"李文","vi":"Vẫn chưa biết, tôi đang tìm đây. Có phải nó ở phía sau siêu thị không?"},{"hanzi":"是的。你开车没开车？","pinyin":"Shì de. Nǐ kāichē méi kāichē?","speaker":"王一飞","vi":"Đúng vậy. Bạn có lái xe không?"},{"hanzi":"我没开车，坐车呢。","pinyin":"Wǒ méi kāichē, zuò chē ne.","speaker":"李文","vi":"Tôi không lái xe, tôi đang ngồi xe (đi xe)."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Lý Văn hỏi \"它是不是在超市后边？\" (Có phải nó ở phía sau siêu thị không?) và Vương Nhất Phi xác nhận \"是的。\" (Đúng vậy.), nên đáp án đúng là 在超市后边.","options":["在超市前边","在超市后边","在学校外边","在电影院里边"],"q":"李文找的饭店在哪儿？"},{"answerIdx":2,"explanation":"Trong bài, Lý Văn nói \"我没开车，坐车呢。\" (Tôi không lái xe, đang ngồi xe đây.), nên đáp án đúng là 他坐车去.","options":["他开车去","他走路去","他坐车去","他骑车去"],"q":"李文怎么去饭店？"}],"scene":"在路上，李文在找饭店，王一飞给他打电话。","sceneVi":"Trên đường đi, Lý Văn đang tìm nhà hàng, Vương Nhất Phi gọi điện cho anh ấy."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"你还在读大学吗？","pinyin":"Nǐ hái zài dú dàxué ma?","speaker":"王一飞","vi":"Bạn vẫn đang học đại học à?"},{"hanzi":"对，我读大学呢，还是大学生。","pinyin":"Duì, wǒ dú dàxué ne, hái shì dàxuéshēng.","speaker":"李文","vi":"Đúng vậy, tôi đang học đại học, vẫn là sinh viên đại học."},{"hanzi":"你们学习忙不忙？","pinyin":"Nǐmen xuéxí máng bu máng?","speaker":"王一飞","vi":"Việc học của các bạn có bận không?"},{"hanzi":"非常忙，我学医，我们的课很多。","pinyin":"Fēicháng máng, wǒ xué yī, wǒmen de kè hěn duō.","speaker":"李文","vi":"Vô cùng bận, tôi học ngành y, tiết học của chúng tôi rất nhiều."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài, Lý Văn nói \"对，我读大学呢，还是大学生。\" (Đúng, tôi đang học đại học, vẫn là sinh viên đại học.), nên đáp án đúng là 他在读大学.","options":["他在饭店工作","他在医院工作","他在读大学","他在家休息"],"q":"李文现在在做什么？"},{"answerIdx":1,"explanation":"Trong bài, khi được hỏi \"你们学习忙不忙？\" (Việc học của các bạn có bận không?), Lý Văn trả lời \"非常忙，我学医，我们的课很多。\" (Rất bận, tôi học y, tiết học của chúng tôi rất nhiều.), nên đáp án đúng là 学医，非常忙.","options":["学中文，不忙","学医，非常忙","学医，不太忙","学中文，非常忙"],"q":"李文学什么？他们的学习忙吗？"}],"scene":"在饭店里，王一飞和李文见面后聊天儿。","sceneVi":"Ở trong nhà hàng, sau khi gặp mặt, Vương Nhất Phi và Lý Văn nói chuyện phiếm."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"弟弟起床没起床呢？","pinyin":"Dìdi qǐchuáng méi qǐchuáng ne?","speaker":"刘明","vi":"Em trai đã thức dậy chưa?"},{"hanzi":"没起床呢，还在睡觉。","pinyin":"Méi qǐchuáng ne, hái zài shuìjiào.","speaker":"刘小雪","vi":"Chưa dậy đâu ạ, vẫn đang ngủ."},{"hanzi":"还睡呢？他今天去不去那里？","pinyin":"Hái shuì ne? Tā jīntiān qù bu qù nàlǐ?","speaker":"刘明","vi":"Vẫn ngủ à? Hôm nay em ấy có đến chỗ đó không?"},{"hanzi":"去哪里？","pinyin":"Qù nǎlǐ?","speaker":"刘小雪","vi":"Đến đâu ạ?"},{"hanzi":"去超市。","pinyin":"Qù chāoshì.","speaker":"刘明","vi":"Đến siêu thị."},{"hanzi":"我昨天问他，他对我说，他不去，他今天要和小朋友玩。","pinyin":"Wǒ zuótiān wèn tā, tā duì wǒ shuō, tā bú qù, tā jīntiān yào hé xiǎopéngyǒu wán.","speaker":"刘小雪","vi":"Hôm qua con hỏi em ấy rồi, em ấy nói với con là em ấy không đi, hôm nay em ấy muốn chơi cùng các bạn nhỏ."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, khi Lưu Minh hỏi em trai đã dậy chưa, Lưu Tiểu Tuyết trả lời \"没起床呢，还在睡觉。\" (Chưa dậy đâu ạ, vẫn đang ngủ.), nên đáp án đúng là 还在睡觉.","options":["正在吃饭","还在睡觉","已经去超市了","在和小朋友玩"],"q":"刘明问女儿的时候，弟弟在做什么？"},{"answerIdx":3,"explanation":"Trong bài, Lưu Tiểu Tuyết nói \"他不去，他今天要和小朋友玩。\" (Em ấy không đi, hôm nay em ấy muốn chơi với các bạn nhỏ.), nên đáp án đúng là 和小朋友玩.","options":["和爸爸去医院","和姐姐去超市","在家里睡觉一天","和小朋友玩"],"q":"弟弟今天要做什么？"}],"scene":"星期六早上，刘明要去医院加班，出门前和女儿对话。","sceneVi":"Sáng thứ Bảy, Lưu Minh chuẩn bị đến bệnh viện làm thêm giờ, trước khi ra khỏi nhà ông nói chuyện với con gái."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (短文 tổng hợp)","lines":[{"hanzi":"李文没开车，坐车去超市后边的饭店。","pinyin":"Lǐ Wén méi kāichē, zuò chē qù chāoshì hòubian de fàndiàn.","speaker":"Đoạn văn","vi":"Lý Văn không lái xe, anh ấy ngồi xe đến nhà hàng ở phía sau siêu thị."},{"hanzi":"在饭店里，李文对王一飞说，他在读大学，他学医，课很多。","pinyin":"Zài fàndiàn lǐ, Lǐ Wén duì Wáng Yīfēi shuō, tā zài dú dàxué, tā xué yī, kè hěn duō.","speaker":"Đoạn văn","vi":"Trong nhà hàng, Lý Văn nói với Vương Nhất Phi rằng anh ấy đang học đại học, anh ấy học ngành y và có rất nhiều tiết học."},{"hanzi":"星期六早上，刘明问刘小雪弟弟起床没起床。","pinyin":"Xīngqīliù zǎoshang, Liú Míng wèn Liú Xiǎoxuě dìdi qǐchuáng méi qǐchuáng.","speaker":"Đoạn văn","vi":"Sáng thứ Bảy, Lưu Minh hỏi Lưu Tiểu Tuyết xem em trai đã thức dậy chưa."},{"hanzi":"弟弟还在睡觉，他今天不去超市，要和小朋友玩。","pinyin":"Dìdi hái zài shuìjiào, tā jīntiān bú qù chāoshì, yào hé xiǎopéngyǒu wán.","speaker":"Đoạn văn","vi":"Em trai vẫn đang ngủ, hôm nay em ấy không đi siêu thị mà muốn chơi cùng các bạn nhỏ."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu \"在饭店里，李文对王一飞说，他在读大学，他学医，课很多。\" (Ở nhà hàng, Lý Văn nói với Vương Nhất Phi rằng anh đang học đại học, học ngành y, rất nhiều tiết học.), nên đáp án đúng là 王一飞.","options":["刘明","刘小雪","王一飞","小朋友"],"q":"李文在超市后边的饭店里和谁说话？"},{"answerIdx":1,"explanation":"Trong bài có câu \"李文对王一飞说，他在读大学，他学医\" (Lý Văn nói với Vương Nhất Phi rằng anh đang học đại học, học y), còn các lựa chọn khác đều sai so với nội dung bài (Lý Văn ngồi xe chứ không tự lái, em trai vẫn đang ngủ và hôm nay không đi siêu thị), nên đáp án đúng là 李文在读大学，学医.","options":["李文开车去饭店","李文在读大学，学医","弟弟已经起床了","弟弟今天要去超市"],"q":"下面哪句话是对的？"}],"scene":"课文一至三的故事总结。","sceneVi":"Tóm tắt câu chuyện của Bài khóa 1 đến 3."}],"hsk1-12":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"今天天气怎么样？","pinyin":"Jīntiān tiānqì zěnmeyàng?","speaker":"王一雪","vi":"Hôm nay thời tiết thế nào?"},{"hanzi":"这里的天不太好，下雨了。","pinyin":"Zhèlǐ de tiān bú tài hǎo, xià yǔ le.","speaker":"王一飞","vi":"Trời ở đây không tốt lắm, mưa rồi."},{"hanzi":"雨大吗？","pinyin":"Yǔ dà ma?","speaker":"王一雪","vi":"Mưa có to không?"},{"hanzi":"有点儿大，我觉得很冷。","pinyin":"Yǒudiǎnr dà, wǒ juéde hěn lěng.","speaker":"王一飞","vi":"Hơi to, tôi cảm thấy rất lạnh."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài, Vương Nhất Phi nói \"这里的天不太好，下雨了。\" (Thời tiết ở đây không tốt lắm, trời mưa rồi.), nên đáp án đúng là 不太好，下雨了.","options":["天气很好","下雪了","不太好，下雨了","很热，没下雨"],"q":"王一飞那儿今天天气怎么样？"},{"answerIdx":1,"explanation":"Trong bài, Vương Nhất Phi trả lời về cơn mưa \"有点儿大，我觉得很冷。\" (Hơi to một chút, tôi thấy rất lạnh.), nên đáp án đúng là 雨有点儿大，她觉得很冷.","options":["雨不大，她觉得很热","雨有点儿大，她觉得很冷","雨很大，她不觉得冷","没下雨，她觉得有点儿冷"],"q":"王一飞那儿的雨大吗？她觉得怎么样？"}],"scene":"王一雪给王一飞打电话，询问王一飞那边的情况。","sceneVi":"Vương Nhất Tuyết gọi điện cho Vương Nhất Phi, hỏi thăm tình hình bên chỗ Vương Nhất Phi."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"昨天下雪了。","pinyin":"Zuótiān xià xuě le.","speaker":"王一雪","vi":"Hôm qua tuyết rơi rồi."},{"hanzi":"是的，太冷了。","pinyin":"Shì de, tài lěng le.","speaker":"杨同乐","vi":"Đúng vậy, lạnh quá đi."},{"hanzi":"你昨天没来公司，生病了？","pinyin":"Nǐ zuótiān méi lái gōngsī, shēngbìng le?","speaker":"王一雪","vi":"Hôm qua bạn không đến công ty, bị ốm à?"},{"hanzi":"对，我昨天去医院看病了。","pinyin":"Duì, wǒ zuótiān qù yīyuàn kànbìng le.","speaker":"杨同乐","vi":"Đúng vậy, hôm qua tôi đã đến bệnh viện khám bệnh."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Vương Nhất Tuyết nói \"昨天下雪了。\" (Hôm qua trời đổ tuyết rồi.) và Dương Đồng Nhạc đáp \"是的，太冷了。\" (Đúng vậy, lạnh quá.), nên đáp án đúng là 下雪了，太冷了.","options":["下雨了，不冷","下雪了，太冷了","天气很好，很热","没下雪，有点儿冷"],"q":"他们那儿昨天的天气怎么样？"},{"answerIdx":2,"explanation":"Trong bài, khi được hỏi có phải bị ốm không, Dương Đồng Nhạc đáp \"对，我昨天去医院看病了。\" (Đúng, hôm qua tôi đã đi bệnh viện khám bệnh.), nên đáp án đúng là 他生病了，去医院看病了.","options":["他去外边唱歌了","他在家看电视了","他生病了，去医院看病了","他去学校学习了"],"q":"杨同乐昨天为什么没来公司？"}],"scene":"在公司电梯里，王一雪和杨同乐在聊天儿。","sceneVi":"Trong thang máy công ty, Vương Nhất Tuyết và Dương Đồng Nhạc đang nói chuyện phiếm."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"医生，我病了。","pinyin":"Yīshēng, wǒ bìng le.","speaker":"杨同乐","vi":"Bác sĩ ơi, tôi bị ốm rồi."},{"hanzi":"我看看。你觉得怎么样？","pinyin":"Wǒ kànkan. Nǐ juéde zěnmeyàng?","speaker":"胡医生","vi":"Để tôi xem chút. Anh cảm thấy thế nào?"},{"hanzi":"我很冷。","pinyin":"Wǒ hěn lěng.","speaker":"杨同乐","vi":"Tôi rất lạnh."},{"hanzi":"好的，吃一点儿药，今天休息半天吧。","pinyin":"Hǎo de, chī yìdiǎnr yào, jīntiān xiūxi bàn tiān ba.","speaker":"胡医生","vi":"Được rồi, uống một chút thuốc, hôm nay nghỉ ngơi nửa ngày đi nhé."},{"hanzi":"好的。","pinyin":"Hǎo de.","speaker":"杨同乐","vi":"Vâng ạ."},{"hanzi":"回家后再喝些热水。","pinyin":"Huí jiā hòu zài hē xiē rè shuǐ.","speaker":"胡医生","vi":"Sau khi về nhà hãy uống thêm chút nước ấm nhé."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài, khi bác sĩ Hồ hỏi \"你觉得怎么样？\" (Anh cảm thấy thế nào?), Dương Đồng Nhạc trả lời \"我很冷。\" (Tôi rất lạnh.), nên đáp án đúng là 很冷.","options":["很冷","很热","很忙","很好"],"q":"杨同乐看病时，对胡医生说自己觉得怎么样？"},{"answerIdx":2,"explanation":"Trong bài, bác sĩ Hồ dặn \"吃一点儿药，今天休息半天吧。\" (Uống một chút thuốc, hôm nay nghỉ nửa ngày nhé.) và \"回家后再喝些热水。\" (Sau khi về nhà uống thêm chút nước nóng nữa.), nên đáp án đúng là 吃一点儿药，休息半天，回家后再喝些热水.","options":["去公司上班，多喝冷水","吃药，休息一天，去外边玩","吃一点儿药，休息半天，回家后再喝些热水","不吃药，在医院休息半天"],"q":"胡医生让杨同乐做什么？"}],"scene":"昨天在医院，医生给杨同乐看病。","sceneVi":"Hôm qua ở bệnh viện, bác sĩ khám bệnh cho Dương Đồng Nhạc."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (短文 tổng hợp)","lines":[{"hanzi":"王一飞那里的天不太好，下雨了，她觉得很冷。","pinyin":"Wáng Yīfēi nàlǐ de tiān bú tài hǎo, xià yǔ le, tā juéde hěn lěng.","speaker":"Đoạn văn","vi":"Trời bên chỗ Vương Nhất Phi không tốt lắm, trời mưa rồi, cô ấy cảm thấy rất lạnh."},{"hanzi":"王一雪这里昨天下雪了，天气太冷了。","pinyin":"Wáng Yīxuě zhèlǐ zuótiān xià xuě le, tiānqì tài lěng le.","speaker":"Đoạn văn","vi":"Bên chỗ Vương Nhất Tuyết hôm qua tuyết rơi rồi, thời tiết lạnh quá."},{"hanzi":"杨同乐昨天生病了，没来公司，他去医院看病了。","pinyin":"Yáng Tónglè zuótiān shēngbìng le, méi lái gōngsī, tā qù yīyuàn kànbìng le.","speaker":"Đoạn văn","vi":"Dương Đồng Nhạc hôm qua bị ốm, không đến công ty, anh ấy đã đi bệnh viện khám bệnh."},{"hanzi":"胡医生对杨同乐说，吃一点儿药，休息半天，回家后再喝些热水。","pinyin":"Hú yīshēng duì Yáng Tónglè shuō, chī yìdiǎnr yào, xiūxi bàn tiān, huí jiā hòu zài hē xiē rè shuǐ.","speaker":"Đoạn văn","vi":"Bác sĩ Hồ nói với Dương Đồng Nhạc uống một chút thuốc, nghỉ ngơi nửa ngày, sau khi về nhà hãy uống thêm chút nước ấm."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"王一飞那里的天不太好，下雨了\" (Thời tiết chỗ Vương Nhất Phi không tốt lắm, trời mưa) và \"王一雪这里昨天下雪了\" (Chỗ Vương Nhất Tuyết hôm qua có tuyết rơi), nên đáp án đúng là 王一飞那里下雨了，王一雪这里昨天下雪了.","options":["王一飞那里下雪了，王一雪这里下雨了","王一飞那里下雨了，王一雪这里昨天下雪了","两个地方都下雨了，都不冷","王一飞那里很热，王一雪这里很冷"],"q":"王一飞那里和王一雪这里的天气有什么不一样？"},{"answerIdx":2,"explanation":"Trong bài có câu \"胡医生对杨同乐说，吃一点儿药，休息半天，回家后再喝些热水。\" (Bác sĩ Hồ nói với Dương Đồng Nhạc: uống chút thuốc, nghỉ nửa ngày, sau khi về nhà uống thêm chút nước nóng.), nên đáp án đúng là 喝些热水.","options":["看电视","做饭","喝些热水","睡觉"],"q":"除了吃药和休息半天，胡医生还让杨同乐回家后做什么？"}],"scene":"课文一至三的故事总结。","sceneVi":"Tóm tắt câu chuyện của Bài khóa 1 đến 3."}],"hsk1-13":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"王老师，我可以再问您一个问题吗？","pinyin":"Wáng lǎoshī, wǒ kěyǐ zài wèn nín yí gè wèntí ma?","speaker":"白家月","vi":"Thưa cô Vương, em có thể hỏi cô thêm một câu hỏi nữa không ạ?"},{"hanzi":"可以。你有什么问题？","pinyin":"Kěyǐ. Nǐ yǒu shénme wèntí?","speaker":"王一飞","vi":"Được chứ. Em có câu hỏi gì?"},{"hanzi":"那个小店卖不卖手机？","pinyin":"Nàge xiǎo diàn mài bu mài shǒujī?","speaker":"白家月","vi":"Cửa hàng nhỏ kia có bán điện thoại di động không ạ?"},{"hanzi":"我不知道。你可以打电话问一下。","pinyin":"Wǒ bù zhīdào. Nǐ kěyǐ dǎ diànhuà wèn yíxià.","speaker":"王一飞","vi":"Cô không biết. Em có thể gọi điện thoại hỏi thử xem."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài có câu \"那个小店卖不卖手机？\" (\"Cửa hàng nhỏ kia có bán điện thoại không?\"), nên Bạch Gia Nguyệt đang hỏi cô Vương về việc cửa hàng nhỏ đó có bán điện thoại hay không.","options":["那个小店卖不卖手机","王老师的手机号码是多少","那个小店在哪里","王老师买不买手机"],"q":"白家月问王老师什么问题？"},{"answerIdx":2,"explanation":"Trong bài, cô Vương trả lời \"我不知道。你可以打电话问一下。\" (\"Tôi không biết. Em có thể gọi điện hỏi thử xem.\"), nên đáp án đúng là cô nói mình không biết và bảo Bạch Gia Nguyệt gọi điện hỏi thử.","options":["她说那个小店不卖手机。","她说她知道那个小店在哪里。","她说她不知道，让白家月打电话问一下。","她说她可以去小店帮白家月买手机。"],"q":"王老师怎么回答白家月的问题？"}],"scene":"在教室里，下课后，白家月问王老师问题。","sceneVi":"Trong phòng học, sau giờ tan học, Bạch Gia Nguyệt hỏi cô Vương một câu hỏi."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"女士，请坐！您喝什么？","pinyin":"Nǚshì, qǐng zuò! Nín hē shénme?","speaker":"服务员","vi":"Thưa quý cô, mời ngồi! Cô uống gì ạ?"},{"hanzi":"我看一下。请给我一杯牛奶。","pinyin":"Wǒ kàn yíxià. Qǐng gěi wǒ yì bēi niúnǎi.","speaker":"王一雪","vi":"Để tôi xem một chút. Làm ơn cho tôi một cốc sữa bò."},{"hanzi":"好的。您还要什么？","pinyin":"Hǎo de. Nín hái yào shénme?","speaker":"服务员","vi":"Vâng ạ. Cô còn muốn gọi thêm gì nữa không?"},{"hanzi":"我还没吃早饭，再要这个面包和鸡蛋吧。","pinyin":"Wǒ hái méi chī zǎofàn, zài yào zhège miànbāo hé jīdàn ba.","speaker":"王一雪","vi":"Tôi vẫn chưa ăn sáng, lấy thêm cái bánh mì và trứng gà này nhé."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"请给我一杯牛奶。\" (\"Làm ơn cho tôi một cốc sữa bò.\"), nên đồ uống Vương Nhất Tuyết muốn gọi là một cốc sữa bò.","options":["一杯茶","一杯牛奶","一杯咖啡","一杯水"],"q":"王一雪想喝什么？"},{"answerIdx":0,"explanation":"Trong bài có câu \"我还没吃早饭，再要这个面包和鸡蛋吧。\" (\"Tôi vẫn chưa ăn sáng, lấy thêm cái bánh mì này và trứng gà nữa nhé.\"), nên lý do là vì cô ấy chưa ăn sáng.","options":["因为她还没吃早饭。","因为她想给朋友买。","因为她最喜欢喝牛奶。","因为她晚上没吃饭。"],"q":"王一雪为什么还要面包和鸡蛋？"}],"scene":"在咖啡馆里，王一雪想吃早餐。","sceneVi":"Ở trong quán cà phê, Vương Nhất Tuyết muốn ăn bữa sáng."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"先生，请坐！您要什么？","pinyin":"Xiānsheng, qǐng zuò! Nín yào shénme?","speaker":"服务员","vi":"Thưa ông, mời ngồi! Ông muốn gọi gì ạ?"},{"hanzi":"我要一斤饺子。","pinyin":"Wǒ yào yì jīn jiǎozi.","speaker":"刘明","vi":"Tôi muốn một cân (nửa ký) sủi cảo."},{"hanzi":"好的。一斤饺子40个。","pinyin":"Hǎo de. Yì jīn jiǎozi sìshí gè.","speaker":"服务员","vi":"Vâng ạ. Một cân sủi cảo có 40 cái."},{"hanzi":"40个太多了，我要一半吧。","pinyin":"Sìshí gè tài duō le, wǒ yào yíbàn ba.","speaker":"刘明","vi":"40 cái nhiều quá rồi, tôi lấy một nửa thôi nhé."},{"hanzi":"半斤20个。您想喝什么？","pinyin":"Bàn jīn èrshí gè. Nín xiǎng hē shénme?","speaker":"服务员","vi":"Nửa cân là 20 cái. Ông muốn uống gì ạ?"},{"hanzi":"请给我一杯茶吧。","pinyin":"Qǐng gěi wǒ yì bēi chá ba.","speaker":"刘明","vi":"Làm ơn cho tôi một tách trà nhé."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"40个太多了，我要一半吧。\" (\"40 cái nhiều quá, tôi lấy một nửa thôi.\") và người phục vụ xác nhận \"半斤20个。\" (\"Nửa cân là 20 cái.\"), nên cuối cùng Lưu Minh gọi 20 cái sủi cảo.","options":["十个","二十个","三十个","四十个"],"q":"刘明最后要了多少个饺子？"},{"answerIdx":0,"explanation":"Khi được hỏi \"您想喝什么？\" (\"Anh muốn uống gì?\"), Lưu Minh trả lời \"请给我一杯茶吧。\" (\"Làm ơn cho tôi một cốc trà nhé.\"), nên ngoài sủi cảo anh ấy gọi thêm một cốc trà.","options":["一杯茶","一杯牛奶","一杯咖啡","一点儿水"],"q":"除了饺子，刘明还想喝什么？"}],"scene":"在餐馆里，刘明在点餐。","sceneVi":"Ở trong nhà hàng, Lưu Minh đang gọi món."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (短文 tổng hợp)","lines":[{"hanzi":"下课后，白家月问王老师那个小店卖不卖手机，王老师不知道，她说白家月可以打电话问一下。","pinyin":"Xiàkè hòu, Bái Jiāyuè wèn Wáng lǎoshī nàge xiǎo diàn mài bu mài shǒujī, Wáng lǎoshī bù zhīdào, tā shuō Bái Jiāyuè kěyǐ dǎ diànhuà wèn yíxià.","speaker":"Đoạn văn","vi":"Sau giờ tan học, Bạch Gia Nguyệt hỏi cô Vương xem cửa hàng nhỏ kia có bán điện thoại không, cô Vương không biết và bảo Bạch Gia Nguyệt có thể gọi điện hỏi thử."},{"hanzi":"在咖啡馆里，王一雪还没吃早饭，她要一杯牛奶，再要这个面包和鸡蛋。","pinyin":"Zài kāfēiguǎn lǐ, Wáng Yīxuě hái méi chī zǎofàn, tā yào yì bēi niúnǎi, zài yào zhège miànbāo hé jīdàn.","speaker":"Đoạn văn","vi":"Ở quán cà phê, Vương Nhất Tuyết vẫn chưa ăn sáng, cô gọi một cốc sữa bò, rồi gọi thêm bánh mì và trứng gà."},{"hanzi":"在餐馆里，一斤饺子40个太多了，刘明要一半，再要一杯茶。","pinyin":"Zài cānguǎn lǐ, yì jīn jiǎozi sìshí gè tài duō le, Liú Míng yào yíbàn, zài yào yì bēi chá.","speaker":"Đoạn văn","vi":"Ở nhà hàng, một cân sủi cảo 40 cái nhiều quá, Lưu Minh gọi một nửa, rồi gọi thêm một tách trà."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu \"在咖啡馆里，王一雪还没吃早饭，她要一杯牛奶，再要这个面包和鸡蛋。\" (\"Ở quán cà phê, Vương Nhất Tuyết vẫn chưa ăn sáng, cô gọi một cốc sữa bò, lấy thêm bánh mì này và trứng gà.\"), nên đáp án đúng là một cốc sữa bò, bánh mì và trứng gà.","options":["一杯茶和饺子","一杯牛奶和饺子","一杯牛奶、面包和鸡蛋","一杯咖啡、面包和鸡蛋"],"q":"在咖啡馆里，王一雪要了什么？"},{"answerIdx":2,"explanation":"Trong bài có câu \"在餐馆里，一斤饺子40个太多了，刘明要一半，再要一杯茶。\" (\"Ở nhà hàng, một cân sủi cảo 40 cái nhiều quá, Lưu Minh lấy một nửa, gọi thêm một cốc trà.\"), nên lý do anh ấy chỉ gọi một nửa là vì 40 cái quá nhiều.","options":["因为他不爱吃饺子。","因为他想喝茶，不想吃东西。","因为四十个太多了。","因为餐馆里只有二十个饺子。"],"q":"刘明为什么只要一半饺子？"}],"scene":"总结第13课的三篇课文。","sceneVi":"Tóm tắt ba bài khóa của Bài 13."}],"hsk1-14":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"你们上火车后看见王老师了吗？","pinyin":"Nǐmen shàng huǒchē hòu kànjiàn Wáng lǎoshī le ma?","speaker":"白家月","vi":"Sau khi lên tàu hỏa, các bạn có nhìn thấy cô Vương không?"},{"hanzi":"没看见。中午车开后，有些人在看书，有些人睡觉了。","pinyin":"Méi kànjiàn. Zhōngwǔ chē kāi hòu, yǒuxiē rén zài kàn shū, yǒuxiē rén shuìjiào le.","speaker":"陈天中","vi":"Không thấy. Buổi trưa sau khi tàu chạy, một số người đang đọc sách, một số người đi ngủ rồi."},{"hanzi":"你呢？","pinyin":"Nǐ ne?","speaker":"白家月","vi":"Còn bạn thì sao?"},{"hanzi":"我看了一个电影。","pinyin":"Wǒ kànle yí gè diànyǐng.","speaker":"陈天中","vi":"Tôi đã xem một bộ phim."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài, khi Bạch Gia Nguyệt hỏi \"你们上火车后看见王老师了吗？\" (\"Sau khi lên tàu hỏa các cậu có nhìn thấy cô Vương không?\"), Trần Thiên Trung đáp \"没看见。\" (\"Không thấy.\"), nên đáp án đúng là không nhìn thấy.","options":["看见了，王老师在看书。","看见了，王老师在睡觉。","没看见。","看见了，王老师在看电影。"],"q":"上火车后，陈天中看见王老师了吗？"},{"answerIdx":1,"explanation":"Trong bài có câu \"我看了一个电影。\" (\"Mình đã xem một bộ phim.\"), nên sau khi tàu chạy vào buổi trưa, Trần Thiên Trung đã xem một bộ phim.","options":["他在看书。","他看了一个电影。","他睡觉了。","他和王老师说话。"],"q":"中午车开后，陈天中在火车上做什么？"}],"scene":"在教室里，下课后，白家月和陈天中在谈论上一次课外旅行。","sceneVi":"Trong phòng học, sau giờ tan học, Bạch Gia Nguyệt và Trần Thiên Trung đang nói chuyện về chuyến đi ngoại khóa lần trước."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"你们会说汉语了，也会写汉字了吗？","pinyin":"Nǐmen huì shuō Hànyǔ le, yě huì xiě Hànzì le ma?","speaker":"王一飞","vi":"Các em đã biết nói tiếng Hán rồi, cũng biết viết chữ Hán rồi chứ?"},{"hanzi":"我们都会写了。","pinyin":"Wǒmen dōu huì xiě le.","speaker":"白家月","vi":"Chúng em đều biết viết rồi ạ."},{"hanzi":"老师，我听不见。","pinyin":"Lǎoshī, wǒ tīng bú jiàn.","speaker":"陈天中","vi":"Thưa cô, em không nghe rõ ạ."},{"hanzi":"请大家不要说话！请听老师的问题：你们都会写哪些汉字了？","pinyin":"Qǐng dàjiā búyào shuōhuà! Qǐng tīng lǎoshī de wèntí: Nǐmen dōu huì xiě nǎxiē Hànzì le?","speaker":"王一飞","vi":"Mọi người đừng nói chuyện nữa! Hãy nghe câu hỏi của cô: Các em đều đã biết viết những chữ Hán nào rồi?"},{"hanzi":"我会写这些字了，您看！","pinyin":"Wǒ huì xiě zhèxiē zì le, nín kàn!","speaker":"陈天中","vi":"Em biết viết những chữ này rồi, cô xem ạ!"}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"老师，我听不见。\" (\"Thưa cô, em không nghe thấy ạ.\") và ngay sau đó cô Vương nói \"请大家不要说话！请听老师的问题\" (\"Mời cả lớp đừng nói chuyện! Hãy nghe câu hỏi của cô\"), nên cô nhắc cả lớp giữ trật tự là vì Trần Thiên Trung không nghe rõ.","options":["因为要下课了。","因为陈天中听不见老师的问题。","因为白家月想睡觉。","因为大家不会说汉语。"],"q":"王老师为什么请大家不要说话？"},{"answerIdx":0,"explanation":"Ở cuối bài khóa, Trần Thiên Trung nói \"我会写这些字了，您看！\" (\"Em biết viết những chữ này rồi, cô xem ạ!\"), chứng tỏ bạn ấy đã biết viết một số chữ Hán.","options":["会写一些字了。","还不会写。","他听不见，所以没写。","他只会说汉语，不会写字。"],"q":"最后，陈天中会写汉字了吗？"}],"scene":"在课堂上，王一飞询问学生们的学习情况。","sceneVi":"Trong giờ học trên lớp, Vương Nhất Phi hỏi thăm tình hình học tập của các học sinh."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"明年女儿上中学。","pinyin":"Míngnián nǚ'ér shàng zhōngxué.","speaker":"刘明","vi":"Sang năm con gái lên cấp hai (trung học)."},{"hanzi":"对。儿子也上小学了。","pinyin":"Duì. Érzi yě shàng xiǎoxué le.","speaker":"王一雪","vi":"Đúng vậy. Con trai cũng vào tiểu học rồi."},{"hanzi":"我们家有了一个中学生。","pinyin":"Wǒmen jiā yǒule yí gè zhōngxuéshēng.","speaker":"刘明","vi":"Nhà mình có một học sinh trung học rồi."},{"hanzi":"还有了一个小学生。","pinyin":"Hái yǒule yí gè xiǎoxuéshēng.","speaker":"王一雪","vi":"Còn có thêm một học sinh tiểu học nữa."},{"hanzi":"上学后，他们都忙了。","pinyin":"Shàngxué hòu, tāmen dōu máng le.","speaker":"刘明","vi":"Sau khi đi học, chúng đều bận rộn cả rồi."},{"hanzi":"是的。太晚了，睡觉吧。","pinyin":"Shì de. Tài wǎn le, shuìjiào ba.","speaker":"王一雪","vi":"Phải đấy. Muộn quá rồi, đi ngủ thôi."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có hai câu \"明年女儿上中学。\" (\"Sang năm con gái lên cấp hai.\") và \"儿子也上小学了。\" (\"Con trai cũng vào tiểu học rồi.\"), nên con gái học trung học và con trai học tiểu học.","options":["女儿上小学，儿子上中学。","女儿上中学，儿子上小学。","女儿和儿子都上中学。","女儿和儿子都上小学。"],"q":"明年他们的女儿和儿子上什么学校？"},{"answerIdx":0,"explanation":"Trong bài có câu \"上学后，他们都忙了。\" (\"Sau khi đi học, bọn trẻ đều bận rộn cả rồi.\"), nên Lưu Minh nhận xét rằng sau khi đi học các con đều trở nên bận rộn.","options":["他们都很忙。","他们都爱睡觉。","他们不说话了。","他们去坐火车。"],"q":"刘明说孩子们上学后怎么样？"}],"scene":"在家里，刘明和王一雪在谈论孩子的升学情况。","sceneVi":"Ở nhà, Lưu Minh và Vương Nhất Tuyết đang bàn về việc lên lớp chuyển cấp của các con."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (短文 tổng hợp)","lines":[{"hanzi":"上火车后，陈天中没看见王老师，中午车开后，他看了一个电影。","pinyin":"Shàng huǒchē hòu, Chén Tiānzhōng méi kànjiàn Wáng lǎoshī, zhōngwǔ chē kāi hòu, tā kànle yí gè diànyǐng.","speaker":"Đoạn văn","vi":"Sau khi lên tàu hỏa, Trần Thiên Trung không nhìn thấy cô Vương, buổi trưa sau khi tàu chạy, cậu ấy đã xem một bộ phim."},{"hanzi":"在课堂上，同学们都会说汉语、写汉字了，陈天中也写了一些字给王老师看。","pinyin":"Zài kètáng shàng, tóngxuémen dōu huì shuō Hànyǔ, xiě Hànzì le, Chén Tiānzhōng yě xiěle yìxiē zì gěi Wáng lǎoshī kàn.","speaker":"Đoạn văn","vi":"Trên lớp học, các bạn học đều đã biết nói tiếng Hán, viết chữ Hán, Trần Thiên Trung cũng viết một số chữ cho cô Vương xem."},{"hanzi":"明年刘明和王一雪的女儿上中学、儿子上小学了，上学后孩子们都忙了。","pinyin":"Míngnián Liú Míng hé Wáng Yīxuě de nǚ'ér shàng zhōngxué, érzi shàng xiǎoxué le, shàngxué hòu háizimen dōu máng le.","speaker":"Đoạn văn","vi":"Sang năm con gái của Lưu Minh và Vương Nhất Tuyết lên trung học, con trai vào tiểu học, sau khi đi học bọn trẻ đều bận rộn cả."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"上火车后，陈天中没看见王老师，中午车开后，他看了一个电影。\" (\"Sau khi lên tàu hỏa, Trần Thiên Trung không nhìn thấy cô Vương; sau khi tàu chạy vào buổi trưa, cậu ấy đã xem một bộ phim.\"), nên thời điểm xem phim là sau khi tàu chạy vào buổi trưa.","options":["上午上课的时候","中午火车开后","晚上睡觉前","下课后在教室里"],"q":"陈天中是什么时候看电影的？"},{"answerIdx":0,"explanation":"Trong bài có câu \"在课堂上，同学们都会说汉语、写汉字了，陈天中也写了一些字给王老师看。\" (\"Trên lớp, các bạn học đều đã biết nói tiếng Hán và viết chữ Hán, Trần Thiên Trung cũng viết một số chữ cho cô Vương xem.\"), nên đáp án đúng là cả lớp đều biết nói tiếng Hán và viết chữ Hán.","options":["都会说汉语，也会写汉字了。","只会说汉语，还不会写汉字。","只有白家月会写汉字。","陈天中没有写汉字。"],"q":"同学们在课堂上的汉语学习情况怎么样？"}],"scene":"总结第14课的三篇课文。","sceneVi":"Tóm tắt ba bài khóa của Bài 14."}],"hsk1-15":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"你们爱吃哪个菜？","pinyin":"Nǐmen ài chī nǎge cài?","speaker":"李文","vi":"Các bạn thích ăn món nào?"},{"hanzi":"我喜欢这个，也喜欢那个。","pinyin":"Wǒ xǐhuan zhège, yě xǐhuan nàge.","speaker":"白家月","vi":"Tôi thích món này, cũng thích món kia."},{"hanzi":"这些菜都好吃，还很好看。","pinyin":"Zhèxiē cài dōu hǎochī, hái hěn hǎokàn.","speaker":"陈天中","vi":"Những món này đều ngon, lại còn rất đẹp mắt."},{"hanzi":"我爱吃中国菜，也喜欢做。大家多吃点儿。","pinyin":"Wǒ ài chī Zhōngguó cài, yě xǐhuan zuò. Dàjiā duō chī diǎnr.","speaker":"李文","vi":"Tôi thích ăn món Trung Quốc, cũng thích nấu nữa. Mọi người ăn nhiều một chút nhé."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu \"这些菜都好吃，还很好看。\" (\"Những món này đều ngon, lại còn rất đẹp mắt nữa.\"), nên Trần Thiên Trung khen các món ăn vừa ngon vừa đẹp mắt.","options":["太辣了，不好吃。","只有一点儿好看。","都好吃，还很好看。","不太好看，但是很好吃。"],"q":"陈天中觉得这些菜怎么样？"},{"answerIdx":2,"explanation":"Trong bài có câu \"我爱吃中国菜，也喜欢做。\" (\"Mình thích ăn món Trung Quốc, cũng thích nấu nữa.\"), nên thông tin đúng về Lý Văn là anh ấy vừa thích ăn vừa thích nấu món Trung Quốc.","options":["他不爱吃中国菜。","他只会吃，不会做中国菜。","他爱吃中国菜，也喜欢做。","他请朋友去餐馆吃饭。"],"q":"关于李文，下面哪句话是对的？"}],"scene":"在李文家，李文邀请陈天中、白家月等朋友品尝中餐。","sceneVi":"Tại nhà Lý Văn, Lý Văn mời các bạn như Trần Thiên Trung, Bạch Gia Nguyệt thưởng thức món ăn Trung Quốc."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"你们都想去哪儿？","pinyin":"Nǐmen dōu xiǎng qù nǎr?","speaker":"李文","vi":"Các bạn đều muốn đi đâu?"},{"hanzi":"去年我和男朋友去了西安，今年我想去北京。","pinyin":"Qùnián wǒ hé nánpéngyou qùle Xī'ān, jīnnián wǒ xiǎng qù Běijīng.","speaker":"安妮","vi":"Năm ngoái tôi và bạn trai đã đi Tây An, năm nay tôi muốn đi Bắc Kinh."},{"hanzi":"前几年我去了西安，非常好玩儿。今年我也想去北京。","pinyin":"Qián jǐ nián wǒ qùle Xī'ān, fēicháng hǎowánr. Jīnnián wǒ yě xiǎng qù Běijīng.","speaker":"白家月","vi":"Mấy năm trước tôi đã đi Tây An, rất thú vị. Năm nay tôi cũng muốn đi Bắc Kinh."},{"hanzi":"我和王老师都是北京人，北京非常漂亮。","pinyin":"Wǒ hé Wáng lǎoshī dōu shì Běijīng rén, Běijīng fēicháng piàoliang.","speaker":"李文","vi":"Tôi và cô Vương đều là người Bắc Kinh, Bắc Kinh vô cùng xinh đẹp."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, An Ni nói \"去年我和男朋友去了西安，今年我想去北京。\" (\"Năm ngoái mình và bạn trai đã đi Tây An, năm nay mình muốn đi Bắc Kinh.\"), nên năm ngoái An Ni đã cùng bạn trai đi Tây An.","options":["她和男朋友去了北京。","她和男朋友去了西安。","她和白家月去了西安。","她和王老师去了北京。"],"q":"去年安妮做什么了？"},{"answerIdx":0,"explanation":"Trong bài, Lý Văn nói \"我和王老师都是北京人，北京非常漂亮。\" (\"Mình và cô Vương đều là người Bắc Kinh, Bắc Kinh rất đẹp.\"), nên người Bắc Kinh là Lý Văn và cô Vương.","options":["李文和王老师","安妮和白家月","李文和安妮","白家月和王老师"],"q":"谁是北京人？"}],"scene":"在李文家，大家边吃饭边谈论假期计划。","sceneVi":"Tại nhà Lý Văn, mọi người vừa ăn cơm vừa bàn luận về kế hoạch kỳ nghỉ."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"你们的飞机到北京要几个小时？","pinyin":"Nǐmen de fēijī dào Běijīng yào jǐ gè xiǎoshí?","speaker":"王一飞","vi":"Chuyến bay của các em đến Bắc Kinh mất mấy tiếng?"},{"hanzi":"九个小时。","pinyin":"Jiǔ gè xiǎoshí.","speaker":"白家月","vi":"Chín tiếng ạ."},{"hanzi":"我家人都在北京，星期天我姐姐也有时间，她可以去机场接你们，你们也可以住我家。","pinyin":"Wǒ jiārén dōu zài Běijīng, Xīngqītiān wǒ jiějie yě yǒu shíjiān, tā kěyǐ qù jīchǎng jiē nǐmen, nǐmen yě kěyǐ zhù wǒ jiā.","speaker":"王一飞","vi":"Người nhà cô đều ở Bắc Kinh, Chủ nhật chị gái cô cũng có thời gian, chị ấy có thể ra sân bay đón các em, các em cũng có thể ở nhà cô."},{"hanzi":"我们星期日早上八点到大兴机场，早不早？","pinyin":"Wǒmen Xīngqīrì zǎoshang bā diǎn dào Dàxīng Jīchǎng, zǎo bu zǎo?","speaker":"安妮","vi":"Sáng Chủ nhật 8 giờ bọn em đến sân bay Đại Hưng, có sớm quá không ạ?"},{"hanzi":"不早。","pinyin":"Bù zǎo.","speaker":"王一飞","vi":"Không sớm đâu."},{"hanzi":"谢谢老师！那我们和您姐姐在大兴机场见！","pinyin":"Xièxie lǎoshī! Nà wǒmen hé nín jiějie zài Dàxīng Jīchǎng jiàn!","speaker":"白家月","vi":"Em cảm ơn cô ạ! Vậy bọn em hẹn gặp chị gái cô ở sân bay Đại Hưng nhé!"}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"星期天我姐姐也有时间，她可以去机场接你们\" (\"Chủ nhật chị gái cô cũng rảnh, chị ấy có thể ra sân bay đón các em\"), nên người ra sân bay đón là chị gái của cô Vương.","options":["王老师","王老师的姐姐","李文","安妮的男朋友"],"q":"星期天谁可以去机场接白家月和安妮？"},{"answerIdx":1,"explanation":"Trong bài có câu \"九个小时。\" (\"Chín tiếng.\") và \"我们星期日早上八点到大兴机场\" (\"Chúng em đến sân bay Đại Hưng vào lúc 8 giờ sáng Chủ nhật\"), nên chuyến bay mất 9 tiếng và đến nơi lúc 8 giờ sáng Chủ nhật.","options":["要八个小时，星期天早上九点到。","要九个小时，星期天早上八点到。","要九个小时，星期六早上八点到。","要八个小时，星期天晚上八点到。"],"q":"她们坐飞机去北京要几个小时，什么时候到？"}],"scene":"在教室外，白家月、安妮和王老师在谈论去北京旅游的事。","sceneVi":"Ngoài phòng học, Bạch Gia Nguyệt, An Ni và cô Vương đang nói chuyện về việc đi du lịch Bắc Kinh."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (短文 tổng hợp)","lines":[{"hanzi":"李文爱吃中国菜，也喜欢做，陈天中和白家月觉得这些菜都好吃，还很好看。","pinyin":"Lǐ Wén ài chī Zhōngguó cài, yě xǐhuan zuò, Chén Tiānzhōng hé Bái Jiāyuè juéde zhèxiē cài dōu hǎochī, hái hěn hǎokàn.","speaker":"Đoạn văn","vi":"Lý Văn thích ăn món Trung Quốc và cũng thích nấu, Trần Thiên Trung và Bạch Gia Nguyệt thấy những món này đều ngon, lại còn rất đẹp mắt."},{"hanzi":"去年安妮和男朋友去了西安，前几年白家月也去了西安，今年她们都想去北京。","pinyin":"Qùnián Ānnī hé nánpéngyou qùle Xī'ān, qián jǐ nián Bái Jiāyuè yě qùle Xī'ān, jīnnián tāmen dōu xiǎng qù Běijīng.","speaker":"Đoạn văn","vi":"Năm ngoái An Ni và bạn trai đã đi Tây An, mấy năm trước Bạch Gia Nguyệt cũng đã đi Tây An, năm nay hai bạn đều muốn đi Bắc Kinh."},{"hanzi":"李文和王老师都是北京人，王老师的家人都在北京。","pinyin":"Lǐ Wén hé Wáng lǎoshī dōu shì Běijīng rén, Wáng lǎoshī de jiārén dōu zài Běijīng.","speaker":"Đoạn văn","vi":"Lý Văn và cô Vương đều là người Bắc Kinh, người nhà của cô Vương đều ở Bắc Kinh."},{"hanzi":"安妮和白家月坐飞机去北京要九个小时，星期天早上八点到大兴机场，王老师的姐姐可以去机场接她们，她们也可以住王老师家。","pinyin":"Ānnī hé Bái Jiāyuè zuò fēijī qù Běijīng yào jiǔ gè xiǎoshí, Xīngqītiān zǎoshang bā diǎn dào Dàxīng Jīchǎng, Wáng lǎoshī de jiějie kěyǐ qù jīchǎng jiē tāmen, tāmen yě kěyǐ zhù Wáng lǎoshī jiā.","speaker":"Đoạn văn","vi":"An Ni và Bạch Gia Nguyệt đi máy bay đến Bắc Kinh mất chín tiếng, 8 giờ sáng Chủ nhật đến sân bay Đại Hưng, chị gái của cô Vương có thể ra sân bay đón họ, họ cũng có thể ở nhà cô Vương."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu \"去年安妮和男朋友去了西安，前几年白家月也去了西安，今年她们都想去北京。\" (\"Năm ngoái An Ni và bạn trai đã đi Tây An, mấy năm trước Bạch Gia Nguyệt cũng từng đi Tây An, năm nay hai cô ấy đều muốn đi Bắc Kinh.\"), nên điểm chung là cả hai đều từng đi Tây An và năm nay đều muốn đi Bắc Kinh.","options":["她们去年一起去了西安。","她们今年都想去西安。","她们都去过西安，今年都想去北京。","她们都是北京人。"],"q":"关于安妮和白家月，下面哪句话是对的？"},{"answerIdx":1,"explanation":"Trong bài có câu \"王老师的姐姐可以去机场接她们，她们也可以住王老师家。\" (\"Chị gái của cô Vương có thể ra sân bay đón họ, và họ cũng có thể ở nhà cô Vương.\"), nên gia đình cô Vương giúp đón ở sân bay và cho ở nhờ tại nhà.","options":["给她们做中国菜和买机票。","王老师的姐姐可以去机场接她们，她们也可以住王老师家。","王老师自己去机场接她们，还带她们去西安。","带她们去咖啡馆吃早饭。"],"q":"她们到北京后，王老师的家人可以帮她们做什么？"}],"scene":"总结李文、陈天中、白家月、安妮和王老师的故事。","sceneVi":"Tóm tắt câu chuyện của Lý Văn, Trần Thiên Trung, Bạch Gia Nguyệt, An Ni và cô Vương."}],"hsk2-1":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"请问，您是王一飞老师的姐姐吗？","pinyin":"Qǐngwèn, nín shì Wáng Yīfēi lǎoshī de jiějie ma?","speaker":"白家月","vi":"Xin hỏi, chị có phải là chị gái của cô giáo Vương Nhất Phi không ạ?"},{"hanzi":"是的，你们就是她的学生吧？","pinyin":"Shì de, nǐmen jiù shì tā de xuéshēng ba?","speaker":"王一雪","vi":"Đúng rồi, các em chính là học sinh của cô ấy phải không?"},{"hanzi":"对。我是白家月，她是安妮。","pinyin":"Duì. Wǒ shì Bái Jiāyuè, tā shì Ānnī.","speaker":"白家月","vi":"Vâng. Em là Bạch Gia Nguyệt, còn bạn ấy là An Ni."},{"hanzi":"你们好，我叫王一雪。一飞给我打电话了，让我来接你们。","pinyin":"Nǐmen hǎo, wǒ jiào Wáng Yīxuě. Yīfēi gěi wǒ dǎ diànhuà le, ràng wǒ lái jiē nǐmen.","speaker":"王一雪","vi":"Chào các em, chị tên là Vương Nhất Tuyết. Nhất Phi đã gọi điện cho chị, bảo chị đến đón các em."},{"hanzi":"谢谢您。","pinyin":"Xièxie nín.","speaker":"白家月、安妮","vi":"Cảm ơn chị ạ."},{"hanzi":"不客气。","pinyin":"Bú kèqi.","speaker":"王一雪","vi":"Không có gì."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Bạch Gia Nguyệt hỏi \"您是王一飞老师的姐姐吗？\" (\"Chị có phải là chị gái của cô giáo Vương Nhất Phi không?\") và chị ấy xác nhận \"是的\" (\"Đúng rồi\"), đồng thời giới thiệu \"我叫王一雪\" (\"Tôi tên là Vương Nhất Tuyết\"), nên người đón là Vương Nhất Tuyết – chị gái cô giáo Vương Nhất Phi.","options":["王一飞老师","王一雪，王一飞老师的姐姐","李文的朋友","陈天中"],"q":"在机场是谁接了白家月和安妮？"},{"answerIdx":1,"explanation":"Trong bài có câu \"一飞给我打电话了，让我来接你们。\" (\"Nhất Phi đã gọi điện cho tôi, bảo tôi đến đón các bạn.\"), nên lý do là vì Vương Nhất Phi đã gọi điện nhờ chị gái ra đón.","options":["因为她正好也要坐飞机。","因为王一飞给她打电话，让她来接她们。","因为白家月昨天给她发了信息。","因为她和安妮是老朋友。"],"q":"王一雪为什么来机场接她们？"}],"scene":"在机场，王一雪接到了白家月和安妮。","sceneVi":"Ở sân bay, Vương Nhất Tuyết đã đón được Bạch Gia Nguyệt và An Ni."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"你们是第一次来北京吗？","pinyin":"Nǐmen shì dì-yī cì lái Běijīng ma?","speaker":"王一雪","vi":"Đây là lần đầu tiên các em đến Bắc Kinh à?"},{"hanzi":"是的，我们都是第一次来。","pinyin":"Shì de, wǒmen dōu shì dì-yī cì lái.","speaker":"白家月","vi":"Vâng, chúng em đều là lần đầu tiên đến ạ."},{"hanzi":"你们是来学中文的吗？","pinyin":"Nǐmen shì lái xué Zhōngwén de ma?","speaker":"王一雪","vi":"Các em đến đây để học tiếng Trung phải không?"},{"hanzi":"不是，我们是来旅游的。","pinyin":"Bú shì, wǒmen shì lái lǚyóu de.","speaker":"安妮","vi":"Không phải ạ, chúng em đến để du lịch."},{"hanzi":"我这几天都不忙，你们有事就找我。","pinyin":"Wǒ zhè jǐ tiān dōu bù máng, nǐmen yǒu shì jiù zhǎo wǒ.","speaker":"王一雪","vi":"Mấy ngày nay chị đều không bận, các em có việc gì thì cứ tìm chị nhé."},{"hanzi":"好的，谢谢您。","pinyin":"Hǎo de, xièxie nín.","speaker":"白家月","vi":"Vâng ạ, cảm ơn chị."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, khi được hỏi \"你们是来学中文的吗？\" (\"Các bạn đến để học tiếng Trung à?\"), An Ni đáp \"不是，我们是来旅游的。\" (\"Không phải, chúng em đến để du lịch ạ.\"), nên mục đích đến Bắc Kinh là để du lịch.","options":["她们是来学中文的。","她们是来旅游的。","她们是来工作的。","她们是来教中文的。"],"q":"白家月和安妮这次来北京做什么？"},{"answerIdx":2,"explanation":"Trong bài có câu \"我这几天都不忙，你们有事就找我。\" (\"Mấy ngày nay chị đều không bận, các em có việc gì thì cứ tìm chị.\"), nên mấy ngày tới chị ấy đều rảnh và sẵn sàng giúp đỡ.","options":["很忙，没有时间。","只有今天不忙。","这几天都不忙，她们有事可以找她。","太忙了，不能去旅游。"],"q":"王一雪这几天忙不忙？"}],"scene":"在王一雪的车里，白家月、安妮和王一雪在聊天儿。","sceneVi":"Trong xe của Vương Nhất Tuyết, Bạch Gia Nguyệt, An Ni và Vương Nhất Tuyết đang trò chuyện."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"喂，家月，你明天有时间吗？我想请你帮个忙。","pinyin":"Wèi, Jiāyuè, nǐ míngtiān yǒu shíjiān ma? Wǒ xiǎng qǐng nǐ bāng ge máng.","speaker":"陈天中","vi":"Alo, Gia Nguyệt à, ngày mai cậu có rảnh không? Mình muốn nhờ cậu giúp một việc."},{"hanzi":"不好意思，天中，我已经到北京了。","pinyin":"Bù hǎoyìsi, Tiānzhōng, wǒ yǐjīng dào Běijīng le.","speaker":"白家月","vi":"Xin lỗi nhé Thiên Trung, mình đã đến Bắc Kinh rồi."},{"hanzi":"你是什么时候到的？","pinyin":"Nǐ shì shénme shíhou dào de?","speaker":"陈天中","vi":"Cậu đến vào lúc nào thế?"},{"hanzi":"我是今天早上到的。你有事可以叫李文帮忙，他还在学校呢。","pinyin":"Wǒ shì jīntiān zǎoshang dào de. Nǐ yǒu shì kěyǐ jiào Lǐ Wén bāngmáng, tā hái zài xuéxiào ne.","speaker":"白家月","vi":"Mình đến vào sáng nay. Cậu có việc thì có thể bảo Lý Văn giúp, cậu ấy vẫn còn ở trường đấy."},{"hanzi":"好的，那我给他打个电话。","pinyin":"Hǎo de, nà wǒ gěi tā dǎ ge diànhuà.","speaker":"陈天中","vi":"Được rồi, vậy để mình gọi điện cho cậu ấy."},{"hanzi":"好，再见！","pinyin":"Hǎo, zàijiàn!","speaker":"白家月","vi":"Ừ, tạm biệt!"}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"我是今天早上到的。\" (\"Mình đến vào sáng nay.\"), nên Bạch Gia Nguyệt đã đến Bắc Kinh vào sáng hôm nay.","options":["昨天晚上","今天早上","今天中午","明天早上"],"q":"白家月是什么时候到北京的？"},{"answerIdx":3,"explanation":"Trong bài có câu \"你有事可以叫李文帮忙，他还在学校呢。\" (\"Cậu có việc thì có thể nhờ Lý Văn giúp, cậu ấy vẫn đang ở trường đấy.\"), nên Bạch Gia Nguyệt khuyên Trần Thiên Trung gọi cho Lý Văn.","options":["王老师","安妮","王一雪","李文"],"q":"因为自己不在学校，白家月叫陈天中找谁帮忙？"}],"scene":"在王一雪的车上，白家月接了个电话。","sceneVi":"Trên xe của Vương Nhất Tuyết, Bạch Gia Nguyệt nhận được một cuộc điện thoại."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"王老师，我们已经到北京了，是您姐姐来接的我们。","pinyin":"Wáng lǎoshī, wǒmen yǐjīng dào Běijīng le, shì nín jiějie lái jiē de wǒmen.","speaker":"Đoạn văn","vi":"Cô Vương ơi, chúng em đã đến Bắc Kinh rồi ạ, chính chị gái của cô đã đến đón chúng em."},{"hanzi":"她请我们吃了北京烤鸭，还给我们介绍了很多东西。","pinyin":"Tā qǐng wǒmen chīle Běijīng Kǎoyā, hái gěi wǒmen jièshàole hěn duō dōngxi.","speaker":"Đoạn văn","vi":"Chị ấy đã mời chúng em ăn vịt quay Bắc Kinh, còn giới thiệu cho chúng em rất nhiều thứ nữa."},{"hanzi":"我们的中文不太好，有时不太懂她的意思。","pinyin":"Wǒmen de Zhōngwén bú tài hǎo, yǒushí bú tài dǒng tā de yìsi.","speaker":"Đoạn văn","vi":"Tiếng Trung của chúng em chưa tốt lắm, đôi khi không hiểu rõ ý của chị ấy."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài có câu \"是您姐姐来接的我们。她请我们吃了北京烤鸭，还给我们介绍了很多东西。\" (\"Chính chị gái cô đã đến đón chúng em. Chị ấy mời chúng em ăn vịt quay Bắc Kinh, lại còn giới thiệu cho chúng em rất nhiều thứ.\"), nên đáp án đúng là đón họ, mời ăn vịt quay Bắc Kinh và giới thiệu nhiều thứ.","options":["来接她们，请吃北京烤鸭，还介绍了很多东西。","带她们去了酒店，教她们写汉字。","请她们喝了咖啡，吃了面包和鸡蛋。","带她们坐火车去西安旅游。"],"q":"王老师的姐姐为她们做了什么？"},{"answerIdx":2,"explanation":"Trong bài có câu \"我们的中文不太好，有时不太懂她的意思。\" (\"Tiếng Trung của chúng em chưa tốt lắm, đôi khi không hiểu rõ ý của chị ấy.\"), nên nguyên nhân là do tiếng Trung của họ chưa tốt lắm.","options":["因为王老师的姐姐说话太快了。","因为她们刚下飞机，太累了。","因为她们的中文不太好。","因为车里声音太大，听不见。"],"q":"她们为什么有时不太懂王老师姐姐的意思？"}],"scene":"在酒店，白家月给王一飞发信息。","sceneVi":"Ở khách sạn, Bạch Gia Nguyệt nhắn tin cho Vương Nhất Phi."}],"hsk2-2":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"请问，这儿有到北京大学的公交车吗？","pinyin":"Qǐngwèn, zhèr yǒu dào Běijīng Dàxué de gōngjiāochē ma?","speaker":"白家月","vi":"Xin hỏi, ở đây có xe buýt đi đến Đại học Bắc Kinh không ạ?"},{"hanzi":"有，但车站有点儿远。","pinyin":"Yǒu, dàn chēzhàn yǒudiǎnr yuǎn.","speaker":"服务员","vi":"Có ạ, nhưng trạm xe hơi xa một chút."},{"hanzi":"这儿好打车吗？","pinyin":"Zhèr hǎo dǎchē ma?","speaker":"白家月","vi":"Ở đây có dễ bắt taxi không ạ?"},{"hanzi":"好打车。","pinyin":"Hǎo dǎchē.","speaker":"服务员","vi":"Dễ bắt taxi lắm ạ."},{"hanzi":"谢谢。安妮，我们还是打车去吧。","pinyin":"Xièxie. Ānnī, wǒmen háishi dǎchē qù ba.","speaker":"白家月","vi":"Cảm ơn chị. An Ni à, hay là bọn mình bắt taxi đi nhé."},{"hanzi":"好，没问题。","pinyin":"Hǎo, méi wèntí.","speaker":"安妮","vi":"Được thôi, không vấn đề gì."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, nhân viên phục vụ nói \"有，但车站有点儿远。\" (Có, nhưng trạm xe hơi xa một chút.), nên Bạch Gia Nguyệt không chọn đi xe buýt.","options":["因为这儿没有公交车","因为公交车站有点儿远","因为她不喜欢坐公交车","因为坐公交车太贵了"],"q":"为什么白家月不坐公交车去北京大学？"},{"answerIdx":2,"explanation":"Trong bài, Bạch Gia Nguyệt nói \"安妮，我们还是打车去吧。\" (An Ni, chúng ta vẫn nên bắt taxi đi đi.) và An Ni đồng ý \"好，没问题。\" (Được, không vấn đề gì.), nên hai người quyết định bắt taxi đi.","options":["坐公交车去","走路去","打车去","开车去"],"q":"白家月和安妮最后决定怎么去北京大学？"}],"scene":"在宾馆前台，白家月和安妮向服务员咨询。","sceneVi":"Tại quầy lễ tân khách sạn, Bạch Gia Nguyệt và An Ni đang hỏi thông tin từ nhân viên."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"学校里人真多啊！","pinyin":"Xuéxiào li rén zhēn duō a!","speaker":"白家月","vi":"Trong trường đông người thật đấy!"},{"hanzi":"是啊，北京大学有四万多名学生呢！","pinyin":"Shì a, Běijīng Dàxué yǒu sìwàn duō míng xuéshēng ne!","speaker":"安妮","vi":"Đúng vậy, Đại học Bắc Kinh có hơn bốn mươi nghìn sinh viên cơ mà!"},{"hanzi":"你是怎么知道的？","pinyin":"Nǐ shì zěnme zhīdào de?","speaker":"白家月","vi":"Sao cậu lại biết thế?"},{"hanzi":"是网上说的，网上还说北京大学有三千多名外国学生。","pinyin":"Shì wǎngshang shuō de, wǎngshang hái shuō Běijīng Dàxué yǒu sānqiān duō míng wàiguó xuéshēng.","speaker":"安妮","vi":"Là trên mạng nói đấy, trên mạng còn nói Đại học Bắc Kinh có hơn ba nghìn sinh viên nước ngoài nữa."},{"hanzi":"我也想来这儿学习。","pinyin":"Wǒ yě xiǎng lái zhèr xuéxí.","speaker":"白家月","vi":"Mình cũng muốn đến đây học tập."},{"hanzi":"那边就有一间教室，我们去看一下吧。","pinyin":"Nàbiān jiù yǒu yì jiān jiàoshì, wǒmen qù kàn yíxià ba.","speaker":"安妮","vi":"Đằng kia có ngay một phòng học đấy, chúng mình qua xem thử một chút đi."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài, An Ni nói \"网上还说北京大学有三千多名外国学生。\" (Trên mạng còn nói Đại học Bắc Kinh có hơn ba nghìn sinh viên nước ngoài.), nên đáp án đúng là hơn ba nghìn sinh viên.","options":["四万多名","四千多名","三千多名","三万多名"],"q":"安妮在网上看到，北京大学有多少名外国学生？"},{"answerIdx":0,"explanation":"Trong bài, An Ni nói \"那边就有一间教室，我们去看一下吧。\" (Đằng kia có một phòng học, chúng ta qua xem một chút đi.), nên cô ấy rủ Bạch Gia Nguyệt đi xem phòng học.","options":["去那边的教室看一下","去网上查一下学校","去认识外国学生","去学校外面逛一逛"],"q":"说完以后，安妮想和白家月一起去做什么？"}],"scene":"在北京大学，白家月和安妮在参观校园。","sceneVi":"Tại Đại học Bắc Kinh, Bạch Gia Nguyệt và An Ni đang tham quan khuôn viên trường."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"家月，你看，学校里有家电影院！","pinyin":"Jiāyuè, nǐ kàn, xuéxiào li yǒu jiā diànyǐngyuàn!","speaker":"安妮","vi":"Gia Nguyệt, cậu nhìn kìa, trong trường có một rạp chiếu phim đấy!"},{"hanzi":"是啊，电影院还不小。","pinyin":"Shì a, diànyǐngyuàn hái bù xiǎo.","speaker":"白家月","vi":"Đúng vậy, rạp chiếu phim cũng không nhỏ đâu."},{"hanzi":"他们卖的电影票也很便宜。","pinyin":"Tāmen mài de diànyǐngpiào yě hěn piányi.","speaker":"安妮","vi":"Vé xem phim họ bán cũng rất rẻ."},{"hanzi":"天啊！有的还不到二十块钱。","pinyin":"Tiān a! Yǒude hái bú dào èrshí kuài qián.","speaker":"白家月","vi":"Trời ơi! Có vé còn chưa đến hai mươi tệ nữa."},{"hanzi":"那你想不想去看个电影？","pinyin":"Nà nǐ xiǎng bu xiǎng qù kàn ge diànyǐng?","speaker":"安妮","vi":"Thế cậu có muốn đi xem một bộ phim không?"},{"hanzi":"还是别看电影了，北京大学就很好看！","pinyin":"Háishi bié kàn diànyǐng le, Běijīng Dàxué jiù hěn hǎokàn!","speaker":"白家月","vi":"Thôi đừng xem phim nữa, bản thân Đại học Bắc Kinh đã rất đẹp rồi!"}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, An Ni nói \"他们卖的电影票也很便宜。\" (Vé xem phim họ bán cũng rất rẻ.) và Bạch Gia Nguyệt nói thêm \"有的还不到二十块钱。\" (Có vé còn chưa tới hai mươi tệ.), nên giá vé rất rẻ.","options":["很贵，要二十多块钱","很便宜，有的不到二十块钱","不卖给外国学生","今天已经卖完了"],"q":"北京大学电影院的电影票怎么样？"},{"answerIdx":3,"explanation":"Trong bài, Bạch Gia Nguyệt từ chối \"还是别看电影了，北京大学就很好看！\" (Thôi đừng xem phim nữa, Đại học Bắc Kinh đã rất đẹp rồi!), vì cô thấy khuôn viên trường đã rất đẹp.","options":["因为电影票太贵了","因为电影院太小了","因为她不喜欢看电影","因为她觉得北京大学就很好看"],"q":"白家月为什么说现在不看电影了？"}],"scene":"在北京大学，白家月和安妮在参观校园。","sceneVi":"Tại Đại học Bắc Kinh, Bạch Gia Nguyệt và An Ni đang tham quan khuôn viên trường."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"北京大学很大，有四万多名学生。","pinyin":"Běijīng Dàxué hěn dà, yǒu sìwàn duō míng xuéshēng.","speaker":"Đoạn văn","vi":"Đại học Bắc Kinh rất rộng lớn, có hơn bốn mươi nghìn sinh viên."},{"hanzi":"学校很漂亮，里边还有家电影院，电影票也不贵，我们有时间还想再过来看个电影。","pinyin":"Xuéxiào hěn piàoliang, lǐbian hái yǒu jiā diànyǐngyuàn, diànyǐngpiào yě bú guì, wǒmen yǒu shíjiān hái xiǎng zài guòlái kàn ge diànyǐng.","speaker":"Đoạn văn","vi":"Ngôi trường rất đẹp, bên trong còn có một rạp chiếu phim, vé xem phim cũng không đắt, lúc nào có thời gian chúng mình còn muốn quay lại đây xem một bộ phim nữa."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong tin nhắn gửi Trần Thiên Trung, Bạch Gia Nguyệt viết \"北京大学很大，有四万多名学生。学校很漂亮...\" (Đại học Bắc Kinh rất lớn, có hơn bốn vạn sinh viên. Trường rất đẹp...).","options":["很大，也很漂亮","人很少，很安静","不大，没有电影院","电影票非常贵"],"q":"在信息里，白家月觉得北京大学怎么样？"},{"answerIdx":2,"explanation":"Trong bài có câu \"我们有时间还想再过来看个电影。\" (Khi nào có thời gian chúng mình còn muốn quay lại đây xem một bộ phim.), nên họ muốn quay lại xem phim.","options":["找朋友吃饭","来这里上课","再过来看个电影","参观一下教室"],"q":"如果以后有时间，她们还想再来北京大学做什么？"}],"scene":"在北京大学门口，白家月给陈天中发信息。","sceneVi":"Ở cổng Đại học Bắc Kinh, Bạch Gia Nguyệt nhắn tin cho Trần Thiên Trung."}],"hsk2-3":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"今天回来这么晚啊！","pinyin":"Jīntiān huílái zhème wǎn a!","speaker":"王一雪","vi":"Hôm nay anh về muộn thế!"},{"hanzi":"工作太多了，下班的时候没做完。","pinyin":"Gōngzuò tài duō le, xiàbān de shíhou méi zuòwán.","speaker":"刘明","vi":"Công việc nhiều quá, lúc tan làm vẫn chưa làm xong."},{"hanzi":"菜都做好了，过来吃饭吧。","pinyin":"Cài dōu zuòhǎo le, guòlái chī fàn ba.","speaker":"王一雪","vi":"Cơm canh đều nấu xong rồi, lại đây ăn cơm đi."},{"hanzi":"我想休息一下，喝杯水。","pinyin":"Wǒ xiǎng xiūxi yíxià, hē bēi shuǐ.","speaker":"刘明","vi":"Anh muốn nghỉ ngơi một chút, uống cốc nước đã."},{"hanzi":"好的。","pinyin":"Hǎo de.","speaker":"王一雪","vi":"Vâng ạ."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Lưu Minh giải thích với vợ \"工作太多了，下班的时候没做完。\" (Công việc nhiều quá, lúc tan làm vẫn chưa làm xong.), nên anh về muộn.","options":["因为他去外面吃饭了","因为工作太多，下班时没做完","因为路上的车太多了","因为他去买东西了"],"q":"刘明今天为什么这么晚才回家？"},{"answerIdx":1,"explanation":"Trong bài, khi Vương Nhất Tuyết mời ăn cơm, Lưu Minh trả lời \"我想休息一下，喝杯水。\" (Anh muốn nghỉ ngơi một chút, uống một cốc nước.).","options":["马上过来吃饭","先休息一下，喝杯水","再做一点儿工作","去帮王一雪做菜"],"q":"刘明回到家后，现在最想做什么？"}],"scene":"在家门口，刘明开门进到家里。","sceneVi":"Ở cửa nhà, Lưu Minh mở cửa bước vào nhà."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"我们找个时间去旅游，怎么样？","pinyin":"Wǒmen zhǎo gè shíjiān qù lǚyóu, zěnmeyàng?","speaker":"刘明","vi":"Chúng mình tìm thời gian đi du lịch, thế nào?"},{"hanzi":"好啊，我也很想一起出去玩。","pinyin":"Hǎo a, wǒ yě hěn xiǎng yìqǐ chūqù wán.","speaker":"王一雪","vi":"Hay quá, em cũng rất muốn cùng nhau ra ngoài chơi."},{"hanzi":"你想去哪儿？","pinyin":"Nǐ xiǎng qù nǎr?","speaker":"刘明","vi":"Em muốn đi đâu?"},{"hanzi":"我还没想好呢。","pinyin":"Wǒ hái méi xiǎnghǎo ne.","speaker":"王一雪","vi":"Em vẫn chưa nghĩ ra nữa."},{"hanzi":"那你再想一想，你想好了，我来买票。","pinyin":"Nà nǐ zài xiǎng yi xiǎng, nǐ xiǎnghǎo le, wǒ lái mǎi piào.","speaker":"刘明","vi":"Vậy em nghĩ thêm chút đi, khi nào em nghĩ xong thì anh sẽ mua vé."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài, Lưu Minh rủ Vương Nhất Tuyết \"我们找个时间去旅游，怎么样？\" (Chúng ta tìm thời gian đi du lịch nhé, thế nào?).","options":["去看电影","去买东西","去旅游","去朋友家玩"],"q":"刘明想和王一雪找时间去做什么？"},{"answerIdx":0,"explanation":"Trong bài, Lưu Minh nói \"那你再想一想，你想好了，我来买票。\" (Vậy em nghĩ thêm đi, khi nào em nghĩ xong thì anh sẽ mua vé.).","options":["他来买票","他先去休息","他去问朋友","他再去想一想"],"q":"王一雪想好去哪儿以后，刘明打算做什么？"}],"scene":"在客厅，刘明和王一雪在聊天儿。","sceneVi":"Ở phòng khách, Lưu Minh và Vương Nhất Tuyết đang trò chuyện."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"吃个苹果吧，我都洗好了。","pinyin":"Chī gè píngguǒ ba, wǒ dōu xǐhǎo le.","speaker":"刘明","vi":"Ăn quả táo đi, anh rửa sạch cả rồi."},{"hanzi":"好的。","pinyin":"Hǎo de.","speaker":"王一雪","vi":"Vâng ạ."},{"hanzi":"就在桌子上，你自己拿。","pinyin":"Jiù zài zhuōzi shang, nǐ zìjǐ ná.","speaker":"刘明","vi":"Ở ngay trên bàn đấy, em tự lấy nhé."},{"hanzi":"我去洗洗手。对了，我们去西安旅游，怎么样？","pinyin":"Wǒ qù xǐxi shǒu. Duìle, wǒmen qù Xī'ān lǚyóu, zěnmeyàng?","speaker":"王一雪","vi":"Em đi rửa tay đã. À đúng rồi, chúng mình đi Tây An du lịch, thế nào?"},{"hanzi":"为什么想去西安？","pinyin":"Wèi shénme xiǎng qù Xī'ān?","speaker":"刘明","vi":"Sao em lại muốn đi Tây An?"},{"hanzi":"我看了看网上的介绍，这个时候去西安很不错！","pinyin":"Wǒ kànle kàn wǎngshang de jièshào, zhège shíhou qù Xī'ān hěn búcuò!","speaker":"王一雪","vi":"Em có xem qua giới thiệu trên mạng rồi, thời điểm này đi Tây An rất tuyệt đấy!"}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, khi Lưu Minh bảo tự lấy táo trên bàn ăn, Vương Nhất Tuyết nói \"我去洗洗手。\" (Em đi rửa tay đã.).","options":["去洗苹果","去洗洗手","去拿桌子上的水","去网上找介绍"],"q":"吃苹果以前，王一雪先去做什么？"},{"answerIdx":3,"explanation":"Trong bài, Vương Nhất Tuyết giải thích \"我看了看网上的介绍，这个时候去西安很不错！\" (Em xem qua giới thiệu trên mạng rồi, tầm này đi Tây An rất tuyệt!).","options":["因为刘明去过西安","因为西安的苹果很好吃","因为她有朋友在西安","因为她看了网上的介绍，觉得这个时候去很不错"],"q":"王一雪为什么想去西安旅游？"}],"scene":"在客厅，刘明和王一雪在聊天儿。","sceneVi":"Ở phòng khách, Lưu Minh và Vương Nhất Tuyết đang trò chuyện."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"早上，刘明开车送孩子去学校，送完孩子回家后，医院就来电话了，让他回去上班。","pinyin":"Zǎoshang, Liú Míng kāichē sòng háizi qù xuéxiào, sòngwán háizi huí jiā hòu, yīyuàn jiù lái diànhuà le, ràng tā huíqù shàngbān.","speaker":"Đoạn văn","vi":"Buổi sáng, Lưu Minh lái xe đưa con đi học, đưa con xong về đến nhà thì bệnh viện gọi điện tới, bảo anh ấy quay lại đi làm."},{"hanzi":"我觉得他这个月每天都很累，真想让他休息休息。","pinyin":"Wǒ juéde tā zhège yuè měi tiān dōu hěn lèi, zhēn xiǎng ràng tā xiūxi xiūxi.","speaker":"Đoạn văn","vi":"Mình thấy tháng này ngày nào anh ấy cũng rất mệt, thật sự muốn để anh ấy nghỉ ngơi một chút."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"送完孩子回家后，医院就来电话了，让他回去上班。\" (Sau khi đưa con đi học về nhà thì bệnh viện gọi điện đến, bảo anh ấy quay lại làm việc.).","options":["他在家里休息了一天","医院来电话让他回去上班","他和王一雪一起去旅游了","他又开车去买东西了"],"q":"刘明送完孩子回家以后，发生了什么事？"},{"answerIdx":2,"explanation":"Trong bài, Vương Nhất Tuyết nói \"我觉得他这个月每天都很累，真想让他休息休息。\" (Mình thấy tháng này ngày nào anh ấy cũng rất mệt, thật muốn để anh ấy nghỉ ngơi.).","options":["每天都很开心","有很多时间休息","每天都很累","工作很少，不太忙"],"q":"王一雪觉得刘明这个月怎么样？"}],"scene":"在家里，王一雪给好朋友打电话。","sceneVi":"Ở nhà, Vương Nhất Tuyết đang gọi điện thoại cho bạn thân."}],"hsk2-4":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"妈妈，我们来过这家商场吗？","pinyin":"Māma, wǒmen láiguo zhè jiā shāngchǎng ma?","speaker":"刘小雪","vi":"Mẹ ơi, chúng ta từng đến trung tâm thương mại này chưa?"},{"hanzi":"没来过，这是新开的。","pinyin":"Méi láiguo, zhè shì xīn kāi de.","speaker":"王一雪","vi":"Chưa từng đến, đây là chỗ mới mở đấy."},{"hanzi":"我们进去看看吧。","pinyin":"Wǒmen jìnqù kànkan ba.","speaker":"刘小雪","vi":"Chúng ta vào trong xem thử đi."},{"hanzi":"好啊！你想买点儿什么？","pinyin":"Hǎo a! Nǐ xiǎng mǎi diǎnr shénme?","speaker":"王一雪","vi":"Được thôi! Con muốn mua chút gì?"},{"hanzi":"我想买条裤子。","pinyin":"Wǒ xiǎng mǎi tiáo kùzi.","speaker":"刘小雪","vi":"Con muốn mua một chiếc quần."},{"hanzi":"没问题。","pinyin":"Méi wèntí.","speaker":"王一雪","vi":"Không thành vấn đề."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, khi Lưu Tiểu Tuyết hỏi đã từng đến trung tâm thương mại này chưa, Vương Nhất Tuyết trả lời \"没来过，这是新开的。\" (Chưa từng đến, đây là chỗ mới mở.).","options":["她们以前来过很多次","她们没来过，因为这是新开的","这家商场今天没开门","这家商场只卖书包"],"q":"关于这家商场，下面哪句话是对的？"},{"answerIdx":0,"explanation":"Trong bài, khi mẹ hỏi muốn mua gì, Lưu Tiểu Tuyết trả lời \"我想买条裤子。\" (Con muốn mua một chiếc quần.).","options":["一条裤子","一件白色的衣服","一个新书包","一些水果"],"q":"刘小雪进商场想买什么？"}],"scene":"在商场门口，王一雪和刘小雪在聊天儿。","sceneVi":"Ở cổng trung tâm thương mại, Vương Nhất Tuyết và Lưu Tiểu Tuyết đang trò chuyện."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"妈妈，我想买这条白色的裤子。","pinyin":"Māma, wǒ xiǎng mǎi zhè tiáo báisè de kùzi.","speaker":"刘小雪","vi":"Mẹ ơi, con muốn mua chiếc quần màu trắng này."},{"hanzi":"你有很多白色的衣服，为什么还买白色的？","pinyin":"Nǐ yǒu hěn duō báisè de yīfu, wèi shénme hái mǎi báisè de?","speaker":"王一雪","vi":"Con có rất nhiều quần áo màu trắng rồi, sao còn mua màu trắng nữa?"},{"hanzi":"因为我喜欢白色啊！","pinyin":"Yīnwèi wǒ xǐhuan báisè a!","speaker":"刘小雪","vi":"Vì con thích màu trắng mà!"},{"hanzi":"我觉得这条白色的不太好看，你试试那条红色的吧。","pinyin":"Wǒ juéde zhè tiáo báisè de bú tài hǎokàn, nǐ shìshi nà tiáo hóngsè de ba.","speaker":"王一雪","vi":"Mẹ thấy chiếc màu trắng này không đẹp lắm, con thử chiếc màu đỏ kia xem."},{"hanzi":"我没穿过红色的，红色的好看吗？","pinyin":"Wǒ méi chuānguo hóngsè de, hóngsè de hǎokàn ma?","speaker":"刘小雪","vi":"Con chưa từng mặc đồ màu đỏ, màu đỏ có đẹp không ạ?"},{"hanzi":"就是因为没穿过，所以要试试啊！","pinyin":"Jiù shì yīnwèi méi chuānguo, suǒyǐ yào shìshi a!","speaker":"王一雪","vi":"Chính vì chưa từng mặc nên mới phải thử đấy!"}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Lưu Tiểu Tuyết nói \"妈妈，我想买这条白色的裤子。\" (Mẹ ơi, con muốn mua chiếc quần màu trắng này.) và giải thích \"因为我喜欢白色啊！\" (Vì con thích màu trắng mà!).","options":["红色的，因为她有很多白色的衣服","白色的，因为她喜欢白色","红色的，因为她没穿过红色的","白色的，因为红色的不好看"],"q":"刘小雪本来想买什么颜色的裤子？为什么？"},{"answerIdx":2,"explanation":"Trong bài, mẹ nói \"我觉得这条白色的不太好看，你试试那条红色的吧。\" (Mẹ thấy chiếc màu trắng này không đẹp lắm, con thử chiếc màu đỏ kia xem.) và nói thêm \"就是因为没穿过，所以要试试啊！\" (Chính vì chưa từng mặc nên mới phải thử đấy!).","options":["因为那条白色的卖完了","因为那条红色的更便宜","因为妈妈觉得白色的不太好看，而且小雪没穿过红色的","因为小雪有很多红色的衣服"],"q":"妈妈为什么让刘小雪试试那条红色的裤子？"}],"scene":"在商场，王一雪和刘小雪在看衣服。","sceneVi":"Trong trung tâm thương mại, Vương Nhất Tuyết và Lưu Tiểu Tuyết đang xem quần áo."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"妈妈，我想买个新书包。","pinyin":"Māma, wǒ xiǎng mǎi gè xīn shūbāo.","speaker":"刘小雪","vi":"Mẹ ơi, con muốn mua một chiếc cặp sách mới."},{"hanzi":"好，那边卖书包，我们过去看看吧。","pinyin":"Hǎo, nàbiān mài shūbāo, wǒmen guòqù kànkan ba.","speaker":"王一雪","vi":"Được, bên kia có bán cặp sách, chúng ta qua xem thử đi."},{"hanzi":"这么多漂亮的书包！","pinyin":"Zhème duō piàoliang de shūbāo!","speaker":"刘小雪","vi":"Nhiều cặp sách đẹp quá đi!"},{"hanzi":"红色的、绿色的、黑色的，你想买哪个？","pinyin":"Hóngsè de, lǜsè de, hēisè de, nǐ xiǎng mǎi nǎge?","speaker":"王一雪","vi":"Cái màu đỏ, màu xanh lá, màu đen, con muốn mua cái nào?"},{"hanzi":"绿色的吧。","pinyin":"Lǜsè de ba.","speaker":"刘小雪","vi":"Cái màu xanh lá đi ạ."},{"hanzi":"不错，我也觉得绿色的更好看。","pinyin":"Búcuò, wǒ yě juéde lǜsè de gèng hǎokàn.","speaker":"王一雪","vi":"Ổn đấy, mẹ cũng thấy cái màu xanh lá đẹp hơn."}],"readingQuiz":[{"answerIdx":3,"explanation":"Trong bài, khi mẹ hỏi muốn mua chiếc cặp sách màu đỏ, xanh lá hay đen, Lưu Tiểu Tuyết chọn \"绿色的吧。\" (Chiếc màu xanh lá đi ạ.).","options":["白色的","红色的","黑色的","绿色的"],"q":"刘小雪最后想买什么颜色的书包？"},{"answerIdx":0,"explanation":"Trong bài, Vương Nhất Tuyết đồng tình với lựa chọn của con \"不错，我也觉得绿色的更好看。\" (Được đấy, mẹ cũng thấy màu xanh lá đẹp hơn.).","options":["她也觉得绿色的更好看","她觉得黑色的更好看","她觉得绿色的不太好看","她觉得那里的书包都不漂亮"],"q":"王一雪对刘小雪选的书包怎么看？"}],"scene":"在商场，王一雪和刘小雪在看书包。","sceneVi":"Trong trung tâm thương mại, Vương Nhất Tuyết và Lưu Tiểu Tuyết đang xem cặp sách."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"我和妈妈去了一家商场。","pinyin":"Wǒ hé māma qùle yì jiā shāngchǎng.","speaker":"Đoạn văn","vi":"Mình và mẹ đã đi đến một trung tâm thương mại."},{"hanzi":"因为是新开的，所以这几天东西很便宜。","pinyin":"Yīnwèi shì xīn kāi de, suǒyǐ zhè jǐ tiān dōngxi hěn piányi.","speaker":"Đoạn văn","vi":"Vì mới khai trương nên mấy hôm nay đồ đạc rất rẻ."},{"hanzi":"商场里的衣服颜色很多。","pinyin":"Shāngchǎng li de yīfu yánsè hěn duō.","speaker":"Đoạn văn","vi":"Quần áo trong trung tâm thương mại có rất nhiều màu sắc."},{"hanzi":"我没穿过红色的裤子，妈妈让我试了试，我觉得我穿红色的也很好看。","pinyin":"Wǒ méi chuānguo hóngsè de kùzi, māma ràng wǒ shìle shì, wǒ juéde wǒ chuān hóngsè de yě hěn hǎokàn.","speaker":"Đoạn văn","vi":"Mình chưa từng mặc quần màu đỏ, mẹ bảo mình thử xem sao, mình thấy mình mặc màu đỏ cũng rất đẹp."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong nhật ký, Lưu Tiểu Tuyết viết \"因为是新开的，所以这几天东西很便宜。\" (Vì mới khai trương nên mấy hôm nay đồ đạc rất rẻ.).","options":["因为里面的衣服很少","因为那家商场是新开的","因为那里的衣服不好看","因为商场很大"],"q":"为什么这几天那家商场里的东西很便宜？"},{"answerIdx":2,"explanation":"Trong bài có câu \"妈妈让我试了试，我觉得我穿红色的也很好看。\" (Mẹ bảo mình thử một chút, mình thấy mình mặc màu đỏ cũng rất đẹp.).","options":["她觉得自己穿白色的更好看","她觉得自己穿红色的不太好看","她觉得自己穿红色的也很好看","她不想试红色的裤子"],"q":"试了红色的裤子以后，刘小雪觉得怎么样？"}],"scene":"在房间，刘小雪在写日记。","sceneVi":"Trong phòng, Lưu Tiểu Tuyết đang viết nhật ký."}],"hsk2-5":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"家月，快下来吧，第一次去中国朋友家，别晚了。","pinyin":"Jiāyuè, kuài xiàlái ba, dì-yī cì qù Zhōngguó péngyou jiā, bié wǎn le.","speaker":"安妮","vi":"Gia Nguyệt, mau xuống đi, lần đầu tiên đến nhà bạn người Trung Quốc, đừng đến muộn đấy."},{"hanzi":"还有时间，你上来吧。","pinyin":"Hái yǒu shíjiān, nǐ shànglái ba.","speaker":"白家月","vi":"Vẫn còn thời gian mà, cậu lên đây đi."},{"hanzi":"我不上去了，就在下面等你。","pinyin":"Wǒ bú shàngqù le, jiù zài xiàmiàn děng nǐ.","speaker":"安妮","vi":"Mình không lên nữa đâu, cứ ở dưới này đợi cậu."},{"hanzi":"那我一会儿就下去。","pinyin":"Nà wǒ yíhuìr jiù xiàqù.","speaker":"白家月","vi":"Vậy một lát nữa mình xuống ngay."},{"hanzi":"你快点儿吧。","pinyin":"Nǐ kuài diǎnr ba.","speaker":"安妮","vi":"Cậu nhanh lên một chút đi."},{"hanzi":"没事，一雪姐说11点前到就可以。","pinyin":"Méishì, Yīxuě jiě shuō shíyī diǎn qián dào jiù kěyǐ.","speaker":"白家月","vi":"Không sao đâu, chị Nhất Tuyết nói đến trước 11 giờ là được rồi."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bối cảnh có ghi \"在宾馆楼下，安妮给白家月打电话。\" (Ở dưới tầng khách sạn, An Ni gọi điện cho Bạch Gia Nguyệt.) và An Ni nói \"我不上去了，就在下面等你。\" (Mình không lên đâu, đợi cậu ở dưới thôi.).","options":["在白家月的房间里","在宾馆楼下","在王一雪家门口","在公交车站"],"q":"打电话的时候，安妮在哪里等白家月？"},{"answerIdx":1,"explanation":"Trong bài, Bạch Gia Nguyệt nói \"没事，一雪姐说11点前到就可以。\" (Không sao, chị Nhất Tuyết nói đến trước 11 giờ là được.).","options":["十一点以后","十一点前","十二点前","下午一点"],"q":"一雪姐让她们什么时候到她家？"}],"scene":"在宾馆楼下，安妮给白家月打电话。","sceneVi":"Ở dưới lầu khách sạn, An Ni gọi điện thoại cho Bạch Gia Nguyệt."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"家月、安妮，快进来！我给你们介绍一下，这是孩子们的爷爷、奶奶。","pinyin":"Jiāyuè, Ānnī, kuài jìnlái! Wǒ gěi nǐmen jièshào yíxià, zhè shì háizimen de yéye, nǎinai.","speaker":"王一雪","vi":"Gia Nguyệt, An Ni, mau vào đi! Để chị giới thiệu với hai em, đây là ông nội, bà nội của các cháu."},{"hanzi":"你们好！","pinyin":"Nǐmen hǎo!","speaker":"白家月、安妮","vi":"Cháu chào ông bà ạ!"},{"hanzi":"爸，妈，这是白家月，这是安妮。她们都是一飞的学生。","pinyin":"Bà, mā, zhè shì Bái Jiāyuè, zhè shì Ānnī. Tāmen dōu shì Yīfēi de xuésheng.","speaker":"王一雪","vi":"Bố, mẹ, đây là Bạch Gia Nguyệt, đây là An Ni. Hai bạn ấy đều là học sinh của Nhất Phi."},{"hanzi":"家月、安妮，你们好！","pinyin":"Jiāyuè, Ānnī, nǐmen hǎo!","speaker":"刘爷爷","vi":"Chào Gia Nguyệt, An Ni!"},{"hanzi":"这是送你们的礼物。","pinyin":"Zhè shì sòng nǐmen de lǐwù.","speaker":"白家月","vi":"Đây là quà tặng ông bà ạ."},{"hanzi":"你们太客气了，还拿这么多礼物来！","pinyin":"Nǐmen tài kèqi le, hái ná zhème duō lǐwù lái!","speaker":"刘爷爷","vi":"Các cháu khách sáo quá, còn mang nhiều quà đến thế này!"},{"hanzi":"一雪姐，这是给孩子们准备的礼物。","pinyin":"Yīxuě jiě, zhè shì gěi háizimen zhǔnbèi de lǐwù.","speaker":"白家月","vi":"Chị Nhất Tuyết, đây là quà bọn em chuẩn bị cho các cháu."},{"hanzi":"谢谢！你们别客气，快坐吧！","pinyin":"Xièxie! Nǐmen bié kèqi, kuài zuò ba!","speaker":"王一雪","vi":"Cảm ơn hai em! Đừng khách sáo, mau ngồi đi!"}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài, Vương Nhất Tuyết giới thiệu với bố mẹ \"她们都是一飞的学生。\" (Hai bạn ấy đều là học sinh của Nhất Phi.).","options":["王一雪的学生","刘爷爷的学生","一飞的学生","孩子们的老师"],"q":"白家月和安妮是谁的学生？"},{"answerIdx":2,"explanation":"Trong bài, sau khi tặng quà cho ông bà, Bạch Gia Nguyệt nói tiếp \"一雪姐，这是给孩子们准备的礼物。\" (Chị Nhất Tuyết ơi, đây là quà chuẩn bị cho các cháu ạ.).","options":["给一飞的","给安妮的","给孩子们的","给朋友们的"],"q":"除了送给爷爷、奶奶的礼物以外，白家月还给谁准备了礼物？"}],"scene":"在王一雪家，白家月和安妮来做客。","sceneVi":"Ở nhà Vương Nhất Tuyết, Bạch Gia Nguyệt và An Ni đến chơi."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"都12点了，我们吃饭吧。","pinyin":"Dōu shí'èr diǎn le, wǒmen chī fàn ba.","speaker":"王一雪","vi":"Đã 12 giờ rồi, chúng ta ăn cơm thôi."},{"hanzi":"这么多好吃的，您太客气了！","pinyin":"Zhème duō hǎochī de, nín tài kèqi le!","speaker":"白家月","vi":"Nhiều món ngon quá, chị khách sáo quá rồi!"},{"hanzi":"都是我自己做的，你们多吃点儿。","pinyin":"Dōu shì wǒ zìjǐ zuò de, nǐmen duō chī diǎnr.","speaker":"王一雪","vi":"Đều là tự tay chị nấu cả đấy, hai em ăn nhiều vào nhé."},{"hanzi":"奶茶也很好喝，是您自己做的吗？","pinyin":"Nǎichá yě hěn hǎohē, shì nín zìjǐ zuò de ma?","speaker":"白家月","vi":"Trà sữa cũng rất ngon, có phải do chị tự làm không ạ?"},{"hanzi":"不是，奶茶是爷爷买的。","pinyin":"Bú shì, nǎichá shì yéye mǎi de.","speaker":"王一雪","vi":"Không phải, trà sữa là ông nội mua đấy."},{"hanzi":"在哪儿买的？我还没喝过这么好喝的奶茶。","pinyin":"Zài nǎr mǎi de? Wǒ hái méi hēguo zhème hǎohē de nǎichá.","speaker":"白家月","vi":"Mua ở đâu thế ạ? Em chưa từng uống trà sữa nào ngon như vậy."},{"hanzi":"就在前边的商场，吃完饭你们可以跟我去看看。","pinyin":"Jiù zài qiánbiān de shāngchǎng, chīwán fàn nǐmen kěyǐ gēn wǒ qù kànkan.","speaker":"王一雪","vi":"Ngay ở trung tâm thương mại phía trước, ăn cơm xong hai em có thể đi cùng chị qua xem thử."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, khi Bạch Gia Nguyệt hỏi trà sữa có phải do chị tự làm không, Vương Nhất Tuyết đáp \"不是，奶茶是爷爷买的。\" (Không phải, trà sữa là do ông nội mua đấy.).","options":["王一雪自己做的","爷爷买的","安妮买的","孩子们买的"],"q":"白家月喝的奶茶是谁买的？"},{"answerIdx":1,"explanation":"Trong bài, Vương Nhất Tuyết nói \"就在前边的商场，吃完饭你们可以跟我去看看。\" (Ở ngay trung tâm thương mại phía trước, ăn cơm xong các em có thể đi cùng chị qua đó xem.).","options":["在家多喝点儿奶茶","跟她去前边的商场看看","回宾馆休息一下","学怎么做奶茶"],"q":"吃完饭以后，王一雪建议她们去做什么？"}],"scene":"在王一雪家，白家月和安妮在吃饭。","sceneVi":"Ở nhà Vương Nhất Tuyết, Bạch Gia Nguyệt và An Ni đang ăn cơm."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"回国前一天，我们去一雪姐家了。","pinyin":"Huí guó qián yì tiān, wǒmen qù Yīxuě jiě jiā le.","speaker":"Đoạn văn","vi":"Một ngày trước khi về nước, chúng tôi đã đến nhà chị Nhất Tuyết."},{"hanzi":"到她家的时候，饭菜都做好了。","pinyin":"Dào tā jiā de shíhou, fàncài dōu zuòhǎo le.","speaker":"Đoạn văn","vi":"Khi đến nhà chị ấy, cơm nước đều đã nấu xong cả rồi."},{"hanzi":"刘爷爷还准备了奶茶。","pinyin":"Liú yéye hái zhǔnbèile nǎichá.","speaker":"Đoạn văn","vi":"Ông nội Lưu còn chuẩn bị cả trà sữa nữa."},{"hanzi":"因为吃了太多东西，我们吃完饭是走回酒店的。","pinyin":"Yīnwèi chīle tài duō dōngxi, wǒmen chīwán fàn shì zǒuhuí jiǔdiàn de.","speaker":"Đoạn văn","vi":"Vì ăn quá nhiều đồ ăn nên ăn cơm xong chúng tôi đã đi bộ về khách sạn."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong tin nhắn, Bạch Gia Nguyệt viết \"回国前一天，我们去一雪姐家了。\" (Một ngày trước khi về nước, chúng mình đã đến nhà chị Nhất Tuyết.).","options":["回国前一天","刚到中国的那一天","回国以后","去商场买东西以后"],"q":"她们是什么时候去一雪姐家的？"},{"answerIdx":2,"explanation":"Trong bài có câu \"因为吃了太多东西，我们吃完饭是走回酒店的。\" (Vì ăn quá nhiều đồ nên sau khi ăn xong chúng mình đã đi bộ về khách sạn.).","options":["因为酒店离一雪姐家很远","因为那边不好打车","因为她们吃了太多东西","因为她们想去商场看衣服"],"q":"吃完饭以后，她们为什么走回酒店？"}],"scene":"在宾馆，白家月给李文发信息。","sceneVi":"Ở khách sạn, Bạch Gia Nguyệt nhắn tin cho Lý Văn."}],"hsk2-6":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"明天就是女儿的生日了。","pinyin":"Míngtiān jiù shì nǚ'ér de shēngrì le.","speaker":"王一雪","vi":"Ngày mai là sinh nhật của con gái rồi đấy."},{"hanzi":"你不说，我还真忘了。我们给她准备个什么礼物呢？","pinyin":"Nǐ bù shuō, wǒ hái zhēn wàng le. Wǒmen gěi tā zhǔnbèi gè shénme lǐwù ne?","speaker":"刘明","vi":"Em không nhắc là anh quên thật đấy. Chúng ta chuẩn bị món quà gì cho con bé đây?"},{"hanzi":"她喜欢画画，你觉得画笔怎么样？","pinyin":"Tā xǐhuan huà huà, nǐ juéde huàbǐ zěnmeyàng?","speaker":"王一雪","vi":"Con bé thích vẽ tranh, anh thấy bút vẽ thì thế nào?"},{"hanzi":"就送画笔吧！","pinyin":"Jiù sòng huàbǐ ba!","speaker":"刘明","vi":"Vậy tặng bút vẽ đi!"},{"hanzi":"那我明天上午就去买。","pinyin":"Nà wǒ míngtiān shàngwǔ jiù qù mǎi.","speaker":"王一雪","vi":"Vậy sáng mai em đi mua luôn."},{"hanzi":"好的！我再给她买个大大的生日蛋糕。","pinyin":"Hǎo de! Wǒ zài gěi tā mǎi gè dàdà de shēngrì dàngāo.","speaker":"刘明","vi":"Được! Anh sẽ mua thêm cho con bé một chiếc bánh sinh nhật thật to."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"她喜欢画画，你觉得画笔怎么样？\" (Con bé thích vẽ tranh, anh thấy bút vẽ thế nào?) và \"就送画笔吧！\" (Vậy tặng bút vẽ đi!), nên đáp án đúng là 画笔 (bút vẽ).","options":["一本新书","画笔","一件白色的衣服","黑色的狗"],"q":"他们决定给女儿买什么生日礼物？"},{"answerIdx":0,"explanation":"Trong bài, Lưu Minh nói: \"我再给她买个大大的生日蛋糕。\" (Anh sẽ mua thêm cho con bé một chiếc bánh sinh nhật thật to.), nên đáp án đúng là 一个大大的生日蛋糕 (một chiếc bánh sinh nhật thật to).","options":["一个大大的生日蛋糕","一些长长的面条儿","一只白色的小猫","一张电影票"],"q":"除了礼物以外，刘明还要给女儿买什么？"}],"scene":"在家里，刘明和王一雪在聊天儿。","sceneVi":"Ở nhà, Lưu Minh và Vương Nhất Tuyết đang trò chuyện."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"小雪，生日快乐！","pinyin":"Xiǎoxuě, shēngrì kuàilè!","speaker":"刘明","vi":"Tiểu Tuyết, chúc mừng sinh nhật con!"},{"hanzi":"姐姐，生日快乐！","pinyin":"Jiějie, shēngrì kuàilè!","speaker":"刘小明","vi":"Chị ơi, chúc mừng sinh nhật chị!"},{"hanzi":"小雪，这是爸爸、妈妈送你的礼物。","pinyin":"Xiǎoxuě, zhè shì bàba, māma sòng nǐ de lǐwù.","speaker":"王一雪","vi":"Tiểu Tuyết, đây là món quà bố mẹ tặng cho con."},{"hanzi":"你打开看看喜欢不喜欢。","pinyin":"Nǐ dǎkāi kànkan xǐhuan bu xǐhuan.","speaker":"刘明","vi":"Con mở ra xem có thích không."},{"hanzi":"画笔！我很喜欢！","pinyin":"Huàbǐ! Wǒ hěn xǐhuan!","speaker":"刘小雪","vi":"Bút vẽ! Con thích lắm ạ!"},{"hanzi":"那你想画点儿什么？","pinyin":"Nà nǐ xiǎng huà diǎnr shénme?","speaker":"王一雪","vi":"Thế con muốn vẽ gì nào?"},{"hanzi":"画我们的家！有爸爸、妈妈、弟弟，还有黑色的狗、白色的猫什么的。","pinyin":"Huà wǒmen de jiā! Yǒu bàba, māma, dìdi, hái yǒu hēisè de gǒu, báisè de māo shénmede.","speaker":"刘小雪","vi":"Vẽ gia đình mình ạ! Có bố, mẹ, em trai, còn có chú chó màu đen, chú mèo màu trắng nữa..."},{"hanzi":"那我要画一个穿白色衣服的姐姐。","pinyin":"Nà wǒ yào huà yí gè chuān báisè yīfu de jiějie.","speaker":"刘小明","vi":"Vậy em sẽ vẽ một người chị mặc áo màu trắng."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài, khi được hỏi muốn vẽ gì, Lưu Tiểu Tuyết trả lời: \"画我们的家！有爸爸、妈妈、弟弟，还有黑色的狗、白色的猫什么的。\" (Vẽ gia đình chúng ta! Có bố, mẹ, em trai, còn có chó đen, mèo trắng nữa.), nên đáp án đúng là 画他们的家 (vẽ gia đình của họ).","options":["画学校和同学","画穿白色衣服的姐姐","画他们的家","画生日蛋糕和面条儿"],"q":"收到画笔后，刘小雪想画什么？"},{"answerIdx":3,"explanation":"Trong bài, em trai Lưu Tiểu Minh nói: \"那我要画一个穿白色衣服的姐姐。\" (Vậy em muốn vẽ một người chị mặc áo trắng.), nên đáp án đúng là 画穿白色衣服的姐姐 (vẽ người chị mặc áo trắng).","options":["画一条黑色的狗","画一只白色的猫","画爸爸和妈妈","画穿白色衣服的姐姐"],"q":"弟弟刘小明想画什么？"}],"scene":"在客厅，刘明一家人在聊天儿。","sceneVi":"Ở phòng khách, gia đình Lưu Minh đang trò chuyện."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"小雪，看看今天有什么好吃的。","pinyin":"Xiǎoxuě, kànkan jīntiān yǒu shénme hǎochī de.","speaker":"刘明","vi":"Tiểu Tuyết, xem hôm nay có những món gì ngon nào."},{"hanzi":"长长的面条儿，大大的蛋糕。","pinyin":"Chángcháng de miàntiáor, dàdà de dàngāo.","speaker":"刘小雪","vi":"Mì sợi dài thật dài, bánh kem to thật to ạ."},{"hanzi":"你看，还有鱼啊肉啊什么的，都是你喜欢吃的。","pinyin":"Nǐ kàn, hái yǒu yú a ròu a shénmede, dōu shì nǐ xǐhuan chī de.","speaker":"刘明","vi":"Con xem, còn có cá, thịt các thứ nữa, đều là những món con thích ăn đấy."},{"hanzi":"谢谢爸爸、妈妈！","pinyin":"Xièxie bàba, māma!","speaker":"刘小雪","vi":"Con cảm ơn bố mẹ ạ!"},{"hanzi":"快去叫弟弟过来吃饭吧，吃完饭我们还要出去玩呢。","pinyin":"Kuài qù jiào dìdi guòlái chī fàn ba, chīwán fàn wǒmen hái yào chūqù wán ne.","speaker":"王一雪","vi":"Mau đi gọi em trai qua ăn cơm đi con, ăn xong chúng ta còn đi ra ngoài chơi nữa đấy."},{"hanzi":"过生日真好啊！","pinyin":"Guò shēngrì zhēn hǎo a!","speaker":"刘小雪","vi":"Đón sinh nhật thật là thích quá đi!"},{"hanzi":"是的，过生日就要吃好吃的，还要高高兴兴地玩。","pinyin":"Shì de, guò shēngrì jiù yào chī hǎochī de, hái yào gāogāoxìngxìng de wán.","speaker":"王一雪","vi":"Đúng rồi, đón sinh nhật thì phải ăn đồ ngon, lại còn phải chơi thật vui vẻ nữa."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"长长的面条儿，大大的蛋糕。\" (Mì sợi dài, bánh kem to.) và \"你看，还有鱼啊肉啊什么的，都是你喜欢吃的。\" (Con xem, còn có cá, thịt các thứ nữa, đều là món con thích ăn.), nên đáp án đúng là 面条儿、蛋糕、鱼和肉等 (mì sợi, bánh kem, cá và thịt...).","options":["只有面条儿和蛋糕","面条儿、蛋糕、鱼和肉等","只有鱼和肉","面包、牛奶和水果"],"q":"今天小雪的生日有什么好吃的？"},{"answerIdx":0,"explanation":"Trong bài, Vương Nhất Tuyết nói: \"吃完饭我们还要出去玩呢。\" (Ăn cơm xong chúng ta còn phải ra ngoài chơi nữa đấy.), nên đáp án đúng là 出去玩 (ra ngoài chơi).","options":["出去玩","在家画画","早早地上床睡觉","去商店买礼物"],"q":"吃完饭以后，他们打算做什么？"}],"scene":"在客厅，刘明一家人在给刘小雪过生日。","sceneVi":"Ở phòng khách, gia đình Lưu Minh đang tổ chức sinh nhật cho Lưu Tiểu Tuyết."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"今天是女儿的生日。","pinyin":"Jīntiān shì nǚ'ér de shēngrì.","speaker":"Đoạn văn","vi":"Hôm nay là sinh nhật của con gái."},{"hanzi":"我们买了蛋糕，做了面条儿，还做了鱼啊肉啊什么的。","pinyin":"Wǒmen mǎile dàngāo, zuòle miàntiáor, hái zuòle yú a ròu a shénmede.","speaker":"Đoạn văn","vi":"Chúng tôi đã mua bánh kem, làm mì sợi, còn nấu cá, thịt các thứ nữa."},{"hanzi":"吃完晚饭，一家人去看了个电影。","pinyin":"Chīwán wǎnfàn, yì jiā rén qù kànle gè diànyǐng.","speaker":"Đoạn văn","vi":"Ăn cơm tối xong, cả nhà đi xem một bộ phim."},{"hanzi":"回家后，孩子们早早地就上床了。","pinyin":"Huí jiā hòu, háizimen zǎozǎo de jiù shàng chuáng le.","speaker":"Đoạn văn","vi":"Sau khi về nhà, bọn trẻ đã lên giường đi ngủ từ sớm."},{"hanzi":"明天不上学，他们说要舒舒服服地睡一觉，让我们晚点儿叫他们起床。","pinyin":"Míngtiān bú shàngxué, tāmen shuō yào shūshūfúfú de shuì yí jiào, ràng wǒmen wǎn diǎnr jiào tāmen qǐchuáng.","speaker":"Đoạn văn","vi":"Ngày mai không phải đi học, chúng bảo muốn ngủ một giấc thật thoải mái và dặn chúng tôi gọi chúng dậy muộn một chút."},{"hanzi":"这是很忙、很累，但很快乐的一天。","pinyin":"Zhè shì hěn máng, hěn lèi, dàn hěn kuàilè de yì tiān.","speaker":"Đoạn văn","vi":"Đây là một ngày rất bận rộn, rất mệt nhưng vô cùng vui vẻ."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu \"吃完晚饭，一家人去看了个电影。\" (Ăn tối xong, cả nhà đi xem một bộ phim.), nên đáp án đúng là 去看电影了 (đã đi xem phim).","options":["去商场购物了","去朋友家玩了","去看电影了","去公园跑步了"],"q":"吃完晚饭以后，一家人去做什么了？"},{"answerIdx":1,"explanation":"Trong bài có câu \"明天不上学，他们说要舒舒服服地睡一觉，让我们晚点儿叫他们起床。\" (Ngày mai không phải đi học, bọn trẻ nói muốn ngủ một giấc thật thoải mái, bảo chúng tôi gọi chúng dậy muộn một chút.), nên đáp án đúng là 因为明天不上学，他们想好好睡一觉.","options":["因为他们生病了","因为明天不上学，他们想好好睡一觉","因为他们还要继续画画","因为明天要很早去学校"],"q":"为什么孩子们让爸爸妈妈明天晚点儿叫他们起床？"}],"scene":"在房间，王一雪在写日记。","sceneVi":"Ở trong phòng, Vương Nhất Tuyết đang viết nhật ký."}],"hsk2-7":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"安妮，你是什么时候从北京回来的？","pinyin":"Ānnī, nǐ shì shénme shíhou cóng Běijīng huílái de?","speaker":"陈天中","vi":"An Ni, cậu từ Bắc Kinh về lúc nào vậy?"},{"hanzi":"昨天下午。天中，你怎么一下课就往外跑？","pinyin":"Zuótiān xiàwǔ. Tiānzhōng, nǐ zěnme yí xiàkè jiù wǎng wài pǎo?","speaker":"安妮","vi":"Chiều hôm qua. Thiên Trung, sao cậu vừa tan học đã chạy ra ngoài thế?"},{"hanzi":"我跟同学说好了，一起去打篮球。","pinyin":"Wǒ gēn tóngxué shuōhǎo le, yìqǐ qù dǎ lánqiú.","speaker":"陈天中","vi":"Tớ đã hẹn với bạn học rồi, cùng đi chơi bóng rổ."},{"hanzi":"我也想跟你们一起玩。","pinyin":"Wǒ yě xiǎng gēn nǐmen yìqǐ wán.","speaker":"安妮","vi":"Tớ cũng muốn đi chơi cùng các cậu."},{"hanzi":"没问题，走吧。","pinyin":"Méi wèntí, zǒu ba.","speaker":"陈天中","vi":"Không vấn đề gì, đi thôi."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, khi được hỏi lúc nào từ Bắc Kinh trở về, An Ni trả lời: \"昨天下午。\" (Chiều hôm qua.), nên đáp án đúng là 昨天下午.","options":["今天上午","昨天下午","昨天上午","上个星期天"],"q":"安妮是什么时候从北京回来的？"},{"answerIdx":2,"explanation":"Trong bài, Trần Thiên Trung nói: \"我跟同学说好了，一起去打篮球。\" (Tớ đã hẹn với bạn học rồi, cùng đi chơi bóng rổ.), nên đáp án đúng là 因为他跟同学约好了一起打篮球.","options":["因为他要回家吃饭","因为他要去北京","因为他跟同学约好了一起打篮球","因为他要去游泳"],"q":"陈天中为什么一下课就往外跑？"}],"scene":"在教室，安妮和陈天中在聊天儿。","sceneVi":"Trong lớp học, An Ni và Trần Thiên Trung đang trò chuyện."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"天中，你是不是很喜欢打篮球？","pinyin":"Tiānzhōng, nǐ shì bu shì hěn xǐhuan dǎ lánqiú?","speaker":"安妮","vi":"Thiên Trung, có phải cậu rất thích chơi bóng rổ không?"},{"hanzi":"没错。","pinyin":"Méi cuò.","speaker":"陈天中","vi":"Đúng vậy."},{"hanzi":"你还喜欢什么运动？","pinyin":"Nǐ hái xǐhuan shénme yùndòng?","speaker":"安妮","vi":"Cậu còn thích môn thể thao nào nữa?"},{"hanzi":"我还喜欢踢足球，一到星期天就跟朋友们去踢球。","pinyin":"Wǒ hái xǐhuan tī zúqiú, yí dào Xīngqītiān jiù gēn péngyoumen qù tī qiú.","speaker":"陈天中","vi":"Tớ còn thích đá bóng, cứ đến Chủ nhật là đi đá bóng với bạn bè."},{"hanzi":"你踢得怎么样？","pinyin":"Nǐ tī de zěnmeyàng?","speaker":"安妮","vi":"Cậu đá thế nào?"},{"hanzi":"我踢得还可以。","pinyin":"Wǒ tī de hái kěyǐ.","speaker":"陈天中","vi":"Tớ đá cũng tạm được."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu \"我还喜欢踢足球，一到星期天就跟朋友们去踢球。\" (Tớ còn thích đá bóng, cứ đến Chủ nhật là đi đá bóng cùng bạn bè.), nên đáp án đúng là 跟朋友们去踢足球.","options":["在家看电影","去北京看朋友","跟朋友们去踢足球","跟爸爸去跑步"],"q":"一到星期天，陈天中常做什么？"},{"answerIdx":0,"explanation":"Trong bài, khi An Ni hỏi \"你踢得怎么样？\" (Cậu đá thế nào?), Trần Thiên Trung trả lời: \"我踢得还可以。\" (Tớ đá cũng tạm được / khá ổn.), nên đáp án đúng là 踢得还可以.","options":["踢得还可以","踢得不太好","踢得非常慢","一点儿也不会踢"],"q":"陈天中觉得自己足球踢得怎么样？"}],"scene":"在校园，安妮和陈天中边走边聊。","sceneVi":"Trong khuôn viên trường, An Ni và Trần Thiên Trung vừa đi vừa trò chuyện."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"你篮球打得怎么样？","pinyin":"Nǐ lánqiú dǎ de zěnmeyàng?","speaker":"陈天中","vi":"Cậu chơi bóng rổ thế nào?"},{"hanzi":"打得还可以。","pinyin":"Dǎ de hái kěyǐ.","speaker":"安妮","vi":"Chơi cũng tạm được."},{"hanzi":"跑步呢？你跑得快不快？","pinyin":"Pǎobù ne? Nǐ pǎo de kuài bu kuài?","speaker":"陈天中","vi":"Còn chạy bộ thì sao? Cậu chạy có nhanh không?"},{"hanzi":"我跑得不快，也不太喜欢跑步。","pinyin":"Wǒ pǎo de bú kuài, yě bú tài xǐhuan pǎobù.","speaker":"安妮","vi":"Tớ chạy không nhanh, cũng không thích chạy bộ lắm."},{"hanzi":"那你喜欢游泳吗？","pinyin":"Nà nǐ xǐhuan yóuyǒng ma?","speaker":"陈天中","vi":"Vậy cậu có thích bơi lội không?"},{"hanzi":"喜欢，但我游泳游得不快。","pinyin":"Xǐhuan, dàn wǒ yóuyǒng yóu de bú kuài.","speaker":"安妮","vi":"Thích, nhưng tớ bơi không nhanh."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, An Ni nói: \"我跑得不快，也不太喜欢跑步。\" (Tớ chạy không nhanh, cũng không thích chạy bộ lắm.), nên đáp án đúng là 她跑得不快，也不太喜欢跑步.","options":["她跑得很快，也很喜欢跑步","她跑得不快，也不太喜欢跑步","她每天都去跑步","她跑得还可以，但是没时间跑"],"q":"关于跑步，安妮是怎么说的？"},{"answerIdx":2,"explanation":"Trong bài, khi được hỏi có thích bơi không, An Ni đáp: \"喜欢，但我游泳游得不快。\" (Thích, nhưng tớ bơi không nhanh.), nên đáp án đúng là 她喜欢游泳，但是游得不快.","options":["她不喜欢游泳，游得也不快","她喜欢游泳，而且游得非常快","她喜欢游泳，但是游得不快","她不会游泳，只喜欢打篮球"],"q":"安妮喜欢游泳吗？她游得怎么样？"}],"scene":"在校园，安妮和陈天中边走边聊。","sceneVi":"Trong khuôn viên trường, An Ni và Trần Thiên Trung vừa đi vừa trò chuyện."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"我的爱好是运动。","pinyin":"Wǒ de àihào shì yùndòng.","speaker":"Đoạn văn","vi":"Sở thích của tôi là thể thao."},{"hanzi":"从上小学开始，我每天都跟爸爸去运动。","pinyin":"Cóng shàng xiǎoxué kāishǐ, wǒ měi tiān dōu gēn bàba qù yùndòng.","speaker":"Đoạn văn","vi":"Từ khi học tiểu học, ngày nào tôi cũng đi tập thể thao cùng bố."},{"hanzi":"现在我篮球打得很好，足球踢得不错，游泳游得也很快。","pinyin":"Xiànzài wǒ lánqiú dǎ de hěn hǎo, zúqiú tī de búcuò, yóuyǒng yóu de yě hěn kuài.","speaker":"Đoạn văn","vi":"Bây giờ tôi chơi bóng rổ rất giỏi, đá bóng khá tốt, bơi cũng rất nhanh."},{"hanzi":"我一有时间就去运动。","pinyin":"Wǒ yì yǒu shíjiān jiù qù yùndòng.","speaker":"Đoạn văn","vi":"Cứ hễ có thời gian là tôi lại đi tập thể thao."}],"readingQuiz":[{"answerIdx":3,"explanation":"Trong bài có câu \"从上小学开始，我每天都跟爸爸去运动。\" (Từ khi học tiểu học, ngày nào tôi cũng đi tập thể thao cùng bố.), nên đáp án đúng là 跟爸爸 (cùng bố).","options":["跟同学","跟安妮","跟哥哥","跟爸爸"],"q":"从上小学开始，陈天中每天都跟谁一起去运动？"},{"answerIdx":1,"explanation":"Trong bài có câu \"现在我篮球打得很好，足球踢得不错，游泳游得也很快。\" (Hiện tại tôi chơi bóng rổ rất giỏi, đá bóng khá tốt, bơi lội cũng rất nhanh.), nên đáp án đúng là 陈天中现在篮球、足球和游泳都很好.","options":["陈天中游泳游得不快","陈天中现在篮球、足球和游泳都很好","陈天中只有星期天才去运动","陈天中不太喜欢运动"],"q":"下面哪句话符合日记的内容？"}],"scene":"在房间，陈天中在写日记。","sceneVi":"Trong phòng, Trần Thiên Trung đang viết nhật ký."}],"hsk2-8":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"你看，这两块手表怎么样？","pinyin":"Nǐ kàn, zhè liǎng kuài shǒubiǎo zěnmeyàng?","speaker":"王一雪","vi":"Anh xem, hai chiếc đồng hồ đeo tay này thế nào?"},{"hanzi":"都不错！","pinyin":"Dōu búcuò!","speaker":"刘明","vi":"Cả hai đều đẹp!"},{"hanzi":"我喜欢左边这个。","pinyin":"Wǒ xǐhuan zuǒbian zhège.","speaker":"王一雪","vi":"Em thích chiếc bên trái này."},{"hanzi":"我也觉得左边的比右边的好看。","pinyin":"Wǒ yě juéde zuǒbian de bǐ yòubian de hǎokàn.","speaker":"刘明","vi":"Anh cũng thấy chiếc bên trái đẹp hơn chiếc bên phải."},{"hanzi":"你看看要多少钱！","pinyin":"Nǐ kànkan yào duōshao qián!","speaker":"王一雪","vi":"Anh xem thử giá bao nhiêu tiền!"},{"hanzi":"真不便宜！八千八！","pinyin":"Zhēn bù piányi! Bā qiān bā!","speaker":"刘明","vi":"Thật không rẻ chút nào! Tám nghìn tám!"}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Vương Nhất Tuyết nói \"我喜欢左边这个。\" (Em thích chiếc bên trái này.) và Lưu Minh cũng đồng ý \"我也觉得左边的比右边的好看。\" (Anh cũng thấy chiếc bên trái đẹp hơn chiếc bên phải.), nên đáp án đúng là 左边那块 (chiếc bên trái).","options":["右边那块","左边那块","两块都不好看","最便宜的那块"],"q":"王一雪和刘明都觉得哪块手表更好看？"},{"answerIdx":2,"explanation":"Trong bài, Lưu Minh nói: \"真不便宜！八千八！\" (Thật không rẻ chút nào! Tám nghìn tám!), nên đáp án đúng là 八千八 (8.800).","options":["八百八","八千块","八千八","非常便宜"],"q":"他们看的手表多少钱？"}],"scene":"在商场，王一雪和刘明在购物。","sceneVi":"Ở trung tâm thương mại, Vương Nhất Tuyết và Lưu Minh đang mua sắm."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"今天有不少电影，我们看个电影吧。","pinyin":"Jīntiān yǒu bù shǎo diànyǐng, wǒmen kàn gè diànyǐng ba.","speaker":"刘明","vi":"Hôm nay có khá nhiều phim, chúng ta xem một bộ phim đi."},{"hanzi":"好啊！我们看哪个？","pinyin":"Hǎo a! Wǒmen kàn nǎge?","speaker":"王一雪","vi":"Được đấy! Chúng ta xem phim nào?"},{"hanzi":"我记得你喜欢看爱情片，我们看那个爱情片，怎么样？","pinyin":"Wǒ jìde nǐ xǐhuan kàn àiqíngpiàn, wǒmen kàn nàge àiqíngpiàn, zěnmeyàng?","speaker":"刘明","vi":"Anh nhớ em thích xem phim tình cảm, chúng ta xem bộ phim tình cảm kia nhé, thế nào?"},{"hanzi":"还是看这个吧，我看网上说这个电影比那个爱情片更有意思。","pinyin":"Háishi kàn zhège ba, wǒ kàn wǎngshang shuō zhège diànyǐng bǐ nàge àiqíngpiàn gèng yǒu yìsi.","speaker":"王一雪","vi":"Hay là xem bộ này đi, em thấy trên mạng nói bộ phim này hay hơn bộ phim tình cảm kia đấy."},{"hanzi":"好。我去买票。","pinyin":"Hǎo. Wǒ qù mǎi piào.","speaker":"刘明","vi":"Được. Anh đi mua vé."},{"hanzi":"到网上买吧，网上买比在这里买便宜。","pinyin":"Dào wǎngshang mǎi ba, wǎngshang mǎi bǐ zài zhèlǐ mǎi piányi.","speaker":"王一雪","vi":"Mua trên mạng đi anh, mua trên mạng rẻ hơn mua ở đây."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài, Vương Nhất Tuyết nói: \"我看网上说这个电影比那个爱情片更有意思。\" (Em thấy trên mạng nói bộ phim này thú vị hơn bộ phim tình cảm kia.), nên đáp án đúng là 因为网上说这个电影比那个爱情片更有意思.","options":["因为这个电影的票更便宜","因为她不喜欢看爱情片","因为网上说这个电影比那个爱情片更有意思","因为那个爱情片今天不演"],"q":"王一雪为什么想看这个电影，不想看那个爱情片？"},{"answerIdx":1,"explanation":"Trong bài có câu \"到网上买吧，网上买比在这里买便宜。\" (Lên mạng mua đi anh, mua trên mạng rẻ hơn mua ở đây.), nên đáp án đúng là 在网上买，因为比在电影院买便宜.","options":["在电影院买，因为更快","在网上买，因为比在电影院买便宜","请朋友买，因为不用花钱","在商场买，因为有礼物送"],"q":"王一雪建议在哪里买电影票？为什么？"}],"scene":"在电影院外面，王一雪和刘明在聊天儿。","sceneVi":"Bên ngoài rạp chiếu phim, Vương Nhất Tuyết và Lưu Minh đang trò chuyện."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"您好！就要这几个菜吧，谢谢！","pinyin":"Nín hǎo! Jiù yào zhè jǐ gè cài ba, xièxie!","speaker":"刘明","vi":"Xin chào! Lấy mấy món này nhé, cảm ơn!"},{"hanzi":"怎么点这么多菜？","pinyin":"Zěnme diǎn zhème duō cài?","speaker":"王一雪","vi":"Sao anh gọi nhiều món thế?"},{"hanzi":"你想想，今天是几月几号？","pinyin":"Nǐ xiǎngxiang, jīntiān shì jǐ yuè jǐ hào?","speaker":"刘明","vi":"Em nghĩ xem, hôm nay là ngày mấy tháng mấy?"},{"hanzi":"8月27号。啊！我的生日！","pinyin":"Bā yuè èrshíqī hào. À! Wǒ de shēngrì!","speaker":"王一雪","vi":"Ngày 27 tháng 8. À! Sinh nhật của em!"},{"hanzi":"生日快乐！虽然你忘了，但是我记得。看看这是什么？","pinyin":"Shēngrì kuàilè! Suīrán nǐ wàng le, dànshì wǒ jìde. Kànkan zhè shì shénme?","speaker":"刘明","vi":"Chúc mừng sinh nhật! Tuy em quên rồi, nhưng anh vẫn nhớ. Xem thử đây là gì nào?"},{"hanzi":"手表！吃饭、看电影、买手表，今天花了不少钱吧？","pinyin":"Shǒubiǎo! Chī fàn, kàn diànyǐng, mǎi shǒubiǎo, jīntiān huā le bù shǎo qián ba?","speaker":"王一雪","vi":"Đồng hồ đeo tay! Ăn cơm, xem phim, mua đồng hồ, hôm nay tiêu không ít tiền rồi đúng không?"},{"hanzi":"虽然花了一些钱，但是我们过了一个快乐的生日。","pinyin":"Suīrán huā le yìxiē qián, dànshì wǒmen guò le yí gè kuàilè de shēngrì.","speaker":"刘明","vi":"Tuy có tiêu một ít tiền, nhưng chúng ta đã đón một ngày sinh nhật vui vẻ."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có đoạn \"你想想，今天是几月几号？\" - \"8月27号。啊！我的生日！\" (Em nghĩ xem, hôm nay ngày mấy tháng mấy? - Ngày 27 tháng 8. A! Sinh nhật của em!), nên đáp án đúng là 八月二十七号 (ngày 27 tháng 8).","options":["七月二十八号","八月二十七号","八月十七号","九月二十七号"],"q":"王一雪的生日是几月几号？"},{"answerIdx":2,"explanation":"Trong bài, Lưu Minh nói: \"生日快乐！虽然你忘了，但是我记得。看看这是什么？\" (Chúc mừng sinh nhật! Tuy em quên nhưng anh vẫn nhớ. Xem đây là gì nào?), nên đáp án đúng là 因为今天是王一雪的生日.","options":["因为今天有很多朋友来吃饭","因为饭馆今天的菜很便宜","因为今天是王一雪的生日","因为刘明今天忘了带礼物"],"q":"刘明为什么点这么多菜，还买了手表？"}],"scene":"在饭馆，王一雪和刘明在点菜。","sceneVi":"Ở nhà hàng, Vương Nhất Tuyết và Lưu Minh đang gọi món."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"虽然妻子忘了今天是自己的生日，但是丈夫记得。","pinyin":"Suīrán qīzi wàng le jīntiān shì zìjǐ de shēngrì, dànshì zhàngfu jìde.","speaker":"Đoạn văn","vi":"Tuy người vợ quên hôm nay là sinh nhật của mình, nhưng người chồng vẫn nhớ."},{"hanzi":"丈夫请妻子去饭馆吃饭、去电影院看电影，还给妻子买了一块非常漂亮的手表。","pinyin":"Zhàngfu qǐng qīzi qù fànguǎn chī fàn, qù diànyǐngyuàn kàn diànyǐng, hái gěi qīzi mǎi le yí kuài fēicháng piàoliang de shǒubiǎo.","speaker":"Đoạn văn","vi":"Người chồng mời vợ đi nhà hàng ăn cơm, đi rạp chiếu phim xem phim, lại còn mua tặng vợ một chiếc đồng hồ đeo tay vô cùng đẹp."},{"hanzi":"妻子觉得今天很快乐。","pinyin":"Qīzi juéde jīntiān hěn kuàilè.","speaker":"Đoạn văn","vi":"Người vợ cảm thấy hôm nay rất vui vẻ."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong đoạn văn có câu \"虽然妻子忘了今天是自己的生日，但是丈夫记得。\" (Tuy người vợ quên hôm nay là sinh nhật của mình, nhưng người chồng vẫn nhớ.), nên đáp án đúng là 妻子忘了 (người vợ quên).","options":["丈夫忘了","妻子忘了","两个人都忘了","小语忘了"],"q":"这段话里，谁忘了今天是自己的生日？"},{"answerIdx":3,"explanation":"Trong đoạn văn có câu \"丈夫请妻子去饭馆吃饭、去电影院看电影，还给妻子买了一块非常漂亮的手表。\" (Người chồng mời vợ đi nhà hàng ăn cơm, đi rạp chiếu phim xem phim, còn mua tặng vợ một chiếc đồng hồ rất đẹp.), không nhắc đến việc mua quần áo mới, nên đáp án đúng là 给她买了一件新衣服.","options":["请她去饭馆吃饭","请她去看电影","给她买了一块手表","给她买了一件新衣服"],"q":"那一天，丈夫没有为妻子做什么？"}],"scene":"小语在讲述王一雪和刘明的一天。","sceneVi":"Tiểu Ngữ đang kể lại một ngày của Vương Nhất Tuyết và Lưu Minh."}],"hsk2-9":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"儿子的裤子坏了，我们给他买条新的吧。","pinyin":"Érzi de kùzi huài le, wǒmen gěi tā mǎi tiáo xīn de ba.","speaker":"王一雪","vi":"Quần của con trai hỏng rồi, chúng ta mua cho con một cái mới nhé."},{"hanzi":"好啊。","pinyin":"Hǎo a.","speaker":"刘明","vi":"Được thôi."},{"hanzi":"你看这条黑色的怎么样？","pinyin":"Nǐ kàn zhè tiáo hēisè de zěnmeyàng?","speaker":"王一雪","vi":"Anh xem cái màu đen này thế nào?"},{"hanzi":"没有你上次买的那条好看。","pinyin":"Méiyǒu nǐ shàng cì mǎi de nà tiáo hǎokàn.","speaker":"刘明","vi":"Không đẹp bằng cái lần trước em mua."},{"hanzi":"旁边那个男孩儿就穿了这样的裤子，我觉得很好看啊！","pinyin":"Pángbiān nàge nánháir jiù chuānle zhèyàng de kùzi, wǒ juéde hěn hǎokàn a!","speaker":"王一雪","vi":"Cậu bé bên cạnh mặc quần giống thế này đấy, em thấy rất đẹp mà!"},{"hanzi":"儿子的个子没有他那么高，穿上就不会太好看。","pinyin":"Érzi de gèzi méiyǒu tā nàme gāo, chuānshàng jiù bú huì tài hǎokàn.","speaker":"刘明","vi":"Vóc dáng của con trai mình không cao bằng cậu bé ấy, mặc vào sẽ không đẹp lắm đâu."},{"hanzi":"好吧，我们再去那边看看。","pinyin":"Hǎo ba, wǒmen zài qù nàbiān kànkan.","speaker":"王一雪","vi":"Được rồi, chúng ta qua bên kia xem thêm đi."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Vương Nhất Tuyết nói: \"儿子的裤子坏了，我们给他买条新的吧。\" (Quần của con trai hỏng rồi, chúng ta mua cho con một chiếc mới đi.), nên đáp án đúng là 因为儿子的裤子坏了.","options":["因为今天是儿子的生日","因为儿子的裤子坏了","因为儿子喜欢黑色的裤子","因为商店的裤子很便宜"],"q":"他们为什么要给儿子买新裤子？"},{"answerIdx":2,"explanation":"Trong bài, Lưu Minh nhận xét: \"没有你上次买的那条好看。\" (Không đẹp bằng chiếc lần trước em mua.) và \"儿子的个子没有他那么高，穿上就不会太好看。\" (Con trai không cao bằng cậu bé kia, mặc vào sẽ không đẹp lắm đâu.), nên đáp án đúng là 他觉得没有上次买的那条好看，儿子个子不够高.","options":["他觉得比上次买的那条好看","他觉得儿子穿上一定很好看","他觉得没有上次买的那条好看，儿子个子不够高","他觉得这条裤子太贵了"],"q":"关于那条黑色的裤子，刘明怎么看？"}],"scene":"在商店，王一雪和刘明在看裤子。","sceneVi":"Ở cửa hàng, Vương Nhất Tuyết và Lưu Minh đang xem quần."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"门口有家奶茶店。你想喝杯奶茶吗？","pinyin":"Ménkǒu yǒu jiā nǎichádiàn. Nǐ xiǎng hē bēi nǎichá ma?","speaker":"王一雪","vi":"Ngay cửa có một quán trà sữa. Anh có muốn uống một ly trà sữa không?"},{"hanzi":"我想喝咖啡，还是去咖啡店吧。","pinyin":"Wǒ xiǎng hē kāfēi, háishi qù kāfēidiàn ba.","speaker":"刘明","vi":"Anh muốn uống cà phê, hay là đi quán cà phê đi."},{"hanzi":"咖啡店离这儿有点儿远。","pinyin":"Kāfēidiàn lí zhèr yǒudiǎnr yuǎn.","speaker":"王一雪","vi":"Quán cà phê cách đây hơi xa."},{"hanzi":"没关系，那家店的咖啡很好喝。","pinyin":"Méi guānxi, nà jiā diàn de kāfēi hěn hǎo hē.","speaker":"刘明","vi":"Không sao đâu, cà phê ở quán đó rất ngon."},{"hanzi":"那你等一下，我去买杯奶茶。","pinyin":"Nà nǐ děng yíxià, wǒ qù mǎi bēi nǎichá.","speaker":"王一雪","vi":"Vậy anh đợi một chút, em đi mua ly trà sữa."},{"hanzi":"你不想喝咖啡吗？","pinyin":"Nǐ bù xiǎng hē kāfēi ma?","speaker":"刘明","vi":"Em không muốn uống cà phê à?"},{"hanzi":"喝了咖啡，晚上就别想睡觉了。","pinyin":"Hēle kāfēi, wǎnshang jiù bié xiǎng shuìjiào le.","speaker":"王一雪","vi":"Uống cà phê rồi thì tối đừng hòng ngủ được."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Lưu Minh nói: \"我想喝咖啡，还是去咖啡店吧。\" (Anh muốn uống cà phê, hay là đi quán cà phê đi.), nên đáp án đúng là 去那家咖啡店 (đến quán cà phê kia).","options":["去门口的奶茶店","去那家咖啡店","直接回家睡觉","去大商场看衣服"],"q":"从商店出来后，刘明想去哪儿？"},{"answerIdx":2,"explanation":"Trong bài, Vương Nhất Tuyết giải thích: \"喝了咖啡，晚上就别想睡觉了。\" (Uống cà phê rồi thì buổi tối đừng hòng ngủ được.), nên đáp án đúng là 因为喝了咖啡，她晚上就睡不着了.","options":["因为那家店的咖啡不好喝","因为咖啡太贵了","因为喝了咖啡，她晚上就睡不着了","因为咖啡店关门了"],"q":"王一雪为什么不想喝咖啡？"}],"scene":"在商店门口，王一雪和刘明往外走。","sceneVi":"Ở cửa cửa hàng, Vương Nhất Tuyết và Lưu Minh đang đi ra ngoài."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"我们打车回去吧。","pinyin":"Wǒmen dǎchē huíqù ba.","speaker":"刘明","vi":"Chúng ta bắt taxi về đi."},{"hanzi":"这里离家很近，还是走路吧。","pinyin":"Zhèlǐ lí jiā hěn jìn, háishi zǒulù ba.","speaker":"王一雪","vi":"Ở đây cách nhà rất gần, hay là đi bộ đi."},{"hanzi":"要走多长时间？","pinyin":"Yào zǒu duō cháng shíjiān?","speaker":"刘明","vi":"Phải đi bộ mất bao lâu?"},{"hanzi":"走半个多小时就到了。","pinyin":"Zǒu bàn gè duō xiǎoshí jiù dào le.","speaker":"王一雪","vi":"Đi hơn nửa tiếng là tới rồi."},{"hanzi":"好的。每天上下班都坐车，今天运动运动吧。","pinyin":"Hǎo de. Měi tiān shàng xià bān dōu zuò chē, jīntiān yùndòng yùndòng ba.","speaker":"刘明","vi":"Được đấy. Ngày nào đi làm và tan làm cũng ngồi xe, hôm nay vận động một chút đi."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Vương Nhất Tuyết trả lời: \"走半个多小时就到了。\" (Đi bộ hơn nửa tiếng là tới rồi.), nên đáp án đúng là 半个多小时 (hơn nửa tiếng).","options":["十分钟左右","半个多小时","两个小时","一刻钟"],"q":"王一雪说从这里走路回家要多长时间？"},{"answerIdx":2,"explanation":"Trong bài, Lưu Minh nói: \"好的。每天上下班都坐车，今天运动运动吧。\" (Được thôi. Ngày nào đi làm cũng ngồi xe, hôm nay vận động một chút đi.), nên đáp án đúng là 因为他每天坐车上下班，想借机运动运动.","options":["因为打车太贵了","因为外面打不到车","因为他每天坐车上下班，想借机运动运动","因为他想在路上再买件衣服"],"q":"刘明最后为什么同意走路回家？"}],"scene":"在咖啡店门口，王一雪和刘明在聊天儿。","sceneVi":"Ở cửa quán cà phê, Vương Nhất Tuyết và Lưu Minh đang trò chuyện."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"这周刘明休息，我下班后跟他去了一家商店。","pinyin":"Zhè zhōu Liú Míng xiūxi, wǒ xiàbān hòu gēn tā qùle yì jiā shāngdiàn.","speaker":"Đoạn văn","vi":"Tuần này Lưu Minh nghỉ làm, sau khi tan làm tôi đã cùng anh ấy đi một cửa hàng."},{"hanzi":"商店里边的衣服没有大商场里的好看。","pinyin":"Shāngdiàn lǐbian de yīfu méiyǒu dà shāngchǎng lǐ de hǎokàn.","speaker":"Đoạn văn","vi":"Quần áo bên trong cửa hàng không đẹp bằng ở trung tâm thương mại lớn."},{"hanzi":"我们没有买到喜欢的衣服，从商店出来就到咖啡店坐了坐。","pinyin":"Wǒmen méiyǒu mǎidào xǐhuan de yīfu, cóng shāngdiàn chūlái jiù dào kāfēidiàn zuòle zuò.","speaker":"Đoạn văn","vi":"Chúng tôi không mua được bộ quần áo nào ưng ý, ra khỏi cửa hàng liền đến quán cà phê ngồi một lát."},{"hanzi":"因为想运动运动，所以喝完东西，我们就走回家了。","pinyin":"Yīnwèi xiǎng yùndòng yùndòng, suǒyǐ hēwán dōngxi, wǒmen jiù zǒuhuí jiā le.","speaker":"Đoạn văn","vi":"Vì muốn vận động một chút, nên uống xong nước, chúng tôi đã đi bộ về nhà."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"我们没有买到喜欢的衣服，从商店出来就到咖啡店坐了坐。\" (Chúng tôi không mua được quần áo ưng ý, ra khỏi cửa hàng liền đến quán cà phê ngồi một lát.), nên đáp án đúng là 没有买到喜欢的衣服.","options":["买到了很多好看的衣服","没有买到喜欢的衣服","只买了一条黑色的裤子","买了一块漂亮的手表"],"q":"王一雪和刘明在商店买到喜欢的衣服了吗？"},{"answerIdx":2,"explanation":"Trong bài có câu \"因为想运动运动，所以喝完东西，我们就走回家了。\" (Vì muốn vận động một chút nên uống xong đồ uống, chúng tôi liền đi bộ về nhà.), nên đáp án đúng là 走路回家的 (đi bộ về nhà).","options":["打车回家的","坐公共汽车回家的","走路回家的","骑自行车回家的"],"q":"从咖啡店喝完东西后，他们是怎么回家的？"}],"scene":"在房间，王一雪在写日记。","sceneVi":"Trong phòng, Vương Nhất Tuyết đang viết nhật ký."}],"hsk2-10":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"小明，你们明天开学，你准备好了吗？","pinyin":"Xiǎomíng, nǐmen míngtiān kāixué, nǐ zhǔnbèi hǎo le ma?","speaker":"刘明","vi":"Tiểu Minh, ngày mai các con khai giảng rồi, con đã chuẩn bị xong chưa?"},{"hanzi":"明天就开学啊？爸爸，我的书包你看见了吗？","pinyin":"Míngtiān jiù kāixué a? Bàba, wǒ de shūbāo nǐ kànjiànle ma?","speaker":"刘小明","vi":"Ngày mai đã khai giảng rồi ạ? Bố ơi, bố có thấy cặp sách của con đâu không?"},{"hanzi":"书包在门后面。","pinyin":"Shūbāo zài mén hòumiàn.","speaker":"刘明","vi":"Cặp sách ở đằng sau cửa."},{"hanzi":"书在哪儿呢？笔呢？","pinyin":"Shū zài nǎr ne? Bǐ ne?","speaker":"刘小明","vi":"Sách ở đâu ạ? Còn bút nữa ạ?"},{"hanzi":"书在床上，笔在桌子上。","pinyin":"Shū zài chuáng shang, bǐ zài zhuōzi shang.","speaker":"刘明","vi":"Sách ở trên giường, bút ở trên bàn."},{"hanzi":"太好了！现在都准备好了。","pinyin":"Tài hǎo le! Xiànzài dōu zhǔnbèi hǎo le.","speaker":"刘小明","vi":"Tuyệt quá! Bây giờ đều chuẩn bị xong hết rồi ạ."},{"hanzi":"这次爸爸帮你，下次你自己准备，好不好？","pinyin":"Zhè cì bàba bāng nǐ, xià cì nǐ zìjǐ zhǔnbèi, hǎo bu hǎo?","speaker":"刘明","vi":"Lần này bố giúp con, lần sau con tự chuẩn bị nhé, được không?"},{"hanzi":"好！","pinyin":"Hǎo!","speaker":"刘小明","vi":"Vâng ạ!"}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Lưu Minh đã nói với con trai \"书包在门后面。\" (Cặp sách ở phía sau cửa), còn sách ở trên giường và bút ở trên bàn, nên đáp án đúng là 在门后面.","options":["在床上","在门后面","在桌子上","在椅子下面"],"q":"刘小明的书包在哪儿？"},{"answerIdx":2,"explanation":"Trong bài có câu \"这次爸爸帮你，下次你自己准备，好不好？\" (Lần này bố giúp con, lần sau con tự chuẩn bị, được không?), nên lần sau Lưu Tiểu Minh phải tự chuẩn bị đồ dùng học tập của mình.","options":["让姐姐帮他准备","买新的书包和笔","自己准备学习的东西","早一点儿去学校"],"q":"爸爸让刘小明下次怎么做？"}],"scene":"在房间，刘明在帮刘小明准备东西。","sceneVi":"Trong phòng, Lưu Minh đang giúp Lưu Tiểu Minh chuẩn bị đồ đạc."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"小雪，你在做什么呢？","pinyin":"Xiǎoxuě, nǐ zài zuò shénme ne?","speaker":"王一雪","vi":"Tiểu Tuyết, con đang làm gì thế?"},{"hanzi":"明天考试，我在看书呢。","pinyin":"Míngtiān kǎoshì, wǒ zài kàn shū ne.","speaker":"刘小雪","vi":"Ngày mai thi rồi, con đang đọc sách ạ."},{"hanzi":"这些词要好好看看。","pinyin":"Zhèxiē cí yào hǎohǎo kànkan.","speaker":"王一雪","vi":"Những từ này phải xem cho kỹ vào."},{"hanzi":"我看过了，意思也都懂了。","pinyin":"Wǒ kànguo le, yìsi yě dōu dǒng le.","speaker":"刘小雪","vi":"Con xem qua rồi, nghĩa cũng hiểu hết rồi ạ."},{"hanzi":"你的本子呢？本子上做错的题也要看一看。","pinyin":"Nǐ de běnzi ne? Běnzi shang zuòcuò de tí yě yào kàn yi kàn.","speaker":"王一雪","vi":"Vở của con đâu? Những câu làm sai trong vở cũng phải xem lại một chút."},{"hanzi":"妈妈，是您准备考试还是我准备考试？","pinyin":"Māma, shì nín zhǔnbèi kǎoshì háishi wǒ zhǔnbèi kǎoshì?","speaker":"刘小雪","vi":"Mẹ ơi, là mẹ chuẩn bị thi hay con chuẩn bị thi vậy ạ?"}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài, mẹ Vương Nhất Tuyết nói \"你的本子呢？本子上做错的题也要看一看。\" (Vở của con đâu? Những câu làm sai trên vở cũng phải xem qua một chút), nên ngoài từ mới còn phải xem lại câu làm sai trên vở.","options":["本子上做错的题","昨天的报纸","新的中文书","弟弟的本子"],"q":"除了这些词以外，妈妈还让小雪看什么？"},{"answerIdx":0,"explanation":"Trong bài, Tiểu Tuyết đã xem sách và hiểu hết nghĩa các từ mới (\"我看过了，意思也都懂了。\"), nhưng mẹ vẫn liên tục dặn xem cái này cái kia nên cô bé nói đùa hỏi lại như vậy vì mẹ cứ nhắc mãi.","options":["因为妈妈一直告诉她要看什么","因为妈妈明天也要考试","因为她没有看懂这些词","因为她找不到自己的本子"],"q":"小雪为什么问“是您准备考试还是我准备考试”？"}],"scene":"在房间，王一雪和刘小雪在聊学习。","sceneVi":"Trong phòng, Vương Nhất Tuyết và Lưu Tiểu Tuyết đang nói chuyện học hành."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"妈妈，我回来了！","pinyin":"Māma, wǒ huílái le!","speaker":"刘小雪","vi":"Mẹ ơi, con về rồi ạ!"},{"hanzi":"我买了奶茶，就在桌子上，自己去拿吧。","pinyin":"Wǒ mǎile nǎichá, jiù zài zhuōzi shang, zìjǐ qù ná ba.","speaker":"王一雪","vi":"Mẹ có mua trà sữa đấy, ở ngay trên bàn, tự ra lấy đi con."},{"hanzi":"谢谢妈妈！","pinyin":"Xièxie māma!","speaker":"刘小雪","vi":"Con cảm ơn mẹ ạ!"},{"hanzi":"今天考试考得怎么样？","pinyin":"Jīntiān kǎoshì kǎo de zěnmeyàng?","speaker":"王一雪","vi":"Hôm nay con thi thế nào?"},{"hanzi":"我觉得比上次好。","pinyin":"Wǒ juéde bǐ shàng cì hǎo.","speaker":"刘小雪","vi":"Con thấy làm tốt hơn lần trước ạ."},{"hanzi":"真不错！饭菜快要做好了，你叫弟弟一起去洗手吧。","pinyin":"Zhēn búcuò! Fàncài kuàiyào zuòhǎo le, nǐ jiào dìdi yìqǐ qù xǐshǒu ba.","speaker":"王一雪","vi":"Giỏi lắm! Cơm sắp nấu xong rồi, con gọi em trai cùng đi rửa tay đi."},{"hanzi":"妈妈，我是第一名，姐姐还没洗完呢。","pinyin":"Māma, wǒ shì dì-yī míng, jiějie hái méi xǐwán ne.","speaker":"刘小明","vi":"Mẹ ơi, con về nhất rồi, chị vẫn chưa rửa xong đâu ạ."},{"hanzi":"你洗得真快啊！","pinyin":"Nǐ xǐ de zhēn kuài a!","speaker":"王一雪","vi":"Con rửa nhanh thật đấy!"}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, khi mẹ hỏi bài thi hôm nay thế nào, Lưu Tiểu Tuyết trả lời \"我觉得比上次好。\" (Con thấy tốt hơn lần trước), nên đáp án đúng là 比上次考得好.","options":["比上次差一点儿","比上次考得好","和上次一样","题太多，没做完"],"q":"刘小雪觉得今天的考试怎么样？"},{"answerIdx":2,"explanation":"Trong bài, Lưu Tiểu Minh khoe với mẹ \"妈妈，我是第一名，姐姐还没洗完呢。\" (Mẹ ơi, con về nhất rồi, chị vẫn chưa rửa xong đâu) và được mẹ khen rửa rất nhanh, nên em trai rửa xong trước chị gái.","options":["妈妈洗得最快","姐姐比弟弟先洗完","弟弟比姐姐先洗完","他们两个一起洗完"],"q":"姐姐和弟弟去洗手的时候，谁洗得更快？"}],"scene":"在客厅，王一雪和孩子们在聊天儿。","sceneVi":"Ở phòng khách, Vương Nhất Tuyết và các con đang trò chuyện."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"快要开学了，爸爸帮弟弟准备书包、本子和笔。","pinyin":"Kuàiyào kāixué le, bàba bāng dìdi zhǔnbèi shūbāo, běnzi hé bǐ.","speaker":"Đoạn văn","vi":"Sắp khai giảng rồi, bố giúp em trai chuẩn bị cặp sách, vở và bút."},{"hanzi":"我就要考试了，妈妈让我看书、看做错的题。","pinyin":"Wǒ jiù yào kǎoshì le, māma ràng wǒ kàn shū, kàn zuòcuò de tí.","speaker":"Đoạn văn","vi":"Tôi sắp thi rồi, mẹ bảo tôi đọc sách và xem lại những câu làm sai."},{"hanzi":"我们上学，爸爸、妈妈比我们还忙。","pinyin":"Wǒmen shàngxué, bàba, māma bǐ wǒmen hái máng.","speaker":"Đoạn văn","vi":"Chúng tôi đi học, bố mẹ còn bận rộn hơn cả chúng tôi."},{"hanzi":"我问他们：“是我和弟弟上学还是你们上学？”","pinyin":"Wǒ wèn tāmen: “Shì wǒ hé dìdi shàngxué háishi nǐmen shàngxué?”","speaker":"Đoạn văn","vi":"Tôi hỏi bố mẹ: “Là con và em trai đi học hay là bố mẹ đi học vậy ạ?”"},{"hanzi":"我问完，他们都笑了。","pinyin":"Wǒ wènwán, tāmen dōu xiào le.","speaker":"Đoạn văn","vi":"Tôi hỏi xong, bố mẹ đều bật cười."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài có câu \"快要开学了，爸爸帮弟弟准备书包、本子和笔。\" (Sắp khai giảng rồi, bố giúp em trai chuẩn bị cặp sách, vở và bút), nên lý do là vì em trai sắp khai giảng.","options":["因为弟弟快要开学了","因为弟弟的书包丢了","因为弟弟明天要考试","因为弟弟今天去买东西"],"q":"爸爸为什么帮弟弟准备书包、本子和笔？"},{"answerIdx":1,"explanation":"Trong bài, thấy bố mẹ còn bận rộn hơn hai chị em, Tiểu Tuyết hỏi đùa \"是我和弟弟上学还是你们上学？\" (Là con và em trai đi học hay là bố mẹ đi học ạ?), và \"我问完，他们都笑了。\" (Con hỏi xong, bố mẹ đều bật cười) vì câu hỏi rất thú vị.","options":["因为弟弟考试考了第一名","因为小雪的问题很有意思","因为他们买到了好喝的奶茶","因为小雪不用去上学了"],"q":"日记的最后，爸爸和妈妈为什么都笑了？"}],"scene":"在房间，刘小雪在写日记。","sceneVi":"Trong phòng, Lưu Tiểu Tuyết đang viết nhật ký."}],"hsk2-11":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"家月，都下课了，你怎么还不回家？","pinyin":"Jiāyuè, dōu xiàkè le, nǐ zěnme hái bù huí jiā?","speaker":"王一飞","vi":"Gia Nguyệt, tan học cả rồi, sao em vẫn chưa về nhà?"},{"hanzi":"我头疼，不太舒服。","pinyin":"Wǒ tóu téng, bú tài shūfu.","speaker":"白家月","vi":"Em bị đau đầu, không được khỏe lắm."},{"hanzi":"你这几天经常头疼，去医院看看吧。","pinyin":"Nǐ zhè jǐ tiān jīngcháng tóu téng, qù yīyuàn kànkan ba.","speaker":"王一飞","vi":"Mấy hôm nay em hay bị đau đầu, đi bệnh viện khám xem sao nhé."},{"hanzi":"我想休息一下，现在不能动，一动就疼。","pinyin":"Wǒ xiǎng xiūxi yíxià, xiànzài bù néng dòng, yí dòng jiù téng.","speaker":"白家月","vi":"Em muốn nghỉ ngơi một chút, bây giờ không cử động được, cứ cử động là đau."},{"hanzi":"那你在这儿坐着，我去开车，一会儿送你去医院。","pinyin":"Nà nǐ zài zhèr zuòzhe, wǒ qù kāichē, yíhuìr sòng nǐ qù yīyuàn.","speaker":"王一飞","vi":"Vậy em ngồi đây đi, cô đi lấy xe, lát nữa đưa em đi bệnh viện."},{"hanzi":"谢谢王老师。","pinyin":"Xièxie Wáng lǎoshī.","speaker":"白家月","vi":"Cảm ơn cô Vương ạ."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Bạch Gia Nguyệt nói với cô Vương \"我头疼，不太舒服。\" (Em bị đau đầu, không được khỏe lắm) và muốn ngồi nghỉ vì hễ cử động là đau.","options":["因为她在等李文一起走","因为她头疼，身体不太舒服","因为她要在教室写作业","因为外面正在下大雨"],"q":"下课以后，白家月为什么还没回家？"},{"answerIdx":2,"explanation":"Trong bài, cô Vương Nhất Phi nói \"那你在这儿坐着，我去开车，一会儿送你去医院。\" (Vậy em ngồi đây nhé, cô đi lấy xe, lát nữa đưa em đi bệnh viện), nên cô sẽ lái xe đưa Gia Nguyệt đi bệnh viện.","options":["去药店帮她买药","给她的妈妈打电话","开车送她去医院","陪她在教室休息"],"q":"王老师打算怎么帮助白家月？"}],"scene":"在教室，王一飞和白家月在聊天儿。","sceneVi":"Trong phòng học, Vương Nhất Phi và Bạch Gia Nguyệt đang trò chuyện."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"现在路上车多，还下着雪，我开慢一点儿。","pinyin":"Xiànzài lùshang chē duō, hái xiàzhe xuě, wǒ kāi màn yìdiǎnr.","speaker":"王一飞","vi":"Bây giờ trên đường nhiều xe, trời lại đang có tuyết rơi, cô lái chậm một chút."},{"hanzi":"没问题，现在头没那么疼了。","pinyin":"Méi wèntí, xiànzài tóu méi nàme téng le.","speaker":"白家月","vi":"Không sao đâu ạ, bây giờ đầu em đỡ đau hơn nhiều rồi."},{"hanzi":"好。李文来电话了，你帮我接一下。","pinyin":"Hǎo. Lǐ Wén lái diànhuà le, nǐ bāng wǒ jiē yíxià.","speaker":"王一飞","vi":"Được. Lý Văn gọi điện tới kìa, em nghe máy giúp cô với."},{"hanzi":"喂，李文，王老师开着车呢，你找她有事吗？","pinyin":"Wèi, Lǐ Wén, Wáng lǎoshī kāizhe chē ne, nǐ zhǎo tā yǒu shì ma?","speaker":"白家月","vi":"Alo, Lý Văn à, cô Vương đang lái xe, cậu tìm cô có việc gì không?"},{"hanzi":"没什么事。今天雪这么大，你们开车去哪儿啊？","pinyin":"Méi shénme shì. Jīntiān xuě zhème dà, nǐmen kāichē qù nǎr a?","speaker":"李文","vi":"Không có việc gì quan trọng đâu. Hôm nay tuyết rơi to thế này, hai người lái xe đi đâu vậy?"},{"hanzi":"去医院，我头有点儿疼。","pinyin":"Qù yīyuàn, wǒ tóu yǒudiǎnr téng.","speaker":"白家月","vi":"Đi bệnh viện, mình hơi đau đầu một chút."},{"hanzi":"那我一会儿去看看你。","pinyin":"Nà wǒ yíhuìr qù kànkan nǐ.","speaker":"李文","vi":"Vậy lát nữa mình qua thăm cậu nhé."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài có câu \"现在路上车多，还下着雪，我开慢一点儿。\" (Bây giờ trên đường nhiều xe, trời lại đang có tuyết rơi, cô lái chậm một chút), nên đó là nguyên nhân cô Vương lái xe chậm.","options":["因为路上的车很多，而且在下雪","因为她不知道医院怎么走","因为她在接李文的电话","因为白家月说头越来越疼"],"q":"王老师为什么把车开得慢一点儿？"},{"answerIdx":1,"explanation":"Trong bài, khi nghe Bạch Gia Nguyệt nói đang đi bệnh viện vì đau đầu, Lý Văn liền trả lời \"那我一会儿去看看你。\" (Vậy lát nữa mình qua thăm cậu nhé).","options":["去学校帮她请假","过一会儿去看望白家月","给白家月买点儿水果","请王老师帮忙买药"],"q":"李文知道白家月去医院以后，打算怎么做？"}],"scene":"在王一飞车里，王一飞和白家月在聊天儿，李文打来一个电话。","sceneVi":"Trong xe của Vương Nhất Phi, Vương Nhất Phi và Bạch Gia Nguyệt đang trò chuyện thì Lý Văn gọi điện tới."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"李文，快请进！","pinyin":"Lǐ Wén, kuài qǐng jìn!","speaker":"白家月","vi":"Lý Văn, mau vào đi!"},{"hanzi":"家月，你怎么样了？头还疼吗？","pinyin":"Jiāyuè, nǐ zěnmeyàng le? Tóu hái téng ma?","speaker":"李文","vi":"Gia Nguyệt, cậu sao rồi? Đầu còn đau không?"},{"hanzi":"不那么疼了。医生开了一些药，吃完就好多了。","pinyin":"Bú nàme téng le. Yīshēng kāile yìxiē yào, chīwán jiù hǎoduō le.","speaker":"白家月","vi":"Không đau như trước nữa rồi. Bác sĩ kê cho một ít thuốc, uống xong là đỡ hơn nhiều rồi."},{"hanzi":"那就好！","pinyin":"Nà jiù hǎo!","speaker":"李文","vi":"Thế thì tốt quá!"},{"hanzi":"家月，你想不想吃点儿东西？","pinyin":"Jiāyuè, nǐ xiǎng bu xiǎng chī diǎnr dōngxi?","speaker":"王一飞","vi":"Gia Nguyệt, em có muốn ăn chút gì không?"},{"hanzi":"吃点儿吧，身体不舒服时更要好好吃饭。","pinyin":"Chī diǎnr ba, shēntǐ bù shūfu shí gèng yào hǎohāo chī fàn.","speaker":"李文","vi":"Ăn chút đi, lúc cơ thể không khỏe càng phải ăn uống đàng hoàng."},{"hanzi":"吃点儿什么呢？","pinyin":"Chī diǎnr shénme ne?","speaker":"白家月","vi":"Ăn món gì bây giờ ạ?"},{"hanzi":"你最喜欢吃中国菜，我做几个中国菜吧。","pinyin":"Nǐ zuì xǐhuan chī Zhōngguó cài, wǒ zuò jǐ gè Zhōngguó cài ba.","speaker":"王一飞","vi":"Em thích ăn món Trung Quốc nhất, để cô nấu vài món Trung Quốc nhé."},{"hanzi":"好的，谢谢王老师。","pinyin":"Hǎo de, xièxie Wáng lǎoshī.","speaker":"白家月","vi":"Vâng ạ, cảm ơn cô Vương."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài, Bạch Gia Nguyệt trả lời Lý Văn \"不那么疼了。医生开了一些药，吃完就好多了。\" (Không đau như trước nữa rồi. Bác sĩ kê cho một ít thuốc, uống xong thì đỡ nhiều rồi).","options":["因为她喝了很多热茶","因为她睡了一整天","因为她吃了医生开的药","因为李文带她去外面散步"],"q":"白家月的头为什么没有以前那么疼了？"},{"answerIdx":0,"explanation":"Trong bài, cô Vương Nhất Phi nói với Bạch Gia Nguyệt \"你最喜欢吃中国菜，我做几个中国菜吧。\" (Em thích ăn món Trung Quốc nhất, cô làm vài món Trung Quốc nhé), nên đáp án đúng là 几个中国菜.","options":["几个中国菜","一碗面条","几个面包","一点儿水果"],"q":"王一飞老师打算给白家月做什么吃的？"}],"scene":"在房间，李文来看望白家月。","sceneVi":"Trong phòng, Lý Văn đến thăm Bạch Gia Nguyệt."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"我这几天经常头疼，从药店买了点儿药，没去医院。","pinyin":"Wǒ zhè jǐ tiān jīngcháng tóu téng, cóng yàodiàn mǎile diǎnr yào, méi qù yīyuàn.","speaker":"Đoạn văn","vi":"Mấy hôm nay tôi thường xuyên bị đau đầu, đã mua một ít thuốc ở hiệu thuốc chứ không đi bệnh viện."},{"hanzi":"今天下课后，王老师看我不舒服，就送我去医院了。","pinyin":"Jīntiān xiàkè hòu, Wáng lǎoshī kàn wǒ bù shūfu, jiù sòng wǒ qù yīyuàn le.","speaker":"Đoạn văn","vi":"Hôm nay sau khi tan học, cô Vương thấy tôi không khỏe nên đã đưa tôi đến bệnh viện."},{"hanzi":"从医院回来，李文也来看我了。","pinyin":"Cóng yīyuàn huílái, Lǐ Wén yě lái kàn wǒ le.","speaker":"Đoạn văn","vi":"Từ bệnh viện trở về, Lý Văn cũng đã đến thăm tôi."},{"hanzi":"现在他们都回去了，我也要睡觉了。","pinyin":"Xiànzài tāmen dōu huíqù le, wǒ yě yào shuìjiào le.","speaker":"Đoạn văn","vi":"Bây giờ họ đều đã về rồi, tôi cũng chuẩn bị đi ngủ đây."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"我这几天经常头疼，从药店买了点儿药，没去医院。\" (Mấy hôm nay tôi thường xuyên đau đầu, mua chút thuốc ở hiệu thuốc chứ không đi bệnh viện), nên trước hôm nay cô ấy tự mua thuốc ở hiệu thuốc.","options":["天天去医院看医生","自己从药店买了点儿药","在家休息，什么药也没吃","让李文开车送她去医院"],"q":"今天以前，白家月头疼的时候做了什么？"},{"answerIdx":2,"explanation":"Ở câu cuối nhật ký, Bạch Gia Nguyệt viết \"现在他们都回去了，我也要睡觉了。\" (Bây giờ mọi người đều về hết rồi, tôi cũng phải đi ngủ đây), nên cô ấy chuẩn bị đi ngủ.","options":["再吃一次药","出去送李文回家","上床睡觉","给王老师打电话"],"q":"写日记的时候，白家月接下来打算做什么？"}],"scene":"在房间，白家月在写日记。","sceneVi":"Trong phòng, Bạch Gia Nguyệt đang viết nhật ký."}],"hsk2-12":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"喂，家月，是你啊！有什么事情吗？","pinyin":"Wèi, Jiāyuè, shì nǐ a! Yǒu shénme shìqing ma?","speaker":"王一雪","vi":"Alo, Gia Nguyệt à, là cháu đấy à! Có chuyện gì thế?"},{"hanzi":"没什么事，就想跟您说说话。","pinyin":"Méi shénme shì, jiù xiǎng gēn nín shuōshuo huà.","speaker":"白家月","vi":"Không có chuyện gì đâu ạ, cháu chỉ muốn trò chuyện với cô một chút thôi."},{"hanzi":"好啊。你今天没课吗？","pinyin":"Hǎo a. Nǐ jīntiān méi kè ma?","speaker":"王一雪","vi":"Được chứ. Hôm nay cháu không có tiết học à?"},{"hanzi":"下午有课。您那里天气怎么样？","pinyin":"Xiàwǔ yǒu kè. Nín nàlǐ tiānqì zěnmeyàng?","speaker":"白家月","vi":"Buổi chiều cháu có tiết ạ. Thời tiết ở chỗ cô thế nào ạ?"},{"hanzi":"北京这几天虽然是晴天，但是有点儿冷。","pinyin":"Běijīng zhè jǐ tiān suīrán shì qíng tiān, dànshì yǒudiǎnr lěng.","speaker":"王一雪","vi":"Bắc Kinh mấy hôm nay tuy là trời nắng nhưng hơi lạnh một chút."},{"hanzi":"我这里比北京冷多了，外边还正下着雪呢！","pinyin":"Wǒ zhèlǐ bǐ Běijīng lěngduō le, wàibian hái zhèng xiàzhe xuě ne!","speaker":"白家月","vi":"Ở chỗ cháu lạnh hơn Bắc Kinh nhiều lắm, bên ngoài trời còn đang rơi tuyết nữa cơ!"}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài, Vương Nhất Tuyết nói \"北京这几天虽然是晴天，但是有点儿冷。\" (Bắc Kinh mấy hôm nay tuy trời nắng nhưng hơi lạnh), nên đáp án đúng là 是晴天，但是有点儿冷.","options":["是晴天，但是有点儿冷","一直阴天，还下着雪","很热，天天都是大晴天","刮大风，也下了雨"],"q":"北京这几天的天气怎么样？"},{"answerIdx":2,"explanation":"Trong bài, Bạch Gia Nguyệt nói \"我这里比北京冷多了，外边还正下着雪呢！\" (Chỗ cháu lạnh hơn Bắc Kinh nhiều, bên ngoài trời còn đang có tuyết rơi nữa!), nên đáp án đúng là 比北京冷多了，而且正在下雪.","options":["比北京暖和多了","和北京一样冷","比北京冷多了，而且正在下雪","没有北京那么冷，但是下雨了"],"q":"跟北京比，白家月那里的天气怎么样？"}],"scene":"在房间，王一雪接到白家月的电话。","sceneVi":"Trong phòng, Vương Nhất Tuyết nhận được cuộc gọi từ Bạch Gia Nguyệt."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"喂，一飞，听家月说你那边下雪了，下得大不大？","pinyin":"Wèi, Yīfēi, tīng Jiāyuè shuō nǐ nàbiān xià xuě le, xià de dà bu dà?","speaker":"王一雪","vi":"Alo, Nhất Phi à, nghe Gia Nguyệt nói bên chỗ em có tuyết rơi rồi, rơi có to không?"},{"hanzi":"今天不大，昨天比今天下得大。","pinyin":"Jīntiān bú dà, zuótiān bǐ jīntiān xià de dà.","speaker":"王一飞","vi":"Hôm nay không to lắm, hôm qua rơi to hơn hôm nay."},{"hanzi":"天气不好，你去外面的时候多穿点儿衣服。","pinyin":"Tiānqì bù hǎo, nǐ qù wàimiàn de shíhou duō chuān diǎnr yīfu.","speaker":"王一雪","vi":"Thời tiết không tốt, khi ra ngoài em nhớ mặc thêm nhiều quần áo vào nhé."},{"hanzi":"这几天我在网上上课，没出去过。","pinyin":"Zhè jǐ tiān wǒ zài wǎngshang shàngkè, méi chūqùguo.","speaker":"王一飞","vi":"Mấy hôm nay em dạy học trực tuyến nên chưa ra ngoài lần nào."},{"hanzi":"那就好，有事记得给我打电话。","pinyin":"Nà jiù hǎo, yǒu shì jìde gěi wǒ dǎ diànhuà.","speaker":"王一雪","vi":"Thế thì tốt rồi, có việc gì nhớ gọi điện cho chị nhé."},{"hanzi":"好的。现在不下雪了，我出去买点儿吃的。","pinyin":"Hǎo de. Xiànzài bú xià xuě le, wǒ chūqù mǎi diǎnr chī de.","speaker":"王一飞","vi":"Vâng ạ. Bây giờ hết tuyết rơi rồi, em ra ngoài mua chút đồ ăn."},{"hanzi":"一次多买点儿，阴天下雪什么的就少出去吧。","pinyin":"Yí cì duō mǎi diǎnr, yīn tiān xià xuě shénmede jiù shǎo chūqù ba.","speaker":"王一雪","vi":"Mua một lần nhiều một chút, trời âm u hay tuyết rơi thì hạn chế ra ngoài nhé."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài, Vương Nhất Phi giải thích \"这几天我在网上上课，没出去过。\" (Mấy hôm nay em dạy học trên mạng, chưa từng ra ngoài), nên đáp án đúng là 因为她在网上上课.","options":["因为她在网上上课","因为她的车坏了","因为她生病了，头疼","因为家里有很多吃的"],"q":"王一飞这几天为什么没出去过？"},{"answerIdx":2,"explanation":"Trong bài, Vương Nhất Tuyết dặn dò \"一次多买点儿，阴天下雪什么的就少出去吧。\" (Mua nhiều một chút trong một lần, trời âm u hay tuyết rơi thì ít ra ngoài thôi), nên đáp án đúng là 一次多买点儿，天气不好时少出去.","options":["顺便买一件新衣服","坐地铁去超市，别开车","一次多买点儿，天气不好时少出去","买完吃的马上给家月打电话"],"q":"王一雪让王一飞去买东西的时候注意什么？"}],"scene":"在客厅，王一雪给王一飞打电话。","sceneVi":"Trong phòng khách, Vương Nhất Tuyết gọi điện thoại cho Vương Nhất Phi."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"喂，家月，今天天气不错，我们去跑步吧！","pinyin":"Wèi, Jiāyuè, jīntiān tiānqì búcuò, wǒmen qù pǎobù ba!","speaker":"李文","vi":"Alo, Gia Nguyệt à, hôm nay thời tiết khá đẹp, chúng mình đi chạy bộ đi!"},{"hanzi":"你跑步跑得比我快，我们能一起跑吗？","pinyin":"Nǐ pǎobù pǎo de bǐ wǒ kuài, wǒmen néng yìqǐ pǎo ma?","speaker":"白家月","vi":"Cậu chạy bộ nhanh hơn mình, chúng mình có chạy cùng nhau được không?"},{"hanzi":"可以的，我慢慢跑，等着你。","pinyin":"Kěyǐ de, wǒ mànmàn pǎo, děngzhe nǐ.","speaker":"李文","vi":"Được chứ, mình chạy chầm chậm rồi đợi cậu."},{"hanzi":"好吧。你真爱跑步啊！","pinyin":"Hǎo ba. Nǐ zhēn ài pǎobù a!","speaker":"白家月","vi":"Được thôi. Cậu đúng là thích chạy bộ thật đấy!"},{"hanzi":"我从小就经常跟爸爸跑步，跑步能让人快乐！","pinyin":"Wǒ cóngxiǎo jiù jīngcháng gēn bàba pǎobù, pǎobù néng ràng rén kuàilè!","speaker":"李文","vi":"Từ nhỏ mình đã thường xuyên chạy bộ cùng bố, chạy bộ có thể khiến người ta vui vẻ!"},{"hanzi":"好，那我准备一下。","pinyin":"Hǎo, nà wǒ zhǔnbèi yíxià.","speaker":"白家月","vi":"Ừ, vậy để mình chuẩn bị một chút."},{"hanzi":"我现在坐地铁去找你，一会儿楼下见。","pinyin":"Wǒ xiànzài zuò dìtiě qù zhǎo nǐ, yíhuìr lóu xià jiàn.","speaker":"李文","vi":"Bây giờ mình đi tàu điện ngầm qua tìm cậu, lát nữa gặp dưới tòa nhà nhé."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài, Lý Văn nói \"今天天气不错，我们去跑步吧！\" (Hôm nay thời tiết đẹp đấy, chúng ta đi chạy bộ đi!) và giải thích \"跑步能让人快乐！\" (Chạy bộ có thể khiến người ta vui vẻ!).","options":["因为今天天气不错，而且他觉得跑步能让人快乐","因为他们明天有跑步比赛","因为李文想早点儿去学校","因为家月请他教自己跑步"],"q":"李文为什么邀请白家月一起去跑步？"},{"answerIdx":1,"explanation":"Ở câu cuối bài, Lý Văn nói \"我现在坐地铁去找你，一会儿楼下见。\" (Bây giờ mình đi tàu điện ngầm qua chỗ cậu, lát nữa gặp nhau dưới lầu nhé), nên phương tiện là tàu điện ngầm và điểm hẹn là dưới lầu.","options":["他走路去，在学校门口见","他坐地铁去，在楼下见","他开车去，在公园里见","他坐公交车去，在教室见"],"q":"李文怎么去找白家月，两个人在哪儿见面？"}],"scene":"在房间，李文给白家月打电话。","sceneVi":"Trong phòng, Lý Văn gọi điện thoại cho Bạch Gia Nguyệt."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"前几天天气不好，我没走路，每天坐两站地铁去学校。","pinyin":"Qián jǐ tiān tiānqì bù hǎo, wǒ méi zǒulù, měitiān zuò liǎng zhàn dìtiě qù xuéxiào.","speaker":"Đoạn văn","vi":"Mấy hôm trước thời tiết không tốt, tôi không đi bộ mà mỗi ngày đi tàu điện ngầm hai trạm đến trường."},{"hanzi":"今天是个大晴天，李文让我跟他去外面跑步。","pinyin":"Jīntiān shì gè dà qíng tiān, Lǐ Wén ràng wǒ gēn tā qù wàimiàn pǎobù.","speaker":"Đoạn văn","vi":"Hôm nay là một ngày nắng đẹp, Lý Văn rủ tôi cùng cậu ấy ra ngoài chạy bộ."},{"hanzi":"他小时候经常跑步，跑得比我快，但是他会等我。","pinyin":"Tā xiǎoshíhou jīngcháng pǎobù, pǎo de bǐ wǒ kuài, dànshì tā huì děng wǒ.","speaker":"Đoạn văn","vi":"Hồi nhỏ cậu ấy thường xuyên chạy bộ, chạy nhanh hơn tôi, nhưng cậu ấy sẽ đợi tôi."},{"hanzi":"跟李文一起跑步，我好高兴啊！","pinyin":"Gēn Lǐ Wén yìqǐ pǎobù, wǒ hǎo gāoxìng a!","speaker":"Đoạn văn","vi":"Chạy bộ cùng Lý Văn, tôi vui lắm!"}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài có câu \"前几天天气不好，我没走路，每天坐两站地铁去学校。\" (Mấy hôm trước thời tiết không tốt, tôi không đi bộ mà mỗi ngày đi hai trạm tàu điện ngầm đến trường).","options":["坐两站地铁去学校","走路去学校","跟李文一起跑步去","坐王老师的车去"],"q":"前几天天气不好的时候，白家月怎么去学校？"},{"answerIdx":1,"explanation":"Ở câu cuối nhật ký, Bạch Gia Nguyệt viết \"跟李文一起跑步，我好高兴啊！\" (Chạy bộ cùng Lý Văn, tôi vui lắm!), nên cảm nhận của cô là rất vui.","options":["觉得太累了","觉得非常高兴","觉得天气还是有点儿冷","觉得自己跑得比李文快"],"q":"今天跟李文一起跑步，白家月觉得怎么样？"}],"scene":"在房间，白家月在写日记。","sceneVi":"Trong phòng, Bạch Gia Nguyệt đang viết nhật ký."}],"hsk2-13":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"时间过得真快啊！新年就要到了。","pinyin":"Shíjiān guò de zhēn kuài a! Xīnnián jiù yào dào le.","speaker":"白家月","vi":"Thời gian trôi qua thật nhanh! Năm mới sắp đến rồi."},{"hanzi":"这一年王老师教我们中文，每天工作都很累。","pinyin":"Zhè yì nián Wáng lǎoshī jiāo wǒmen Zhōngwén, měi tiān gōngzuò dōu hěn lèi.","speaker":"陈天中","vi":"Một năm qua cô Vương dạy chúng ta tiếng Trung, ngày nào làm việc cũng rất mệt."},{"hanzi":"是啊，她教得很好。因为她，我们都非常爱上中文课。","pinyin":"Shì a, tā jiāo de hěn hǎo. Yīnwèi tā, wǒmen dōu fēicháng ài shàng Zhōngwén kè.","speaker":"白家月","vi":"Đúng vậy, cô ấy dạy rất hay. Vì cô ấy, chúng ta đều rất thích đi học tiết tiếng Trung."},{"hanzi":"我们给她准备个新年礼物吧。你觉得送给她什么好呢？","pinyin":"Wǒmen gěi tā zhǔnbèi gè xīnnián lǐwù ba. Nǐ juéde sòng gěi tā shénme hǎo ne?","speaker":"陈天中","vi":"Chúng ta chuẩn bị cho cô ấy một món quà năm mới đi. Bạn thấy tặng cô ấy cái gì thì tốt nhỉ?"},{"hanzi":"王老师喜欢花，就送给她花吧。","pinyin":"Wáng lǎoshī xǐhuan huā, jiù sòng gěi tā huā ba.","speaker":"白家月","vi":"Cô Vương thích hoa, vậy tặng cô ấy hoa đi."},{"hanzi":"那我们去花店看看，现在买花的人多，希望花店还有漂亮的花。","pinyin":"Nà wǒmen qù huādiàn kànkan, xiànzài mǎi huā de rén duō, xīwàng huādiàn hái yǒu piàoliang de huā.","speaker":"陈天中","vi":"Vậy chúng ta đến tiệm hoa xem thử đi, bây giờ người mua hoa đông, hy vọng tiệm hoa vẫn còn hoa đẹp."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Bạch Gia Nguyệt nói \"王老师喜欢花，就送给她花吧。\" (Cô Vương thích hoa, vậy thì tặng hoa cho cô đi) và Trần Thiên Trung đồng ý, nên món quà họ muốn tặng là hoa.","options":["一个新本子","一些花","一个咖啡杯","一些中文书"],"q":"同学们想给王老师准备什么新年礼物？"},{"answerIdx":2,"explanation":"Ở cuối bài, Trần Thiên Trung nói \"那我们去花店看看，现在买花的人多，希望花店还有漂亮的花。\" (Vậy chúng ta đến tiệm hoa xem thử đi, bây giờ người mua hoa nhiều, hy vọng tiệm hoa vẫn còn hoa đẹp).","options":["去办公室找王老师","去超市买咖啡","去花店看看","去书店买礼物"],"q":"说完以后，白家月和陈天中打算去哪儿？"}],"scene":"在教室，白家月和陈天中在聊天儿。","sceneVi":"Trong lớp học, Bạch Gia Nguyệt và Trần Thiên Trung đang trò chuyện."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"王老师，今天的词比昨天多了十个。","pinyin":"Wáng lǎoshī, jīntiān de cí bǐ zuótiān duōle shí gè.","speaker":"白家月","vi":"Cô Vương ơi, từ vựng hôm nay nhiều hơn hôm qua mười từ."},{"hanzi":"是啊！你们都学会了吗？","pinyin":"Shì a! Nǐmen dōu xuéhuìle ma?","speaker":"王一飞","vi":"Đúng vậy! Các em đều học thuộc hết chưa?"},{"hanzi":"学会了，没有问题。","pinyin":"Xuéhuì le, méiyǒu wèntí.","speaker":"安妮","vi":"Học được rồi ạ, không có vấn đề gì."},{"hanzi":"好。现在我来说，你们在本子上面写。","pinyin":"Hǎo. Xiànzài wǒ lái shuō, nǐmen zài běnzi shàngmiàn xiě.","speaker":"王一飞","vi":"Tốt. Bây giờ cô đọc, các em viết lên vở nhé."},{"hanzi":"同学们，“洗手间”的“间”字写错了，它的里面是“日”，不是“口”。","pinyin":"Tóngxuémen, “xǐshǒujiān” de “jiān” zì xiěcuò le, tā de lǐmiàn shì “rì”, bú shì “kǒu”.","speaker":"王一飞","vi":"Các em ơi, chữ “间” trong từ “洗手间” (nhà vệ sinh) viết sai rồi, bên trong nó là chữ “日”, không phải chữ “口”."},{"hanzi":"“日”比“口”多一笔，写“口”就是“问题”的“问”了。","pinyin":"“Rì” bǐ “kǒu” duō yì bǐ, xiě “kǒu” jiù shì “wèntí” de “wèn” le.","speaker":"白家月","vi":"Chữ “日” nhiều hơn chữ “口” một nét, viết chữ “口” thì thành chữ “问” trong “问题” (vấn đề) rồi."},{"hanzi":"没错，你说得很对。","pinyin":"Méi cuò, nǐ shuō de hěn duì.","speaker":"王一飞","vi":"Không sai, em nói rất đúng."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Bạch Gia Nguyệt nói \"王老师，今天的词比昨天多了十个。\" (Thưa cô Vương, từ mới hôm nay nhiều hơn hôm qua mười từ), nên đáp án đúng là 比昨天多了十个.","options":["比昨天少了十个","比昨天多了十个","比昨天的词难多了","跟昨天的一样多"],"q":"今天要学的词跟昨天比有什么不一样？"},{"answerIdx":0,"explanation":"Trong bài, cô Vương nhắc \"“洗手间”的“间”字写错了，它的里面是“日”，不是“口”。\" (Chữ \"间\" trong \"洗手间\" viết sai rồi, bên trong là \"日\" chứ không phải \"口\"), và Bạch Gia Nguyệt nói thêm nếu viết \"口\" thì thành chữ \"问\" trong \"问题\".","options":["把“洗手间”的“间”写成了“问”","把“问题”的“问”写成了“间”","把“洗手间”的“手”写错了","把“十个”的“十”写错了"],"q":"写汉字的时候，同学们把哪个字写错了？"}],"scene":"在教室，王一飞在上课。","sceneVi":"Trong lớp học, Vương Nhất Phi đang giảng bài."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"家月，你觉得这个本子怎么样？","pinyin":"Jiāyuè, nǐ juéde zhège běnzi zěnmeyàng?","speaker":"安妮","vi":"Gia Nguyệt, bạn thấy quyển vở này thế nào?"},{"hanzi":"很漂亮，多少钱一个？","pinyin":"Hěn piàoliang, duōshao qián yí gè?","speaker":"白家月","vi":"Đẹp lắm, bao nhiêu tiền một quyển vậy?"},{"hanzi":"比我们一起买的那个本子贵一点儿。","pinyin":"Bǐ wǒmen yìqǐ mǎi de nàge běnzi guì yìdiǎnr.","speaker":"安妮","vi":"Đắt hơn quyển vở chúng ta cùng mua một chút."},{"hanzi":"这么漂亮的本子，不可能贵一点儿吧？","pinyin":"Zhème piàoliang de běnzi, bù kěnéng guì yìdiǎnr ba?","speaker":"白家月","vi":"Quyển vở đẹp thế này, không thể chỉ đắt hơn một chút được chứ?"},{"hanzi":"我是上网买的，真没那么贵。我买了两个，送你一个。","pinyin":"Wǒ shì shàngwǎng mǎi de, zhēn méi nàme guì. Wǒ mǎile liǎng gè, sòng nǐ yí gè.","speaker":"安妮","vi":"Mình mua trên mạng đấy, thật sự không đắt thế đâu. Mình mua hai quyển, tặng bạn một quyển."},{"hanzi":"谢谢！那我送给你什么呢？","pinyin":"Xièxie! Nà wǒ sòng gěi nǐ shénme ne?","speaker":"白家月","vi":"Cảm ơn bạn! Vậy mình tặng lại bạn cái gì nhỉ?"},{"hanzi":"咖啡杯吧，我最喜欢喝咖啡了。","pinyin":"Kāfēibēi ba, wǒ zuì xǐhuan hē kāfēi le.","speaker":"安妮","vi":"Cốc cà phê đi, mình thích uống cà phê nhất mà."},{"hanzi":"好，那样我们就都有新年礼物了！","pinyin":"Hǎo, nàyàng wǒmen jiù dōu yǒu xīnnián lǐwù le!","speaker":"白家月","vi":"Được, như vậy cả hai chúng ta đều có quà năm mới rồi!"}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài, An Ni nói \"我是上网买的，真没那么贵。\" (Mình mua trên mạng đấy, thật sự không đắt thế đâu), nên đáp án đúng là 在网上买的.","options":["在学校旁边的商店","和家月一起去买的","在网上买的","从老师那里买的"],"q":"安妮的这个新本子是在哪儿买的？"},{"answerIdx":3,"explanation":"Trong bài, khi Bạch Gia Nguyệt hỏi nên tặng lại món gì, An Ni trả lời \"咖啡杯吧，我最喜欢喝咖啡了。\" (Cốc cà phê đi, mình thích uống cà phê nhất đấy), nên đáp án đúng là 一个咖啡杯.","options":["一个新本子","一杯奶茶","一些漂亮的花","一个咖啡杯"],"q":"安妮希望白家月送给她什么新年礼物？"}],"scene":"在教室，安妮和白家月在聊天儿。","sceneVi":"Trong lớp học, An Ni và Bạch Gia Nguyệt đang trò chuyện."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"新年就要到了，安妮送给我一个新本子。","pinyin":"Xīnnián jiù yào dào le, Ānnī sòng gěi wǒ yí gè xīn běnzi.","speaker":"Đoạn văn","vi":"Năm mới sắp đến rồi, An Ni tặng cho tôi một quyển vở mới."},{"hanzi":"她告诉我是在网上买的，比我的本子贵一点儿。","pinyin":"Tā gàosu wǒ shì zài wǎngshang mǎi de, bǐ wǒ de běnzi guì yìdiǎnr.","speaker":"Đoạn văn","vi":"Cô ấy nói với tôi là mua trên mạng, đắt hơn quyển vở của tôi một chút."},{"hanzi":"我们班同学也送了王老师漂亮的花，希望她高高兴兴地过个新年。","pinyin":"Wǒmen bān tóngxué yě sòngle Wáng lǎoshī piàoliang de huā, xīwàng tā gāogāoxìngxìng de guò gè xīnnián.","speaker":"Đoạn văn","vi":"Các bạn học lớp chúng tôi cũng đã tặng cô Vương hoa đẹp, mong cô đón một năm mới thật vui vẻ."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài có câu \"她告诉我是在网上买的，比我的本子贵一点儿。\" (Cậu ấy bảo với tôi là mua trên mạng, đắt hơn quyển vở của tôi một chút), nên giá quyển vở mới đắt hơn vở của Bạch Gia Nguyệt một chút.","options":["比白家月的本子贵一点儿","比白家月的本子便宜多了","跟白家月的本子一样贵","非常贵，要很多钱"],"q":"安妮送给白家月的新本子价钱怎么样？"},{"answerIdx":2,"explanation":"Trong bài có câu \"我们班同学也送了王老师漂亮的花，希望她高高兴兴地过个新年。\" (Các bạn trong lớp chúng tôi cũng tặng cô Vương hoa đẹp, mong cô đón một năm mới thật vui vẻ), nên lý do là mong cô đón năm mới vui vẻ.","options":["因为王老师最喜欢买花","因为今天是王老师的生日","因为希望王老师开开心心地过新年","因为王老师生病了，同学们去看她"],"q":"同学们为什么送给王老师漂亮的花？"}],"scene":"在房间，白家月在写日记。","sceneVi":"Trong phòng, Bạch Gia Nguyệt đang viết nhật ký."}],"hsk2-14":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"王老师，你家楼下站着一个人。","pinyin":"Wáng lǎoshī, nǐ jiā lóu xià zhànzhe yí gè rén.","speaker":"李文","vi":"Cô Vương ơi, dưới tòa nhà của cô có một người đang đứng."},{"hanzi":"我家楼下？我看看。","pinyin":"Wǒ jiā lóu xià? Wǒ kànkan.","speaker":"王一飞","vi":"Dưới tòa nhà của tôi à? Để tôi xem thử."},{"hanzi":"那个人穿着黑色的裤子，手里还拿着一个黑色的包。","pinyin":"Nàge rén chuānzhe hēisè de kùzi, shǒuli hái názhe yí gè hēisè de bāo.","speaker":"李文","vi":"Người đó mặc chiếc quần màu đen, trong tay còn cầm một chiếc túi màu đen."},{"hanzi":"我看见那个人了，他是我男朋友。","pinyin":"Wǒ kànjiàn nàge rén le, tā shì wǒ nánpéngyou.","speaker":"王一飞","vi":"Tôi nhìn thấy người đó rồi, anh ấy là bạn trai của tôi."},{"hanzi":"那我们快过去吧。","pinyin":"Nà wǒmen kuài guòqù ba.","speaker":"李文","vi":"Vậy chúng ta mau qua đó đi."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài có câu \"王老师，你家楼下站着一个人。\" (Thầy/cô Vương ơi, dưới tòa nhà nhà thầy/cô có một người đang đứng.), nên đáp án đúng là dưới tòa nhà nhà thầy/cô Vương.","options":["王老师家楼下","李文家楼下","学校的门口","回家路上的商店里"],"q":"李文看见那个人站在哪儿？"},{"answerIdx":2,"explanation":"Trong bài có câu \"那个人穿着黑色的裤子，手里还拿着一个黑色的包。\" (Người đó mặc quần màu đen, trong tay còn cầm một chiếc túi màu đen.) và \"他是我男朋友。\" (Anh ấy là bạn trai của tôi.), nên đáp án đúng là bạn trai của Vương Nhất Phi, tay cầm một chiếc túi màu đen.","options":["王一飞的哥哥，拿着一件黑色的衣服","李文的朋友，拿着一双黑色的鞋","王一飞的男朋友，拿着一个黑色的包","王一飞的同事，拿着一本书"],"q":"楼下站着的那个人是谁？他手里拿着什么？"}],"scene":"在回家路上，李文和王一飞边走边聊。","sceneVi":"Trên đường về nhà, Lý Văn và Vương Nhất Phi vừa đi vừa trò chuyện."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"同乐，真是你啊！上次打电话，你说有时间过来看我，没想到这么快就来了！","pinyin":"Tónglè, zhēn shì nǐ a! Shàng cì dǎ diànhuà, nǐ shuō yǒu shíjiān guòlái kàn wǒ, méi xiǎngdào zhème kuài jiù lái le!","speaker":"王一飞","vi":"Đồng Nhạc, đúng là anh rồi! Lần trước gọi điện thoại, anh nói có thời gian sẽ qua thăm em, không ngờ nhanh thế đã đến rồi!"},{"hanzi":"就要过年了，你一个人在这儿多没意思啊，所以我就早早过来了。","pinyin":"Jiù yào guònián le, nǐ yí gè rén zài zhèr duō méi yìsi a, suǒyǐ wǒ jiù zǎozǎo guòlái le.","speaker":"杨同乐","vi":"Sắp đến Tết rồi, em ở đây một mình chán biết bao nhiêu, vì thế anh đã qua đây sớm."},{"hanzi":"你能来，我太高兴了！","pinyin":"Nǐ néng lái, wǒ tài gāoxìng le!","speaker":"王一飞","vi":"Anh đến được, em vui quá đi mất!"},{"hanzi":"一飞，你旁边这位是？","pinyin":"Yīfēi, nǐ pángbiān zhè wèi shì?","speaker":"杨同乐","vi":"Nhất Phi, vị bên cạnh em đây là ai vậy?"},{"hanzi":"同乐，这是李文，他在我们学校学医。李文，这是我男朋友杨同乐。","pinyin":"Tónglè, zhè shì Lǐ Wén, tā zài wǒmen xuéxiào xué yī. Lǐ Wén, zhè shì wǒ nánpéngyou Yáng Tónglè.","speaker":"王一飞","vi":"Đồng Nhạc, đây là Lý Văn, cậu ấy học ngành y ở trường chúng ta. Lý Văn, đây là bạn trai tôi Dương Đồng Nhạc."},{"hanzi":"李文，很高兴认识你！","pinyin":"Lǐ Wén, hěn gāoxìng rènshi nǐ!","speaker":"杨同乐","vi":"Lý Văn, rất vui được làm quen với bạn!"},{"hanzi":"认识你我也很高兴！我家就在前面那个楼，有时间来玩。","pinyin":"Rènshi nǐ wǒ yě hěn gāoxìng! Wǒ jiā jiù zài qiánmiàn nàge lóu, yǒu shíjiān lái wán.","speaker":"李文","vi":"Làm quen với anh tôi cũng rất vui! Nhà tôi ở ngay tòa nhà phía trước kia, có thời gian ghé chơi nhé."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"就要过年了，你一个人在这儿多没意思啊，所以我就早早过来了。\" (Sắp đón năm mới rồi, em ở đây một mình buồn tẻ lắm, nên anh liền qua sớm.), nên đáp án đúng là vì sắp đón năm mới và sợ Vương Nhất Phi ở một mình buồn chán.","options":["因为他要来这个学校学习医学","因为快要过年了，怕王一飞一个人没意思","因为王一飞生病了，请他来照顾自己","因为他正好在前面那个楼有工作"],"q":"杨同乐为什么这么早过来看王一飞？"},{"answerIdx":3,"explanation":"Trong bài có câu \"这是李文，他在我们学校学医。\" (Đây là Lý Văn, cậu ấy học y ở trường chúng tôi.) và \"我家就在前面那个楼\" (Nhà tôi ở ngay tòa nhà phía trước), nên đáp án đúng là Lý Văn học y ở trường của Vương Nhất Phi và nhà ở tòa nhà phía trước.","options":["李文和杨同乐是好朋友","李文在王一飞的学校学中文","李文住在王一飞家后面那个楼","李文在王一飞的学校学医，家就在前面那个楼"],"q":"关于李文，下面哪句话是对的？"}],"scene":"在楼下，王一飞见到杨同乐。","sceneVi":"Ở dưới nhà, Vương Nhất Phi gặp Dương Đồng Nhạc."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"一飞，你住的房子真不错，很大，离学校也不远。","pinyin":"Yīfēi, nǐ zhù de fángzi zhēn búcuò, hěn dà, lí xuéxiào yě bù yuǎn.","speaker":"杨同乐","vi":"Nhất Phi, căn nhà em ở thật tuyệt, rất rộng, lại cách trường không xa."},{"hanzi":"是啊！我楼下还住着一家中国人，他们人很好。","pinyin":"Shì a! Wǒ lóu xià hái zhùzhe yì jiā Zhōngguó rén, tāmen rén hěn hǎo.","speaker":"王一飞","vi":"Đúng vậy! Tầng dưới nhà em còn có một gia đình người Trung Quốc ở, họ rất tốt bụng."},{"hanzi":"这样你有事情就可以找他们帮忙。","pinyin":"Zhèyàng nǐ yǒu shìqing jiù kěyǐ zhǎo tāmen bāngmáng.","speaker":"杨同乐","vi":"Như vậy khi em có việc thì có thể nhờ họ giúp đỡ."},{"hanzi":"对，我也帮他们家的小孩儿学中文。","pinyin":"Duì, wǒ yě bāng tāmen jiā de xiǎoháir xué Zhōngwén.","speaker":"王一飞","vi":"Đúng rồi, em cũng giúp em bé nhà họ học tiếng Trung."},{"hanzi":"我记得你跟我说过，是个女孩儿，学得也很好。","pinyin":"Wǒ jìde nǐ gēn wǒ shuōguo, shì gè nǚháir, xué de yě hěn hǎo.","speaker":"杨同乐","vi":"Anh nhớ em từng kể với anh rồi, là một bé gái, học cũng rất giỏi."},{"hanzi":"没错，她经常跑上来找我玩。","pinyin":"Méi cuò, tā jīngcháng pǎo shànglái zhǎo wǒ wán.","speaker":"王一飞","vi":"Không sai, cô bé thường chạy lên đây tìm em chơi."},{"hanzi":"你问问他们什么时候有时间，我请他们吃个饭。","pinyin":"Nǐ wènwen tāmen shénme shíhou yǒu shíjiān, wǒ qǐng tāmen chī gè fàn.","speaker":"杨同乐","vi":"Em hỏi họ xem khi nào có thời gian, anh mời họ ăn một bữa cơm."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"一飞，你住的房子真不错，很大，离学校也不远。\" (Nhất Phi, căn nhà em ở thật tuyệt, rất rộng, cách trường cũng không xa.), nên đáp án đúng là căn nhà rất rộng và gần trường.","options":["房子有点儿小，但是很干净","房子很大，而且离学校很近","房子离学校很远，但是很安静","房子太旧了，不太方便"],"q":"杨同乐觉得王一飞住的房子怎么样？"},{"answerIdx":2,"explanation":"Trong bài có câu \"我也帮他们家的小孩儿学中文。\" (Em cũng giúp em bé nhà họ học tiếng Trung.), nên đáp án đúng là giúp em bé tầng dưới học tiếng Trung.","options":["帮她做晚饭","帮她学唱歌和跳舞","帮她学中文","每天送她去学校"],"q":"王一飞经常帮楼下那家人的小孩儿做什么？"}],"scene":"在王一飞家里，王一飞和杨同乐在客厅聊天儿。","sceneVi":"Ở nhà Vương Nhất Phi, Vương Nhất Phi và Dương Đồng Nhạc đang trò chuyện trong phòng khách."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"我男朋友姓杨，叫杨同乐。","pinyin":"Wǒ nánpéngyou xìng Yáng, jiào Yáng Tónglè.","speaker":"Đoạn văn","vi":"Bạn trai tôi họ Dương, tên là Dương Đồng Nhạc."},{"hanzi":"他高个子、大眼睛，唱歌唱得很好，跳舞跳得也不错。","pinyin":"Tā gāo gèzi, dà yǎnjing, chànggē chàng de hěn hǎo, tiàowǔ tiào de yě búcuò.","speaker":"Đoạn văn","vi":"Anh ấy dáng cao, mắt to, hát rất hay, nhảy cũng khá giỏi."},{"hanzi":"他和我的姐姐一起工作，是姐姐介绍我们认识的。","pinyin":"Tā hé wǒ de jiějie yìqǐ gōngzuò, shì jiějie jièshào wǒmen rènshi de.","speaker":"Đoạn văn","vi":"Anh ấy làm việc cùng chị gái tôi, là chị gái đã giới thiệu chúng tôi quen nhau."},{"hanzi":"他告诉我，从见到我的第一天开始，他就喜欢上我了。","pinyin":"Tā gàosu wǒ, cóng jiàndào wǒ de dì-yī tiān kāishǐ, tā jiù xǐhuan shàng wǒ le.","speaker":"Đoạn văn","vi":"Anh ấy nói với tôi rằng, bắt đầu từ ngày đầu tiên gặp tôi, anh ấy đã thích tôi rồi."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"他和我的姐姐一起工作，是姐姐介绍我们认识的。\" (Anh ấy làm việc cùng chị gái tôi, là chị gái đã giới thiệu chúng tôi quen nhau.), nên đáp án đúng là do chị gái của Vương Nhất Phi giới thiệu.","options":["在学校学中文的时候认识的","王一飞的姐姐介绍他们认识的","他们在一家饭馆吃饭的时候认识的","杨同乐搬到王一飞楼下后认识的"],"q":"王一飞和杨同乐是怎么认识的？"},{"answerIdx":2,"explanation":"Trong bài có câu \"唱歌唱得很好，跳舞跳得也不错\" (hát rất hay, nhảy cũng rất khá) và \"从见到我的第一天开始，他就喜欢上我了\" (từ ngày đầu tiên gặp tôi, anh ấy đã thích tôi rồi), nên đáp án đúng là Dương Đồng Nhạc hát hay, nhảy giỏi và thích Vương Nhất Phi từ ngày đầu tiên gặp mặt.","options":["杨同乐个子不高，也不太会跳舞","杨同乐在认识王一飞很久以后才喜欢上她","杨同乐唱歌和跳舞都很好，第一天见王一飞就喜欢上她了","杨同乐和王一飞在同一个公司一起工作"],"q":"根据日记内容，下面哪句话是对的？"}],"scene":"在房间，王一飞在写日记。","sceneVi":"Trong phòng, Vương Nhất Phi đang viết nhật ký."}],"hsk2-15":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"考试就要开始了，请大家写上姓名，写好后就可以做题了。","pinyin":"Kǎoshì jiù yào kāishǐ le, qǐng dàjiā xiě shàng xìngmíng, xiěhǎo hòu jiù kěyǐ zuò tí le.","speaker":"王一飞","vi":"Bài thi sắp bắt đầu rồi, mời mọi người viết họ tên vào, viết xong là có thể làm bài rồi."},{"hanzi":"老师，我做完了。","pinyin":"Lǎoshī, wǒ zuòwán le.","speaker":"白家月","vi":"Thưa cô, em làm xong rồi ạ."},{"hanzi":"老师，我也做完了。","pinyin":"Lǎoshī, wǒ yě zuòwán le.","speaker":"陈天中","vi":"Thưa cô, em cũng làm xong rồi ạ."},{"hanzi":"……对了，你们考完试想做什么？","pinyin":"……Duìle, nǐmen kǎowán shì xiǎng zuò shénme?","speaker":"王一飞","vi":"……À đúng rồi, các em thi xong muốn làm gì?"},{"hanzi":"我很想去中国，虽然去过一次，但是很想再去一次。","pinyin":"Wǒ hěn xiǎng qù Zhōngguó, suīrán qùguo yí cì, dànshì hěn xiǎng zài qù yí cì.","speaker":"白家月","vi":"Em rất muốn đi Trung Quốc, tuy đã từng đi một lần rồi, nhưng rất muốn đi thêm lần nữa."},{"hanzi":"不错，到中国后你就可以经常说中文了。","pinyin":"Búcuò, dào Zhōngguó hòu nǐ jiù kěyǐ jīngcháng shuō Zhōngwén le.","speaker":"王一飞","vi":"Tốt lắm, sau khi đến Trung Quốc em có thể thường xuyên nói tiếng Trung rồi."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"考试就要开始了，请大家写上姓名，写好后就可以做题了。\" (Kỳ thi sắp bắt đầu rồi, mời cả lớp viết họ tên vào, viết xong thì có thể làm bài.), nên đáp án đúng là viết họ tên của mình trước.","options":["先开始做题","先写上自己的姓名","先用中文介绍一下自己","先休息几分钟"],"q":"考试开始以前，王老师让大家先做什么？"},{"answerIdx":1,"explanation":"Trong bài có câu \"我很想去中国，虽然去过一次，但是很想再去一次。\" (Em rất muốn đi Trung Quốc, tuy đã từng đi một lần nhưng rất muốn đi thêm lần nữa.), nên đáp án đúng là Bạch Gia Nguyệt từng đến Trung Quốc một lần và muốn đi lại sau khi thi xong.","options":["她从来没有去过中国","她以前去过一次中国，考完试还想再去一次","她觉得今天的考试题太难了，还没做完","她考完试不想去旅游，只想在学校学中文"],"q":"关于白家月，下面哪句话是对的？"}],"scene":"在教室，同学们在考试。","sceneVi":"Ở trong lớp học, các bạn học sinh đang làm bài thi."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"考完试了，我现在可以出国旅游了。","pinyin":"Kǎowán shì le, wǒ xiànzài kěyǐ chūguó lǚyóu le.","speaker":"白家月","vi":"Thi xong rồi, bây giờ mình có thể đi du lịch nước ngoài rồi."},{"hanzi":"你要去哪儿？","pinyin":"Nǐ yào qù nǎr?","speaker":"李文","vi":"Cậu định đi đâu thế?"},{"hanzi":"我要再去一次北京。","pinyin":"Wǒ yào zài qù yí cì Běijīng.","speaker":"白家月","vi":"Mình muốn đi Bắc Kinh thêm một lần nữa."},{"hanzi":"为什么还去北京？","pinyin":"Wèi shénme hái qù Běijīng?","speaker":"李文","vi":"Tại sao lại đi Bắc Kinh nữa thế?"},{"hanzi":"因为我想再吃一次烤鸭，再喝一次奶茶，再去北京大学看一次电影……","pinyin":"Yīnwèi wǒ xiǎng zài chī yí cì kǎoyā, zài hē yí cì nǎichá, zài qù Běijīng Dàxué kàn yí cì diànyǐng……","speaker":"白家月","vi":"Vì mình muốn ăn vịt quay một lần nữa, uống trà sữa một lần nữa, rồi đến Đại học Bắc Kinh xem phim một lần nữa……"},{"hanzi":"你想做的事情很多啊！","pinyin":"Nǐ xiǎng zuò de shìqing hěn duō a!","speaker":"李文","vi":"Cậu muốn làm nhiều việc thật đấy!"},{"hanzi":"是啊，你看，我还在网上买好颐和园的门票了呢。","pinyin":"Shì a, nǐ kàn, wǒ hái zài wǎngshang mǎihǎo Yíhé Yuán de ménpiào le ne.","speaker":"白家月","vi":"Đúng vậy, cậu xem, mình còn mua sẵn vé vào Di Hòa Viên trên mạng rồi cơ đấy."},{"hanzi":"我的高中同学就在颐和园上班，可以让他给你好好介绍介绍。","pinyin":"Wǒ de gāozhōng tóngxué jiù zài Yíhé Yuán shàngbān, kěyǐ ràng tā gěi nǐ hǎohǎo jièshào jièshào.","speaker":"李文","vi":"Bạn học cấp ba của mình làm việc ngay ở Di Hòa Viên, có thể nhờ cậu ấy giới thiệu kỹ cho cậu."},{"hanzi":"太好了！出门旅游，多个朋友多条路。","pinyin":"Tài hǎo le! Chūmén lǚyóu, duō gè péngyou duō tiáo lù.","speaker":"白家月","vi":"Tuyệt quá! Ra ngoài du lịch, thêm một người bạn là thêm một con đường."}],"readingQuiz":[{"answerIdx":3,"explanation":"Trong bài có câu \"因为我想再吃一次烤鸭，再喝一次奶茶，再去北京大学看一次电影……\" (Vì tôi muốn ăn vịt quay một lần nữa, uống trà sữa một lần nữa, đến Đại học Bắc Kinh xem phim một lần nữa...), không nhắc đến việc học tiếng Trung tại Đại học Bắc Kinh, nên đáp án đúng là \"去北京大学上中文课\".","options":["再吃一次烤鸭","再喝一次奶茶","去北京大学看一次电影","去北京大学上中文课"],"q":"下面哪件事不是白家月想再去北京做的？"},{"answerIdx":2,"explanation":"Trong bài có câu \"我的高中同学就在颐和园上班，可以让他给你好好介绍介绍。\" (Bạn học cấp ba của tôi làm việc ở Di Hòa Viên, có thể nhờ cậu ấy giới thiệu kỹ cho bạn.), nên đáp án đúng là giới thiệu về Di Hòa Viên cho Bạch Gia Nguyệt.","options":["帮她在网上买颐和园的门票","带她去吃便宜又好吃的烤鸭","因为他在颐和园上班，可以好好给她介绍一下颐和园","去机场接她，送她去宾馆"],"q":"李文的高中同学能给白家月什么帮助？"}],"scene":"在咖啡店，李文和白家月在聊天儿。","sceneVi":"Ở quán cà phê, Lý Văn và Bạch Gia Nguyệt đang trò chuyện."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"李文，你有一年没回国了吧？","pinyin":"Lǐ Wén, nǐ yǒu yì nián méi huí guó le ba?","speaker":"白家月","vi":"Lý Văn, cậu đã một năm chưa về nước rồi nhỉ?"},{"hanzi":"不到一年。我六月的时候回去了一次。","pinyin":"Bú dào yì nián. Wǒ Liùyuè de shíhou huíqùle yí cì.","speaker":"李文","vi":"Chưa đến một năm đâu. Hồi tháng Sáu mình có về một lần."},{"hanzi":"我怎么忘了？还是我送你去的机场呢。","pinyin":"Wǒ zěnme wàng le? Hái shì wǒ sòng nǐ qù de jīchǎng ne.","speaker":"白家月","vi":"Sao mình lại quên được nhỉ? Chính mình còn tiễn cậu ra sân bay cơ mà."},{"hanzi":"是啊。","pinyin":"Shì a.","speaker":"李文","vi":"Đúng vậy."},{"hanzi":"我记得你那次的机票很便宜。","pinyin":"Wǒ jìde nǐ nà cì de jīpiào hěn piányi.","speaker":"白家月","vi":"Mình nhớ vé máy bay lần đó của cậu rất rẻ."},{"hanzi":"没错，可能因为那个时候去北京的人不多吧。","pinyin":"Méi cuò, kěnéng yīnwèi nàge shíhou qù Běijīng de rén bù duō ba.","speaker":"李文","vi":"Đúng rồi, có lẽ vì lúc đó không có nhiều người đi Bắc Kinh."},{"hanzi":"这次的机票虽然有点儿贵，但想到就要飞北京了，我还是很高兴的。","pinyin":"Zhè cì de jīpiào suīrán yǒudiǎnr guì, dàn xiǎngdào jiù yào fēi Běijīng le, wǒ hái shì hěn gāoxìng de.","speaker":"白家月","vi":"Vé máy bay lần này tuy hơi đắt một chút, nhưng nghĩ đến việc sắp được bay đi Bắc Kinh rồi, mình vẫn thấy rất vui."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu \"不到一年。我六月的时候回去了一次。\" (Chưa đến một năm đâu. Tháng Sáu tôi đã về một lần rồi.), nên đáp án đúng là vào tháng Sáu.","options":["去年十二月","一年多以前","六月的时候","下个星期五"],"q":"李文上次是什么时候回国的？"},{"answerIdx":1,"explanation":"Trong bài có câu \"这次的机票虽然有点儿贵，但想到就要飞北京了，我还是很高兴的。\" (Vé máy bay lần này tuy hơi đắt một chút, nhưng nghĩ đến việc sắp được bay tới Bắc Kinh, tôi vẫn rất vui.), nên đáp án đúng là vé hơi đắt nhưng cô ấy vẫn rất vui.","options":["机票很便宜，所以她非常高兴","机票有点儿贵，但她还是很开心","机票太贵了，她决定不坐飞机去北京了","机票很贵，所以她不太高兴"],"q":"关于白家月这次去北京的机票和心情，下面哪句话是对的？"}],"scene":"在咖啡店，李文和白家月在聊天儿。","sceneVi":"Ở quán cà phê, Lý Văn và Bạch Gia Nguyệt đang trò chuyện."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"我六月的时候回过一次北京，现在有半年多没回去了，我有点儿想家。","pinyin":"Wǒ Liùyuè de shíhou huíguo yí cì Běijīng, xiànzài yǒu bàn nián duō méi huíqù le, wǒ yǒudiǎnr xiǎng jiā.","speaker":"Đoạn văn","vi":"Hồi tháng Sáu tôi có về Bắc Kinh một lần, đến nay đã hơn nửa năm chưa về rồi, tôi hơi nhớ nhà."},{"hanzi":"就要过年了，我要回家过年。","pinyin":"Jiù yào guònián le, wǒ yào huí jiā guònián.","speaker":"Đoạn văn","vi":"Sắp đón năm mới rồi, tôi muốn về nhà đón Tết."},{"hanzi":"家月这次也要去北京，我们都是星期五的飞机。","pinyin":"Jiāyuè zhè cì yě yào qù Běijīng, wǒmen dōu shì Xīngqīwǔ de fēijī.","speaker":"Đoạn văn","vi":"Gia Nguyệt lần này cũng muốn đi Bắc Kinh, chúng tôi đều đi chuyến bay thứ Sáu."},{"hanzi":"家月说我们好像小鸟，一起飞到北京，再一起飞回这里。","pinyin":"Jiāyuè shuō wǒmen hǎoxiàng xiǎoniǎo, yìqǐ fēidào Běijīng, zài yìqǐ fēihuí zhèlǐ.","speaker":"Đoạn văn","vi":"Gia Nguyệt nói chúng tôi giống như những chú chim nhỏ, cùng nhau bay đến Bắc Kinh, rồi lại cùng nhau bay về đây."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu \"现在有半年多没回去了，我有点儿想家。就要过年了，我要回家过年。\" (Hiện tại đã hơn nửa năm chưa về rồi, tôi hơi nhớ nhà. Sắp đón năm mới rồi, tôi phải về nhà ăn Tết.), nên đáp án đúng là vì nhớ nhà và về quê đón năm mới.","options":["因为他要陪白家月去颐和园玩","因为他在北京找到了新的工作","因为他有半年多没回去了，有点儿想家，要回家过年","因为那时候去北京的机票非常便宜"],"q":"李文这次为什么回北京？"},{"answerIdx":0,"explanation":"Trong bài có câu \"我们都是星期五的飞机。\" (Chúng tôi đều đi chuyến bay vào thứ Sáu.), nên đáp án đúng là thứ Sáu.","options":["星期五","星期六","六月的时候","下个月底"],"q":"李文和白家月什么时候坐飞机去北京？"}],"scene":"在房间，李文在写日记。","sceneVi":"Trong phòng, Lý Văn đang viết nhật ký."}],"hsk3-1":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"这是杨同乐吗？他怎么跟白家月在一起？","pinyin":"Zhè shì Yáng Tónglè ma? Tā zěnme gēn Bái Jiāyuè zài yìqǐ?","speaker":"刘明","vi":"Đây là Dương Đồng Lạc à? Sao anh ấy lại ở cùng Bạch Gia Nguyệt vậy?"},{"hanzi":"他不是杨同乐，他叫李文，是白家月的好朋友。","pinyin":"Tā bú shì Yáng Tónglè, tā jiào Lǐ Wén, shì Bái Jiāyuè de hǎo péngyou.","speaker":"王一雪","vi":"Anh ấy không phải Dương Đồng Lạc, anh ấy tên là Lý Văn, là bạn thân của Bạch Gia Nguyệt."},{"hanzi":"我还以为是同乐呢，他们看上去有点儿像。","pinyin":"Wǒ hái yǐwéi shì Tónglè ne, tāmen kànshàngqù yǒudiǎnr xiàng.","speaker":"刘明","vi":"Anh còn tưởng là Đồng Lạc chứ, nhìn họ hơi giống nhau đấy."},{"hanzi":"是长得有点儿像，但是他比同乐高，身高有一米八。","pinyin":"Shì zhǎng de yǒudiǎnr xiàng, dànshì tā bǐ Tónglè gāo, shēngāo yǒu yì mǐ bā.","speaker":"王一雪","vi":"Trông cũng hơi giống thật, nhưng anh ấy cao hơn Đồng Lạc, cao tới một mét tám cơ."},{"hanzi":"看起来也比同乐瘦一点儿。","pinyin":"Kànqǐlái yě bǐ Tónglè shòu yìdiǎnr.","speaker":"刘明","vi":"Nhìn cũng có vẻ gầy hơn Đồng Lạc một chút."},{"hanzi":"下个星期家月和李文要来北京，我去机场接他们。","pinyin":"Xià ge xīngqī Jiāyuè hé Lǐ Wén yào lái Běijīng, wǒ qù jīchǎng jiē tāmen.","speaker":"王一雪","vi":"Tuần sau Gia Nguyệt và Lý Văn sẽ đến Bắc Kinh, em ra sân bay đón họ."},{"hanzi":"他们哪天到北京？我跟你一起去机场接他们吧。","pinyin":"Tāmen nǎ tiān dào Běijīng? Wǒ gēn nǐ yìqǐ qù jīchǎng jiē tāmen ba.","speaker":"刘明","vi":"Họ ngày nào đến Bắc Kinh thế? Anh đi sân bay đón họ cùng em nhé."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"他不是杨同乐，他叫李文，是白家月的好朋友。\" (Cậu ấy không phải Dương Đồng Nhạc, cậu ấy tên Lý Văn, là bạn thân của Bạch Gia Nguyệt.), nên đáp án đúng là Lý Văn, bạn thân của Bạch Gia Nguyệt.","options":["王一雪的男朋友杨同乐","白家月的好朋友李文","王一雪的弟弟刘明","李文的哥哥"],"q":"照片里跟白家月在一起的人是谁？"},{"answerIdx":2,"explanation":"Trong bài có câu \"但是他比同乐高，身高有一米八。\" (nhưng cậu ấy cao hơn Đồng Nhạc, cao 1m8.) và \"看起来也比同乐瘦一点儿。\" (nhìn cũng gầy hơn Đồng Nhạc một chút.), nên đáp án đúng là cao hơn và gầy hơn Dương Đồng Nhạc một chút.","options":["比杨同乐矮，也比他胖一点儿","和杨同乐一样高，但是比他瘦","比杨同乐高，也比他瘦一点儿","身高一米八，但是比杨同乐胖一点儿"],"q":"和杨同乐比，李文看起来怎么样？"}],"scene":"在家里，刘明和王一雪在沙发上聊天儿。","sceneVi":"Ở nhà, Lưu Minh và Vương Nhất Tuyết đang trò chuyện trên ghế sô pha."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"我的行李怎么还没出来？是不是丢了？","pinyin":"Wǒ de xíngli zěnme hái méi chūlái? Shì bu shì diū le?","speaker":"白家月","vi":"Sao hành lý của mình vẫn chưa ra nhỉ? Có phải bị mất rồi không?"},{"hanzi":"你的行李箱是什么样的？","pinyin":"Nǐ de xínglixiāng shì shénme yàng de?","speaker":"李文","vi":"Va li của bạn trông như thế nào?"},{"hanzi":"是一个黑色的箱子，上面写着我的名字和电话号码。","pinyin":"Shì yí ge hēisè de xiāngzi, shàngmiàn xiězhe wǒ de míngzi hé diànhuà hàomǎ.","speaker":"白家月","vi":"Là một chiếc va li màu đen, phía trên có ghi tên và số điện thoại của mình."},{"hanzi":"我好像在哪儿看到过这个箱子，是不是有人拿错了？","pinyin":"Wǒ hǎoxiàng zài nǎr kàndào guo zhège xiāngzi, shì bu shì yǒu rén ná cuò le?","speaker":"李文","vi":"Hình như mình đã nhìn thấy chiếc va li này ở đâu đó rồi, có phải có ai cầm nhầm không?"},{"hanzi":"我们快找谁问一下吧，箱子里有不少重要的东西。","pinyin":"Wǒmen kuài zhǎo shéi wèn yíxià ba, xiāngzi lǐ yǒu bùshǎo zhòngyào de dōngxi.","speaker":"白家月","vi":"Chúng ta mau tìm ai đó hỏi thử xem, trong va li có không ít đồ quan trọng."},{"hanzi":"别着急，我们拿着护照和机票，去服务台问问吧。","pinyin":"Bié zháojí, wǒmen názhe hùzhào hé jīpiào, qù fúwùtái wènwen ba.","speaker":"李文","vi":"Đừng lo lắng, chúng ta cầm hộ chiếu và vé máy bay ra quầy dịch vụ hỏi thử xem."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"是一个黑色的箱子，上面写着我的名字和电话号码。\" (Là một chiếc va li màu đen, bên trên có viết tên và số điện thoại của tôi.), nên đáp án đúng là chiếc va li màu đen có ghi tên và số điện thoại của cô ấy.","options":["是一个白色的箱子，上面只有她的名字","是一个黑色的箱子，上面写着她的名字和电话号码","是一个很大很重的红色箱子","上面什么都没写，里面没有重要的东西"],"q":"白家月的行李箱是什么样的？"},{"answerIdx":2,"explanation":"Trong bài có câu \"别着急，我们拿着护照和机票，去服务台问问吧。\" (Đừng lo lắng, chúng ta cầm hộ chiếu và vé máy bay ra quầy dịch vụ hỏi xem sao.), nên đáp án đúng là mang hộ chiếu và vé máy bay đến quầy dịch vụ hỏi.","options":["先走出机场去找王一雪和刘明","在行李领取处一直等下去","拿着护照和机票去服务台问一问","给拿错箱子的人打电话"],"q":"没有看到行李箱，李文打算怎么帮白家月？"}],"scene":"在机场，李文和白家月在行李领取处。","sceneVi":"Tại sân bay, Lý Văn và Bạch Gia Nguyệt đang ở khu vực nhận hành lý."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"飞机早就到了，你看见白家月他们了吗？","pinyin":"Fēijī zǎo jiù dào le, nǐ kànjiàn Bái Jiāyuè tāmen le ma?","speaker":"刘明","vi":"Máy bay đã hạ cánh từ sớm rồi, em đã thấy nhóm Bạch Gia Nguyệt chưa?"},{"hanzi":"没有，他们应该快出来了。","pinyin":"Méiyǒu, tāmen yīnggāi kuài chūlái le.","speaker":"王一雪","vi":"Chưa ạ, chắc họ sắp ra rồi."},{"hanzi":"我们站到中间去吧，这样他们好找一些。","pinyin":"Wǒmen zhàn dào zhōngjiān qù ba, zhèyàng tāmen hǎo zhǎo yìxiē.","speaker":"刘明","vi":"Chúng ta đứng ra giữa đi, như vậy họ sẽ dễ tìm hơn một chút."},{"hanzi":"你看那个高个子的人是李文吗？","pinyin":"Nǐ kàn nàge gāogèzi de rén shì Lǐ Wén ma?","speaker":"王一雪","vi":"Anh nhìn xem người cao lớn kia có phải là Lý Văn không?"},{"hanzi":"你说的是哪个？那个穿着黑衣服的短头发的年轻人？","pinyin":"Nǐ shuō de shì nǎge? Nàge chuānzhe hēi yīfu de duǎn tóufa de niánqīngrén?","speaker":"刘明","vi":"Em nói người nào? Cái người trẻ tuổi tóc ngắn mặc áo đen kia à?"},{"hanzi":"对，那个人就是李文！你看，家月在他后面呢。","pinyin":"Duì, nàge rén jiù shì Lǐ Wén! Nǐ kàn, Jiāyuè zài tā hòumiàn ne.","speaker":"王一雪","vi":"Đúng rồi, người đó chính là Lý Văn đấy! Anh nhìn kìa, Gia Nguyệt đang ở phía sau anh ấy."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"我们站到中间去吧，这样他们好找一些。\" (Chúng ta đứng ra chính giữa đi, như vậy họ sẽ dễ tìm hơn một chút.), nên đáp án đúng là đứng ở giữa để Bạch Gia Nguyệt và Lý Văn dễ tìm thấy họ hơn.","options":["因为中间有座位，可以坐着休息","因为站在中间，白家月和李文更容易找到他们","因为飞机还没到，中间比较凉快","因为服务台就在大厅中间"],"q":"刘明为什么建议站到中间去？"},{"answerIdx":0,"explanation":"Trong bài có câu \"你看那个高个子的人是李文吗？\" (Anh nhìn người cao lớn kia có phải Lý Văn không?) và \"那个穿着黑衣服的短头发的年轻人？\" (Cậu thanh niên tóc ngắn mặc áo đen kia à?), nên đáp án đúng là cao lớn, tóc ngắn, mặc quần áo màu đen.","options":["高个子、短头发、穿着黑衣服","矮个子、长头发、穿着黑衣服","高个子、戴着帽子、拿着白色的包","走在白家月后面的年轻人"],"q":"在机场大厅出现的李文是什么样子的？"}],"scene":"在机场大厅，刘明和王一雪接机。","sceneVi":"Tại sảnh sân bay, Lưu Minh và Vương Nhất Tuyết đang đón người."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"昨天我到北京了。","pinyin":"Zuótiān wǒ dào Běijīng le.","speaker":"Đoạn văn","vi":"Hôm qua tôi đã đến Bắc Kinh rồi."},{"hanzi":"虽然路上花了十几个小时，但是跟家月坐在一起，我觉得时间过得很快。","pinyin":"Suīrán lùshang huā le shí jǐ ge xiǎoshí, dànshì gēn Jiāyuè zuò zài yìqǐ, wǒ juéde shíjiān guò de hěn kuài.","speaker":"Đoạn văn","vi":"Tuy trên đường mất hơn mười tiếng đồng hồ, nhưng ngồi cùng Gia Nguyệt, tôi cảm thấy thời gian trôi qua rất nhanh."},{"hanzi":"到机场的时候，家月发现行李箱不见了，我带她去服务台，帮助她找到了行李箱。","pinyin":"Dào jīchǎng de shíhou, Jiāyuè fāxiàn xínglixiāng bújiàn le, wǒ dài tā qù fúwùtái, bāngzhù tā zhǎodào le xínglixiāng.","speaker":"Đoạn văn","vi":"Khi đến sân bay, Gia Nguyệt phát hiện va li hành lý không thấy đâu, tôi đưa cô ấy đến quầy dịch vụ và giúp cô ấy tìm lại được va li."},{"hanzi":"走出机场的时候，已经八点多了，我们一出来就看见了王老师的姐姐，她看起来比照片上年轻。","pinyin":"Zǒuchū jīchǎng de shíhou, yǐjīng bā diǎn duō le, wǒmen yì chūlái jiù kànjiàn le Wáng lǎoshī de jiějie, tā kànqǐlái bǐ zhàopiàn shàng niánqīng.","speaker":"Đoạn văn","vi":"Lúc đi ra khỏi sân bay đã hơn tám giờ rồi, chúng tôi vừa ra ngoài đã nhìn thấy chị gái của thầy/cô Vương, chị ấy trông trẻ hơn trong ảnh."},{"hanzi":"晚上，一雪姐带我们去吃了一家很好吃的中国菜。","pinyin":"Wǎnshang, Yīxuě jiě dài wǒmen qù chī le yì jiā hěn hǎochī de Zhōngguó cài.","speaker":"Đoạn văn","vi":"Buổi tối, chị Nhất Tuyết dẫn chúng tôi đi ăn ở một nhà hàng món Trung Quốc rất ngon."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu \"虽然路上花了十几个小时，但是跟家月坐在一起，我觉得时间过得很快。\" (Tuy trên đường mất hơn mười tiếng, nhưng ngồi cùng Gia Nguyệt nên tôi thấy thời gian trôi qua rất nhanh.), nên đáp án đúng là vì ngồi cùng Bạch Gia Nguyệt.","options":["因为他在飞机上一直睡觉","因为飞机上有很多好吃的东西","因为他和白家月坐在一起","因为他一直在看电影和看书"],"q":"在飞机上花了十几个小时，李文为什么还是觉得时间过得很快？"},{"answerIdx":2,"explanation":"Trong bài có câu \"我们一出来就看见了王老师的姐姐，她看起来比照片上年轻。\" (Chúng tôi vừa ra ngoài đã nhìn thấy chị gái của thầy/cô Vương, chị ấy trông trẻ hơn trong ảnh.), nên đáp án đúng là trông trẻ hơn so với trong ảnh.","options":["比照片上胖一点儿","和照片上不太像","比照片上年轻","看起来很累，因为等了很久"],"q":"李文见到王老师的姐姐时，觉得她怎么样？"}],"scene":"在宾馆房间，李文在写日记。","sceneVi":"Trong phòng khách sạn, Lý Văn đang viết nhật ký."}],"hsk3-2":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"家月、李文，你们看看菜单，想吃点儿什么？","pinyin":"Jiāyuè, Lǐ Wén, nǐmen kànkan càidān, xiǎng chī diǎnr shénme?","speaker":"王一雪","vi":"Gia Nguyệt, Lý Văn, hai bạn xem thực đơn đi, muốn ăn chút gì nào?"},{"hanzi":"谢谢一雪姐，我都可以，你们点吧。","pinyin":"Xièxie Yīxuě jiě, wǒ dōu kěyǐ, nǐmen diǎn ba.","speaker":"李文","vi":"Cảm ơn chị Nhất Tuyết, em món gì cũng được, mọi người gọi đi ạ."},{"hanzi":"飞了这么远，现在还真是又饿又渴。","pinyin":"Fēi le zhème yuǎn, xiànzài hái zhēn shì yòu è yòu kě.","speaker":"白家月","vi":"Bay xa như vậy, giờ đúng là vừa đói vừa khát thật."},{"hanzi":"那多点点儿，别客气。你们喝什么饮料？","pinyin":"Nà duō diǎn diǎnr, bié kèqi. Nǐmen hē shénme yǐnliào?","speaker":"王一雪","vi":"Vậy gọi nhiều một chút đi, đừng khách sáo. Các bạn uống đồ uống gì?"},{"hanzi":"好久没喝中国茶，也好久没吃饺子了。我想喝绿茶、吃饺子，可以吗？","pinyin":"Hǎojiǔ méi hē Zhōngguó chá, yě hǎojiǔ méi chī jiǎozi le. Wǒ xiǎng hē lǜchá, chī jiǎozi, kěyǐ ma?","speaker":"白家月","vi":"Lâu rồi không uống trà Trung Quốc, cũng lâu rồi không ăn sủi cảo. Em muốn uống trà xanh và ăn sủi cảo, được không ạ?"},{"hanzi":"没问题。你们看看还想吃什么。","pinyin":"Méi wèntí. Nǐmen kànkan hái xiǎng chī shénme.","speaker":"王一雪","vi":"Không vấn đề gì. Các bạn xem còn muốn ăn gì nữa không."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"飞了这么远，现在还真是又饿又渴。\" (Bay xa như vậy, giờ đúng là vừa đói vừa khát.), nên đáp án đúng là vừa đói vừa khát.","options":["刚睡醒，不太想吃东西","又饿又渴","只是有点儿渴，不饿","又冷又累，只想喝热茶"],"q":"在饭馆点菜的时候，白家月现在感觉怎么样？"},{"answerIdx":2,"explanation":"Trong bài có câu \"我想喝绿茶、吃饺子，可以吗？\" (Em muốn uống trà xanh, ăn sủi cảo, được không ạ?), nên đáp án đúng là trà xanh và sủi cảo.","options":["红茶和面条","咖啡和蛋糕","绿茶和饺子","奶茶和烤鸭"],"q":"白家月想点什么饮料和吃的？"}],"scene":"在饭馆，王一雪、刘明、白家月和李文在点菜。","sceneVi":"Ở nhà hàng, Vương Nhất Tuyết, Lưu Minh, Bạch Gia Nguyệt và Lý Văn đang gọi món."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"服务员，再给我们拿一双筷子、一个勺子和一个碗。","pinyin":"Fúwùyuán, zài gěi wǒmen ná yì shuāng kuàizi, yí ge sháozi hé yí ge wǎn.","speaker":"王一雪","vi":"Nhân viên phục vụ ơi, lấy thêm cho chúng tôi một đôi đũa, một cái thìa và một cái bát nhé."},{"hanzi":"好的，请等一下，我马上去拿。","pinyin":"Hǎo de, qǐng děng yíxià, wǒ mǎshàng qù ná.","speaker":"服务员","vi":"Vâng ạ, xin đợi một chút, tôi đi lấy ngay đây."},{"hanzi":"这家饭馆的服务很热情，菜也都做得很好吃。你们尝尝，看喜不喜欢这些菜。","pinyin":"Zhè jiā fànguǎn de fúwù hěn rèqíng, cài yě dōu zuò de hěn hǎochī. Nǐmen chángchang, kàn xǐ bu xǐhuan zhèxiē cài.","speaker":"王一雪","vi":"Phục vụ của nhà hàng này rất nhiệt tình, món ăn cũng đều nấu rất ngon. Các bạn nếm thử xem có thích những món này không."},{"hanzi":"哪个菜都好吃。您点的这些菜真不错。","pinyin":"Nǎge cài dōu hǎochī. Nín diǎn de zhèxiē cài zhēn búcuò.","speaker":"白家月","vi":"Món nào cũng ngon cả. Những món chị gọi thật sự rất tuyệt."},{"hanzi":"这里的饭菜又便宜又好吃，我们经常来，服务员都记住我们爱吃的菜了。","pinyin":"Zhèlǐ de fàncài yòu piányi yòu hǎochī, wǒmen jīngcháng lái, fúwùyuán dōu jìzhù wǒmen ài chī de cài le.","speaker":"王一雪","vi":"Đồ ăn ở đây vừa rẻ vừa ngon, bọn chị thường xuyên đến, nhân viên phục vụ nhớ hết những món bọn chị thích ăn rồi."},{"hanzi":"王姐，您经常来吃饭，今天送您一些水果，请慢用。","pinyin":"Wáng jiě, nín jīngcháng lái chīfàn, jīntiān sòng nín yìxiē shuǐguǒ, qǐng màn yòng.","speaker":"服务员","vi":"Chị Vương, chị thường xuyên đến ăn, hôm nay xin tặng chị một ít hoa quả, chúc chị dùng bữa ngon miệng."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu \"服务员，再给我们拿一双筷子、一个勺子和一个碗。\" (Phục vụ ơi, lấy thêm cho chúng tôi một đôi đũa, một cái thìa và một cái bát.), nên đáp án đúng là một đôi đũa, một cái thìa và một cái bát.","options":["一张菜单和一壶绿茶","两双筷子和两个盘子","一双筷子、一个勺子和一个碗","一双筷子和一些水果"],"q":"王一雪让服务员再拿什么东西过来？"},{"answerIdx":2,"explanation":"Trong bài có câu \"王姐，您经常来吃饭，今天送您一些水果，请慢用。\" (Chị Vương, chị thường xuyên đến ăn cơm, hôm nay quán tặng chị một ít hoa quả, chúc chị ngon miệng.), nên đáp án đúng là vì Vương Nhất Tuyết thường xuyên đến ăn ở nhà hàng này.","options":["因为今天饭馆刚刚开门","因为他们点了很多很贵的菜","因为王一雪经常来这家饭馆吃饭","因为今天是白家月的生日"],"q":"服务员为什么今天送给王一雪他们一些水果？"}],"scene":"在饭馆，王一雪、刘明、白家月和李文一起吃饭。","sceneVi":"Ở nhà hàng, Vương Nhất Tuyết, Lưu Minh, Bạch Gia Nguyệt và Lý Văn cùng nhau ăn cơm."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"这个鸡肉饭太好吃了，我要再来吃一次。","pinyin":"Zhège jīròufàn tài hǎochī le, wǒ yào zài lái chī yí cì.","speaker":"白家月","vi":"Món cơm gà này ngon quá đi mất, em nhất định phải đến ăn lại một lần nữa."},{"hanzi":"你可以拿走这张菜单，看看下次还吃点儿什么。","pinyin":"Nǐ kěyǐ názǒu zhè zhāng càidān, kànkan xià cì hái chī diǎnr shénme.","speaker":"李文","vi":"Bạn có thể cầm tờ thực đơn này về, xem lần sau còn muốn ăn thêm món gì nữa."},{"hanzi":"不用拿菜单，在手机上就能看到，也可以选好了让他们给你送。","pinyin":"Búyòng ná càidān, zài shǒujī shàng jiù néng kàndào, yě kěyǐ xuǎnhǎo le ràng tāmen gěi nǐ sòng.","speaker":"王一雪","vi":"Không cần lấy thực đơn đâu, trên điện thoại là xem được ngay, cũng có thể chọn xong rồi bảo họ giao đến cho bạn."},{"hanzi":"他们家还能送外卖？","pinyin":"Tāmen jiā hái néng sòng wàimài?","speaker":"白家月","vi":"Nhà hàng này còn có thể giao đồ ăn tận nơi nữa à?"},{"hanzi":"对，现在很多饭馆都能送外卖，想吃什么就点什么。","pinyin":"Duì, xiànzài hěn duō fànguǎn dōu néng sòng wàimài, xiǎng chī shénme jiù diǎn shénme.","speaker":"王一雪","vi":"Đúng vậy, bây giờ rất nhiều nhà hàng đều có thể giao đồ ăn, muốn ăn gì thì gọi món đó."},{"hanzi":"那真是太方便了！","pinyin":"Nà zhēn shì tài fāngbiàn le!","speaker":"白家月","vi":"Vậy thì thật sự tiện lợi quá rồi!"}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"这个鸡肉饭太好吃了，我要再来吃一次。\" (Cơm thịt gà này ngon quá, tôi nhất định sẽ quay lại ăn thêm một lần nữa.), nên đáp án đúng là vì cơm thịt gà ở đây quá ngon.","options":["因为这家饭馆的水果都是免费的","因为她觉得这里的鸡肉饭太好吃了","因为这里离她住的宾馆很近","因为服务员非常热情，还送了她菜单"],"q":"白家月为什么说以后还要再来这家饭馆吃一次？"},{"answerIdx":2,"explanation":"Trong bài có câu \"不用拿菜单，在手机上就能看到，也可以选好了让他们给你送。\" (Không cần cầm thực đơn đâu, trên điện thoại là xem được rồi, cũng có thể chọn xong rồi bảo họ giao đến cho bạn.) và \"现在很多饭馆都能送外卖\" (bây giờ rất nhiều nhà hàng đều có thể giao đồ ăn), nên đáp án đúng là xem thực đơn trên điện thoại và gọi giao đồ ăn tận nơi.","options":["必须拿着纸菜单来饭馆点","只能让李文帮忙打电话点菜","可以在手机上看菜单点菜，还能让饭馆送外卖","只能晚上去饭馆里吃，不能送外卖"],"q":"按照王一雪说的，白家月以后怎么点这家饭馆的菜？"}],"scene":"在饭馆，王一雪、刘明、白家月和李文继续边吃边聊。","sceneVi":"Ở nhà hàng, Vương Nhất Tuyết, Lưu Minh, Bạch Gia Nguyệt và Lý Văn tiếp tục vừa ăn vừa trò chuyện."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"这些年在国外，我很少自己做饭。","pinyin":"Zhèxiē nián zài guówài, wǒ hěn shǎo zìjǐ zuòfàn.","speaker":"Đoạn văn","vi":"Những năm qua ở nước ngoài, tôi rất ít khi tự nấu cơm."},{"hanzi":"早饭我吃一个面包，有时候吃一块蛋糕，再喝一杯咖啡。","pinyin":"Zǎofàn wǒ chī yí ge miànbāo, yǒushíhou chī yí kuài dàngāo, zài hē yì bēi kāfēi.","speaker":"Đoạn văn","vi":"Bữa sáng tôi ăn một chiếc bánh mì, thỉnh thoảng ăn một miếng bánh ngọt, rồi uống thêm một cốc cà phê."},{"hanzi":"午饭和晚饭也都在外面吃。","pinyin":"Wǔfàn hé wǎnfàn yě dōu zài wàimiàn chī.","speaker":"Đoạn văn","vi":"Bữa trưa và bữa tối cũng đều ăn ở ngoài."},{"hanzi":"快要考试的时候又忙又累，没时间出去吃饭，家里又什么吃的都没有，我可能好几天只吃方便面。","pinyin":"Kuài yào kǎoshì de shíhou yòu máng yòu lèi, méi shíjiān chūqù chīfàn, jiālǐ yòu shénme chī de dōu méiyǒu, wǒ kěnéng hǎo jǐ tiān zhǐ chī fāngbiànmiàn.","speaker":"Đoạn văn","vi":"Lúc sắp thi vừa bận vừa mệt, không có thời gian ra ngoài ăn, trong nhà lại chẳng có đồ gì để ăn, có thể mấy ngày liền tôi chỉ ăn mì ăn liền."},{"hanzi":"现在回到中国了，每天能吃到妈妈做的饭，我真是太高兴了！","pinyin":"Xiànzài huídào Zhōngguó le, měitiān néng chīdào māma zuò de fàn, wǒ zhēn shì tài gāoxìng le!","speaker":"Đoạn văn","vi":"Bây giờ về đến Trung Quốc rồi, ngày nào cũng được ăn cơm mẹ nấu, tôi thật sự vui quá!"},{"hanzi":"有时候妈妈只做几个简单的菜，我也非常爱吃，因为什么都没有妈妈做的饭好吃。","pinyin":"Yǒushíhou māma zhǐ zuò jǐ ge jiǎndān de cài, wǒ yě fēicháng ài chī, yīnwèi shénme dōu méiyǒu māma zuò de fàn hǎochī.","speaker":"Đoạn văn","vi":"Có lúc mẹ chỉ nấu vài món đơn giản thôi, tôi cũng rất thích ăn, vì chẳng có gì ngon bằng cơm mẹ nấu cả."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"快要考试的时候又忙又累，没时间出去吃饭，家里又什么吃的都没有，我可能好几天只吃方便面。\" (Lúc sắp thi vừa bận vừa mệt, không có thời gian ra ngoài ăn cơm, trong nhà lại chẳng có đồ ăn gì, có khi mấy ngày liền tôi chỉ ăn mì ăn liền.), nên đáp án đúng là vì vừa bận vừa mệt, không có thời gian ra ngoài ăn và trong nhà không có đồ ăn.","options":["因为他最喜欢吃方便面，不喜欢在外面吃","因为那时候他又忙又累，没时间出去吃饭，家里也没有别的东西吃","因为在国外买面包和蛋糕太贵了","因为他天天在学校图书馆学习，图书馆只卖方便面"],"q":"在国外的时候，为什么快要考试时李文可能好几天只吃方便面？"},{"answerIdx":2,"explanation":"Trong bài có câu \"现在回到中国了，每天能吃到妈妈做的饭，我真是太高兴了！\" (Bây giờ về Trung Quốc rồi, ngày nào cũng được ăn cơm mẹ nấu, tôi thật sự rất vui sướng!), nên đáp án đúng là mỗi ngày đều được ăn cơm mẹ nấu.","options":["在中国每天都可以吃饺子和鸡肉饭","回到中国以后不需要再参加考试了","每天都能吃到妈妈做的饭","可以经常去外面跟朋友一起吃方便面"],"q":"回到中国以后，什么事情让李文觉得非常高兴？"}],"scene":"在李文家，李文在写日记。","sceneVi":"Ở nhà Lý Văn, Lý Văn đang viết nhật ký."}],"hsk3-3":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"小雪的初中离家有点儿远，咱们换一个近点儿的房子吧。","pinyin":"Xiǎoxuě de chūzhōng lí jiā yǒudiǎnr yuǎn, zánmen huàn yí gè jìndiǎnr de fángzi ba.","speaker":"王一雪","vi":"Trường cấp hai của Tiểu Tuyết hơi xa nhà, chúng ta đổi sang một căn nhà gần hơn chút đi."},{"hanzi":"好啊，我上网看看。你觉得这个小区怎么样？","pinyin":"Hǎo a, wǒ shàngwǎng kànkan. Nǐ juéde zhège xiǎoqū zěnmeyàng?","speaker":"刘明","vi":"Được thôi, để anh lên mạng xem thử. Em thấy khu dân cư này thế nào?"},{"hanzi":"环境挺好的，离地铁站还不远。","pinyin":"Huánjìng tǐng hǎo de, lí dìtiězhàn hái bù yuǎn.","speaker":"王一雪","vi":"Môi trường khá tốt đấy, lại còn không xa ga tàu điện ngầm."},{"hanzi":"房子里面也不错，空调和洗衣机都是新的。","pinyin":"Fángzi lǐmiàn yě búcuò, kōngtiáo hé xǐyījī dōu shì xīn de.","speaker":"刘明","vi":"Bên trong nhà cũng ổn lắm, điều hòa và máy giặt đều là đồ mới."},{"hanzi":"是不错，但是我不喜欢住一层。","pinyin":"Shì búcuò, dànshì wǒ bù xǐhuan zhù yì céng.","speaker":"王一雪","vi":"Ổn thật đấy, nhưng em không thích ở tầng một."},{"hanzi":"这个一层带一个小花园，我觉得咱们可以去看看。","pinyin":"Zhège yì céng dài yí gè xiǎo huāyuán, wǒ juéde zánmen kěyǐ qù kànkan.","speaker":"刘明","vi":"Căn tầng một này có kèm một khu vườn nhỏ, anh thấy chúng ta có thể đi xem thử."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Vương Nhất Tuyết nói \"小雪的初中离家有点儿远，咱们换一个近点儿的房子吧。\" (Trường cấp hai của Tiểu Tuyết hơi xa nhà, chúng ta đổi một căn nhà gần hơn chút đi.), nên lý do họ muốn đổi nhà là trường của Tiểu Tuyết cách nhà hơi xa.","options":["现在的房子没有小花园","小雪的初中离家有点儿远","现在的房子空调和洗衣机都坏了","现在的房子离地铁站太远了"],"q":"王一雪和刘明为什么想换房子？"},{"answerIdx":2,"explanation":"Trong bài, Vương Nhất Tuyết nói \"是不错，但是我不喜欢住一层。\" (Cũng ổn đấy, nhưng em không thích ở tầng một.), nên điểm khiến cô ấy chưa ưng ý là căn nhà nằm ở tầng một.","options":["小区的环境不太好","离地铁站太远了","房子在一层","房子里的空调太旧了"],"q":"关于刘明在网上看到的房子，王一雪不太喜欢什么？"}],"scene":"在家里，刘明和王一雪在聊天儿。","sceneVi":"Ở nhà, Lưu Minh và Vương Nhất Tuyết đang trò chuyện."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"我今天早上来的时候，灯还开着。","pinyin":"Wǒ jīntiān zǎoshang lái de shíhou, dēng hái kāizhe.","speaker":"王一雪","vi":"Sáng nay lúc em đến, đèn vẫn còn đang bật."},{"hanzi":"我这几天忙坏了，可能走的时候忘关了。","pinyin":"Wǒ zhè jǐ tiān máng huài le, kěnéng zǒu de shíhou wàng guān le.","speaker":"刘明","vi":"Mấy hôm nay anh bận muốn chết, có lẽ lúc đi quên tắt rồi."},{"hanzi":"冰箱不能用，这些吃的东西放在哪儿？","pinyin":"Bīngxiāng bù néng yòng, zhèxiē chī de dōngxi fàng zài nǎr?","speaker":"王一雪","vi":"Tủ lạnh không dùng được, mấy đồ ăn này để ở đâu bây giờ?"},{"hanzi":"不可能吧？冰箱是新买的，我来看看。","pinyin":"Bù kěnéng ba? Bīngxiāng shì xīn mǎi de, wǒ lái kànkan.","speaker":"刘明","vi":"Không thể nào chứ? Tủ lạnh là mới mua mà, để anh ra xem thử."},{"hanzi":"洗衣机也坏了吗？","pinyin":"Xǐyījī yě huài le ma?","speaker":"王一雪","vi":"Máy giặt cũng hỏng rồi à?"},{"hanzi":"没坏，但是卫生间没打扫好，还不能洗衣服。","pinyin":"Méi huài, dànshì wèishēngjiān méi dǎsǎo hǎo, hái bù néng xǐ yīfu.","speaker":"刘明","vi":"Không hỏng, nhưng nhà vệ sinh chưa dọn xong nên vẫn chưa giặt quần áo được."},{"hanzi":"星期天我们真的能搬家吗？","pinyin":"Xīngqītiān wǒmen zhēn de néng bānjiā ma?","speaker":"王一雪","vi":"Chủ nhật chúng ta thật sự chuyển nhà được không đấy?"}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Lưu Minh nói \"我这几天忙坏了，可能走的时候忘关了。\" (Mấy hôm nay anh bận túi bụi, có lẽ lúc đi quên tắt rồi.), nên đèn vẫn bật là do Lưu Minh có thể đã quên tắt khi rời đi.","options":["王一雪昨天晚上忘记关了","刘明走的时候可能忘记关了","家里一直有人在收拾房间","新家的灯坏了，关不上"],"q":"王一雪今天早上来新家时，为什么灯还开着？"},{"answerIdx":2,"explanation":"Trong bài, Lưu Minh giải thích \"没坏，但是卫生间没打扫好，还不能洗衣服。\" (Không hỏng đâu, nhưng nhà vệ sinh chưa dọn xong, vẫn chưa giặt đồ được.), nên nguyên nhân chưa giặt đồ được là nhà vệ sinh chưa dọn xong.","options":["洗衣机是旧的，已经坏了","新家还没有买洗衣机","卫生间还没有打扫好","房间里没有地方放衣服"],"q":"现在为什么还不能在新家洗衣服？"}],"scene":"在新家，王一雪在收拾房间，刘明进来了。","sceneVi":"Ở nhà mới, Vương Nhất Tuyết đang dọn dẹp phòng thì Lưu Minh bước vào."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"这个月花了不少钱。","pinyin":"Zhège yuè huā le bù shǎo qián.","speaker":"王一雪","vi":"Tháng này tiêu không ít tiền rồi."},{"hanzi":"是的，我们买了很多搬家时要用的东西。","pinyin":"Shì de, wǒmen mǎi le hěn duō bānjiā shí yào yòng de dōngxi.","speaker":"刘明","vi":"Đúng vậy, chúng ta đã mua rất nhiều đồ cần dùng khi chuyển nhà."},{"hanzi":"咱们办张信用卡吧，花的钱可以慢慢还。听说中国银行的服务不错，办了信用卡买东西还能便宜。","pinyin":"Zánmen bàn zhāng xìnyòngkǎ ba, huā de qián kěyǐ mànmàn huán. Tīngshuō Zhōngguó Yínháng de fúwù búcuò, bàn le xìnyòngkǎ mǎi dōngxi hái néng piányi.","speaker":"王一雪","vi":"Chúng ta làm một chiếc thẻ tín dụng đi, tiền tiêu rồi có thể từ từ trả. Nghe nói dịch vụ của Ngân hàng Trung Quốc khá tốt, làm thẻ tín dụng rồi khi mua đồ còn được rẻ hơn nữa."},{"hanzi":"好啊！中国银行很近，走路几分钟就能到。咱们什么时候去？","pinyin":"Hǎo a! Zhōngguó Yínháng hěn jìn, zǒulù jǐ fēnzhōng jiù néng dào. Zánmen shénme shíhou qù?","speaker":"刘明","vi":"Được đấy! Ngân hàng Trung Quốc rất gần, đi bộ vài phút là tới. Bao giờ chúng ta đi?"},{"hanzi":"今天下午？","pinyin":"Jīntiān xiàwǔ?","speaker":"王一雪","vi":"Chiều nay thì sao?"},{"hanzi":"我下午要去医院，很晚才能回来。","pinyin":"Wǒ xiàwǔ yào qù yīyuàn, hěn wǎn cái néng huílái.","speaker":"刘明","vi":"Chiều nay anh phải đi bệnh viện, rất muộn mới về được."},{"hanzi":"那我下午自己去吧。","pinyin":"Nà wǒ xiàwǔ zìjǐ qù ba.","speaker":"王一雪","vi":"Vậy chiều nay em tự đi nhé."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Vương Nhất Tuyết nói \"听说中国银行的服务不错，办了信用卡买东西还能便宜。\" (Nghe nói dịch vụ của Ngân hàng Trung Quốc rất tốt, làm thẻ tín dụng rồi mua đồ còn được rẻ hơn.), nên đó là lý do cô ấy muốn làm thẻ ở Ngân hàng Trung Quốc.","options":["因为中国银行就在医院旁边","因为中国银行服务不错，买东西还能便宜","因为他们还没有钱买搬家的东西","因为刘明在中国银行工作"],"q":"王一雪为什么想办中国银行的信用卡？"},{"answerIdx":2,"explanation":"Trong bài, vì buổi chiều Lưu Minh phải đi bệnh viện và về muộn nên Vương Nhất Tuyết nói \"那我下午自己去吧。\" (Vậy chiều nay em tự đi vậy.), nên chiều nay Vương Nhất Tuyết sẽ tự đi ngân hàng.","options":["刘明一个人去","王一雪和刘明一起去","王一雪自己去","他们明天上午再去"],"q":"今天下午谁去银行办信用卡？"}],"scene":"在家里，刘明和王一雪在客厅聊天儿。","sceneVi":"Ở nhà, Lưu Minh và Vương Nhất Tuyết đang trò chuyện ở phòng khách."},{"id":4,"isNarrative":false,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"我觉得这个星期就能搬家。我明天去买一些纸箱，很快就能准备好。搬家那天，我想请几位朋友来帮忙，最多一天就能搬完。","pinyin":"Wǒ juéde zhège xīngqī jiù néng bānjiā. Wǒ míngtiān qù mǎi yìxiē zhǐxiāng, hěn kuài jiù néng zhǔnbèi hǎo. Bānjiā nà tiān, wǒ xiǎng qǐng jǐ wèi péngyou lái bāngmáng, zuìduō yì tiān jiù néng bān wán.","speaker":"刘明","vi":"Anh thấy tuần này là có thể chuyển nhà được rồi. Ngày mai anh đi mua ít thùng giấy, rất nhanh sẽ chuẩn bị xong. Hôm chuyển nhà, anh định nhờ vài người bạn đến giúp, nhiều nhất một ngày là chuyển xong."},{"hanzi":"我觉得下个月才能搬家。这周开始准备，下周去打扫新家，这么多事情最少需要两个星期才能做完。搬家那天，我们应该找一家搬家公司。","pinyin":"Wǒ juéde xià gè yuè cái néng bānjiā. Zhè zhōu kāishǐ zhǔnbèi, xià zhōu qù dǎsǎo xīnjiā, zhème duō shìqing zuìshǎo xūyào liǎng gè xīngqī cái néng zuò wán. Bānjiā nà tiān, wǒmen yīnggāi zhǎo yì jiā bānjiā gōngsī.","speaker":"王一雪","vi":"Em thấy tháng sau mới chuyển nhà được. Tuần này bắt đầu chuẩn bị, tuần sau đi dọn dẹp nhà mới, nhiều việc thế này ít nhất cần hai tuần mới làm xong. Hôm chuyển nhà, chúng ta nên tìm một công ty chuyển nhà."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Lưu Minh nói \"我觉得这个星期就能搬家……搬家那天，我想请几位朋友来帮忙，最多一天就能搬完。\" (Anh thấy tuần này là có thể chuyển nhà rồi... Ngày chuyển nhà, anh muốn mời vài người bạn đến giúp, nhiều nhất một ngày là chuyển xong.), nên anh ấy định chuyển nhà trong tuần này và nhờ vài người bạn đến giúp.","options":["下个月请搬家公司来帮忙","这个星期请几位朋友来帮忙","明天一个人先搬一部分东西","等两个星期以后再找朋友帮忙"],"q":"关于搬家，刘明打算怎么搬？"},{"answerIdx":2,"explanation":"Trong bài, Vương Nhất Tuyết nói \"这周开始准备，下周去打扫新家，这么多事情最少需要两个星期才能做完。\" (Tuần này bắt đầu chuẩn bị, tuần sau đi dọn nhà mới, nhiều việc như vậy ít nhất cần hai tuần mới làm xong.), nên cô ấy cho rằng tháng sau mới chuyển nhà được.","options":["因为她明天买不到纸箱","因为朋友这个星期没有时间","因为这么多事情最少需要两个星期才能做完","因为搬家公司这个月没有空"],"q":"王一雪为什么觉得下个月才能搬家？"}],"scene":"在家里，刘明和王一雪讨论搬家计划。","sceneVi":"Ở nhà, Lưu Minh và Vương Nhất Tuyết đang thảo luận kế hoạch chuyển nhà."}],"hsk3-4":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"这个假期咱们去哪儿玩玩吧。","pinyin":"Zhège jiàqī zánmen qù nǎr wánwan ba.","speaker":"杨同乐","vi":"Kỳ nghỉ này chúng mình đi đâu đó chơi đi."},{"hanzi":"好啊，你想去哪儿，咱们就去哪儿。","pinyin":"Hǎo a, nǐ xiǎng qù nǎr, zánmen jiù qù nǎr.","speaker":"王一飞","vi":"Được thôi, anh muốn đi đâu thì chúng mình đi đấy."},{"hanzi":"你喜欢海，找个海边住几天，怎么样？","pinyin":"Nǐ xǐhuan hǎi, zhǎo gè hǎibiān zhù jǐ tiān, zěnmeyàng?","speaker":"杨同乐","vi":"Em thích biển, tìm một vùng biển ở vài ngày thì sao?"},{"hanzi":"现在去海边有点儿冷。","pinyin":"Xiànzài qù hǎibiān yǒudiǎnr lěng.","speaker":"王一飞","vi":"Bây giờ đi biển hơi lạnh."},{"hanzi":"那去草原吧？草原一点儿也不冷。","pinyin":"Nà qù cǎoyuán ba? Cǎoyuán yìdiǎnr yě bù lěng.","speaker":"杨同乐","vi":"Thế đi thảo nguyên nhé? Thảo nguyên không lạnh chút nào đâu."},{"hanzi":"这个主意好！我好久没骑马了。","pinyin":"Zhège zhǔyi hǎo! Wǒ hǎojiǔ méi qímǎ le.","speaker":"王一飞","vi":"Ý kiến này hay đấy! Em lâu lắm rồi chưa cưỡi ngựa."},{"hanzi":"对，在草原上骑马、吃羊肉、看月亮，一定很有意思。","pinyin":"Duì, zài cǎoyuán shàng qímǎ, chī yángròu, kàn yuèliang, yídìng hěn yǒuyìsi.","speaker":"杨同乐","vi":"Đúng vậy, cưỡi ngựa, ăn thịt cừu, ngắm trăng trên thảo nguyên chắc chắn rất thú vị."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, khi Dương Đồng Nhạc gợi ý đi biển, Vương Nhất Phi trả lời \"现在去海边有点儿冷。\" (Bây giờ đi biển hơi lạnh.), nên lý do anh ấy không muốn đi biển là trời hơi lạnh.","options":["因为他不喜欢海","因为现在去海边有点儿冷","因为海边没有好玩儿的地方","因为他更想去看月亮"],"q":"王一飞为什么现在不想去海边？"},{"answerIdx":1,"explanation":"Trong bài, Dương Đồng Nhạc nói \"在草原上骑马、吃羊肉、看月亮，一定很有意思。\" (Ở trên thảo nguyên cưỡi ngựa, ăn thịt cừu, ngắm trăng, nhất định rất thú vị.), nên họ có thể cưỡi ngựa, ăn thịt cừu và ngắm trăng.","options":["游泳、吃海鲜、晒太阳","骑马、吃羊肉、看月亮","爬山、照相、喝茶","散步、看星星、吃水果"],"q":"根据对话，他们决定去草原做什么？"}],"scene":"在王一飞家客厅，杨同乐和王一飞在聊天儿。","sceneVi":"Tại phòng khách nhà Vương Nhất Phi, Dương Đồng Nhạc và Vương Nhất Phi đang trò chuyện."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"出去玩的机票买好了吗？","pinyin":"Chūqù wán de jīpiào mǎi hǎo le ma?","speaker":"杨同乐","vi":"Vé máy bay đi chơi đã mua xong chưa?"},{"hanzi":"买好了。星期六上午十点一刻起飞。","pinyin":"Mǎi hǎo le. Xīngqīliù shàngwǔ shí diǎn yí kè qǐfēi.","speaker":"王一飞","vi":"Mua xong rồi. 10 giờ 15 phút sáng thứ Bảy cất cánh."},{"hanzi":"宾馆也选好了吗？","pinyin":"Bīnguǎn yě xuǎn hǎo le ma?","speaker":"杨同乐","vi":"Khách sạn cũng chọn xong rồi à?"},{"hanzi":"是的，这家宾馆很特别，跟别的都不一样，一出门就能看见牛和羊！","pinyin":"Shì de, zhè jiā bīnguǎn hěn tèbié, gēn biéde dōu bù yíyàng, yì chūmén jiù néng kànjiàn niú hé yáng!","speaker":"王一飞","vi":"Đúng vậy, khách sạn này rất đặc biệt, không giống bất kỳ chỗ nào khác, vừa bước ra cửa là có thể nhìn thấy trâu bò và cừu!"},{"hanzi":"太好了！你看看要带什么东西？","pinyin":"Tài hǎo le! Nǐ kànkan yào dài shénme dōngxi?","speaker":"杨同乐","vi":"Tuyệt quá! Em xem thử cần mang theo những gì?"},{"hanzi":"我们不用带太多东西，别忘了拿上新买的相机。","pinyin":"Wǒmen búyòng dài tài duō dōngxi, bié wàng le náshang xīn mǎi de xiàngjī.","speaker":"王一飞","vi":"Chúng ta không cần mang quá nhiều đồ đâu, đừng quên mang theo chiếc máy ảnh mới mua nhé."},{"hanzi":"一定不会忘带的。我现在就去准备行李。","pinyin":"Yídìng bú huì wàng dài de. Wǒ xiànzài jiù qù zhǔnbèi xíngli.","speaker":"杨同乐","vi":"Chắc chắn sẽ không quên mang đâu. Anh đi chuẩn bị hành lý ngay đây."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài, Vương Nhất Phi giới thiệu \"这家宾馆很特别，跟别的都不一样，一出门就能看见牛和羊！\" (Khách sạn này rất đặc biệt, không giống những nơi khác, vừa ra khỏi cửa là có thể nhìn thấy bò và cừu!), nên điểm đặc biệt là ra khỏi cửa đã thấy bò và cừu.","options":["离飞机场特别近","房间里有很多新东西","一出门就能看见牛和羊","是新开的，非常便宜"],"q":"王一飞选的宾馆有什么特别的地方？"},{"answerIdx":3,"explanation":"Trong bài, Vương Nhất Phi dặn \"我们不用带太多东西，别忘了拿上新买的相机。\" (Chúng ta không cần mang quá nhiều đồ, đừng quên mang theo chiếc máy ảnh mới mua.), nên thứ không được quên mang theo là chiếc máy ảnh mới mua.","options":["护照和机票","厚衣服和运动鞋","吃的东西和水果","新买的相机"],"q":"王一飞提醒杨同乐别忘了带什么？"}],"scene":"在王一飞家客厅，杨同乐和王一飞在聊天儿。","sceneVi":"Tại phòng khách nhà Vương Nhất Phi, Dương Đồng Nhạc và Vương Nhất Phi đang trò chuyện."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"欢迎你们！我是你们的司机，我姓李，叫我小李就可以。","pinyin":"Huānyíng nǐmen! Wǒ shì nǐmen de sījī, wǒ xìng Lǐ, jiào wǒ Xiǎo Lǐ jiù kěyǐ.","speaker":"小李","vi":"Chào mừng anh chị! Tôi là tài xế của anh chị, tôi họ Lý, gọi tôi là Tiểu Lý là được."},{"hanzi":"您好！不好意思，飞机晚点了，让您久等了。","pinyin":"Nínhǎo! Bùhǎoyìsi, fēijī wǎndiǎn le, ràng nín jiǔ děng le.","speaker":"杨同乐","vi":"Chào anh! Ngại quá, máy bay bị trễ chuyến, để anh phải đợi lâu rồi."},{"hanzi":"没关系。除了这个行李箱以外，还有别的东西吗？","pinyin":"Méi guānxi. Chúle zhège xínglixiāng yǐwài, hái yǒu biéde dōngxi ma?","speaker":"小李","vi":"Không sao đâu. Ngoài chiếc vali này ra, còn đồ đạc nào khác nữa không ạ?"},{"hanzi":"还有一个包，我自己拿就可以。","pinyin":"Hái yǒu yí gè bāo, wǒ zìjǐ ná jiù kěyǐ.","speaker":"杨同乐","vi":"Còn một cái túi nữa, tôi tự cầm là được rồi."},{"hanzi":"车在一层，请跟我来。","pinyin":"Chē zài yì céng, qǐng gēn wǒ lái.","speaker":"小李","vi":"Xe đỗ ở tầng một, xin mời đi theo tôi."},{"hanzi":"我们住的宾馆离机场远吗？","pinyin":"Wǒmen zhù de bīnguǎn lí jīchǎng yuǎn ma?","speaker":"杨同乐","vi":"Khách sạn chúng tôi ở có xa sân bay không?"},{"hanzi":"不远，三十分钟就能到。两位到了可以先休息休息，晚饭的时候我叫你们。","pinyin":"Bù yuǎn, sānshí fēnzhōng jiù néng dào. Liǎng wèi dào le kěyǐ xiān xiūxi xiūxi, wǎnfàn de shíhou wǒ jiào nǐmen.","speaker":"小李","vi":"Không xa đâu, ba mươi phút là tới. Hai anh chị đến nơi có thể nghỉ ngơi trước một lát, đến giờ ăn tối tôi sẽ gọi anh chị."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Dương Đồng Nhạc nói \"不好意思，飞机晚点了，让您久等了。\" (Ngại quá, máy bay bị trễ chuyến, để anh đợi lâu rồi.), nên lý do họ đến muộn là máy bay bị trễ chuyến.","options":["因为他们找错了机场的门","因为他们的飞机晚点了","因为他们带的行李太多了","因为他们起床起晚了"],"q":"为什么杨同乐对小李说“不好意思，让您久等了”？"},{"answerIdx":2,"explanation":"Trong bài, Tiểu Lý nói \"不远，三十分钟就能到。\" (Không xa đâu, ba mươi phút là tới rồi.), mà 30 phút chính là nửa tiếng (半个小时), nên đáp án đúng là nửa tiếng.","options":["十五分钟","二十分钟","半个小时","一个小时"],"q":"从机场到他们住的宾馆要多长时间？"}],"scene":"在机场，杨同乐和王一飞走出来，跟他们预约的司机兼导游见面。","sceneVi":"Tại sân bay, Dương Đồng Nhạc và Vương Nhất Phi bước ra ngoài, gặp tài xế kiêm hướng dẫn viên mà họ đã đặt trước."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"今天是我们旅游的第一天。","pinyin":"Jīntiān shì wǒmen lǚyóu de dì-yī tiān.","speaker":"Đoạn văn","vi":"Hôm nay là ngày đầu tiên trong chuyến du lịch của chúng tôi."},{"hanzi":"我们很早就起床去机场了，没想到飞机晚点了。","pinyin":"Wǒmen hěn zǎo jiù qǐchuáng qù jīchǎng le, méi xiǎngdào fēijī wǎndiǎn le.","speaker":"Đoạn văn","vi":"Chúng tôi dậy rất sớm để ra sân bay, không ngờ máy bay lại bị trễ chuyến."},{"hanzi":"我们到的时候，天已经黑了，但是司机小李一直在机场等我们，一点儿也没着急。","pinyin":"Wǒmen dào de shíhou, tiān yǐjīng hēi le, dànshì sījī Xiǎo Lǐ yìzhí zài jīchǎng děng wǒmen, yìdiǎnr yě méi zháojí.","speaker":"Đoạn văn","vi":"Lúc chúng tôi đến nơi thì trời đã tối rồi, nhưng tài xế Tiểu Lý vẫn luôn đợi chúng tôi ở sân bay, không hề sốt ruột chút nào."},{"hanzi":"他特别热情，路上给我们介绍了很多东西，还准备了水果。","pinyin":"Tā tèbié rèqíng, lùshang gěi wǒmen jièshào le hěn duō dōngxi, hái zhǔnbèi le shuǐguǒ.","speaker":"Đoạn văn","vi":"Anh ấy cực kỳ nhiệt tình, trên đường đi giới thiệu cho chúng tôi rất nhiều thứ, lại còn chuẩn bị cả hoa quả nữa."},{"hanzi":"宾馆的房间跟我想的一样漂亮，又大又干净，我非常满意。","pinyin":"Bīnguǎn de fángjiān gēn wǒ xiǎng de yíyàng piàoliang, yòu dà yòu gānjìng, wǒ fēicháng mǎnyì.","speaker":"Đoạn văn","vi":"Phòng khách sạn đẹp đúng như tôi nghĩ, vừa rộng rãi vừa sạch sẽ, tôi vô cùng hài lòng."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu \"司机小李一直在机场等我们，一点儿也没着急。他特别热情，路上给我们介绍了很多东西，还准备了水果。\" (Tài xế Tiểu Lý luôn đợi chúng tôi ở sân bay, không hề sốt ruột chút nào. Anh ấy vô cùng nhiệt tình, trên đường giới thiệu cho chúng tôi rất nhiều thứ, còn chuẩn bị cả trái cây.), nên câu đúng là anh ấy luôn đợi ở sân bay và còn chuẩn bị trái cây.","options":["因为等太久，他有点儿着急","他在路上只开车，没说话","他一直在机场等，还准备了水果","他没有去机场，在宾馆等他们"],"q":"关于司机小李，下面哪句话是对的？"},{"answerIdx":0,"explanation":"Trong bài có câu \"宾馆的房间跟我想的一样漂亮，又大又干净，我非常满意。\" (Phòng khách sạn đẹp giống như tôi nghĩ, vừa rộng vừa sạch, tôi vô cùng hài lòng.), nên Vương Nhất Phi nhận xét phòng vừa rộng vừa sạch và rất hài lòng.","options":["又大又干净，非常满意","很漂亮，但是有点儿小","很干净，但是离路边太近","跟他想的不太一样，有点儿旧"],"q":"王一飞觉得宾馆的房间怎么样？"}],"scene":"在宾馆房间，王一飞在写日记。","sceneVi":"Trong phòng khách sạn, Vương Nhất Phi đang viết nhật ký."}],"hsk3-5":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"这个星期总是阴天，今天终于晴了。","pinyin":"Zhège xīngqī zǒngshì yīntiān, jīntiān zhōngyú qíng le.","speaker":"白家月","vi":"Tuần này lúc nào cũng âm u, hôm nay cuối cùng cũng nắng rồi."},{"hanzi":"现在天气好得很！我们去爬山怎么样？","pinyin":"Xiànzài tiānqì hǎo de hěn! Wǒmen qù páshān zěnmeyàng?","speaker":"李文","vi":"Bây giờ thời tiết đẹp lắm! Chúng ta đi leo núi thế nào?"},{"hanzi":"好啊！又能锻炼身体，又能照好看的照片。","pinyin":"Hǎo a! Yòu néng duànliàn shēntǐ, yòu néng zhào hǎokàn de zhàopiàn.","speaker":"白家月","vi":"Được đấy! Vừa rèn luyện sức khỏe được, vừa chụp được những bức ảnh đẹp."},{"hanzi":"那我带点儿水和吃的，咱们现在就去？","pinyin":"Nà wǒ dài diǎnr shuǐ hé chī de, zánmen xiànzài jiù qù?","speaker":"李文","vi":"Vậy mình mang một chút nước và đồ ăn, bây giờ chúng ta đi luôn nhé?"},{"hanzi":"我回去穿上运动鞋，拿上大衣。要不要叫一雪姐一起去？","pinyin":"Wǒ huíqù chuānshàng yùndòngxié, náshàng dàyī. Yào bu yào jiào Yīxuě jiě yìqǐ qù?","speaker":"白家月","vi":"Mình về đi giày thể thao, lấy áo khoác. Có nên rủ chị Nhất Tuyết đi cùng không?"},{"hanzi":"好主意。给她打个电话吧。","pinyin":"Hǎo zhǔyi. Gěi tā dǎ ge diànhuà ba.","speaker":"李文","vi":"Ý kiến hay đấy. Gọi điện thoại cho chị ấy đi."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài, Bạch Gia Nguyệt nói \"这个星期总是阴天，今天终于晴了。\" (Tuần này toàn trời âm u, hôm nay cuối cùng cũng nắng rồi.) và Lý Văn nói \"现在天气好得很！\" (Bây giờ thời tiết đẹp lắm!), nên hôm nay trời cuối cùng đã nắng và thời tiết rất đẹp.","options":["还是阴天，有点儿冷","下小雨了，不能爬山","终于晴了，天气很好","刮风了，需要穿大衣"],"q":"今天的天气怎么样？"},{"answerIdx":1,"explanation":"Trong bài, Bạch Gia Nguyệt nói \"我回去穿上运动鞋，拿上大衣。\" (Tôi về xỏ giày thể thao, lấy thêm áo khoác dài.), nên trước khi đi leo núi cô ấy cần về nhà đi giày thể thao và lấy áo khoác.","options":["带点儿水和吃的东西","穿运动鞋，拿上大衣","拿照相机和手机","去叫王一雪一起出发"],"q":"去爬山以前，白家月要回家做什么？"}],"scene":"在街上，白家月和李文边散步边聊天儿。","sceneVi":"Trên đường, Bạch Gia Nguyệt và Lý Văn vừa đi dạo vừa trò chuyện."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"这些照片是谁给您照的？张张都非常好看。","pinyin":"Zhèxiē zhàopiàn shì shéi gěi nín zhào de? Zhāngzhāng dōu fēicháng hǎokàn.","speaker":"白家月","vi":"Những bức ảnh này là ai chụp cho chị thế? Tấm nào cũng rất đẹp."},{"hanzi":"一飞。她对拍照一直很感兴趣，经常给我照相。","pinyin":"Yīfēi. Tā duì pāizhào yìzhí hěn gǎn xìngqù, jīngcháng gěi wǒ zhàoxiàng.","speaker":"王一雪","vi":"Nhất Phi. Em ấy trước giờ rất thích chụp ảnh, thường xuyên chụp ảnh cho chị."},{"hanzi":"我喜欢您大笑的这张，看起来很漂亮。","pinyin":"Wǒ xǐhuan nín dàxiào de zhè zhāng, kàn qǐlái hěn piàoliang.","speaker":"白家月","vi":"Em thích tấm chị cười lớn này, trông rất xinh đẹp."},{"hanzi":"我觉得这张有点儿难看，那时候我不知道她在给我照相。","pinyin":"Wǒ juéde zhè zhāng yǒudiǎnr nánkàn, nà shíhou wǒ bù zhīdào tā zài gěi wǒ zhàoxiàng.","speaker":"王一雪","vi":"Chị thấy tấm này hơi xấu một chút, lúc đó chị không biết em ấy đang chụp ảnh cho chị."},{"hanzi":"这样的照片才好看。我也喜欢拍照，爬山的时候我给您照几张照片吧。","pinyin":"Zhèyàng de zhàopiàn cái hǎokàn. Wǒ yě xǐhuan pāizhào, páshān de shíhou wǒ gěi nín zhào jǐ zhāng zhàopiàn ba.","speaker":"白家月","vi":"Ảnh như thế này mới đẹp chứ. Em cũng thích chụp ảnh, lúc leo núi em chụp cho chị vài tấm nhé."},{"hanzi":"好，我可以比较一下你们两个谁的水平高。","pinyin":"Hǎo, wǒ kěyǐ bǐjiào yíxià nǐmen liǎng ge shéi de shuǐpíng gāo.","speaker":"王一雪","vi":"Được, chị có thể so sánh xem trình độ của hai đứa ai cao hơn."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Vương Nhất Tuyết nói \"我觉得这张有点儿难看，那时候我不知道她在给我照相。\" (Chị thấy tấm này hơi xấu, lúc đó chị không biết em ấy đang chụp ảnh cho chị.), nên lý do là lúc đó chị ấy không biết Nhất Phi đang chụp ảnh cho mình.","options":["因为那张照片照得不清楚","因为照相的时候她不知道一飞在拍照","因为一飞对拍照不感兴趣","因为当时天气不好，没有太阳"],"q":"王一雪为什么觉得自己大笑的那张照片有点儿难看？"},{"answerIdx":2,"explanation":"Trong bài, Bạch Gia Nguyệt nói \"我也喜欢拍照，爬山的时候我给您照几张照片吧。\" (Em cũng thích chụp ảnh, lúc leo núi em chụp cho chị vài tấm nhé.), nên cô ấy định chụp cho Vương Nhất Tuyết vài bức ảnh.","options":["请一飞给她们两个拍照","教王一雪怎么用手机拍照","给王一雪照几张照片","看看王一雪的手机里有什么照片"],"q":"爬山的时候，白家月打算做什么？"}],"scene":"在出租车上，王一雪和白家月在聊天儿。","sceneVi":"Trên xe taxi, Vương Nhất Tuyết và Bạch Gia Nguyệt đang trò chuyện."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"家月，这里挺漂亮的，咱们在这里拍照吧。","pinyin":"Jiāyuè, zhèlǐ tǐng piàoliang de, zánmen zài zhèlǐ pāizhào ba.","speaker":"王一雪","vi":"Gia Nguyệt, chỗ này đẹp ghê, chúng ta chụp ảnh ở đây đi."},{"hanzi":"这边没有太阳，咱们去那边吧。","pinyin":"Zhèbiān méiyǒu tàiyáng, zánmen qù nàbiān ba.","speaker":"白家月","vi":"Bên này không có nắng, chúng ta sang bên kia đi."},{"hanzi":"好。你觉得我站在这些树中间怎么样？","pinyin":"Hǎo. Nǐ juéde wǒ zhàn zài zhèxiē shù zhōngjiān zěnmeyàng?","speaker":"王一雪","vi":"Được. Em thấy chị đứng ở giữa những cái cây này thế nào?"},{"hanzi":"挺好的。等一下，后边走过去两个人。","pinyin":"Tǐng hǎo de. Děng yíxià, hòubiān zǒu guòqù liǎng ge rén.","speaker":"白家月","vi":"Đẹp lắm. Đợi một chút, phía sau có hai người đi qua."},{"hanzi":"我准备好了，你照的时候告诉我。","pinyin":"Wǒ zhǔnbèi hǎo le, nǐ zhào de shíhou gàosu wǒ.","speaker":"王一雪","vi":"Chị chuẩn bị xong rồi, lúc nào em chụp thì bảo chị nhé."},{"hanzi":"你不用看着我，想干什么都可以。","pinyin":"Nǐ búyòng kànzhe wǒ, xiǎng gàn shénme dōu kěyǐ.","speaker":"白家月","vi":"Chị không cần nhìn vào em đâu, muốn làm gì cũng được."},{"hanzi":"树上飞来了几只鸟，我就看它们吧。","pinyin":"Shù shang fēi lái le jǐ zhī niǎo, wǒ jiù kàn tāmen ba.","speaker":"王一雪","vi":"Trên cây có mấy con chim bay tới, chị nhìn chúng nó vậy."},{"hanzi":"啊，手机没电了。","pinyin":"A, shǒujī méi diàn le.","speaker":"白家月","vi":"Á, điện thoại hết pin rồi."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài, Bạch Gia Nguyệt nói \"挺好的。等一下，后边走过去两个人。\" (Đẹp lắm. Đợi chút, phía sau có hai người đi qua.), nên cô ấy bảo Vương Nhất Tuyết đợi một lát vì có hai người đi qua phía sau.","options":["因为那边没有太阳","因为手机突然没电了","因为后边走过去两个人","因为树上飞来了几只鸟"],"q":"王一雪站在树中间以后，白家月为什么让她等一下？"},{"answerIdx":3,"explanation":"Trong bài, ở câu cuối Bạch Gia Nguyệt nói \"啊，手机没电了。\" (Á, điện thoại hết pin rồi.), nên cuối cùng họ không chụp được ảnh ngay lúc đó vì điện thoại của Bạch Gia Nguyệt hết pin.","options":["拍到了，她拍了王一雪看鸟的照片","没拍到，因为树太多，看不清楚","没拍到，因为后边一直有人走过去","没拍到，因为白家月的手机没电了"],"q":"最后白家月给王一雪拍到照片了吗？为什么？"}],"scene":"在山上，王一雪和白家月边走边聊。","sceneVi":"Trên núi, Vương Nhất Tuyết và Bạch Gia Nguyệt vừa đi vừa trò chuyện."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"家月，我收到了你的那封邮件，也看到了你给我照的照片，张张都很漂亮。","pinyin":"Jiāyuè, wǒ shōudào le nǐ de nà fēng yóujiàn, yě kàndào le nǐ gěi wǒ zhào de zhàopiàn, zhāngzhāng dōu hěn piàoliang.","speaker":"Đoạn văn","vi":"Gia Nguyệt, chị nhận được email của em rồi, cũng đã xem những bức ảnh em chụp cho chị, tấm nào cũng rất đẹp."},{"hanzi":"我已经告诉了一飞，你的拍照水平比她高，她难过得很，哈哈。","pinyin":"Wǒ yǐjīng gàosu le Yīfēi, nǐ de pāizhào shuǐpíng bǐ tā gāo, tā nánguò de hěn, hāhā.","speaker":"Đoạn văn","vi":"Chị đã nói với Nhất Phi rồi, trình độ chụp ảnh của em cao hơn em ấy, em ấy buồn lắm đấy, ha ha."},{"hanzi":"不知道你对中国的音乐有没有兴趣？","pinyin":"Bù zhīdào nǐ duì Zhōngguó de yīnyuè yǒu méiyǒu xìngqù?","speaker":"Đoạn văn","vi":"Không biết em có hứng thú với âm nhạc Trung Quốc không?"},{"hanzi":"我送你一张明天下午音乐会的门票。","pinyin":"Wǒ sòng nǐ yì zhāng míngtiān xiàwǔ yīnyuèhuì de ménpiào.","speaker":"Đoạn văn","vi":"Chị tặng em một tấm vé buổi hòa nhạc chiều mai."},{"hanzi":"音乐会七点多结束，你听完了音乐会就来我家吃饭，尝尝我做的中国菜。","pinyin":"Yīnyuèhuì qī diǎn duō jiéshù, nǐ tīngwán le yīnyuèhuì jiù lái wǒ jiā chīfàn, chángchang wǒ zuò de Zhōngguó cài.","speaker":"Đoạn văn","vi":"Buổi hòa nhạc hơn bảy giờ kết thúc, em nghe xong buổi hòa nhạc thì qua nhà chị ăn cơm, nếm thử món ăn Trung Quốc chị nấu."},{"hanzi":"你觉得怎么样？","pinyin":"Nǐ juéde zěnmeyàng?","speaker":"Đoạn văn","vi":"Em thấy thế nào?"}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"我已经告诉了一飞，你的拍照水平比她高，她难过得很，哈哈。\" (Chị đã nói với Nhất Phi rồi, trình độ chụp ảnh của em cao hơn em ấy, em ấy buồn lắm đấy, haha.), nên Vương Nhất Tuyết đánh giá trình độ chụp ảnh của Bạch Gia Nguyệt cao hơn Nhất Phi.","options":["还可以，跟一飞的差不多","比一飞的拍照水平高","没一飞照得那么好看","只有几张照片看起来不错"],"q":"王一雪觉得白家月的拍照水平怎么样？"},{"answerIdx":1,"explanation":"Trong bài có câu \"你听完了音乐会就来我家吃饭，尝尝我做的中国菜。\" (Em nghe xong buổi hòa nhạc thì đến nhà chị ăn cơm, nếm thử món Trung Quốc chị nấu nhé.), nên Vương Nhất Tuyết mời Bạch Gia Nguyệt đến nhà chị ăn cơm và thử món Trung Quốc chị nấu.","options":["去咖啡厅喝咖啡、聊天儿","来自己家吃她做的中国菜","再一起去山上照几张相","给一飞发一封邮件"],"q":"明天听完音乐会以后，王一雪请白家月做什么？"}],"scene":"在咖啡厅里，王一雪给白家月发短信。","sceneVi":"Trong quán cà phê, Vương Nhất Tuyết nhắn tin cho Bạch Gia Nguyệt."}],"hsk3-6":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"家月，咱们该买去上海的票了。你打算怎么去上海？","pinyin":"Jiāyuè, zánmen gāi mǎi qù Shànghǎi de piào le. Nǐ dǎsuàn zěnme qù Shànghǎi?","speaker":"李文","vi":"Gia Nguyệt, chúng ta nên mua vé đi Thượng Hải rồi. Cậu dự định đi Thượng Hải bằng cách nào?"},{"hanzi":"我还没坐过高铁，咱们坐高铁去，怎么样？","pinyin":"Wǒ hái méi zuòguo gāotiě, zánmen zuò gāotiě qù, zěnmeyàng?","speaker":"白家月","vi":"Mình vẫn chưa đi tàu cao tốc bao giờ, chúng ta đi tàu cao tốc nhé, thế nào?"},{"hanzi":"没问题，从北京到上海的高铁很多，非常方便。","pinyin":"Méi wèntí, cóng Běijīng dào Shànghǎi de gāotiě hěn duō, fēicháng fāngbiàn.","speaker":"李文","vi":"Không vấn đề gì, tàu cao tốc từ Bắc Kinh đi Thượng Hải rất nhiều, vô cùng tiện lợi."},{"hanzi":"行！怎么买高铁票？","pinyin":"Xíng! Zěnme mǎi gāotiě piào?","speaker":"白家月","vi":"Được đấy! Mua vé tàu cao tốc như thế nào?"},{"hanzi":"用手机App就能买。给我你的护照，我帮你买。","pinyin":"Yòng shǒujī App jiù néng mǎi. Gěi wǒ nǐ de hùzhào, wǒ bāng nǐ mǎi.","speaker":"李文","vi":"Dùng ứng dụng trên điện thoại là mua được ngay. Đưa hộ chiếu của cậu đây, mình mua giúp cậu."},{"hanzi":"早就听说过高铁，终于可以坐上了。","pinyin":"Zǎo jiù tīngshuōguo gāotiě, zhōngyú kěyǐ zuòshàng le.","speaker":"白家月","vi":"Mình đã nghe nói về tàu cao tốc từ lâu rồi, cuối cùng cũng được đi thử rồi."},{"hanzi":"高铁又快又舒服，你一定会喜欢的。","pinyin":"Gāotiě yòu kuài yòu shūfu, nǐ yídìng huì xǐhuan de.","speaker":"李文","vi":"Tàu cao tốc vừa nhanh vừa thoải mái, cậu nhất định sẽ thích."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Bạch Gia Nguyệt nói \"我还没坐过高铁，咱们坐高铁去，怎么样？\" (Tôi vẫn chưa từng đi tàu cao tốc, chúng ta đi tàu cao tốc nhé, thấy sao?) và \"早就听说过高铁，终于可以坐上了。\" (Tôi nghe nói về tàu cao tốc từ lâu rồi, cuối cùng cũng được đi rồi.), nên cô ấy muốn đi tàu cao tốc vì chưa từng đi bao giờ và đã nghe nói từ lâu.","options":["因为高铁票比飞机票便宜很多","因为她还没坐过高铁，早就听说过了","因为只有高铁能从北京到上海","因为李文在高铁站工作"],"q":"白家月为什么想坐高铁去上海？"},{"answerIdx":2,"explanation":"Trong bài, Lý Văn nói \"用手机App就能买。给我你的护照，我帮你买。\" (Dùng ứng dụng điện thoại là mua được. Đưa hộ chiếu của bạn cho tôi, tôi mua giúp bạn.), nên Lý Văn sẽ cầm hộ chiếu của Bạch Gia Nguyệt và dùng điện thoại mua vé giúp cô ấy.","options":["他们要去火车站窗口排队买票","白家月用手机自己买两个人的票","李文拿白家月的护照，用手机帮她买票","坐高铁不需要用护照买票"],"q":"关于买高铁票，下面哪句话是对的？"}],"scene":"在咖啡厅里，李文和白家月在聊天儿。","sceneVi":"Trong quán cà phê, Lý Văn và Bạch Gia Nguyệt đang trò chuyện."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"过了前面的路口就到高铁站了。","pinyin":"Guò le qiánmiàn de lùkǒu jiù dào gāotiězhàn le.","speaker":"刘明","vi":"Qua ngã tư phía trước là tới ga tàu cao tốc rồi."},{"hanzi":"我看见了。马上就到了，这条路车很多，您小心点儿。","pinyin":"Wǒ kànjiàn le. Mǎshàng jiù dào le, zhè tiáo lù chē hěn duō, nín xiǎoxīn diǎnr.","speaker":"白家月","vi":"Em nhìn thấy rồi. Sắp tới nơi rồi, con đường này nhiều xe lắm, anh cẩn thận một chút."},{"hanzi":"好，你们还有一个小时，应该不会迟到的。","pinyin":"Hǎo, nǐmen hái yǒu yí ge xiǎoshí, yīnggāi búhuì chídào de.","speaker":"刘明","vi":"Ừ, hai người vẫn còn một tiếng nữa, chắc sẽ không bị muộn đâu."},{"hanzi":"我发现这条路车多，红绿灯也多。","pinyin":"Wǒ fāxiàn zhè tiáo lù chē duō, hónglǜdēng yě duō.","speaker":"白家月","vi":"Em thấy con đường này vừa nhiều xe, lại vừa nhiều đèn giao thông nữa."},{"hanzi":"是啊，这条路我走过一次，后来再也不走了。","pinyin":"Shì a, zhè tiáo lù wǒ zǒuguo yí cì, hòulái zài yě bù zǒu le.","speaker":"刘明","vi":"Đúng vậy, con đường này anh từng đi một lần, sau đó không bao giờ đi nữa."},{"hanzi":"那您今天为什么走了这条路？","pinyin":"Nà nín jīntiān wèishénme zǒu le zhè tiáo lù?","speaker":"白家月","vi":"Vậy sao hôm nay anh lại đi con đường này thế?"},{"hanzi":"我一急就走错了。如果没走错，二十分钟以前就到了。","pinyin":"Wǒ yì jí jiù zǒucuò le. Rúguǒ méi zǒucuò, èrshí fēnzhōng yǐqián jiù dào le.","speaker":"刘明","vi":"Anh vội quá nên đi nhầm đường. Nếu không đi nhầm thì hai mươi phút trước đã tới nơi rồi."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài, Lưu Minh nói \"好，你们还有一个小时，应该不会迟到的。\" (Được rồi, hai bạn vẫn còn một tiếng nữa, chắc sẽ không trễ đâu.), nên họ vẫn còn một tiếng đồng hồ.","options":["二十分钟","半个小时","一个小时","已经迟到了"],"q":"离坐高铁的时间还有多久？"},{"answerIdx":1,"explanation":"Trong bài, Lưu Minh giải thích \"我一急就走错了。如果没走错，二十分钟以前就到了。\" (Tôi vội quá nên đi nhầm đường rồi. Nếu không đi nhầm thì hai mươi phút trước đã tới rồi.), nên lý do hôm nay ông đi vào con đường đó là vì vội nên đi nhầm.","options":["因为他以前没走过这条路","因为他一着急就走错了","因为这条路比别的路近一些","因为白家月让他走这条路的"],"q":"刘明今天为什么走了这条车多、红绿灯也多的路？"}],"scene":"在车上，刘明开车送白家月和李文去高铁站。","sceneVi":"Trên xe, Lưu Minh lái xe đưa Bạch Gia Nguyệt và Lý Văn đến ga tàu cao tốc."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"李文，我的耳机没电了，你有充电宝吗？","pinyin":"Lǐ Wén, wǒ de ěrjī méi diàn le, nǐ yǒu chōngdiànbǎo ma?","speaker":"白家月","vi":"Lý Văn, tai nghe của mình hết pin rồi, cậu có sạc dự phòng không?"},{"hanzi":"有，这些常用的东西我都放在包里了，我给你拿。","pinyin":"Yǒu, zhèxiē chángyòng de dōngxi wǒ dōu fàng zài bāo lǐ le, wǒ gěi nǐ ná.","speaker":"李文","vi":"Có, những đồ hay dùng này mình đều để hết trong túi rồi, để mình lấy cho cậu."},{"hanzi":"前面的人越来越多。","pinyin":"Qiánmiàn de rén yuèláiyuè duō.","speaker":"白家月","vi":"Người phía trước ngày càng đông."},{"hanzi":"对，马上就进高铁站了。咱们一起走，别分开。","pinyin":"Duì, mǎshàng jiù jìn gāotiězhàn le. Zánmen yìqǐ zǒu, bié fēnkāi.","speaker":"李文","vi":"Đúng thế, sắp vào trong ga tàu cao tốc rồi. Chúng ta đi cùng nhau nhé, đừng tách nhau ra."},{"hanzi":"好，你检查一下，高铁票都拿好了吗？","pinyin":"Hǎo, nǐ jiǎnchá yíxià, gāotiě piào dōu náhǎo le ma?","speaker":"白家月","vi":"Ừ, cậu kiểm tra lại xem, vé tàu cao tốc đã cầm kỹ chưa?"},{"hanzi":"不用拿票，刷护照就能检票进站。","pinyin":"Búyòng ná piào, shuā hùzhào jiù néng jiǎnpiào jìn zhàn.","speaker":"李文","vi":"Không cần lấy vé đâu, quẹt hộ chiếu là có thể soát vé vào ga rồi."},{"hanzi":"去哪里检票？","pinyin":"Qù nǎlǐ jiǎnpiào?","speaker":"白家月","vi":"Đi đâu để soát vé vậy?"},{"hanzi":"检票口在二层，我们一会儿坐电梯上去。","pinyin":"Jiǎnpiàokǒu zài èr céng, wǒmen yìhuìr zuò diàntī shàngqù.","speaker":"李文","vi":"Cổng soát vé ở tầng hai, lát nữa chúng ta đi thang máy lên."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Lý Văn nói \"不用拿票，刷护照就能检票进站。\" (Không cần lấy vé đâu, quét hộ chiếu là có thể soát vé vào ga.), nên họ vào ga soát vé bằng cách quét hộ chiếu.","options":["拿着高铁票检票进站","刷护照就能检票进站","用手机里的照片检票进站","请高铁站的服务员带进去"],"q":"他们怎么检票进高铁站？"},{"answerIdx":2,"explanation":"Trong bài, Lý Văn nói \"检票口在二层，我们一会儿坐电梯上去。\" (Cửa soát vé ở tầng hai, lát nữa chúng ta đi thang máy lên.), nên cửa soát vé ở tầng hai và họ sẽ đi thang máy lên đó.","options":["在一层，走过去就行","在二层，走楼梯上去","在二层，坐电梯上去","在三层，坐电梯上去"],"q":"检票口在哪里？他们打算怎么上去？"}],"scene":"在高铁站，李文和白家月排队安检、检票。","sceneVi":"Ở ga tàu cao tốc, Lý Văn và Bạch Gia Nguyệt xếp hàng kiểm tra an ninh và soát vé."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"这次放假，我去了北京，还去了上海。","pinyin":"Zhè cì fàngjià, wǒ qù le Běijīng, hái qù le Shànghǎi.","speaker":"Đoạn văn","vi":"Kỳ nghỉ lần này, mình đã đi Bắc Kinh, còn đi cả Thượng Hải nữa."},{"hanzi":"我是从北京南站坐高铁去的上海。","pinyin":"Wǒ shì cóng Běijīng Nán Zhàn zuò gāotiě qù de Shànghǎi.","speaker":"Đoạn văn","vi":"Mình đi tàu cao tốc từ Ga Nam Bắc Kinh đến Thượng Hải."},{"hanzi":"我觉得坐在高铁上跟坐在家里的沙发上一样，又安静又舒服。","pinyin":"Wǒ juéde zuò zài gāotiě shang gēn zuò zài jiālǐ de shāfā shang yíyàng, yòu ānjìng yòu shūfu.","speaker":"Đoạn văn","vi":"Mình cảm thấy ngồi trên tàu cao tốc giống như ngồi trên ghế sô-pha ở nhà vậy, vừa yên tĩnh vừa thoải mái."},{"hanzi":"坐累了就站一会儿，饿了就点外卖。","pinyin":"Zuòlèi le jiù zhàn yíhuìr, è le jiù diǎn wàimài.","speaker":"Đoạn văn","vi":"Ngồi mỏi rồi thì đứng một lát, đói thì gọi đồ ăn giao tận nơi."},{"hanzi":"对，你没听错，高铁上可以点外卖，只需要选择好车站和想吃的东西，到站时不用下车，服务员就会给你拿过来。","pinyin":"Duì, nǐ méi tīngcuò, gāotiě shang kěyǐ diǎn wàimài, zhǐ xūyào xuǎnzé hǎo chēzhàn hé xiǎng chī de dōngxi, dào zhàn shí búyòng xiàchē, fúwùyuán jiù huì gěi nǐ ná guòlái.","speaker":"Đoạn văn","vi":"Đúng vậy, cậu không nghe nhầm đâu, trên tàu cao tốc có thể gọi đồ ăn ngoài, chỉ cần chọn sẵn nhà ga và món muốn ăn, khi tàu đến ga không cần xuống xe, nhân viên phục vụ sẽ mang tới cho cậu."},{"hanzi":"现在喜欢坐高铁的人越来越多。","pinyin":"Xiànzài xǐhuan zuò gāotiě de rén yuèláiyuè duō.","speaker":"Đoạn văn","vi":"Hiện nay người thích đi tàu cao tốc ngày càng nhiều."},{"hanzi":"我爸妈来中国旅游的时候，必须带他们也坐一次高铁。","pinyin":"Wǒ bàmā lái Zhōngguó lǚyóu de shíhou, bìxū dài tāmen yě zuò yí cì gāotiě.","speaker":"Đoạn văn","vi":"Khi bố mẹ mình sang Trung Quốc du lịch, nhất định phải đưa họ đi tàu cao tốc một lần."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu \"只需要选择好车站和想吃的东西，到站时不用下车，服务员就会给你拿过来。\" (Chỉ cần chọn sẵn nhà ga và món muốn ăn, khi đến ga không cần xuống tàu, nhân viên phục vụ sẽ mang tới cho bạn.), nên khi đến ga không cần xuống tàu mà nhân viên sẽ mang đồ ăn tới.","options":["自己下车去车站里面拿","叫司机停车后去买过来","不用下车，到站时服务员会拿过来","上车以前在高铁站门口拿好"],"q":"在高铁上点外卖以后，怎么拿到吃的东西？"},{"answerIdx":0,"explanation":"Trong bài có câu \"我爸妈来中国旅游的时候，必须带他们也坐一次高铁。\" (Khi bố mẹ tôi sang Trung Quốc du lịch, nhất định phải đưa họ đi tàu cao tốc một lần.), nên khi bố mẹ sang Trung Quốc du lịch, cô ấy nhất định sẽ đưa họ đi tàu cao tốc một lần.","options":["坐一次高铁","去北京南站吃外卖","在上海买新沙发","从上海坐飞机回北京"],"q":"白家月的爸妈来中国旅游的时候，她一定要带他们做什么？"}],"scene":"在家里，白家月给安妮打电话介绍自己的旅行。","sceneVi":"Ở nhà, Bạch Gia Nguyệt gọi điện thoại cho Annie kể về chuyến du lịch của mình."}],"hsk3-7":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"这辆自行车是小雪八岁的时候买的，看起来有点儿旧了。","pinyin":"Zhè liàng zìxíngchē shì Xiǎoxuě bā suì de shíhou mǎi de, kàn qǐlái yǒudiǎnr jiù le.","speaker":"王一雪","vi":"Chiếc xe đạp này là mua hồi Tiểu Tuyết tám tuổi, trông hơi cũ rồi."},{"hanzi":"是啊，她现在长高了，这辆车已经太矮了。","pinyin":"Shì a, tā xiànzài zhǎng gāo le, zhè liàng chē yǐjīng tài ǎi le.","speaker":"刘明","vi":"Đúng vậy, bây giờ con bé cao lên rồi, chiếc xe này đã quá thấp rồi."},{"hanzi":"商场里开了一家自行车店，咱们给她买辆新的吧。","pinyin":"Shāngchǎng lǐ kāi le yì jiā zìxíngchē diàn, zánmen gěi tā mǎi liàng xīn de ba.","speaker":"王一雪","vi":"Trong trung tâm thương mại mới mở một cửa hàng xe đạp, chúng ta mua cho con bé một chiếc mới đi."},{"hanzi":"好，咱们带小雪一起去，让她试一下。","pinyin":"Hǎo, zánmen dài Xiǎoxuě yìqǐ qù, ràng tā shì yíxià.","speaker":"刘明","vi":"Được, chúng ta dẫn Tiểu Tuyết cùng đi, để con bé thử một chút."},{"hanzi":"那今天就去吧！我也想再看看衣服。咱们怎么去？","pinyin":"Nà jīntiān jiù qù ba! Wǒ yě xiǎng zài kànkan yīfu. Zánmen zěnme qù?","speaker":"王一雪","vi":"Vậy hôm nay đi luôn đi! Em cũng muốn xem thêm quần áo nữa. Chúng ta đi bằng gì?"},{"hanzi":"商场不远，咱们可以走着去。","pinyin":"Shāngchǎng bù yuǎn, zánmen kěyǐ zǒuzhe qù.","speaker":"刘明","vi":"Trung tâm thương mại không xa, chúng ta có thể đi bộ tới đó."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Vương Nhất Tuyết nói \"这辆自行车是小雪八岁的时候买的，看起来有点儿旧了\" (Chiếc xe đạp này mua lúc Tiểu Tuyết 8 tuổi, trông hơi cũ rồi) và Lưu Minh nói \"她现在长高了，这辆车已经太矮了\" (Con bé giờ cao lên rồi, chiếc xe này đã quá thấp rồi), nên họ muốn mua xe mới vì xe cũ hơi cũ và quá thấp so với Tiểu Tuyết.","options":["小雪的自行车坏了，不能骑了","旧车有点儿旧，而且对长高了的小雪来说太矮了","小雪八岁了，以前没有自行车","商场里的自行车今天正在打折"],"q":"王一雪和刘明为什么想给小雪买一辆新自行车？"},{"answerIdx":2,"explanation":"Trong bài Lưu Minh nói \"商场不远，咱们可以走着去\" (Trung tâm thương mại không xa, chúng ta có thể đi bộ đến đó), nên họ dự định đi bộ.","options":["骑自行车去","坐公共汽车去","走着去","坐出租车去"],"q":"他们打算怎么去商场？"}],"scene":"在家里，王一雪和刘明商量去买东西。","sceneVi":"Ở nhà, Vương Nhất Tuyết và Lưu Minh bàn bạc đi mua đồ."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"你看我穿这条黄色的短裤好看吗？","pinyin":"Nǐ kàn wǒ chuān zhè tiáo huángsè de duǎnkù hǎokàn ma?","speaker":"王一雪","vi":"Anh xem em mặc chiếc quần đùi màu vàng này có đẹp không?"},{"hanzi":"大小合适，但我觉得那条裙子比短裤更好看。","pinyin":"Dàxiǎo héshì, dàn wǒ juéde nà tiáo qúnzi bǐ duǎnkù gèng hǎokàn.","speaker":"刘明","vi":"Kích cỡ vừa vặn, nhưng anh thấy chiếc váy kia đẹp hơn quần đùi."},{"hanzi":"裙子比短裤贵一点儿。","pinyin":"Qúnzi bǐ duǎnkù guì yìdiǎnr.","speaker":"王一雪","vi":"Váy đắt hơn quần đùi một chút."},{"hanzi":"贵多少？","pinyin":"Guì duōshao?","speaker":"刘明","vi":"Đắt hơn bao nhiêu?"},{"hanzi":"裙子480，短裤400。","pinyin":"Qúnzi sìbǎi bāshí, duǎnkù sìbǎi.","speaker":"王一雪","vi":"Váy 480, quần đùi 400."},{"hanzi":"裙子不比短裤贵多少，还是买裙子吧，你穿裙子更好看。","pinyin":"Qúnzi bù bǐ duǎnkù guì duōshao, háishi mǎi qúnzi ba, nǐ chuān qúnzi gèng hǎokàn.","speaker":"刘明","vi":"Váy không đắt hơn quần đùi bao nhiêu đâu, hay là mua váy đi, em mặc váy đẹp hơn."},{"hanzi":"我多看看再决定。你看，那边有买二送一！","pinyin":"Wǒ duō kànkan zài juédìng. Nǐ kàn, nàbiān yǒu mǎi èr sòng yī!","speaker":"王一雪","vi":"Em xem thêm đã rồi quyết định. Anh nhìn kìa, bên kia có chương trình mua 2 tặng 1!"}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài Vương Nhất Tuyết nói \"裙子480，短裤400\" (Váy 480 tệ, quần đùi 400 tệ), nên chiếc váy đắt hơn chiếc quần đùi 80 tệ.","options":["裙子比短裤贵八十块钱","短裤比裙子贵八十块钱","裙子和短裤一样贵","裙子比短裤便宜得多"],"q":"关于这条裙子和短裤的价格，下面哪一项是对的？"},{"answerIdx":2,"explanation":"Trong bài Vương Nhất Tuyết nói \"我多看看再决定。你看，那边有买二送一！\" (Em xem thêm nhiều chút rồi mới quyết định. Anh xem, đằng kia có mua 2 tặng 1 kìa!), nên cô ấy dự định xem thêm rồi mới quyết định.","options":["马上买那条黄色的短裤","听刘明的话，只买那条裙子","再多看看，然后才决定买什么","不买了，直接回家"],"q":"最后王一雪打算怎么做？"}],"scene":"在商场，刘明和王一雪买完自行车，又来挑选衣服。","sceneVi":"Ở trung tâm thương mại, Lưu Minh và Vương Nhất Tuyết mua xong xe đạp, lại qua chọn quần áo."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"西瓜又大又新鲜，不甜不要钱！","pinyin":"Xīguā yòu dà yòu xīnxiān, bù tián bú yào qián!","speaker":"店员","vi":"Dưa hấu vừa to vừa tươi, không ngọt không lấy tiền!"},{"hanzi":"西瓜看起来不错，怎么卖？","pinyin":"Xīguā kàn qǐlái búcuò, zěnme mài?","speaker":"王一雪","vi":"Dưa hấu trông ngon đấy, bán thế nào vậy?"},{"hanzi":"五块钱一公斤。来，您先尝尝这块冰西瓜，甜极了！","pinyin":"Wǔ kuài qián yì gōngjīn. Lái, nín xiān chángchang zhè kuài bīng xīguā, tián jíle!","speaker":"店员","vi":"Năm tệ một ki-lô-gam. Nào, chị nếm thử miếng dưa hấu ướp lạnh này trước đi, ngọt cực kỳ!"},{"hanzi":"是挺甜的！帮我选个大点儿的，再来两斤香蕉。","pinyin":"Shì tǐng tián de! Bāng wǒ xuǎn ge dàdiǎnr de, zài lái liǎng jīn xiāngjiāo.","speaker":"王一雪","vi":"Ngọt thật đấy! Chọn giúp tôi một quả to một chút, lấy thêm hai cân chuối nữa."},{"hanzi":"一共五十八块五毛。","pinyin":"Yígòng wǔshíbā kuài wǔ máo.","speaker":"店员","vi":"Tổng cộng năm mươi tám tệ năm hào."},{"hanzi":"我买了这么多，便宜点儿吧。","pinyin":"Wǒ mǎi le zhème duō, piányi diǎnr ba.","speaker":"王一雪","vi":"Tôi mua nhiều thế này, bớt chút đi."},{"hanzi":"您给我五十五吧，不能再便宜了。","pinyin":"Nín gěi wǒ wǔshíwǔ ba, bù néng zài piányi le.","speaker":"店员","vi":"Chị đưa tôi năm mươi lăm tệ nhé, không thể rẻ hơn nữa đâu."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Vương Nhất Tuyết nói với nhân viên bán hàng \"帮我选个大点儿的，再来两斤香蕉\" (Chọn giúp tôi một quả dưa hấu to hơn chút, lấy thêm hai cân chuối nữa), nên cô ấy đã mua một quả dưa hấu và hai cân (jin) chuối.","options":["一个大西瓜和两公斤苹果","一个西瓜和两斤香蕉","一块冰西瓜和五斤香蕉","两斤西瓜和一斤香蕉"],"q":"王一雪在商店里买了什么水果？"},{"answerIdx":2,"explanation":"Trong bài, tổng tiền ban đầu là 58,5 tệ, sau khi Vương Nhất Tuyết mặc cả thì nhân viên nói \"您给我五十五吧，不能再便宜了\" (Chị đưa tôi 55 tệ nhé, không thể rẻ hơn nữa đâu), nên cô ấy phải trả 55 tệ.","options":["五十块钱","五十八块五毛","五十五块钱","五十三块五毛"],"q":"便宜以后，王一雪需要付多少钱？"}],"scene":"在商店，王一雪在买东西。","sceneVi":"Ở cửa hàng, Vương Nhất Tuyết đang mua đồ."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"这几天我们在新家坐着看电视的时候，又发现了新问题。","pinyin":"Zhè jǐ tiān wǒmen zài xīn jiā zuòzhe kàn diànshì de shíhou, yòu fāxiàn le xīn wèntí.","speaker":"Đoạn văn","vi":"Mấy ngày nay khi chúng tôi ngồi xem ti vi ở nhà mới, lại phát hiện ra vấn đề mới."},{"hanzi":"房子大了，电视看起来就有点儿小。","pinyin":"Fángzi dà le, diànshì kàn qǐlái jiù yǒudiǎnr xiǎo.","speaker":"Đoạn văn","vi":"Nhà rộng ra rồi, ti vi trông có vẻ hơi nhỏ."},{"hanzi":"这个电视是我们结婚时买的，是时候换个新电视了。","pinyin":"Zhège diànshì shì wǒmen jiéhūn shí mǎi de, shì shíhou huàn ge xīn diànshì le.","speaker":"Đoạn văn","vi":"Chiếc ti vi này là mua hồi chúng tôi kết hôn, đã đến lúc đổi một chiếc ti vi mới rồi."},{"hanzi":"今天我一直在网上选电视，没想到，现在的电视不但便宜，而且用着非常方便，有的电视叫它一声就能开机。","pinyin":"Jīntiān wǒ yìzhí zài wǎngshang xuǎn diànshì, méi xiǎngdào, xiànzài de diànshì búdàn piányi, érqiě yòngzhe fēicháng fāngbiàn, yǒude diànshì jiào tā yì shēng jiù néng kāijī.","speaker":"Đoạn văn","vi":"Hôm nay tôi cứ chọn ti vi trên mạng suốt, không ngờ ti vi bây giờ không những rẻ, mà dùng còn vô cùng tiện lợi, có chiếc ti vi chỉ cần gọi một tiếng là có thể bật máy."},{"hanzi":"我看了好几个，都很满意，晚上让一雪来决定吧。","pinyin":"Wǒ kàn le hǎo jǐ gè, dōu hěn mǎnyì, wǎnshang ràng Yīxuě lái juédìng ba.","speaker":"Đoạn văn","vi":"Tôi đã xem qua mấy chiếc rồi, đều rất hài lòng, tối nay để Nhất Tuyết quyết định vậy."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"房子大了，电视看起来就有点儿小。这个电视是我们结婚时买的，是时候换个新电视了\" (Nhà lớn rồi, ti vi nhìn có vẻ hơi nhỏ. Chiếc ti vi này mua lúc chúng tôi kết hôn, đã đến lúc đổi một chiếc ti vi mới rồi), nên nguyên nhân là nhà mới rộng khiến ti vi cũ trông hơi nhỏ.","options":["旧电视坏了，打不开了","新家房子大了，旧电视显得有点儿小","王一雪不喜欢旧电视的颜色","网上的新电视比旧电视贵"],"q":"刘明为什么想换一个新电视？"},{"answerIdx":0,"explanation":"Trong bài có câu \"没想到，现在的电视不但便宜，而且用着非常方便，有的电视叫它一声就能开机\" (Không ngờ ti vi bây giờ không những rẻ mà dùng còn rất tiện lợi, có chiếc chỉ cần gọi một tiếng là có thể bật máy), nên Lưu Minh thấy ti vi hiện nay vừa rẻ vừa dùng rất tiện.","options":["现在的电视不但便宜，而且用着很方便","网上的电视太贵了，不值得买","网上的电视都很小，他不太满意","现在的电视都必须用遥控器开机"],"q":"刘明在网上选电视时有什么发现？"}],"scene":"在家里，刘明在看电视。","sceneVi":"Ở nhà, Lưu Minh đang xem ti vi."}],"hsk3-8":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"天中，最近常看见你来体育馆。","pinyin":"Tiānzhōng, zuìjìn cháng kànjiàn nǐ lái tǐyùguǎn.","speaker":"李文","vi":"Thiên Trung, dạo này thường thấy cậu đến nhà thi đấu."},{"hanzi":"我每天下午都来跑一个小时步。","pinyin":"Wǒ měitiān xiàwǔ dōu lái pǎo yí gè xiǎoshí bù.","speaker":"陈天中","vi":"Chiều nào mình cũng đến chạy bộ một tiếng."},{"hanzi":"你的运动习惯真不错。","pinyin":"Nǐ de yùndòng xíguàn zhēn búcuò.","speaker":"李文","vi":"Thói quen vận động của cậu thật tốt."},{"hanzi":"因为我今年胖了十多斤，不能再胖下去了，有点儿不健康。","pinyin":"Yīnwèi wǒ jīnnián pàng le shí duō jīn, bù néng zài pàng xiàqù le, yǒudiǎnr bú jiànkāng.","speaker":"陈天中","vi":"Vì năm nay mình béo lên hơn mười cân rồi, không thể cứ béo tiếp được nữa, hơi không khỏe mạnh."},{"hanzi":"我下课以后常去打羽毛球，你也来玩吧。","pinyin":"Wǒ xiàkè yǐhòu cháng qù dǎ yǔmáoqiú, nǐ yě lái wán ba.","speaker":"李文","vi":"Sau khi tan học mình thường đi đánh cầu lông, cậu cũng đến chơi đi."},{"hanzi":"我知道，但是你们的水平太高了，我打得不怎么样。","pinyin":"Wǒ zhīdào, dànshì nǐmen de shuǐpíng tài gāo le, wǒ dǎ de bù zěnmeyàng.","speaker":"陈天中","vi":"Mình biết, nhưng trình độ của các cậu cao quá, mình đánh chẳng ra sao cả."},{"hanzi":"没关系，我可以教你。","pinyin":"Méi guānxi, wǒ kěyǐ jiāo nǐ.","speaker":"李文","vi":"Không sao đâu, mình có thể dạy cậu."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài Trần Thiên Trung nói \"因为我今年胖了十多斤，不能再胖下去了，有点儿不健康\" (Vì năm nay mình béo lên hơn chục cân rồi, không thể béo thêm nữa, hơi không khỏe mạnh), nên cậu ấy chạy bộ mỗi chiều để giữ sức khỏe.","options":["因为他今年胖了十多斤，想保持健康","因为他每天都要练习羽毛球比赛","因为体育馆离他的家很近","因为李文每天下午都约他来跑步"],"q":"陈天中为什么每天下午都来体育馆跑步？"},{"answerIdx":2,"explanation":"Trong bài Lý Văn rủ \"我下课以后常去打羽毛球，你也来玩吧\" (Sau giờ học mình thường đi đánh cầu lông, cậu cũng đến chơi nhé) và nói thêm \"没关系，我可以教你\" (Không sao đâu, mình có thể dạy cậu), nên Lý Văn định dạy đánh cầu lông.","options":["跑步","游泳","打羽毛球","打网球"],"q":"李文打算教陈天中什么运动？"}],"scene":"在学校的体育馆，李文遇到了陈天中。","sceneVi":"Ở nhà thi đấu của trường, Lý Văn gặp Trần Thiên Trung."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"你怎么了？看上去有点儿不舒服。","pinyin":"Nǐ zěnme le? Kàn shàngqù yǒudiǎnr bù shūfu.","speaker":"安妮","vi":"Cậu làm sao thế? Trông có vẻ hơi khó chịu."},{"hanzi":"昨天游完泳以后，耳朵一直有点儿疼。","pinyin":"Zuótiān yóuwán yǒng yǐhòu, ěrduo yìzhí yǒudiǎnr téng.","speaker":"陈天中","vi":"Hôm qua sau khi bơi xong, tai cứ hơi đau suốt."},{"hanzi":"是不是感冒了？发烧吗？","pinyin":"Shì bú shì gǎnmào le? Fāshāo ma?","speaker":"安妮","vi":"Có phải bị cảm rồi không? Có sốt không?"},{"hanzi":"好像发低烧了。","pinyin":"Hǎoxiàng fā dīshāo le.","speaker":"陈天中","vi":"Hình như bị sốt nhẹ rồi."},{"hanzi":"我送你去医院，让医生检查一下吧。","pinyin":"Wǒ sòng nǐ qù yīyuàn, ràng yīshēng jiǎnchá yíxià ba.","speaker":"安妮","vi":"Mình đưa cậu đến bệnh viện, để bác sĩ kiểm tra một chút nhé."},{"hanzi":"我先回去睡一觉，可能休息休息就好了。","pinyin":"Wǒ xiān huíqù shuì yí jiào, kěnéng xiūxi xiūxi jiù hǎo le.","speaker":"陈天中","vi":"Mình về ngủ một giấc trước đã, có lẽ nghỉ ngơi một chút là khỏi thôi."},{"hanzi":"好吧，如果下午还发烧，就一定要去看医生。","pinyin":"Hǎo ba, rúguǒ xiàwǔ hái fāshāo, jiù yídìng yào qù kàn yīshēng.","speaker":"安妮","vi":"Được thôi, nếu buổi chiều vẫn còn sốt, thì nhất định phải đi khám bác sĩ đấy."},{"hanzi":"谢谢关心，我会注意的。","pinyin":"Xièxie guānxīn, wǒ huì zhùyì de.","speaker":"陈天中","vi":"Cảm ơn đã quan tâm, mình sẽ chú ý."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Trần Thiên Trung nói \"昨天游完泳以后，耳朵一直有点儿疼\" (Hôm qua sau khi bơi xong, tai cứ hơi đau) và \"好像发低烧了\" (Hình như hơi sốt nhẹ rồi).","options":["昨天游完泳后腿疼，还发高烧","耳朵一直有点儿疼，而且好像发低烧了","肚子疼得厉害，不能去上课","今天早上跑步以后头疼"],"q":"陈天中哪里不舒服？"},{"answerIdx":1,"explanation":"Trong bài Trần Thiên Trung nói với Anny \"我先回去睡一觉，可能休息休息就好了\" (Mình về ngủ một giấc trước đã, có thể nghỉ ngơi một chút sẽ khỏi), nên cậu ấy dự định về ngủ một giấc, nghỉ ngơi trước.","options":["立刻让安妮送他去医院","先回去睡一觉，休息一下","继续留在教室里上课","去体育馆再游一次泳"],"q":"陈天中现在打算先做什么？"}],"scene":"在教室，安妮问候陈天中。","sceneVi":"Trong lớp học, An Ni hỏi thăm Trần Thiên Trung."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"你怎么突然住院了？大家都很担心你。","pinyin":"Nǐ zěnme tūrán zhùyuàn le? Dàjiā dōu hěn dānxīn nǐ.","speaker":"安妮","vi":"Sao cậu đột nhiên phải nhập viện thế? Mọi người đều rất lo lắng cho cậu."},{"hanzi":"我的腿疼了几个星期了，医生说需要住院做检查。","pinyin":"Wǒ de tuǐ téng le jǐ gè xīngqī le, yīshēng shuō xūyào zhùyuàn zuò jiǎnchá.","speaker":"陈天中","vi":"Chân mình đau mấy tuần rồi, bác sĩ nói cần phải nhập viện để làm kiểm tra."},{"hanzi":"你看起来一点儿也不像病人。","pinyin":"Nǐ kàn qǐlái yìdiǎnr yě bú xiàng bìngrén.","speaker":"安妮","vi":"Cậu trông chẳng giống người bệnh chút nào."},{"hanzi":"是啊，我很少生病。我上次来医院已经过去差不多两年了。","pinyin":"Shì a, wǒ hěn shǎo shēngbìng. Wǒ shàngcì lái yīyuàn yǐjīng guòqù chàbuduō liǎng nián le.","speaker":"陈天中","vi":"Đúng vậy, mình rất ít khi ốm. Lần trước mình đến bệnh viện đã trôi qua gần hai năm rồi."},{"hanzi":"你每天跑步，有时候还去游泳，是不是运动太多了？","pinyin":"Nǐ měitiān pǎobù, yǒu shíhou hái qù yóuyǒng, shì bú shì yùndòng tài duō le?","speaker":"安妮","vi":"Cậu ngày nào cũng chạy bộ, có lúc còn đi bơi, có phải vận động nhiều quá rồi không?"},{"hanzi":"医生也这么说，但是还得做完检查才能知道。","pinyin":"Yīshēng yě zhème shuō, dànshì hái děi zuòwán jiǎnchá cái néng zhīdào.","speaker":"陈天中","vi":"Bác sĩ cũng nói vậy, nhưng vẫn phải làm xong kiểm tra mới biết được."},{"hanzi":"别担心！听医生的话，好好休息，你的腿一定能好。","pinyin":"Bié dānxīn! Tīng yīshēng de huà, hǎohāo xiūxi, nǐ de tuǐ yídìng néng hǎo.","speaker":"安妮","vi":"Đừng lo! Nghe lời bác sĩ, nghỉ ngơi cho tốt, chân của cậu nhất định sẽ khỏi."},{"hanzi":"谢谢。有人来看我，我就开心多了。","pinyin":"Xièxie. Yǒu rén lái kàn wǒ, wǒ jiù kāixīn duō le.","speaker":"陈天中","vi":"Cảm ơn nhé. Có người đến thăm mình, mình vui hơn nhiều rồi."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Trần Thiên Trung giải thích \"我的腿疼了几个星期了，医生说需要住院做检查\" (Chân mình đau mấy tuần rồi, bác sĩ nói cần nhập viện để kiểm tra).","options":["因为他的耳朵发炎，一直在发烧","因为他的腿疼了几个星期，需要住院做检查","因为他在医院工作，顺便做检查","因为医生发现他跑步时摔伤了"],"q":"陈天中为什么需要住院？"},{"answerIdx":2,"explanation":"Trong bài Trần Thiên Trung nói \"我上次来医院已经过去差不多两年了\" (Lần trước mình đến bệnh viện đã qua gần hai năm rồi), nên lần gần nhất là khoảng hai năm trước.","options":["几个星期以前","上个月","差不多两年以前","他从来没有来过医院"],"q":"陈天中上一次来医院是什么时候？"}],"scene":"在医院病房，安妮探望陈天中。","sceneVi":"Ở phòng bệnh viện, An Ni đến thăm Trần Thiên Trung."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"今天我出院了。","pinyin":"Jīntiān wǒ chūyuàn le.","speaker":"Đoạn văn","vi":"Hôm nay tôi đã xuất viện rồi."},{"hanzi":"出院前，医生给我开了几种药，而且告诉了我吃药的方法。","pinyin":"Chūyuàn qián, yīshēng gěi wǒ kāi le jǐ zhǒng yào, érqiě gàosu le wǒ chīyào de fāngfǎ.","speaker":"Đoạn văn","vi":"Trước khi xuất viện, bác sĩ đã kê cho tôi mấy loại thuốc, đồng thời nói cho tôi biết cách uống thuốc."},{"hanzi":"有一种药需要每天睡前吃一次，其他几种每天吃三次，饭后吃。","pinyin":"Yǒu yì zhǒng yào xūyào měitiān shuìqián chī yí cì, qítā jǐ zhǒng měitiān chī sān cì, fànhòu chī.","speaker":"Đoạn văn","vi":"Có một loại thuốc cần uống mỗi ngày một lần trước khi đi ngủ, mấy loại khác mỗi ngày uống ba lần, uống sau bữa ăn."},{"hanzi":"除了吃药，医生还说最重要的是多休息。","pinyin":"Chúle chīyào, yīshēng hái shuō zuì zhòngyào de shì duō xiūxi.","speaker":"Đoạn văn","vi":"Ngoài uống thuốc ra, bác sĩ còn nói điều quan trọng nhất là nghỉ ngơi nhiều."},{"hanzi":"我都记在心里了，回家以后一定会多注意。","pinyin":"Wǒ dōu jì zài xīnli le, huíjiā yǐhòu yídìng huì duō zhùyì.","speaker":"Đoạn văn","vi":"Tôi đều ghi nhớ trong lòng rồi, sau khi về nhà nhất định sẽ chú ý nhiều hơn."},{"hanzi":"希望我的腿能快一点儿好。","pinyin":"Xīwàng wǒ de tuǐ néng kuài yìdiǎnr hǎo.","speaker":"Đoạn văn","vi":"Hy vọng chân của tôi có thể nhanh chóng khỏe lại một chút."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"有一种药需要每天睡前吃一次，其他几种每天吃三次，饭后吃\" (Có một loại thuốc cần uống mỗi ngày một lần trước khi đi ngủ, mấy loại khác uống mỗi ngày ba lần sau bữa ăn).","options":["所有药都必须每天饭前吃三次","一种药每天睡前吃一次，其他的每天饭后吃三次","所有药都是每天睡觉以前吃一次","只有腿疼的时候才需要吃药"],"q":"按照医生的要求，陈天中应该怎么吃药？"},{"answerIdx":2,"explanation":"Trong bài có câu \"除了吃药，医生还说最重要的是多休息\" (Ngoài uống thuốc ra, bác sĩ còn nói điều quan trọng nhất là nghỉ ngơi nhiều).","options":["每天坚持跑步锻炼","按时去医院做检查","多休息","多喝水，少吃饭"],"q":"除了吃药以外，医生认为最重要的是什么？"}],"scene":"在家里，陈天中吃药、休息。","sceneVi":"Ở nhà, Trần Thiên Trung uống thuốc, nghỉ ngơi."}],"hsk3-9":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"家月，对不起，我昨天忘了还你校园卡了。","pinyin":"Jiāyuè, duìbuqǐ, wǒ zuótiān wàngle huán nǐ xiàoyuán kǎ le.","speaker":"李文","vi":"Gia Nguyệt, xin lỗi nhé, hôm qua mình quên trả thẻ trường cho cậu rồi."},{"hanzi":"没关系。你怎么这么快就过来了？","pinyin":"Méi guānxi. Nǐ zěnme zhème kuài jiù guòlái le?","speaker":"白家月","vi":"Không sao đâu. Sao cậu qua đây nhanh thế?"},{"hanzi":"我正在球场打球呢，接了你的电话就跑过来了。","pinyin":"Wǒ zhèngzài qiúchǎng dǎqiú ne, jiēle nǐ de diànhuà jiù pǎo guòlái le.","speaker":"李文","vi":"Mình đang chơi bóng ở sân bóng, nhận được điện thoại của cậu là chạy qua ngay."},{"hanzi":"听说为了准备运动会，你们几个男生每天都练球。","pinyin":"Tīngshuō wèile zhǔnbèi yùndònghuì, nǐmen jǐ gè nánshēng měitiān dōu liàn qiú.","speaker":"白家月","vi":"Nghe nói để chuẩn bị cho hội thao, mấy bạn nam các cậu ngày nào cũng tập bóng."},{"hanzi":"是啊！你打算参加运动会吗？","pinyin":"Shì a! Nǐ dǎsuàn cānjiā yùndònghuì ma?","speaker":"李文","vi":"Đúng vậy! Cậu có định tham gia hội thao không?"},{"hanzi":"我想参加网球比赛，最近一直在练习。","pinyin":"Wǒ xiǎng cānjiā wǎngqiú bǐsài, zuìjìn yìzhí zài liànxí.","speaker":"白家月","vi":"Mình muốn tham gia thi đấu quần vợt, dạo này mình vẫn luôn tập luyện."},{"hanzi":"好，到时候我去看你的比赛。","pinyin":"Hǎo, dào shíhou wǒ qù kàn nǐ de bǐsài.","speaker":"李文","vi":"Được, đến lúc đó mình sẽ đi xem trận đấu của cậu."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài Lý Văn xin lỗi Bạch Gia Nguyệt \"家月，对不起，我昨天忘了还你校园卡了\" (Gia Nguyệt, xin lỗi, hôm qua mình quên trả thẻ trường cho cậu rồi).","options":["忘了去球场练球","忘了给白家月打电话","忘了还白家月校园卡","忘了报名参加运动会"],"q":"李文昨天忘了做什么事？"},{"answerIdx":0,"explanation":"Trong bài Bạch Gia Nguyệt nói \"我想参加网球比赛，最近一直在练习\" (Mình muốn tham gia thi đấu quần vợt, dạo này vẫn luôn luyện tập).","options":["网球比赛","羽毛球比赛","足球比赛","跑步比赛"],"q":"在运动会上，白家月想参加什么比赛？"}],"scene":"在图书馆门口，李文向白家月跑过去。","sceneVi":"Ở cổng thư viện, Lý Văn chạy về phía Bạch Gia Nguyệt."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"家月，你跟我们一起打羽毛球吧？","pinyin":"Jiāyuè, nǐ gēn wǒmen yìqǐ dǎ yǔmáoqiú ba?","speaker":"李文","vi":"Gia Nguyệt, cậu chơi cầu lông cùng tụi mình đi?"},{"hanzi":"我好多年没打羽毛球了，几乎忘了怎么打了。","pinyin":"Wǒ hǎoduō nián méi dǎ yǔmáoqiú le, jīhū wàngle zěnme dǎ le.","speaker":"白家月","vi":"Mình nhiều năm không chơi cầu lông rồi, gần như quên cách đánh rồi."},{"hanzi":"不是比赛，打不好没关系。","pinyin":"Bú shì bǐsài, dǎ bu hǎo méi guānxi.","speaker":"李文","vi":"Không phải thi đấu đâu, đánh không tốt cũng không sao."},{"hanzi":"这么多同学一起打，如果总是接不住球，就太不好意思了。","pinyin":"Zhème duō tóngxué yìqǐ dǎ, rúguǒ zǒngshì jiē bu zhù qiú, jiù tài bù hǎoyìsi le.","speaker":"白家月","vi":"Nhiều bạn học cùng chơi như vậy, nếu cứ không đỡ được cầu thì ngại lắm."},{"hanzi":"你想得太多了！大家打球只是为了锻炼身体。","pinyin":"Nǐ xiǎng de tài duō le! Dàjiā dǎqiú zhǐshì wèile duànliàn shēntǐ.","speaker":"李文","vi":"Cậu nghĩ nhiều quá rồi! Mọi người chơi cầu chỉ là để rèn luyện sức khỏe thôi."},{"hanzi":"我先自己练练吧，下周再跟你们一起打。","pinyin":"Wǒ xiān zìjǐ liànlian ba, xià zhōu zài gēn nǐmen yìqǐ dǎ.","speaker":"白家月","vi":"Để mình tự tập trước đã, tuần sau lại chơi cùng các cậu."},{"hanzi":"我在教天中打羽毛球，你可以过来跟我们一起练。","pinyin":"Wǒ zài jiāo Tiānzhōng dǎ yǔmáoqiú, nǐ kěyǐ guòlái gēn wǒmen yìqǐ liàn.","speaker":"李文","vi":"Mình đang dạy Thiên Trung chơi cầu lông, cậu có thể qua đây tập cùng tụi mình."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Bạch Gia Nguyệt nói \"我好多年没打羽毛球了，几乎忘了怎么打了\" (Mình nhiều năm không đánh cầu lông rồi, gần như quên cách đánh) và \"这么多同学一起打，如果总是接不住球，就太不好意思了\" (Nhiều bạn học cùng đánh như vậy, nếu cứ không đỡ được cầu thì ngại lắm).","options":["因为她最近没有时间锻炼身体","因为她好多年没打了，怕总是接不住球会不好意思","因为她觉得跟陈天中一起练太累了","因为她马上要参加羽毛球比赛，很紧张"],"q":"白家月一开始为什么不想跟大家一起打羽毛球？"},{"answerIdx":2,"explanation":"Trong bài Lý Văn nói \"大家打球只是为了锻炼身体\" (Mọi người chơi cầu chỉ là để rèn luyện sức khỏe thôi).","options":["为了准备下周的比赛","为了认识更多新同学","为了锻炼身体","为了教陈天中打球"],"q":"李文认为大家一起打球是为了什么？"}],"scene":"在校园里，李文和白家月在聊天儿。","sceneVi":"Trong khuôn viên trường, Lý Văn và Bạch Gia Nguyệt đang trò chuyện."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"足球比赛已经开始了，快过来看吧！","pinyin":"Zúqiú bǐsài yǐjīng kāishǐ le, kuài guòlái kàn ba!","speaker":"陈天中","vi":"Trận đấu bóng đá bắt đầu rồi, mau qua đây xem đi!"},{"hanzi":"你们先看，冰箱里有啤酒和饮料，我去拿一下。","pinyin":"Nǐmen xiān kàn, bīngxiāng lǐ yǒu píjiǔ hé yǐnliào, wǒ qù ná yíxià.","speaker":"李文","vi":"Các cậu xem trước đi, trong tủ lạnh có bia và đồ uống, mình đi lấy một chút."},{"hanzi":"今天怎么回事？总是踢不进去！","pinyin":"Jīntiān zěnme huí shì? Zǒngshì tī bu jìnqù!","speaker":"白家月","vi":"Hôm nay làm sao thế nhỉ? Cứ sút mãi không vào!"},{"hanzi":"几个老球员生病了，新球员第一次参加这么重要的比赛，太紧张了。","pinyin":"Jǐ gè lǎo qiúyuán shēngbìng le, xīn qiúyuán dì-yī cì cānjiā zhème zhòngyào de bǐsài, tài jǐnzhāng le.","speaker":"陈天中","vi":"Mấy cầu thủ cũ bị ốm rồi, các cầu thủ mới lần đầu tham gia trận đấu quan trọng như thế nên căng thẳng quá."},{"hanzi":"是啊，主要的球员没参加比赛，所以大家也都受到影响了。","pinyin":"Shì a, zhǔyào de qiúyuán méi cānjiā bǐsài, suǒyǐ dàjiā yě dōu shòudào yǐngxiǎng le.","speaker":"李文","vi":"Đúng vậy, những cầu thủ chủ chốt không tham gia thi đấu nên mọi người cũng đều bị ảnh hưởng."},{"hanzi":"越看越着急。我不看了，你们告诉我得分吧。","pinyin":"Yuè kàn yuè zháojí. Wǒ bú kàn le, nǐmen gàosu wǒ défēn ba.","speaker":"白家月","vi":"Càng xem càng sốt ruột. Mình không xem nữa đâu, các cậu báo tỷ số cho mình nhé."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Trần Thiên Trung nói \"几个老球员生病了，新球员第一次参加这么重要的比赛，太紧张了\" (Mấy cầu thủ kỳ cựu bị ốm rồi, cầu thủ mới lần đầu tham gia trận đấu quan trọng như vậy nên quá căng thẳng) và Lý Văn bổ sung \"主要的球员没参加比赛，所以大家也都受到影响了\" (Các cầu thủ chủ chốt không tham gia thi đấu nên mọi người cũng bị ảnh hưởng).","options":["因为今天天气不好，球员看不清楚球","因为几个主要的老球员生病没参加，新球员太紧张了","因为新球员不想参加这么重要的比赛","因为对手的水平比他们高得多"],"q":"这场足球比赛为什么总是踢不进去？"},{"answerIdx":1,"explanation":"Trong bài Bạch Gia Nguyệt nói \"越看越着急。我不看了，你们告诉我得分吧\" (Càng xem càng sốt ruột. Mình không xem nữa đâu, các cậu báo tỷ số cho mình nhé).","options":["她去冰箱拿啤酒和饮料了","她太着急了，决定先不看了，让李文和天中告诉她得分","她继续紧张地看着比赛结束","她和陈天中一起换了别的电视节目"],"q":"对话最后，白家月做了什么决定？"}],"scene":"在李文家，李文、白家月和陈天中一起看电视。","sceneVi":"Ở nhà Lý Văn, Lý Văn, Bạch Gia Nguyệt và Trần Thiên Trung cùng nhau xem ti vi."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"我喜欢看体育比赛，最爱看的就是奥运会。","pinyin":"Wǒ xǐhuan kàn tǐyù bǐsài, zuì ài kàn de jiùshì Àoyùnhuì.","speaker":"Đoạn văn","vi":"Tôi thích xem các trận thi đấu thể thao, thích xem nhất chính là Thế vận hội Olympic."},{"hanzi":"奥运会是世界上影响最大的体育比赛。","pinyin":"Àoyùnhuì shì shìjiè shang yǐngxiǎng zuì dà de tǐyù bǐsài.","speaker":"Đoạn văn","vi":"Thế vận hội Olympic là giải đấu thể thao có sức ảnh hưởng lớn nhất trên thế giới."},{"hanzi":"从1896年到2024年，每次奥运会都有非常多的运动员参加。","pinyin":"Cóng yībājiǔliù nián dào èrlíng'èrsì nián, měi cì Àoyùnhuì dōu yǒu fēicháng duō de yùndòngyuán cānjiā.","speaker":"Đoạn văn","vi":"Từ năm 1896 đến năm 2024, mỗi kỳ Thế vận hội đều có rất nhiều vận động viên tham gia."},{"hanzi":"第一位参加奥运会的中国运动员是刘长春，他1932年参加了100米和200米短跑比赛。","pinyin":"Dì-yī wèi cānjiā Àoyùnhuì de Zhōngguó yùndòngyuán shì Liú Chángchūn, tā yījiǔsān'èr nián cānjiāle yībǎi mǐ hé èrbǎi mǐ duǎnpǎo bǐsài.","speaker":"Đoạn văn","vi":"Vận động viên Trung Quốc đầu tiên tham gia Thế vận hội Olympic là Lưu Trường Xuân, năm 1932 ông đã tham gia thi đấu chạy ngắn 100 mét và 200 mét."},{"hanzi":"虽然他没有得到好成绩，但是他让世界认识了中国。","pinyin":"Suīrán tā méiyǒu dédào hǎo chéngjì, dànshì tā ràng shìjiè rènshi le Zhōngguó.","speaker":"Đoạn văn","vi":"Tuy ông không đạt được thành tích tốt, nhưng ông đã giúp thế giới biết đến Trung Quốc."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài có câu \"第一位参加奥运会的中国运动员是刘长春，他1932年参加了100米和200米短跑比赛\" (Vận động viên Trung Quốc đầu tiên tham gia Thế vận hội là Lưu Trường Xuân, năm 1932 ông đã tham gia thi đấu chạy ngắn 100 mét và 200 mét).","options":["100米和200米短跑比赛","100米和400米短跑比赛","游泳和网球比赛","200米和800米短跑比赛"],"q":"1932年，刘长春在奥运会上参加了什么比赛？"},{"answerIdx":1,"explanation":"Trong bài có câu \"虽然他没有得到好成绩，但是他让世界认识了中国\" (Tuy ông không đạt được thành tích tốt, nhưng ông đã khiến thế giới biết đến Trung Quốc).","options":["他得到了非常好的比赛成绩","他让世界认识了中国","他带动很多中国运动员去打球","他成为了历史上最年轻的运动员"],"q":"刘长春参加1932年奥运会最大的意义是什么？"}],"scene":"在家里，李文准备演讲稿。","sceneVi":"Ở nhà, Lý Văn chuẩn bị bài diễn thuyết."}],"hsk3-10":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"你的数学越来越好，能不能介绍一下学习方法？","pinyin":"Nǐ de shùxué yuèláiyuè hǎo, néng bu néng jièshào yíxià xuéxí fāngfǎ?","speaker":"同学","vi":"Môn toán của cậu ngày càng giỏi, cậu có thể giới thiệu một chút phương pháp học tập được không?"},{"hanzi":"没有什么特别的方法，认真听课，认真记笔记。","pinyin":"Méiyǒu shénme tèbié de fāngfǎ, rènzhēn tīngkè, rènzhēn jì bǐjì.","speaker":"刘小雪","vi":"Không có phương pháp gì đặc biệt đâu, chăm chú nghe giảng, nghiêm túc ghi chép bài."},{"hanzi":"我看过你的笔记，记得非常清楚。","pinyin":"Wǒ kànguo nǐ de bǐjì, jì de fēicháng qīngchu.","speaker":"同学","vi":"Mình đã xem vở ghi của cậu rồi, ghi chép vô cùng rõ ràng."},{"hanzi":"老师写在黑板上的题都很重要，所以我会把这些题都记在本子上。","pinyin":"Lǎoshī xiě zài hēibǎn shang de tí dōu hěn zhòngyào, suǒyǐ wǒ huì bǎ zhèxiē tí dōu jì zài běnzi shang.","speaker":"刘小雪","vi":"Những bài tập thầy cô viết trên bảng đen đều rất quan trọng, vì vậy mình đều ghi hết những bài này vào vở."},{"hanzi":"你说得对。我没有记笔记的习惯。","pinyin":"Nǐ shuō de duì. Wǒ méiyǒu jì bǐjì de xíguàn.","speaker":"同学","vi":"Cậu nói đúng lắm. Mình không có thói quen ghi chép bài."},{"hanzi":"笔记挺重要的，我每天写作业以前，都要看一遍。","pinyin":"Bǐjì tǐng zhòngyào de, wǒ měitiān xiě zuòyè yǐqián, dōu yào kàn yí biàn.","speaker":"刘小雪","vi":"Ghi chép rất quan trọng đấy, mỗi ngày trước khi làm bài tập về nhà mình đều xem lại một lượt."},{"hanzi":"这个方法真好！我以后也试试，希望能提高成绩。","pinyin":"Zhège fāngfǎ zhēn hǎo! Wǒ yǐhòu yě shìshi, xīwàng néng tígāo chéngjì.","speaker":"同学","vi":"Phương pháp này hay thật đấy! Sau này mình cũng thử xem, hy vọng có thể nâng cao thành tích."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài Lưu Tiểu Tuyết nói \"认真听课，认真记笔记\" (Nghe giảng nghiêm túc, ghi chép cẩn thận) và \"我每天写作业以前，都要看一遍\" (Mỗi ngày trước khi làm bài tập mình đều xem lại ghi chép một lượt).","options":["每天多做几本数学练习册","上课前先预习黑板上的题","认真听课、记笔记，写作业前看一遍笔记","下课以后常去请教同学"],"q":"刘小雪学好数学的方法是什么？"},{"answerIdx":1,"explanation":"Trong bài bạn học nói \"这个方法真好！我以后也试试，希望能提高成绩\" (Phương pháp này hay quá! Sau này mình cũng thử xem, hy vọng có thể nâng cao thành tích).","options":["借刘小雪的笔记来抄一遍","也试着记笔记，希望能提高成绩","每天写完作业以后再看笔记","请老师把重要的题写在黑板上"],"q":"听了刘小雪的话，同学打算以后怎么做？"}],"scene":"在教室里，刘小雪跟同学聊学习方法。","sceneVi":"Trong phòng học, Lưu Tiểu Tuyết nói chuyện với bạn học về phương pháp học tập."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"小雪，昨天的考试，你考得怎么样？","pinyin":"Xiǎoxuě, zuótiān de kǎoshì, nǐ kǎo de zěnmeyàng?","speaker":"同学","vi":"Tiểu Tuyết, bài kiểm tra hôm qua cậu làm thế nào?"},{"hanzi":"我觉得历史有点儿难，你呢？","pinyin":"Wǒ juéde lìshǐ yǒudiǎnr nán, nǐ ne?","speaker":"刘小雪","vi":"Mình thấy môn lịch sử hơi khó một chút, còn cậu?"},{"hanzi":"数学考试我没看清楚要求，做错了好几个题，考得挺差的。","pinyin":"Shùxué kǎoshì wǒ méi kàn qīngchu yāoqiú, zuòcuò le hǎojǐ gè tí, kǎo de tǐng chà de.","speaker":"同学","vi":"Bài thi toán mình không đọc kỹ yêu cầu, làm sai mấy câu liền, thi kém lắm."},{"hanzi":"明天还有考试呢，别想那么多了，先复习外语吧。","pinyin":"Míngtiān hái yǒu kǎoshì ne, bié xiǎng nàme duō le, xiān fùxí wàiyǔ ba.","speaker":"刘小雪","vi":"Ngày mai vẫn còn bài thi nữa mà, đừng nghĩ nhiều thế nữa, ôn tập ngoại ngữ trước đi."},{"hanzi":"外语作业里有几个问题，我可以问问你吗？","pinyin":"Wàiyǔ zuòyè lǐ yǒu jǐ gè wèntí, wǒ kěyǐ wènwen nǐ ma?","speaker":"同学","vi":"Trong bài tập ngoại ngữ có mấy câu hỏi, mình có thể hỏi cậu một chút được không?"},{"hanzi":"当然可以。在学习上，遇到什么问题都可以问我。","pinyin":"Dāngrán kěyǐ. Zài xuéxí shang, yùdào shénme wèntí dōu kěyǐ wèn wǒ.","speaker":"刘小雪","vi":"Tất nhiên là được. Trong việc học, gặp vấn đề gì cũng đều có thể hỏi mình."},{"hanzi":"不好意思，这几个题我也不会。咱们还是一起去办公室问问李老师吧。","pinyin":"Bù hǎoyìsi, zhè jǐ gè tí wǒ yě bú huì. Zánmen háishì yìqǐ qù bàngōngshì wènwen Lǐ lǎoshī ba.","speaker":"刘小雪","vi":"Ngại quá, mấy câu này mình cũng không biết làm. Hay là tụi mình cùng đến văn phòng hỏi cô Lý đi."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài bạn học nói \"数学考试我没看清楚要求，做错了好几个题，考得挺差的\" (Bài thi toán mình không đọc kỹ yêu cầu, làm sai mấy câu liền, thi kém lắm).","options":["因为数学题比历史题难得多","因为他没复习数学，一直在做外语作业","因为他没看清楚要求，做错了好几个题","因为他考试的时候太紧张了，没做完"],"q":"同学昨天的数学考试为什么考得不好？"},{"answerIdx":1,"explanation":"Trong bài Lưu Tiểu Tuyết nói \"不好意思，这几个题我也不会。咱们还是一起去办公室问问李老师吧\" (Ngại quá, mấy câu này mình cũng không biết làm. Chúng ta vẫn là cùng lên văn phòng hỏi cô Lý đi).","options":["刘小雪马上教同学怎么做","两个人一起去办公室问李老师","先不做这几个题，明天考试后再说","回家查书自己解决"],"q":"对于外语作业里不会的几个问题，他们最后决定怎么办？"}],"scene":"在教室里，刘小雪跟同学聊昨天的考试。","sceneVi":"Trong phòng học, Lưu Tiểu Tuyết nói chuyện với bạn học về bài kiểm tra hôm qua."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"李老师，书上有几个问题，我们想问问您。","pinyin":"Lǐ lǎoshī, shū shang yǒu jǐ gè wèntí, wǒmen xiǎng wènwen nín.","speaker":"同学","vi":"Thưa cô Lý, trong sách có mấy câu hỏi, chúng em muốn hỏi cô ạ."},{"hanzi":"好，坐下说吧，哪个题不会？","pinyin":"Hǎo, zuòxia shuō ba, nǎge tí bú huì?","speaker":"李老师","vi":"Được, ngồi xuống nói đi, câu nào không biết làm?"},{"hanzi":"书上第五页的这个对话我看不懂，小雪也不明白。","pinyin":"Shū shang dì-wǔ yè de zhège duìhuà wǒ kàn bu dǒng, Xiǎoxuě yě bù míngbai.","speaker":"同学","vi":"Đoạn hội thoại ở trang 5 trong sách này em đọc không hiểu, Tiểu Tuyết cũng không hiểu ạ."},{"hanzi":"我课上讲过这几句话，再给你们讲一遍。","pinyin":"Wǒ kè shang jiǎngguo zhè jǐ jù huà, zài gěi nǐmen jiǎng yí biàn.","speaker":"李老师","vi":"Trên lớp cô đã giảng mấy câu này rồi, để cô giảng lại cho các em một lượt nữa."},{"hanzi":"我终于懂了。这些句子一点儿也不难。","pinyin":"Wǒ zhōngyú dǒng le. Zhèxiē jùzi yìdiǎnr yě bù nán.","speaker":"同学","vi":"Cuối cùng em cũng hiểu rồi. Những câu này chẳng khó chút nào."},{"hanzi":"我也明白了，谢谢您，李老师。","pinyin":"Wǒ yě míngbai le, xièxie nín, Lǐ lǎoshī.","speaker":"刘小雪","vi":"Em cũng hiểu rồi ạ, cảm ơn cô Lý."},{"hanzi":"我这本书上还有几个练习，你们回家也做一做，明天再把书还给我。","pinyin":"Wǒ zhè běn shū shang hái yǒu jǐ gè liànxí, nǐmen huíjiā yě zuò yi zuò, míngtiān zài bǎ shū huán gěi wǒ.","speaker":"李老师","vi":"Trên quyển sách này của cô vẫn còn mấy bài tập, các em về nhà làm thêm đi, ngày mai rồi trả sách lại cho cô."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài bạn học nói với cô Lý \"书上第五页的这个对话我看不懂，小雪也不明白\" (Đoạn hội thoại ở trang thứ năm trong sách em đọc không hiểu, Tiểu Tuyết cũng không rõ).","options":["第三页","第四页","第五页","第六页"],"q":"刘小雪和同学看不懂的对话在书的第几页？"},{"answerIdx":1,"explanation":"Trong bài cô Lý dặn \"我这本书上还有几个练习，你们回家也做一做，明天再把书还给我\" (Trên quyển sách này của cô còn mấy bài tập nữa, các em về nhà cũng làm thử đi, ngày mai trả lại sách cho cô).","options":["在办公室里把第五页的句子再读一遍","回家做老师书上的几个练习，明天再把书还给她","明天上课的时候再问其他问题","把这几句话记在笔记本上"],"q":"讲完题以后，李老师让他们做什么？"}],"scene":"在李老师办公室，刘小雪跟同学问问题。","sceneVi":"Ở văn phòng cô Lý, Lưu Tiểu Tuyết và bạn học đang hỏi bài."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"家月姐姐：你最近怎么样？","pinyin":"Jiāyuè jiějie: Nǐ zuìjìn zěnmeyàng?","speaker":"Đoạn văn","vi":"Chị Gia Nguyệt: Dạo này chị thế nào?"},{"hanzi":"忙不忙？","pinyin":"Máng bu máng?","speaker":"Đoạn văn","vi":"Có bận không ạ?"},{"hanzi":"我现在上初中二年级，学习越来越忙，后年就要考高中了。","pinyin":"Wǒ xiànzài shàng chūzhōng èr niánjí, xuéxí yuèláiyuè máng, hòunián jiù yào kǎo gāozhōng le.","speaker":"Đoạn văn","vi":"Hiện tại em đang học lớp 8 (năm hai trung học cơ sở), việc học ngày càng bận rộn, năm kia là phải thi lên cấp ba rồi."},{"hanzi":"中国的学校一般是小学六年，初中三年，高中三年。","pinyin":"Zhōngguó de xuéxiào yìbān shì xiǎoxué liù nián, chūzhōng sān nián, gāozhōng sān nián.","speaker":"Đoạn văn","vi":"Trường học ở Trung Quốc thông thường là tiểu học 6 năm, trung học cơ sở 3 năm, trung học phổ thông 3 năm."},{"hanzi":"妈妈说想考上好大学，就得上一个好高中；为了考上好高中，初中就得有一个不错的成绩，所以我现在非常努力。","pinyin":"Māma shuō xiǎng kǎoshàng hǎo dàxué, jiù děi shàng yí gè hǎo gāozhōng; wèile kǎoshàng hǎo gāozhōng, chūzhōng jiù děi yǒu yí gè búcuò de chéngjì, suǒyǐ wǒ xiànzài fēicháng nǔlì.","speaker":"Đoạn văn","vi":"Mẹ nói muốn thi đỗ đại học tốt thì phải vào được trường cấp ba tốt; để thi đỗ cấp ba tốt thì cấp hai phải có thành tích khá tốt, vì vậy hiện giờ em đang vô cùng cố gắng."},{"hanzi":"家月姐姐，你知道吗？","pinyin":"Jiāyuè jiějie, nǐ zhīdào ma?","speaker":"Đoạn văn","vi":"Chị Gia Nguyệt ơi, chị có biết không?"},{"hanzi":"在你的影响下，我也开始喜欢拍照了。","pinyin":"Zài nǐ de yǐngxiǎng xià, wǒ yě kāishǐ xǐhuan pāizhào le.","speaker":"Đoạn văn","vi":"Dưới sự ảnh hưởng của chị, em cũng bắt đầu thích chụp ảnh rồi đấy."},{"hanzi":"下次你再来北京，我给你看看我照的照片。","pinyin":"Xià cì nǐ zài lái Běijīng, wǒ gěi nǐ kànkan wǒ zhào de zhàopiàn.","speaker":"Đoạn văn","vi":"Lần sau chị đến Bắc Kinh nữa, em sẽ cho chị xem những bức ảnh em chụp."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Lưu Tiểu Tuyết viết \"我现在上初中二年级，学习越来越忙，后年就要考高中了\" (Hiện tại em đang học lớp hai trung học cơ sở, việc học ngày càng bận, năm kia là thi lên cấp ba rồi).","options":["小学六年级","初中二年级","初中三年级","高中一年级"],"q":"刘小雪现在上几年级？"},{"answerIdx":2,"explanation":"Trong bài Lưu Tiểu Tuyết viết \"在你的影响下，我也开始喜欢拍照了\" (Dưới sự ảnh hưởng của chị, em cũng bắt đầu thích chụp ảnh rồi).","options":["写邮件","去北京旅游","拍照","看高中书"],"q":"在家月姐姐的影响下，刘小雪开始喜欢做什么了？"}],"scene":"在家里，刘小雪在写邮件。","sceneVi":"Ở nhà, Lưu Tiểu Tuyết đang viết email."}],"hsk3-11":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"会议下午几点开始？","pinyin":"Huìyì xiàwǔ jǐ diǎn kāishǐ?","speaker":"王一雪","vi":"Cuộc họp chiều nay mấy giờ bắt đầu vậy?"},{"hanzi":"今天下午经理不在，不开会了。","pinyin":"Jīntiān xiàwǔ jīnglǐ bú zài, bù kāihuì le.","speaker":"杨同乐","vi":"Chiều nay giám đốc không có ở đây, không họp nữa."},{"hanzi":"那什么时候开会？","pinyin":"Nà shénme shíhou kāihuì?","speaker":"王一雪","vi":"Vậy khi nào họp?"},{"hanzi":"后天上午十点，会议地点换到第一会议室。我正要给大家发邮件。","pinyin":"Hòutiān shàngwǔ shí diǎn, huìyì dìdiǎn huàn dào dì-yī huìyìshì. Wǒ zhèng yào gěi dàjiā fā yóujiàn.","speaker":"杨同乐","vi":"10 giờ sáng ngày kia, địa điểm họp đổi sang phòng họp số 1. Tôi đang định gửi email cho mọi người."},{"hanzi":"开会的时候，我们用会议室的电脑还是自己的笔记本电脑？","pinyin":"Kāihuì de shíhou, wǒmen yòng huìyìshì de diànnǎo háishi zìjǐ de bǐjìběn diànnǎo?","speaker":"王一雪","vi":"Lúc họp, chúng ta dùng máy tính của phòng họp hay máy tính xách tay của mình?"},{"hanzi":"会议室的电脑或者自己的电脑都可以。","pinyin":"Huìyìshì de diànnǎo huòzhě zìjǐ de diànnǎo dōu kěyǐ.","speaker":"杨同乐","vi":"Máy tính của phòng họp hoặc máy tính của mình đều được."},{"hanzi":"那到时候咱们早点儿过去，你帮我把电脑接好吧。","pinyin":"Nà dào shíhou zánmen zǎodiǎnr guòqù, nǐ bāng wǒ bǎ diànnǎo jiēhǎo ba.","speaker":"王一雪","vi":"Vậy đến lúc đó chúng ta qua sớm một chút, cậu giúp tôi kết nối sẵn máy tính nhé."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Dương Đồng Nhạc nói: \"今天下午经理不在，不开会了。\" (Chiều nay giám đốc không có mặt nên không họp nữa), nên đáp án đúng là 因为今天下午经理不在。","options":["因为会议室的电脑坏了","因为今天下午经理不在","因为大家还没收到邮件","因为第一会议室有人在用"],"q":"为什么今天下午不开会了？"},{"answerIdx":2,"explanation":"Trong bài có câu: \"后天上午十点，会议地点换到第一会议室。\" (10 giờ sáng ngày kia, địa điểm họp đổi sang phòng họp số 1), nên đáp án đúng là 后天上午十点，第一会议室。","options":["明天上午十点，第二会议室","后天下午十点，第一会议室","后天上午十点，第一会议室","明天下午两点，办公室"],"q":"会议改在什么时候、什么地方举行？"}],"scene":"在办公室里，王一雪跟杨同乐在讨论工作。","sceneVi":"Trong văn phòng, Vương Nhất Tuyết và Dương Đồng Nhạc đang thảo luận công việc."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"电脑接好了吗？","pinyin":"Diànnǎo jiēhǎo le ma?","speaker":"王一雪","vi":"Máy tính đã kết nối xong chưa?"},{"hanzi":"已经接好了，您开机看看有没有问题。","pinyin":"Yǐjīng jiēhǎo le, nín kāijī kànkan yǒu méiyǒu wèntí.","speaker":"杨同乐","vi":"Kết nối xong rồi, chị bật máy xem thử có vấn đề gì không."},{"hanzi":"现在什么都看不见。","pinyin":"Xiànzài shénme dōu kànbujiàn.","speaker":"王一雪","vi":"Bây giờ chẳng nhìn thấy gì cả."},{"hanzi":"我检查一下哪里出问题了……您再试一下。","pinyin":"Wǒ jiǎnchá yíxià nǎlǐ chū wèntí le…… nín zài shì yíxià.","speaker":"杨同乐","vi":"Để tôi kiểm tra xem chỗ nào bị lỗi... Chị thử lại lần nữa xem."},{"hanzi":"看见了，但是听不见声音。","pinyin":"Kànjiàn le, dànshì tīngbujiàn shēngyīn.","speaker":"王一雪","vi":"Thấy hình rồi, nhưng không nghe thấy âm thanh."},{"hanzi":"现在呢？","pinyin":"Xiànzài ne?","speaker":"杨同乐","vi":"Bây giờ thì sao ạ?"},{"hanzi":"听得见声音，但是声音有点儿小，听不清楚。","pinyin":"Tīngdejiàn shēngyīn, dànshì shēngyīn yǒudiǎnr xiǎo, tīngbuqīngchu.","speaker":"王一雪","vi":"Nghe thấy âm thanh rồi, nhưng tiếng hơi nhỏ, nghe không rõ."},{"hanzi":"看来我没办法解决这个问题，只能找别人来帮帮忙了。","pinyin":"Kànlái wǒ méi bànfǎ jiějué zhège wèntí, zhǐ néng zhǎo biérén lái bāngbang máng le.","speaker":"杨同乐","vi":"Xem ra tôi không có cách nào giải quyết vấn đề này rồi, đành phải tìm người khác đến giúp một tay vậy."}],"readingQuiz":[{"answerIdx":2,"explanation":"Sau khi Dương Đồng Nhạc nói: \"我检查一下哪里出问题了……您再试一下。\", Vương Nhất Tuyết trả lời: \"看见了，但是听不见声音。\" (Nhìn thấy rồi, nhưng không nghe thấy tiếng), nên đáp án đúng là 能看见了，可是听不见声音。","options":["声音很清楚，但是什么都看不见","既能看见画面，也能听见大声的声音","能看见了，可是听不见声音","电脑完全修好了，没有任何问题"],"q":"杨同乐第一次检查以后，电脑怎么样了？"},{"answerIdx":2,"explanation":"Ở cuối bài Dương Đồng Nhạc nói: \"看来我没办法解决这个问题，只能找别人来帮帮忙了。\" (Xem ra tôi không giải quyết được vấn đề này, đành phải tìm người khác đến giúp vậy), nên đáp án đúng là 请别人过来帮忙解决问题。","options":["换一台自己的笔记本电脑","再检查一次声音为什么小","请别人过来帮忙解决问题","告诉大家今天的会不开了"],"q":"最后杨同乐打算怎么办？"}],"scene":"在会议室，王一雪跟杨同乐在做会前准备。","sceneVi":"Trong phòng họp, Vương Nhất Tuyết và Dương Đồng Nhạc đang chuẩn bị trước cuộc họp."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"同乐，你看见老张了吗？","pinyin":"Tónglè, nǐ kànjiàn Lǎo Zhāng le ma?","speaker":"王一雪","vi":"Đồng Nhạc, cậu có thấy Lão Trương không?"},{"hanzi":"老张没来。他说家里有点儿事，所以请假了。","pinyin":"Lǎo Zhāng méi lái. Tā shuō jiāli yǒudiǎnr shì, suǒyǐ qǐngjià le.","speaker":"杨同乐","vi":"Lão Trương không đến. Anh ấy nói ở nhà có chút việc nên xin nghỉ phép rồi."},{"hanzi":"好几个同事都休假了，开会前这么多工作我怕干不完。","pinyin":"Hǎo jǐ ge tóngshì dōu xiūjià le, kāihuì qián zhème duō gōngzuò wǒ pà gànbuwán.","speaker":"王一雪","vi":"Mấy đồng nghiệp đều nghỉ phép cả rồi, trước cuộc họp nhiều việc thế này tôi sợ làm không xuể."},{"hanzi":"十二点多了，咱们先去吃饭吧。吃完饭，我跟您一起把这些工作做完。","pinyin":"Shí'èr diǎn duō le, zánmen xiān qù chīfàn ba. Chīwán fàn, wǒ gēn nín yìqǐ bǎ zhèxiē gōngzuò zuòwán.","speaker":"杨同乐","vi":"Hơn mười hai giờ rồi, chúng ta đi ăn cơm trước đi. Ăn xong, tôi sẽ cùng chị làm hết đống việc này."},{"hanzi":"你先去吃，我想再干一会儿。明天开会前要发到公司的邮箱里。","pinyin":"Nǐ xiān qù chī, wǒ xiǎng zài gàn yíhuìr. Míngtiān kāihuì qián yào fā dào gōngsī de yóuxiāng li.","speaker":"王一雪","vi":"Cậu đi ăn trước đi, tôi muốn làm thêm một lát nữa. Trước cuộc họp ngày mai phải gửi vào hộp thư của công ty rồi."},{"hanzi":"您没看到邮件吗？经理还没回来呢，下周才能开会。","pinyin":"Nín méi kàndào yóujiàn ma? Jīnglǐ hái méi huílái ne, xià zhōu cái néng kāihuì.","speaker":"杨同乐","vi":"Chị chưa xem email sao? Giám đốc vẫn chưa về đâu, tuần sau mới có thể họp được."},{"hanzi":"那不着急了。走，吃饭去。","pinyin":"Nà bù zháojí le. Zǒu, chīfàn qù.","speaker":"王一雪","vi":"Thế thì không phải vội nữa rồi. Đi, đi ăn cơm thôi."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Vương Nhất Tuyết nói: \"你先去吃，我想再干一会儿。明天开会前要发到公司的邮箱里。\" (Cậu đi ăn trước đi, tôi muốn làm thêm một lát. Trước buổi họp ngày mai phải gửi vào hòm thư của công ty), nên đáp án đúng là 她以为明天开会前要把工作发到公司邮箱。","options":["她还不太饿，想等老张回来一起吃","她以为明天开会前要把工作发到公司邮箱","她正在给经理和同事们发邮件","她已经点好了外卖，不想出去吃"],"q":"王一雪一开始为什么不想马上去吃饭？"},{"answerIdx":1,"explanation":"Trong bài Dương Đồng Nhạc nói: \"您没看到邮件吗？经理还没回来呢，下周才能开会。\" (Chị chưa xem email sao? Giám đốc vẫn chưa về, tuần sau mới họp được), nghe xong Vương Nhất Tuyết mới yên tâm đi ăn cơm, nên đáp án đúng là 经理还没回来，下周才开会。","options":["老张下午就会回来帮她工作","经理还没回来，下周才开会","其他休假的同事已经把工作做完了","杨同乐已经把邮件发到公司邮箱了"],"q":"王一雪知道了什么消息以后，才决定去吃饭？"}],"scene":"在办公室里，王一雪跟杨同乐在聊天儿。","sceneVi":"Trong văn phòng, Vương Nhất Tuyết và Dương Đồng Nhạc đang trò chuyện."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"前几天，上海的同事来北京了。","pinyin":"Qián jǐ tiān, Shànghǎi de tóngshì lái Běijīng le.","speaker":"Đoạn văn","vi":"Mấy hôm trước, các đồng nghiệp ở Thượng Hải đã đến Bắc Kinh."},{"hanzi":"一起吃饭时，他们跟我说最近有不少同事去上海工作了，问我愿意不愿意也去上海。","pinyin":"Yìqǐ chīfàn shí, tāmen gēn wǒ shuō zuìjìn yǒu bù shǎo tóngshì qù Shànghǎi gōngzuò le, wèn wǒ yuànyì bu yuànyì yě qù Shànghǎi.","speaker":"Đoạn văn","vi":"Khi ăn cơm cùng nhau, họ nói với tôi gần đây có không ít đồng nghiệp đã đến Thượng Hải làm việc, hỏi tôi có muốn cũng đến Thượng Hải không."},{"hanzi":"我是这样想的：现在丈夫和孩子都在北京，刘明的工作很忙，小雪和小明也还小，我去别的城市工作就要离开他们。","pinyin":"Wǒ shì zhèyàng xiǎng de: xiànzài zhàngfu hé háizi dōu zài Běijīng, Liú Míng de gōngzuò hěn máng, Xiǎo Xuě hé Xiǎo Míng yě hái xiǎo, wǒ qù biéde chéngshì gōngzuò jiù yào líkāi tāmen.","speaker":"Đoạn văn","vi":"Tôi nghĩ thế này: hiện tại chồng và các con đều ở Bắc Kinh, công việc của Lưu Minh rất bận, Tiểu Tuyết và Tiểu Minh cũng còn nhỏ, nếu tôi đi thành phố khác làm việc thì sẽ phải rời xa họ."},{"hanzi":"虽然去上海可能会有更好的机会，但是对我来说，生活也很重要，我不愿意为工作或学习离开家人。","pinyin":"Suīrán qù Shànghǎi kěnéng huì yǒu gèng hǎo de jīhuì, dànshì duì wǒ láishuō, shēnghuó yě hěn zhòngyào, wǒ bú yuànyì wèi gōngzuò huò xuéxí líkāi jiārén.","speaker":"Đoạn văn","vi":"Tuy rằng đến Thượng Hải có thể sẽ có cơ hội tốt hơn, nhưng đối với tôi mà nói, cuộc sống cũng rất quan trọng, tôi không muốn vì công việc hay học tập mà rời xa gia đình."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu: \"一起吃饭时，他们跟我说最近有不少同事去上海工作了，问我愿意不愿意也去上海。\" (Khi ăn cơm cùng nhau, họ nói với tôi gần đây có khá nhiều đồng nghiệp đến Thượng Hải làm việc, hỏi tôi có muốn cũng đến Thượng Hải không), nên đáp án đúng là 问她愿不愿意也去上海工作。","options":["问她为什么不让刘明去上海工作","问她愿不愿意也去上海工作","问她小雪和小明喜欢不喜欢北京","问她最近在北京的工作忙不忙"],"q":"上海的同事来北京一起吃饭时，问了王一雪什么问题？"},{"answerIdx":2,"explanation":"Trong bài Vương Nhất Tuyết viết: \"现在丈夫和孩子都在北京……我不愿意为工作或学习离开家人。\" (Hiện tại chồng và các con đều ở Bắc Kinh... tôi không muốn vì công việc hay học tập mà rời xa gia đình), nên đáp án đúng là 因为她不愿意为了工作离开在北京的家人。","options":["因为她觉得上海没有更好的机会","因为她不喜欢跟上海的同事一起工作","因为她不愿意为了工作离开在北京的家人","因为她觉得北京的工作比上海更重要"],"q":"王一雪为什么不想去上海工作？"}],"scene":"在家里，王一雪在写日记。","sceneVi":"Ở nhà, Vương Nhất Tuyết đang viết nhật ký."}],"hsk3-12":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"王老师，您看，这条街上的树都开花了。","pinyin":"Wáng lǎoshī, nín kàn, zhè tiáo jiē shàng de shù dōu kāihuā le.","speaker":"白家月","vi":"Cô Vương ơi, cô nhìn kìa, cây trên con phố này đều nở hoa hết rồi."},{"hanzi":"上周我去公园坐船了，公园里的花也开了。","pinyin":"Shàng zhōu wǒ qù gōngyuán zuòchuán le, gōngyuán li de huā yě kāi le.","speaker":"王一飞","vi":"Tuần trước cô đi công viên ngồi thuyền, hoa trong công viên cũng nở rồi."},{"hanzi":"天气这么好，下午我也想去公园坐船。","pinyin":"Tiānqì zhème hǎo, xiàwǔ wǒ yě xiǎng qù gōngyuán zuòchuán.","speaker":"白家月","vi":"Thời tiết đẹp thế này, chiều nay em cũng muốn đi công viên ngồi thuyền."},{"hanzi":"去吧！今天是工作日，人应该不多。","pinyin":"Qù ba! Jīntiān shì gōngzuòrì, rén yīnggāi bù duō.","speaker":"王一飞","vi":"Đi đi! Hôm nay là ngày làm việc, chắc là không đông người đâu."},{"hanzi":"您有时间吗？我想跟您一起去。","pinyin":"Nín yǒu shíjiān ma? Wǒ xiǎng gēn nín yìqǐ qù.","speaker":"白家月","vi":"Cô có thời gian không ạ? Em muốn đi cùng với cô."},{"hanzi":"我今天下午有课，不能去太远的地方。","pinyin":"Wǒ jīntiān xiàwǔ yǒu kè, bù néng qù tài yuǎn de dìfang.","speaker":"王一飞","vi":"Chiều nay cô có tiết dạy, không thể đi nơi quá xa được."},{"hanzi":"那咱们换一天去？","pinyin":"Nà zánmen huàn yì tiān qù?","speaker":"白家月","vi":"Vậy chúng ta đổi sang hôm khác đi nhé?"},{"hanzi":"行。或者明天去，或者后天去，我给你打电话。","pinyin":"Xíng. Huòzhě míngtiān qù, huòzhě hòutiān qù, wǒ gěi nǐ dǎ diànhuà.","speaker":"王一飞","vi":"Được đấy. Hoặc ngày mai đi, hoặc ngày kia đi, cô sẽ gọi điện cho em."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài thầy/cô Vương nói: \"我今天下午有课，不能去太远的地方。\" (Chiều nay tôi có tiết học, không thể đi nơi quá xa), nên đáp án đúng là 因为王老师今天下午有课。","options":["因为公园里的花还没有开","因为今天是工作日，公园人太多","因为王老师今天下午有课","因为王老师上周刚去过，不想再去了"],"q":"今天下午王老师为什么不能跟白家月一起去公园？"},{"answerIdx":1,"explanation":"Trong bài Vương Nhất Phi hẹn: \"或者明天去，或者后天去，我给你打电话。\" (Hoặc ngày mai đi, hoặc ngày kia đi, tôi sẽ gọi điện cho em), nên đáp án đúng là 明天或者后天。","options":["今天下午下课以后","明天或者后天","下周的工作日","这周六上午"],"q":"他们打算什么时候去公园？"}],"scene":"在街上，王一飞和白家月边走边聊。","sceneVi":"Trên phố, Vương Nhất Phi và Bạch Gia Nguyệt vừa đi vừa trò chuyện."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"刚才还是大晴天呢，怎么突然就刮起风来了？","pinyin":"Gāngcái háishi dà qíngtiān ne, zěnme tūrán jiù guā qǐ fēng lái le?","speaker":"白家月","vi":"Vừa nãy trời còn nắng to mà, sao tự nhiên lại nổi gió lên thế?"},{"hanzi":"好像新闻里说今天有雨。","pinyin":"Hǎoxiàng xīnwén li shuō jīntiān yǒu yǔ.","speaker":"王一飞","vi":"Hình như trong bản tin nói hôm nay có mưa đấy."},{"hanzi":"啊？我每天书包里都放着雨伞，就今天没带。","pinyin":"Á? Wǒ měitiān shūbāo li dōu fàngzhe yǔsǎn, jiù jīntiān méi dài.","speaker":"白家月","vi":"Á? Ngày nào trong cặp sách em cũng để sẵn ô, chỉ có hôm nay là không mang."},{"hanzi":"我可以借给你，我车里有一把伞和一件雨衣。","pinyin":"Wǒ kěyǐ jiè gěi nǐ, wǒ chē li yǒu yì bǎ sǎn hé yí jiàn yǔyī.","speaker":"王一飞","vi":"Cô có thể cho em mượn, trong xe cô có một cái ô và một chiếc áo mưa."},{"hanzi":"谢谢，希望下午天气能变好。","pinyin":"Xièxie, xīwàng xiàwǔ tiānqì néng biànhǎo.","speaker":"白家月","vi":"Cảm ơn cô, hy vọng buổi chiều thời tiết có thể tốt lên."},{"hanzi":"这个季节天气变化很快。","pinyin":"Zhège jìjié tiānqì biànhuà hěn kuài.","speaker":"王一飞","vi":"Mùa này thời tiết thay đổi nhanh lắm."},{"hanzi":"雨已经下起来了，咱们快点儿走吧。","pinyin":"Yǔ yǐjīng xià qǐlái le, zánmen kuài diǎnr zǒu ba.","speaker":"白家月","vi":"Mưa đã bắt đầu rơi rồi, chúng ta đi nhanh lên thôi."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Bạch Gia Nguyệt nói: \"我每天书包里都放着雨伞，就今天没带。\" (Ngày nào em cũng để ô trong cặp sách, chỉ có hôm nay là không mang), nên đáp án đúng là 她每天都把伞放在书包里，只有今天没带。","options":["她平时不带伞，今天书包里正好有一把","她每天都把伞放在书包里，只有今天没带","她的雨伞和雨衣都忘在教室里了","她看到新闻说有雨，所以带了一把伞"],"q":"关于白家月带伞的事，下面哪句话是对的？"},{"answerIdx":2,"explanation":"Trong bài Vương Nhất Phi nói: \"我可以借给你，我车里有一把伞和一件雨衣。\" (Tôi có thể cho em mượn, trong xe tôi có một cái ô và một chiếc áo mưa), nên đáp án đúng là 一把雨伞和一件雨衣。","options":["两把雨伞","两件雨衣","一把雨伞和一件雨衣","一个书包和一把雨伞"],"q":"王一飞的车里有什么东西可以借给白家月？"}],"scene":"在街上，王一飞和白家月一起散步。","sceneVi":"Trên phố, Vương Nhất Phi và Bạch Gia Nguyệt cùng nhau đi dạo."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"您来这里已经一年多了，习惯了吧？","pinyin":"Nín lái zhèlǐ yǐjīng yì nián duō le, xíguàn le ba?","speaker":"白家月","vi":"Cô đến đây đã hơn một năm rồi, quen rồi chứ ạ?"},{"hanzi":"别的早就习惯了，就是天气我还不太习惯。","pinyin":"Biéde zǎo jiù xíguàn le, jiùshì tiānqì wǒ hái bú tài xíguàn.","speaker":"王一飞","vi":"Những thứ khác thì quen từ lâu rồi, chỉ có thời tiết là cô vẫn chưa quen lắm."},{"hanzi":"为什么？您不喜欢这里的天气吗？","pinyin":"Wèishénme? Nín bù xǐhuan zhèlǐ de tiānqì ma?","speaker":"白家月","vi":"Tại sao vậy ạ? Cô không thích thời tiết ở đây sao?"},{"hanzi":"我觉得冬天太冷了。","pinyin":"Wǒ juéde dōngtiān tài lěng le.","speaker":"王一飞","vi":"Cô thấy mùa đông lạnh quá."},{"hanzi":"冬天虽然冷，但是下雪的时候特别漂亮。","pinyin":"Dōngtiān suīrán lěng, dànshì xiàxuě de shíhou tèbié piàoliang.","speaker":"白家月","vi":"Mùa đông tuy lạnh, nhưng lúc tuyết rơi thì đặc biệt đẹp."},{"hanzi":"我也喜欢雪。北京常常下雪，但听说今年就下了一次。","pinyin":"Wǒ yě xǐhuan xuě. Běijīng chángcháng xiàxuě, dàn tīngshuō jīnnián jiù xià le yí cì.","speaker":"王一飞","vi":"Cô cũng thích tuyết. Bắc Kinh thường hay có tuyết rơi, nhưng nghe nói năm nay chỉ rơi có một lần."},{"hanzi":"我没关注过北京的天气，但是新闻里说过，今年冬天很多地方雪下得都少了。","pinyin":"Wǒ méi guānzhù guo Běijīng de tiānqì, dànshì xīnwén li shuō guo, jīnnián dōngtiān hěn duō dìfang xuě xià de dōu shǎo le.","speaker":"白家月","vi":"Em chưa từng theo dõi thời tiết ở Bắc Kinh, nhưng trong bản tin từng nói, mùa đông năm nay nhiều nơi tuyết rơi đều ít đi rồi."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Vương Nhất Phi nói: \"别的早就习惯了，就是天气我还不太习惯。\" (Những thứ khác tôi quen từ lâu rồi, chỉ có thời tiết là tôi vẫn chưa quen lắm), nên đáp án đúng là 这里的天气。","options":["这里的饭菜","这里的天气","这里的教室","这里的交通"],"q":"来这里一年多了，王一飞对什么还不太习惯？"},{"answerIdx":1,"explanation":"Trong bài Bạch Gia Nguyệt nói: \"新闻里说过，今年冬天很多地方雪下得都少了。\" (Trong bản tin có nói, mùa đông năm nay nhiều nơi tuyết đều rơi ít đi), nên đáp án đúng là 今年冬天很多地方的雪都下得少了。","options":["北京今年冬天一次雪也没下","今年冬天很多地方的雪都下得少了","北京的冬天比这里更冷","今年冬天很快就要下大雨了"],"q":"白家月从新闻里知道了什么？"}],"scene":"在教室里，王一飞和白家月躲雨。","sceneVi":"Trong phòng học, Vương Nhất Phi và Bạch Gia Nguyệt đang trú mưa."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"我离开北京到这里工作一年多了。","pinyin":"Wǒ líkāi Běijīng dào zhèlǐ gōngzuò yì nián duō le.","speaker":"Đoạn văn","vi":"Tôi rời Bắc Kinh đến đây làm việc đã hơn một năm rồi."},{"hanzi":"这一年多住下来，我还是更喜欢北京的四季。","pinyin":"Zhè yì nián duō zhù xiàlái, wǒ háishi gèng xǐhuan Běijīng de sìjì.","speaker":"Đoạn văn","vi":"Sống ở đây suốt hơn một năm qua, tôi vẫn thích bốn mùa của Bắc Kinh hơn."},{"hanzi":"北京的春天最舒服，天气不冷不热。","pinyin":"Běijīng de chūntiān zuì shūfu, tiānqì bù lěng bú rè.","speaker":"Đoạn văn","vi":"Mùa xuân ở Bắc Kinh dễ chịu nhất, thời tiết không lạnh không nóng."},{"hanzi":"夏天白天很热，但是晚上比较凉快。","pinyin":"Xiàtiān báitiān hěn rè, dànshì wǎnshang bǐjiào liángkuai.","speaker":"Đoạn văn","vi":"Mùa hè ban ngày rất nóng, nhưng buổi tối khá mát mẻ."},{"hanzi":"秋天树上的叶子都变成了红色、黄色，非常漂亮。","pinyin":"Qiūtiān shù shàng de yèzi dōu biànchéng le hóngsè, huángsè, fēicháng piàoliang.","speaker":"Đoạn văn","vi":"Mùa thu lá trên cây đều biến thành màu đỏ, màu vàng, vô cùng đẹp."},{"hanzi":"冬天不但冷，而且风很大，我最不喜欢冬天。","pinyin":"Dōngtiān búdàn lěng, érqiě fēng hěn dà, wǒ zuì bù xǐhuan dōngtiān.","speaker":"Đoạn văn","vi":"Mùa đông không những lạnh mà gió còn rất to, tôi không thích mùa đông nhất."},{"hanzi":"每个人都有自己最喜欢的季节，你最喜欢哪个季节呢？","pinyin":"Měi ge rén dōu yǒu zìjǐ zuì xǐhuan de jìjié, nǐ zuì xǐhuan nǎge jìjié ne?","speaker":"Đoạn văn","vi":"Mỗi người đều có mùa mà mình thích nhất, còn bạn thích nhất mùa nào vậy?"}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài có câu: \"北京的春天最舒服，天气不冷不热。\" (Mùa xuân ở Bắc Kinh dễ chịu nhất, thời tiết không lạnh không nóng), nên đáp án đúng là 春天。","options":["春天","夏天","秋天","冬天"],"q":"王一飞觉得北京的哪个季节最舒服？"},{"answerIdx":2,"explanation":"Trong bài có câu: \"冬天不但冷，而且风很大，我最不喜欢冬天。\" (Mùa đông không những lạnh mà gió còn rất lớn, tôi không thích mùa đông nhất), nên đáp án đúng là 因为冬天不但冷，而且风很大。","options":["因为冬天树上的叶子都掉了","因为冬天几乎不下雪","因为冬天不但冷，而且风很大","因为冬天晚上太热，不凉快"],"q":"王一飞为什么最不喜欢冬天？"}],"scene":"在家里，王一飞在写日记。","sceneVi":"Ở nhà, Vương Nhất Phi đang viết nhật ký."}],"hsk3-13":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"今天我请客，你们想吃什么就点什么！","pinyin":"Jīntiān wǒ qǐngkè, nǐmen xiǎng chī shénme jiù diǎn shénme!","speaker":"杨同乐","vi":"Hôm nay tôi mời, mọi người muốn ăn gì thì cứ gọi món đó!"},{"hanzi":"那我就不客气了。听说这家饭馆的鱼做得很特别？","pinyin":"Nà wǒ jiù bú kèqi le. Tīngshuō zhè jiā fànguǎn de yú zuò de hěn tèbié?","speaker":"王一雪","vi":"Vậy thì tôi không khách sáo nữa. Nghe nói món cá của nhà hàng này làm rất đặc biệt à?"},{"hanzi":"对，南方菜跟你们北方菜的做法不同。除了鱼，你们还想吃什么？","pinyin":"Duì, nánfāng cài gēn nǐmen běifāng cài de zuòfǎ bù tóng. Chúle yú, nǐmen hái xiǎng chī shénme?","speaker":"杨同乐","vi":"Đúng vậy, cách làm món ăn miền Nam khác với món ăn miền Bắc của các bạn. Ngoài cá ra, mọi người còn muốn ăn gì nữa?"},{"hanzi":"我不常吃南方菜，还是你决定吧。","pinyin":"Wǒ bù cháng chī nánfāng cài, háishi nǐ juédìng ba.","speaker":"同事","vi":"Tôi không thường ăn món miền Nam, hay là anh quyết định đi."},{"hanzi":"好，那再加一个鸡肉，一个……","pinyin":"Hǎo, nà zài jiā yí gè jīròu, yí gè……","speaker":"杨同乐","vi":"Được, vậy gọi thêm một món thịt gà, một……"},{"hanzi":"咱们就三个人，别点那么多。","pinyin":"Zánmen jiù sān gè rén, bié diǎn nàme duō.","speaker":"王一雪","vi":"Chúng ta chỉ có ba người thôi, đừng gọi nhiều thế."},{"hanzi":"好，那先来这几个菜。","pinyin":"Hǎo, nà xiān lái zhè jǐ gè cài.","speaker":"杨同乐","vi":"Được, vậy lên trước mấy món này nhé."},{"hanzi":"对了，下周我儿子过生日，你们有时间的话，就来我家做客，我给你们做北京菜。","pinyin":"Duìle, xià zhōu wǒ érzi guò shēngrì, nǐmen yǒu shíjiān dehuà, jiù lái wǒ jiā zuòkè, wǒ gěi nǐmen zuò Běijīng cài.","speaker":"王一雪","vi":"À đúng rồi, tuần sau con trai tôi đón sinh nhật, nếu mọi người có thời gian thì đến nhà tôi chơi nhé, tôi sẽ nấu món Bắc Kinh cho mọi người ăn."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Vương Nhất Tuyết hỏi: \"听说这家饭馆的鱼做得很特别？\" và Dương Đồng Nhạc đáp: \"对，南方菜跟你们北方菜的做法不同。\" (Đúng vậy, món miền Nam có cách làm khác với món miền Bắc của các bạn), nên đáp án đúng là 这家饭馆的鱼是南方菜，做法很特别。","options":["这家饭馆主要做北方菜","这家饭馆的鱼是南方菜，做法很特别","同事常吃南方菜，所以点了很多菜","他们三个人一共点了十几个菜"],"q":"关于这家饭馆和菜，下面哪句话是对的？"},{"answerIdx":1,"explanation":"Ở cuối bài Vương Nhất Tuyết nói: \"下周我儿子过生日，你们有时间的话，就来我家做客，我给你们做北京菜。\" (Tuần sau con trai tôi sinh nhật, nếu mọi người có thời gian thì đến nhà tôi chơi, tôi sẽ làm món Bắc Kinh cho mọi người ăn), nên đáp án đúng là 因为她儿子下周过生日。","options":["因为她想请大家去家里喝茶聊天儿","因为她儿子下周过生日","因为她刚搬了新家，想请大家吃饭","因为杨同乐很想学做北京菜"],"q":"王一雪为什么请同事们下周去她家做客？"}],"scene":"在饭馆，杨同乐请同事吃饭。","sceneVi":"Ở nhà hàng, Dương Đồng Lạc mời đồng nghiệp ăn cơm."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"第一次请新邻居来做客，总是担心有什么没准备好。","pinyin":"Dì-yī cì qǐng xīn línjū lái zuòkè, zǒngshì dānxīn yǒu shénme méi zhǔnbèi hǎo.","speaker":"王一雪","vi":"Lần đầu tiên mời hàng xóm mới sang nhà chơi, lúc nào cũng lo có thứ gì đó chưa chuẩn bị xong."},{"hanzi":"放心吧，我帮你看了，都已经准备好了。","pinyin":"Fàngxīn ba, wǒ bāng nǐ kàn le, dōu yǐjīng zhǔnbèi hǎo le.","speaker":"刘明","vi":"Yên tâm đi, anh đã xem giúp em rồi, mọi thứ đều đã chuẩn bị xong cả rồi."},{"hanzi":"我记得刚才已经把饮料拿出来了，怎么不见了？","pinyin":"Wǒ jìde gāngcái yǐjīng bǎ yǐnliào ná chūlái le, zěnme bú jiàn le?","speaker":"王一雪","vi":"Em nhớ lúc nãy đã lấy đồ uống ra rồi mà, sao lại không thấy đâu nữa?"},{"hanzi":"我把饮料和酒都放进冰箱里了，客人来了再拿出来。","pinyin":"Wǒ bǎ yǐnliào hé jiǔ dōu fàng jìn bīngxiāng lǐ le, kèrén lái le zài ná chūlái.","speaker":"刘明","vi":"Anh bỏ cả đồ uống và rượu vào trong tủ lạnh rồi, khách đến rồi lấy ra."},{"hanzi":"音乐的声音合适吗？","pinyin":"Yīnyuè de shēngyīn héshì ma?","speaker":"王一雪","vi":"Âm lượng của nhạc có vừa không?"},{"hanzi":"你把声音开得太大了，我去关小一点儿。","pinyin":"Nǐ bǎ shēngyīn kāi de tài dà le, wǒ qù guān xiǎo yìdiǎnr.","speaker":"刘明","vi":"Em mở tiếng to quá rồi, anh đi vặn nhỏ lại một chút."},{"hanzi":"好，那我们就等客人来吧。","pinyin":"Hǎo, nà wǒmen jiù děng kèrén lái ba.","speaker":"王一雪","vi":"Được, vậy chúng ta chờ khách đến thôi."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Lưu Minh nói: \"我把饮料和酒都放进冰箱里了，客人来了再拿出来。\" (Anh để cả đồ uống và rượu vào tủ lạnh rồi, khách đến rồi mới lấy ra), nên đáp án đúng là 被刘明放进冰箱里了。","options":["被孩子喝完了","被刘明放进冰箱里了","忘在超市里没有买","还在桌子上，她没看见"],"q":"王一雪刚才拿出来的饮料去哪儿了？"},{"answerIdx":2,"explanation":"Trong bài Lưu Minh nói: \"你把声音开得太大了，我去关小一点儿。\" (Em mở tiếng to quá rồi, anh đi vặn nhỏ lại một chút), nên đáp án đúng là 声音太大了，需要关小一点儿。","options":["声音太小了，听不见","声音正好，很合适","声音太大了，需要关小一点儿","音乐不好听，要换一首"],"q":"刘明觉得音乐的声音怎么样？"}],"scene":"在家里，王一雪和刘明为生日会做准备。","sceneVi":"Ở nhà, Vương Nhất Tuyết và Lưu Minh đang chuẩn bị cho tiệc sinh nhật."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"谢谢你们来参加我儿子的生日晚会，希望大家今晚玩得开心。","pinyin":"Xièxie nǐmen lái cānjiā wǒ érzi de shēngrì wǎnhuì, xīwàng dàjiā jīnwǎn wán de kāixīn.","speaker":"王一雪","vi":"Cảm ơn mọi người đã đến tham gia tiệc sinh nhật con trai tôi, hy vọng tối nay mọi người chơi vui vẻ."},{"hanzi":"小明，生日快乐！我准备了一个小礼物，希望你喜欢！","pinyin":"Xiǎomíng, shēngrì kuàilè! Wǒ zhǔnbèi le yí gè xiǎo lǐwù, xīwàng nǐ xǐhuan!","speaker":"杨同乐","vi":"Tiểu Minh, sinh nhật vui vẻ! Chú chuẩn bị một món quà nhỏ, hy vọng cháu thích!"},{"hanzi":"谢谢您，我可以打开吗？","pinyin":"Xièxie nín, wǒ kěyǐ dǎkāi ma?","speaker":"刘小明","vi":"Cảm ơn chú ạ, cháu có thể mở ra không ạ?"},{"hanzi":"当然可以，你妈妈说你跟姐姐一样，都喜欢画画，对吗？","pinyin":"Dāngrán kěyǐ, nǐ māma shuō nǐ gēn jiějie yíyàng, dōu xǐhuan huàhuà, duì ma?","speaker":"杨同乐","vi":"Tất nhiên là được, mẹ cháu nói cháu cũng giống chị gái, đều thích vẽ tranh, đúng không?"},{"hanzi":"对，我想做一名画家。啊！画板和画笔，这正是我需要的。我太喜欢了。","pinyin":"Duì, wǒ xiǎng zuò yì míng huàjiā. À! Huàbǎn hé huàbǐ, zhè zhèng shì wǒ xūyào de. Wǒ tài xǐhuan le.","speaker":"刘小明","vi":"Vâng, cháu muốn trở thành một họa sĩ. Ôi! Bảng vẽ và bút vẽ, đây đúng là thứ cháu đang cần. Cháu thích quá đi mất."},{"hanzi":"我去把盘子拿过来，咱们一边吃蛋糕，一边聊天儿吧。","pinyin":"Wǒ qù bǎ pánzi ná guòlái, zánmen yìbiān chī dàngāo, yìbiān liáotiānr ba.","speaker":"王一雪","vi":"Tôi đi lấy đĩa lại đây, chúng ta vừa ăn bánh kem vừa trò chuyện nhé."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Lưu Tiểu Minh mở quà ra và nói: \"啊！画板和画笔，这正是我需要的。我太喜欢了。\" (A! Bảng vẽ và bút vẽ, đây đúng là thứ cháu đang cần. Cháu thích lắm), nên đáp án đúng là 画板和画笔。","options":["一个生日蛋糕","画板和画笔","一本画画儿的书","几个漂亮的盘子"],"q":"杨同乐送给刘小明什么生日礼物？"},{"answerIdx":2,"explanation":"Ở cuối bài Vương Nhất Tuyết nói: \"我去把盘子拿过来，咱们一边吃蛋糕，一边聊天儿吧。\" (Tôi đi lấy đĩa lại đây, chúng ta vừa ăn bánh kem vừa trò chuyện nhé), nên đáp án đúng là 一边吃蛋糕，一边聊天儿。","options":["一起看小明画画儿","先喝茶，再打开其他礼物","一边吃蛋糕，一边聊天儿","一边听音乐，一边做游戏"],"q":"小明打开礼物后，王一雪建议大家做什么？"}],"scene":"在家里，王一雪和刘明办生日会。","sceneVi":"Ở nhà, Vương Nhất Tuyết và Lưu Minh tổ chức tiệc sinh nhật."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"我的新邻居是来自英国的夫妻。","pinyin":"Wǒ de xīn línjū shì láizì Yīngguó de fūqī.","speaker":"Đoạn văn","vi":"Hàng xóm mới của tôi là một cặp vợ chồng đến từ nước Anh."},{"hanzi":"上周我去他们家做客了。","pinyin":"Shàng zhōu wǒ qù tāmen jiā zuòkè le.","speaker":"Đoạn văn","vi":"Tuần trước tôi đã đến nhà họ chơi."},{"hanzi":"他们做了很多好吃的，还准备了英国的红茶。","pinyin":"Tāmen zuò le hěn duō hǎochī de, hái zhǔnbèi le Yīngguó de hóngchá.","speaker":"Đoạn văn","vi":"Họ làm rất nhiều món ngon, còn chuẩn bị cả hồng trà Anh nữa."},{"hanzi":"那天我跟他们一边喝红茶，一边聊天儿，直到十二点多才回家。","pinyin":"Nà tiān wǒ gēn tāmen yìbiān hē hóngchá, yìbiān liáotiānr, zhídào shí'èr diǎn duō cái huí jiā.","speaker":"Đoạn văn","vi":"Hôm đó tôi vừa uống hồng trà vừa trò chuyện với họ, mãi đến hơn mười hai giờ mới về nhà."},{"hanzi":"他们年轻的时候喜欢旅游，他家有一张世界地图，上面每一个红点都是他们去过的地方。","pinyin":"Tāmen niánqīng de shíhou xǐhuan lǚyóu, tā jiā yǒu yì zhāng shìjiè dìtú, shàngmian měi yí gè hóngdiǎn dōu shì tāmen qù guo de dìfang.","speaker":"Đoạn văn","vi":"Hồi trẻ họ rất thích đi du lịch, nhà họ có một tấm bản đồ thế giới, mỗi chấm đỏ trên đó đều là nơi họ từng đi qua."},{"hanzi":"后来，他们感到东方的文化很特别，就开始学习中文。","pinyin":"Hòulái, tāmen gǎndào dōngfāng de wénhuà hěn tèbié, jiù kāishǐ xuéxí Zhōngwén.","speaker":"Đoạn văn","vi":"Sau này, họ cảm thấy văn hóa phương Đông rất đặc biệt nên bắt đầu học tiếng Trung."},{"hanzi":"今天是小明的生日，我请他们到我家玩，来看看中国人的家，也尝尝中国菜。","pinyin":"Jīntiān shì Xiǎomíng de shēngrì, wǒ qǐng tāmen dào wǒ jiā wán, lái kànkan Zhōngguórén de jiā, yě chángchang Zhōngguó cài.","speaker":"Đoạn văn","vi":"Hôm nay là sinh nhật của Tiểu Minh, tôi mời họ đến nhà tôi chơi, đến xem nhà của người Trung Quốc và cũng nếm thử món ăn Trung Quốc."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu: \"他家有一张世界地图，上面每一个红点都是他们去过的地方。\" (Nhà họ có một tấm bản đồ thế giới, mỗi chấm đỏ trên đó đều là nơi họ đã từng đến), nên đáp án đúng là 他们以前去过的地方。","options":["他们想去还没去的地方","他们以前去过的地方","他们住过超过一年的城市","英国和中国有名的城市"],"q":"新邻居家世界地图上的每一个红点表示什么？"},{"answerIdx":1,"explanation":"Trong bài có câu: \"后来，他们感到东方的文化很特别，就开始学习中文。\" (Sau này, họ cảm thấy văn hóa phương Đông rất đặc biệt nên bắt đầu học tiếng Trung), nên đáp án đúng là 因为他们觉得东方文化很特别。","options":["因为他们要来中国做生意","因为他们觉得东方文化很特别","因为王一雪请他们教自己英文","因为他们想看懂世界地图"],"q":"那对英国夫妻为什么开始学习中文？"}],"scene":"在家里，王一雪在写日记。","sceneVi":"Ở nhà, Vương Nhất Tuyết đang viết nhật ký."}],"hsk3-14":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"我借的这本词典最好今天还，但是我没时间去。","pinyin":"Wǒ jiè de zhè běn cídiǎn zuìhǎo jīntiān huán, dànshì wǒ méi shíjiān qù.","speaker":"李文","vi":"Cuốn từ điển này tôi mượn tốt nhất hôm nay phải trả, nhưng tôi không có thời gian đi."},{"hanzi":"下午我只有两节课，可以帮你去图书馆还书。","pinyin":"Xiàwǔ wǒ zhǐ yǒu liǎng jié kè, kěyǐ bāng nǐ qù túshūguǎn huán shū.","speaker":"白家月","vi":"Buổi chiều mình chỉ có hai tiết học, có thể giúp cậu đến thư viện trả sách."},{"hanzi":"那太谢谢了。你能再帮我借本书吗？","pinyin":"Nà tài xièxie le. Nǐ néng zài bāng wǒ jiè běn shū ma?","speaker":"李文","vi":"Vậy thì cảm ơn nhiều quá. Cậu có thể mượn giúp mình thêm một cuốn sách nữa không?"},{"hanzi":"行，你告诉我书名。","pinyin":"Xíng, nǐ gàosu wǒ shūmíng.","speaker":"白家月","vi":"Được, cậu nói cho mình biết tên sách đi."},{"hanzi":"我把名字写在纸上吧。我去了好几次图书馆，这本书都被别人借走了。","pinyin":"Wǒ bǎ míngzi xiě zài zhǐ shàng ba. Wǒ qù le hǎo jǐ cì túshūguǎn, zhè běn shū dōu bèi biérén jiè zǒu le.","speaker":"李文","vi":"Để mình viết tên lên giấy nhé. Mình đến thư viện mấy lần rồi, lần nào cuốn sách này cũng bị người khác mượn mất rồi."},{"hanzi":"《名人的故事》？我有这本书。明天我借给你吧。","pinyin":"《Míngrén de Gùshi》? Wǒ yǒu zhè běn shū. Míngtiān wǒ jiè gěi nǐ ba.","speaker":"白家月","vi":"\"Câu chuyện về những người nổi tiếng\" à? Mình có cuốn sách này đấy. Ngày mai mình cho cậu mượn nhé."}],"readingQuiz":[{"answerIdx":0,"explanation":"Ở đầu bài Lý Văn nói: \"我借的这本词典最好今天还，但是我没时间去。\" và Bạch Gia Nguyệt nhận lời: \"下午我只有两节课，可以帮你去图书馆还书。\" (Buổi chiều mình chỉ có hai tiết, có thể giúp cậu đến thư viện trả sách), nên đáp án đúng là 去图书馆帮他还一本词典。","options":["去图书馆帮他还一本词典","去书店帮他买一本《名人的故事》","帮他写下书的名字","借给他一本中文词典"],"q":"李文一开始请白家月帮什么忙？"},{"answerIdx":2,"explanation":"Ở cuối bài Bạch Gia Nguyệt nói: \"《名人的故事》？我有这本书。明天我借给你吧。\" (\"Câu chuyện danh nhân\" à? Mình có cuốn sách này đấy. Ngày mai mình cho cậu mượn nhé), nên đáp án đúng là 她自己有这本书，明天借给他。","options":["她今天下午去图书馆帮他借","这本书太难借了，让他再等等","她自己有这本书，明天借给他","她也没看过这本书，也想借来看"],"q":"知道李文想借《名人的故事》以后，白家月怎么说？"}],"scene":"在校园餐厅，李文和白家月在聊天儿。","sceneVi":"Ở nhà ăn trong khuôn viên trường, Lý Văn và Bạch Gia Nguyệt đang trò chuyện."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"今天下课早，你一会儿做什么？","pinyin":"Jīntiān xiàkè zǎo, nǐ yíhuìr zuò shénme?","speaker":"安妮","vi":"Hôm nay tan học sớm, lát nữa cậu làm gì thế?"},{"hanzi":"我今天忙得很，要先去图书馆借书，然后去游泳。","pinyin":"Wǒ jīntiān máng de hěn, yào xiān qù túshūguǎn jiè shū, ránhòu qù yóuyǒng.","speaker":"白家月","vi":"Hôm nay mình bận lắm, phải đến thư viện mượn sách trước, sau đó đi bơi."},{"hanzi":"咱们一起走吧，我想去图书馆看看中文报纸。","pinyin":"Zánmen yìqǐ zǒu ba, wǒ xiǎng qù túshūguǎn kànkan Zhōngwén bàozhǐ.","speaker":"安妮","vi":"Chúng mình đi cùng đi, mình muốn đến thư viện đọc báo tiếng Trung."},{"hanzi":"等等，我的校园卡不见了，没有卡进不去图书馆。","pinyin":"Děngdeng, wǒ de xiàoyuánkǎ bú jiàn le, méiyǒu kǎ jìn bu qù túshūguǎn.","speaker":"白家月","vi":"Đợi đã, thẻ sinh viên của mình mất đâu rồi, không có thẻ thì không vào được thư viện."},{"hanzi":"你想想上一次用是什么时候？","pinyin":"Nǐ xiǎngxiang shàng yí cì yòng shì shénme shíhou?","speaker":"安妮","vi":"Cậu thử nghĩ xem lần trước dùng là lúc nào?"},{"hanzi":"我忘记了，可能被我放在家里了。","pinyin":"Wǒ wàngjì le, kěnéng bèi wǒ fàng zài jiā lǐ le.","speaker":"白家月","vi":"Mình quên mất rồi, có thể bị mình để quên ở nhà rồi."},{"hanzi":"进不去图书馆也没关系，上网看看有没有电子书。","pinyin":"Jìn bu qù túshūguǎn yě méi guānxi, shàngwǎng kànkan yǒu méiyǒu diànzǐshū.","speaker":"安妮","vi":"Không vào được thư viện cũng không sao, lên mạng xem thử có sách điện tử không."},{"hanzi":"不行，我必须去，我还得帮李文还书呢。","pinyin":"Bù xíng, wǒ bìxū qù, wǒ hái děi bāng Lǐ Wén huán shū ne.","speaker":"白家月","vi":"Không được, mình nhất định phải đi, mình còn phải trả sách giúp Lý Văn nữa."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Bạch Gia Nguyệt nói: \"等等，我的校园卡不见了，没有卡进不去图书馆。\" (Khoan đã, thẻ sinh viên của mình mất rồi, không có thẻ thì không vào được thư viện), nên đáp án đúng là 她的校园卡不见了，进不去图书馆。","options":["她把李文的书忘在家里了","她的校园卡不见了，进不去图书馆","图书馆今天关门，不能借书","游泳馆快关门了，她没有时间"],"q":"白家月准备跟安妮一起去图书馆时，发现了什么问题？"},{"answerIdx":2,"explanation":"Ở cuối bài Bạch Gia Nguyệt nói: \"不行，我必须去，我还得帮李文还书呢。\" (Không được, mình nhất định phải đi, mình còn phải trả sách giúp Lý Văn nữa), nên đáp án đúng là 因为她还要帮李文还书。","options":["因为她一定要借到中文报纸","因为她必须去那里找她的校园卡","因为她还要帮李文还书","因为她不喜欢看网上的电子书"],"q":"白家月为什么说她必须去图书馆？"}],"scene":"在校园里，白家月和安妮在聊天儿。","sceneVi":"Trong khuôn viên trường, Bạch Gia Nguyệt và Anne đang trò chuyện."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"下周学校有晚会，你知道吗？","pinyin":"Xià zhōu xuéxiào yǒu wǎnhuì, nǐ zhīdào ma?","speaker":"李文","vi":"Tuần sau trường có buổi dạ hội, cậu biết không?"},{"hanzi":"知道，我和几个女生要表演一个节目。你也参加吗？","pinyin":"Zhīdào, wǒ hé jǐ gè nǚshēng yào biǎoyǎn yí gè jiémù. Nǐ yě cānjiā ma?","speaker":"白家月","vi":"Biết chứ, mình và mấy bạn nữ sẽ biểu diễn một tiết mục. Cậu cũng tham gia à?"},{"hanzi":"我想唱中文歌，但是还没找到人一起表演，不知道怎么办。","pinyin":"Wǒ xiǎng chàng Zhōngwén gē, dànshì hái méi zhǎodào rén yìqǐ biǎoyǎn, bù zhīdào zěnme bàn.","speaker":"李文","vi":"Mình muốn hát bài hát tiếng Trung, nhưng vẫn chưa tìm được người biểu diễn cùng, không biết phải làm sao nữa."},{"hanzi":"找不到人，你就一个人唱吧。","pinyin":"Zhǎo bu dào rén, nǐ jiù yí gè rén chàng ba.","speaker":"白家月","vi":"Không tìm được người thì cậu hát một mình đi."},{"hanzi":"一想到要在校长、老师和那么多同学面前表演，我就有些紧张。","pinyin":"Yì xiǎngdào yào zài xiàozhǎng, lǎoshī hé nàme duō tóngxué miànqián biǎoyǎn, wǒ jiù yǒuxiē jǐnzhāng.","speaker":"李文","vi":"Hễ nghĩ đến việc phải biểu diễn trước mặt hiệu trưởng, thầy cô và nhiều bạn học như thế, mình lại thấy hơi hồi hộp."},{"hanzi":"紧张什么啊，我们都喜欢听你唱歌，你要相信自己。","pinyin":"Jǐnzhāng shénme a, wǒmen dōu xǐhuan tīng nǐ chànggē, nǐ yào xiāngxìn zìjǐ.","speaker":"白家月","vi":"Hồi hộp cái gì chứ, bọn mình đều thích nghe cậu hát, cậu phải tin vào bản thân mình chứ."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài Lý Văn nói: \"一想到要在校长、老师和那么多同学面前表演，我就有些紧张。\" (Hễ nghĩ đến việc phải biểu diễn trước hiệu trưởng, thầy cô và nhiều bạn học như vậy là mình hơi căng thẳng), nên đáp án đúng là 他一个人表演，在这么多人面前会有些紧张。","options":["他不知道怎么参加晚会","他还没学会唱那首中文歌","他一个人表演，在这么多人面前会有些紧张","校长和老师不喜欢听他唱中文歌"],"q":"关于下周学校的晚会，李文在担心什么？"},{"answerIdx":1,"explanation":"Ở cuối bài Bạch Gia Nguyệt động viên: \"紧张什么啊，我们都喜欢听你唱歌，你要相信自己。\" (Căng thẳng gì chứ, bọn mình đều thích nghe cậu hát, cậu phải tin vào bản thân mình), nên đáp án đúng là 她说大家都喜欢听他唱歌，让他相信自己。","options":["她说可以陪李文一起唱中文歌","她说大家都喜欢听他唱歌，让他相信自己","她建议李文不要参加这次晚会了","她说校长和老师那天不会来看晚会"],"q":"白家月是怎么鼓励李文的？"}],"scene":"在校园餐厅，李文和白家月边吃边聊。","sceneVi":"Ở nhà ăn trong khuôn viên trường, Lý Văn và Bạch Gia Nguyệt vừa ăn vừa trò chuyện."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"昨天是我们学校的新年晚会，每个班级的同学都表演节目了。","pinyin":"Zuótiān shì wǒmen xuéxiào de xīnnián wǎnhuì, měi gè bānjí de tóngxué dōu biǎoyǎn jiémù le.","speaker":"Đoạn văn","vi":"Hôm qua là buổi dạ hội năm mới của trường chúng tôi, các bạn học ở mỗi lớp đều đã biểu diễn tiết mục."},{"hanzi":"晚会是八点开始的，差不多十二点才结束。","pinyin":"Wǎnhuì shì bā diǎn kāishǐ de, chàbuduō shí'èr diǎn cái jiéshù.","speaker":"Đoạn văn","vi":"Buổi dạ hội bắt đầu lúc tám giờ, gần mười hai giờ mới kết thúc."},{"hanzi":"我一个晚上跟大家一起又唱又跳，开心极了，也累坏了。","pinyin":"Wǒ yí gè wǎnshang gēn dàjiā yìqǐ yòu chàng yòu tiào, kāixīn jíle, yě lèi huài le.","speaker":"Đoạn văn","vi":"Cả buổi tối tôi cùng mọi người vừa hát vừa nhảy, vui cực kỳ, mà cũng mệt lử luôn."},{"hanzi":"我最喜欢的节目是留学生们跳舞，最后老师和校长也被叫起来一块儿跳，特别有意思。","pinyin":"Wǒ zuì xǐhuan de jiémù shì liúxuéshēngmen tiàowǔ, zuìhòu lǎoshī hé xiàozhǎng yě bèi jiào qǐlái yíkuàir tiào, tèbié yǒu yìsi.","speaker":"Đoạn văn","vi":"Tiết mục tôi thích nhất là các lưu học sinh múa, cuối cùng thầy cô và hiệu trưởng cũng được gọi lên nhảy cùng nhau, vô cùng thú vị."},{"hanzi":"过几天学校的网站上会有晚会的视频，我打算再看一遍。","pinyin":"Guò jǐ tiān xuéxiào de wǎngzhàn shàng huì yǒu wǎnhuì de shìpín, wǒ dǎsuàn zài kàn yí biàn.","speaker":"Đoạn văn","vi":"Vài ngày nữa trên trang web của trường sẽ có video của buổi dạ hội, tôi dự định sẽ xem lại một lần nữa."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu: \"晚会是八点开始的，差不多十二点才结束。\" (Buổi dạ hội bắt đầu lúc 8 giờ, gần 12 giờ mới kết thúc), nên đáp án đúng là 八点开始，差不多十二点结束。","options":["七点开始，十一点结束","八点开始，差不多十二点结束","八点半开始，十点半结束","下午开始，晚上八点结束"],"q":"学校的新年晚会是什么时候开始、什么时候结束的？"},{"answerIdx":2,"explanation":"Trong bài Bạch Gia Nguyệt viết: \"我最喜欢的节目是留学生们跳舞，最后老师和校长也被叫起来一块儿跳，特别有意思。\" (Tiết mục mình thích nhất là các du học sinh nhảy múa, cuối cùng thầy cô và hiệu trưởng cũng được gọi lên nhảy cùng, rất thú vị), nên đáp án đúng là 留学生们跳舞。","options":["她和几个女生一起表演的节目","李文一个人唱的中文歌","留学生们跳舞","每个班级的合唱节目"],"q":"白家月最喜欢晚会上的哪个节目？"}],"scene":"在家里，白家月在写日记。","sceneVi":"Ở nhà, Bạch Gia Nguyệt đang viết nhật ký."}],"hsk3-15":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"您搬到蓝天小区一段时间了，觉得怎么样？","pinyin":"Nín bān dào Lántiān Xiǎoqū yí duàn shíjiān le, juéde zěnmeyàng?","speaker":"杨同乐","vi":"Chị chuyển đến khu dân cư Lam Thiên được một thời gian rồi, cảm thấy thế nào?"},{"hanzi":"小区环境挺好的，附近买东西也很方便，过马路就是超市。","pinyin":"Xiǎoqū huánjìng tǐng hǎo de, fùjìn mǎi dōngxi yě hěn fāngbiàn, guò mǎlù jiù shì chāoshì.","speaker":"王一雪","vi":"Môi trường khu dân cư khá tốt, gần đây mua đồ cũng rất tiện, qua đường là tới siêu thị."},{"hanzi":"平时孩子们在哪儿玩？","pinyin":"Píngshí háizimen zài nǎr wán?","speaker":"杨同乐","vi":"Bình thường bọn trẻ chơi ở đâu?"},{"hanzi":"小区里有很多树，孩子们放学后就在树下做游戏。你想买房子吗？","pinyin":"Xiǎoqū lǐ yǒu hěn duō shù, háizimen fàngxué hòu jiù zài shù xià zuò yóuxì. Nǐ xiǎng mǎi fángzi ma?","speaker":"王一雪","vi":"Trong khu dân cư có rất nhiều cây, bọn trẻ sau khi tan học liền chơi trò chơi dưới gốc cây. Cậu muốn mua nhà à?"},{"hanzi":"是。我想买一个大房子，让我爸妈过来跟我一起住。","pinyin":"Shì. Wǒ xiǎng mǎi yí gè dà fángzi, ràng wǒ bàmā guòlái gēn wǒ yìqǐ zhù.","speaker":"杨同乐","vi":"Vâng. Tôi muốn mua một căn nhà lớn để bố mẹ tôi qua ở cùng tôi."},{"hanzi":"蓝天小区的老人挺多的，这几年小区根据他们的需要，有了很多变化。","pinyin":"Lántiān Xiǎoqū de lǎorén tǐng duō de, zhè jǐ nián xiǎoqū gēnjù tāmen de xūyào, yǒu le hěn duō biànhuà.","speaker":"王一雪","vi":"Người cao tuổi ở khu dân cư Lam Thiên khá đông, mấy năm nay khu dân cư dựa theo nhu cầu của họ đã có rất nhiều thay đổi."},{"hanzi":"真不错！过几天我去蓝天小区看看。","pinyin":"Zhēn búcuò! Guò jǐ tiān wǒ qù Lántiān Xiǎoqū kànkan.","speaker":"杨同乐","vi":"Thật tuyệt! Mấy hôm nữa tôi sẽ đến khu dân cư Lam Thiên xem thử."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Vương Nhất Tuyết nói \"小区环境挺好的，附近买东西也很方便，过马路就是超市。\" (Môi trường khu dân cư khá tốt, gần đó mua đồ cũng rất tiện, qua đường là tới siêu thị.), nên đáp án đúng là môi trường tốt và mua sắm thuận tiện.","options":["买东西不太方便，超市很远","环境不错，买东西很方便","小区里没有树，也没有老人","这几年小区一点儿变化也没有"],"q":"关于蓝天小区，王一雪觉得怎么样？"},{"answerIdx":2,"explanation":"Trong bài có câu \"我想买一个大房子，让我爸妈过来跟我一起住。\" (Tôi muốn mua một căn nhà lớn để bố mẹ tôi qua sống cùng tôi.), nên đáp án đúng là vì muốn đón bố mẹ đến ở cùng.","options":["因为现在的房子离公司太远","因为想让孩子们在树下做游戏","因为想让爸爸妈妈过来一起住","因为王一雪劝他马上买房子"],"q":"杨同乐为什么想买一个大房子？"}],"scene":"在办公室里，王一雪和杨同乐在聊天儿。","sceneVi":"Ở trong văn phòng, Vương Nhất Tuyết và Dương Đồng Lạc đang trò chuyện."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"假期我想去南京旅游，但是我不太了解那里。","pinyin":"Jiàqī wǒ xiǎng qù Nánjīng lǚyóu, dànshì wǒ bú tài liǎojiě nàli.","speaker":"王一雪","vi":"Kỳ nghỉ tôi muốn đi Nam Kinh du lịch, nhưng tôi không hiểu rõ nơi đó lắm."},{"hanzi":"我虽然不是南京人，可是我是在南京上的大学，可以说是半个南京人。","pinyin":"Wǒ suīrán bú shì Nánjīng rén, kěshì wǒ shì zài Nánjīng shàng de dàxué, kěyǐ shuō shì bàn gè Nánjīng rén.","speaker":"杨同乐","vi":"Tôi tuy không phải người Nam Kinh, nhưng tôi học đại học ở Nam Kinh, có thể nói là nửa người Nam Kinh rồi."},{"hanzi":"太好了！你快给我介绍一下南京吧。","pinyin":"Tài hǎo le! Nǐ kuài gěi wǒ jièshào yíxià Nánjīng ba.","speaker":"王一雪","vi":"Tuyệt quá! Cậu mau giới thiệu cho tôi một chút về Nam Kinh đi."},{"hanzi":"南京有两千年以上的历史，有老城、老街，还有很多有名的景点，每年去旅游的游客特别多。","pinyin":"Nánjīng yǒu liǎngqiān nián yǐshàng de lìshǐ, yǒu lǎochéng, lǎojiē, hái yǒu hěn duō yǒumíng de jǐngdiǎn, měinián qù lǚyóu de yóukè tèbié duō.","speaker":"杨同乐","vi":"Nam Kinh có lịch sử hơn hai nghìn năm, có thành cổ, phố cổ, còn có rất nhiều danh lam thắng cảnh nổi tiếng, mỗi năm du khách đến du lịch đặc biệt đông."},{"hanzi":"除了这些以外，你再告诉我一些外地人不知道的地方。","pinyin":"Chúle zhèxiē yǐwài, nǐ zài gàosu wǒ yìxiē wàidì rén bù zhīdào de dìfang.","speaker":"王一雪","vi":"Ngoài những chỗ này ra, cậu kể thêm cho tôi một số nơi mà người từ nơi khác đến không biết đi."},{"hanzi":"那太多了，我得一点儿一点儿给您讲。","pinyin":"Nà tài duō le, wǒ děi yìdiǎnr yìdiǎnr gěi nín jiǎng.","speaker":"杨同乐","vi":"Nhiều lắm luôn đấy, tôi phải kể từ từ cho chị nghe."},{"hanzi":"行，下班后我请你吃晚饭，咱们边吃边聊。","pinyin":"Xíng, xiàbān hòu wǒ qǐng nǐ chī wǎnfàn, zánmen biān chī biān liáo.","speaker":"王一雪","vi":"Được, sau giờ làm tôi mời cậu ăn bữa tối, chúng ta vừa ăn vừa trò chuyện."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài, Dương Đồng Lạc nói \"我虽然不是南京人，可是我是在南京上的大学，可以说是半个南京人。\" (Tuy tôi không phải người Nam Kinh, nhưng tôi học đại học ở Nam Kinh, có thể coi là nửa người Nam Kinh.), nên đáp án đúng là vì anh ấy đã học đại học ở Nam Kinh.","options":["因为他在南京上了大学","因为他的爸爸妈妈是南京人","因为他每年都去南京旅游","因为他在南京工作了很多年"],"q":"杨同乐为什么说自己是“半个南京人”？"},{"answerIdx":3,"explanation":"Ở cuối đoạn hội thoại, Vương Nhất Tuyết nói \"行，下班后我请你吃晚饭，咱们边吃边聊。\" (Được, sau khi tan làm tôi mời cậu ăn tối, chúng ta vừa ăn vừa nói chuyện.), nên đáp án đúng là mời Dương Đồng Lạc ăn tối và vừa ăn vừa trò chuyện.","options":["自己回家查南京的景点","马上坐火车去南京旅游","跟杨同乐一起去参观老街","请杨同乐吃晚饭，边吃边聊"],"q":"下班以后，王一雪打算做什么？"}],"scene":"在办公室里，王一雪和杨同乐在聊天儿。","sceneVi":"Ở trong văn phòng, Vương Nhất Tuyết và Dương Đồng Lạc đang trò chuyện."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"小明，中国有一条大河，它的名字跟颜色有关系，你知道是什么河吗？","pinyin":"Xiǎomíng, Zhōngguó yǒu yì tiáo dàhé, tā de míngzi gēn yánsè yǒu guānxi, nǐ zhīdào shì shénme hé ma?","speaker":"王一雪","vi":"Tiểu Minh, Trung Quốc có một con sông lớn, tên của nó có liên quan đến màu sắc, con có biết là sông gì không?"},{"hanzi":"我知道，是黄河！","pinyin":"Wǒ zhīdào, shì Huáng Hé!","speaker":"刘小明","vi":"Con biết ạ, là sông Hoàng Hà!"},{"hanzi":"你说对了。我再问问你，你知道它为什么叫黄河吗？","pinyin":"Nǐ shuō duì le. Wǒ zài wènwen nǐ, nǐ zhīdào tā wèishénme jiào Huáng Hé ma?","speaker":"王一雪","vi":"Con nói đúng rồi. Mẹ hỏi con thêm nhé, con có biết tại sao nó gọi là sông Hoàng Hà không?"},{"hanzi":"因为河水看起来是黄色的，所以叫这个名字。黄河是中国最长的河吗？","pinyin":"Yīnwèi héshuǐ kàn qǐlái shì huángsè de, suǒyǐ jiào zhège míngzi. Huáng Hé shì Zhōngguó zuì cháng de hé ma?","speaker":"刘小明","vi":"Bởi vì nước sông trông có màu vàng, nên gọi bằng tên này ạ. Sông Hoàng Hà có phải là con sông dài nhất Trung Quốc không ạ?"},{"hanzi":"不是。黄河虽然不是最长的河，可是在历史上很重要。","pinyin":"Bú shì. Huáng Hé suīrán bú shì zuì cháng de hé, kěshì zài lìshǐ shàng hěn zhòngyào.","speaker":"王一雪","vi":"Không phải. Sông Hoàng Hà tuy không phải con sông dài nhất, nhưng trong lịch sử lại rất quan trọng."},{"hanzi":"这个我知道。很久以前，很多中国人都住在黄河边上。","pinyin":"Zhège wǒ zhīdào. Hěn jiǔ yǐqián, hěn duō Zhōngguórén dōu zhù zài Huáng Hé biānshang.","speaker":"刘小明","vi":"Điều này con biết ạ. Rất lâu trước đây, rất nhiều người Trung Quốc đều sống ở ven sông Hoàng Hà."},{"hanzi":"对。在我们中国人看来，黄河像妈妈一样，养了我们几千年。","pinyin":"Duì. Zài wǒmen Zhōngguórén kànlái, Huáng Hé xiàng māma yíyàng, yǎng le wǒmen jǐ qiān nián.","speaker":"王一雪","vi":"Đúng vậy. Trong mắt người Trung Quốc chúng ta, sông Hoàng Hà giống như người mẹ vậy, đã nuôi dưỡng chúng ta hàng nghìn năm."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Lưu Tiểu Minh trả lời \"因为河水看起来是黄色的，所以叫这个名字。\" (Vì nước sông trông có màu vàng nên gọi bằng cái tên này.), nên đáp án đúng là vì nước sông trông có màu vàng.","options":["因为它是中国最长的河","因为它的河水看起来是黄色的","因为河边种着很多黄色的花","因为中国人像妈妈一样喜欢它"],"q":"在刘小明看来，黄河为什么叫“黄河”？"},{"answerIdx":2,"explanation":"Trong bài, Vương Nhất Tuyết nói \"黄河虽然不是最长的河，可是在历史上很重要。\" (Hoàng Hà tuy không phải con sông dài nhất, nhưng trong lịch sử rất quan trọng.), nên đáp án đúng là sông Hoàng Hà rất quan trọng trong lịch sử.","options":["它是中国最长的河","很久以前没有人住在河边","它在历史上非常重要","它的名字跟颜色没有关系"],"q":"根据王一雪的话，关于黄河哪句话是对的？"}],"scene":"在家里，王一雪和刘小明在聊天儿。","sceneVi":"Ở nhà, Vương Nhất Tuyết và Lưu Tiểu Minh đang trò chuyện."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"我小时候住在北京的西北边，有一条非常有名的河经过那里。","pinyin":"Wǒ xiǎoshíhou zhù zài Běijīng de xīběibiān, yǒu yì tiáo fēicháng yǒumíng de hé jīngguò nàli.","speaker":"Đoạn văn","vi":"Hồi nhỏ tôi sống ở phía tây bắc Bắc Kinh, có một con sông rất nổi tiếng chảy qua nơi đó."},{"hanzi":"我家就住在河边。","pinyin":"Wǒ jiā jiù zhù zài hébiān.","speaker":"Đoạn văn","vi":"Nhà tôi sống ngay bên bờ sông."},{"hanzi":"那里有高高的大树和绿绿的草地。","pinyin":"Nàli yǒu gāogāo de dàshù hé lǜlǜ de cǎodì.","speaker":"Đoạn văn","vi":"Ở đó có những cây to cao vút và bãi cỏ xanh mướt."},{"hanzi":"春天，河边的花都开了，看起来特别漂亮。","pinyin":"Chūntiān, hébiān de huā dōu kāi le, kàn qǐlái tèbié piàoliang.","speaker":"Đoạn văn","vi":"Mùa xuân, hoa bên bờ sông đều nở rộ, trông đặc biệt xinh đẹp."},{"hanzi":"还记得小时候，一到夏天我就去河里游泳。","pinyin":"Hái jìde xiǎoshíhou, yí dào xiàtiān wǒ jiù qù hé lǐ yóuyǒng.","speaker":"Đoạn văn","vi":"Còn nhớ hồi nhỏ, cứ đến mùa hè là tôi lại xuống sông bơi lội."},{"hanzi":"长大以后，遇到什么不开心的事情，我就去河边的树下坐着，听听鸟叫，看看河水，跟遇见的朋友聊聊天儿，难过的事情不一会儿就忘了。","pinyin":"Zhǎngdà yǐhòu, yùdào shénme bù kāixīn de shìqing, wǒ jiù qù hébiān de shù xià zuòzhe, tīngting niǎo jiào, kànkan héshuǐ, gēn yùjiàn de péngyou liáoliaotiānr, nánguò de shìqing bùyìhuìr jiù wàng le.","speaker":"Đoạn văn","vi":"Sau khi lớn lên, hễ gặp chuyện gì không vui, tôi liền ra ngồi dưới gốc cây bên bờ sông, nghe tiếng chim hót, ngắm nhìn nước sông, trò chuyện với những người bạn gặp gỡ, chuyện buồn chẳng mấy chốc đã quên hết."},{"hanzi":"那是我最喜欢的地方。","pinyin":"Nà shì wǒ zuì xǐhuan de dìfang.","speaker":"Đoạn văn","vi":"Đó là nơi tôi thích nhất."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài nhật ký viết \"我小时候住在北京的西北边，有一条非常有名的河经过那里。我家就住在河边。\" (Hồi nhỏ tôi sống ở phía tây bắc Bắc Kinh, có một con sông rất nổi tiếng chảy qua đó. Nhà tôi sống ngay bên bờ sông.), nên đáp án đúng là bên một con sông nổi tiếng ở phía tây bắc Bắc Kinh.","options":["北京西北边一条有名的河边","南京老街旁边的小区里","动物园附近的高楼里","北京南边草地上的房子里"],"q":"王一雪小时候住在哪里？"},{"answerIdx":3,"explanation":"Trong bài có câu \"长大以后，遇到什么不开心的事情，我就去河边的树下坐着，听听鸟叫，看看河水，跟遇见的朋友聊聊天儿...\" (Sau khi lớn lên, hễ gặp chuyện gì không vui, tôi lại ra dưới tán cây bên bờ sông ngồi, nghe tiếng chim hót, ngắm nước sông, trò chuyện với bạn bè tình cờ gặp...), nên đáp án đúng là ra ngồi dưới tán cây bên bờ sông nghe chim hót và ngắm nước sông.","options":["去河里游泳","去超市买喜欢的东西","在家写日记或者睡觉","去河边的树下坐着听鸟叫、看河水"],"q":"长大以后，遇到不开心的事情时，王一雪常做什么？"}],"scene":"在家里，王一雪在写日记。","sceneVi":"Ở nhà, Vương Nhất Tuyết đang viết nhật ký."}],"hsk3-16":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"这只小猫你们养了多久了？","pinyin":"Zhè zhī xiǎomāo nǐmen yǎng le duōjiǔ le?","speaker":"刘小雪","vi":"Chú mèo con này anh chị nuôi được bao lâu rồi ạ?"},{"hanzi":"已经一年多了。第一天看见它的时候，它又脏又小。","pinyin":"Yǐjīng yì nián duō le. Dì-yī tiān kànjiàn tā de shíhou, tā yòu zāng yòu xiǎo.","speaker":"服务员","vi":"Đã hơn một năm rồi. Ngày đầu tiên nhìn thấy nó, nó vừa bẩn vừa nhỏ."},{"hanzi":"现在它变得又干净又漂亮了。","pinyin":"Xiànzài tā biàn de yòu gānjìng yòu piàoliang le.","speaker":"刘小雪","vi":"Bây giờ nó trở nên vừa sạch sẽ vừa xinh đẹp rồi."},{"hanzi":"是啊。它还特别可爱，一会儿在你脚边睡觉，一会儿在你身上爬。","pinyin":"Shì a. Tā hái tèbié kě'ài, yíhuìr zài nǐ jiǎobiān shuìjiào, yíhuìr zài nǐ shēnshang pá.","speaker":"服务员","vi":"Đúng vậy. Nó còn đặc biệt đáng yêu nữa, lúc thì ngủ bên cạnh chân em, lúc thì trèo lên người em."},{"hanzi":"你们把它照顾得真好。","pinyin":"Nǐmen bǎ tā zhàogù de zhēn hǎo.","speaker":"刘小雪","vi":"Anh chị chăm sóc nó thật tốt."},{"hanzi":"它就好像我们的孩子，我们照顾它，它也认得我们了。","pinyin":"Tā jiù hǎoxiàng wǒmen de háizi, wǒmen zhàogù tā, tā yě rènde wǒmen le.","speaker":"服务员","vi":"Nó cứ như con của chúng tôi vậy, chúng tôi chăm sóc nó, nó cũng nhận ra chúng tôi rồi."},{"hanzi":"妈妈，我们家也养一只小猫吧。","pinyin":"Māma, wǒmen jiā yě yǎng yì zhī xiǎomāo ba.","speaker":"刘小雪","vi":"Mẹ ơi, nhà mình cũng nuôi một con mèo con đi ạ."},{"hanzi":"咱们没时间照顾，还是别养了，我周末带你们去北京动物园看动物吧。","pinyin":"Zánmen méi shíjiān zhàogù, háishi bié yǎng le, wǒ zhōumò dài nǐmen qù Běijīng Dòngwùyuán kàn dòngwù ba.","speaker":"王一雪","vi":"Nhà mình không có thời gian chăm sóc, thôi đừng nuôi nữa, cuối tuần mẹ đưa các con đi Vườn thú Bắc Kinh xem động vật nhé."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, nhân viên cửa hàng nói \"已经一年多了。第一天看见它的时候，它又脏又小。\" (Đã hơn một năm rồi. Ngày đầu tiên nhìn thấy nó, nó vừa bẩn vừa nhỏ.), nên đáp án đúng là ngày đầu tiên nhìn thấy nó, nó vừa bẩn vừa nhỏ.","options":["店员才养了它一个星期","第一天看见它时，它又脏又小","它现在还是很脏，不太漂亮","它不认得照顾它的店员"],"q":"关于店里的这只小猫，下面哪句话是对的？"},{"answerIdx":2,"explanation":"Trong bài, Vương Nhất Tuyết nói \"咱们没时间照顾，还是别养了\" (Nhà mình không có thời gian chăm sóc, thôi đừng nuôi nữa), nên đáp án đúng là vì cả nhà không có thời gian chăm sóc nó.","options":["因为小猫不可爱","因为她不喜欢小动物","因为家里没有时间照顾它","因为动物园里已经有很多猫了"],"q":"王一雪为什么不想在家里养小猫？"}],"scene":"在一家宠物领养店，王一雪和孩子们在看动物。","sceneVi":"Tại một cửa hàng nhận nuôi thú cưng, Vương Nhất Tuyết và các con đang ngắm nhìn các con vật."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"妈妈，大熊猫这个名字很奇怪，它们跟猫有什么关系？","pinyin":"Māma, dàxióngmāo zhège míngzi hěn qíguài, tāmen gēn māo yǒu shénme guānxi?","speaker":"刘小明","vi":"Mẹ ơi, cái tên gấu trúc lớn (đại hùng miêu) rất kỳ lạ, chúng có quan hệ gì với mèo không ạ?"},{"hanzi":"这个问题问得好，它们跟猫没什么关系，其实应该叫大猫熊。","pinyin":"Zhège wèntí wèn de hǎo, tāmen gēn māo méi shénme guānxi, qíshí yīnggāi jiào dà māoxióng.","speaker":"王一雪","vi":"Câu hỏi này hay đấy, chúng chẳng có quan hệ gì với mèo cả, thật ra phải gọi là gấu mèo lớn (đại miêu hùng)."},{"hanzi":"大熊猫为什么只吃竹子不吃肉？","pinyin":"Dàxióngmāo wèishénme zhǐ chī zhúzi bù chī ròu?","speaker":"刘小明","vi":"Tại sao gấu trúc lớn chỉ ăn trúc mà không ăn thịt ạ?"},{"hanzi":"它们跟人一样，也可以吃肉，但是对肉不感兴趣。","pinyin":"Tāmen gēn rén yíyàng, yě kěyǐ chī ròu, dànshì duì ròu bù gǎn xìngqù.","speaker":"王一雪","vi":"Chúng giống như con người vậy, cũng có thể ăn thịt, nhưng không có hứng thú với thịt."},{"hanzi":"大熊猫为什么是中国的国宝？","pinyin":"Dàxióngmāo wèishénme shì Zhōngguó de guóbǎo?","speaker":"刘小明","vi":"Tại sao gấu trúc lớn lại là quốc bảo của Trung Quốc ạ?"},{"hanzi":"全世界只有中国有野生大熊猫，中国是大熊猫的家。","pinyin":"Quán shìjiè zhǐyǒu Zhōngguó yǒu yěshēng dàxióngmāo, Zhōngguó shì dàxióngmāo de jiā.","speaker":"王一雪","vi":"Trên toàn thế giới chỉ có Trung Quốc có gấu trúc lớn hoang dã, Trung Quốc là nhà của gấu trúc lớn."},{"hanzi":"我听说有的熊猫出国了，它们去哪儿了？","pinyin":"Wǒ tīngshuō yǒude xióngmāo chūguó le, tāmen qù nǎr le?","speaker":"刘小明","vi":"Con nghe nói có một số gấu trúc ra nước ngoài rồi, chúng đi đâu vậy ạ?"},{"hanzi":"关于这个问题，我得慢慢给你讲。","pinyin":"Guānyú zhège wèntí, wǒ děi mànmàn gěi nǐ jiǎng.","speaker":"王一雪","vi":"Về vấn đề này, mẹ phải kể từ từ cho con nghe."},{"hanzi":"弟弟，你真是“十万个为什么”。","pinyin":"Dìdi, nǐ zhēn shì “shíwàn gè wèishénme”.","speaker":"刘小雪","vi":"Em trai à, em đúng là “mười vạn câu hỏi vì sao” đấy."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Vương Nhất Tuyết giải thích \"它们跟人一样，也可以吃肉，但是对肉不感兴趣。\" (Chúng giống con người, cũng có thể ăn thịt, nhưng không có hứng thú với thịt.), nên đáp án đúng là vì chúng không hứng thú với thịt.","options":["因为它们不能吃肉","因为它们对肉不感兴趣","因为动物园里没有肉","因为吃肉会让它们生病"],"q":"按照王一雪的回答，大熊猫为什么不吃肉？"},{"answerIdx":0,"explanation":"Trong đoạn hội thoại, Lưu Tiểu Minh liên tiếp hỏi nhiều câu về gấu trúc nên chị gái nói \"弟弟，你真是‘十万个为什么’。\" (Em trai, em đúng là “mười vạn câu hỏi vì sao”.), hàm ý em đã hỏi rất nhiều câu hỏi.","options":["因为弟弟问了很多问题","因为弟弟正在读一本叫这个名字的书","因为弟弟知道很多关于熊猫的知识","因为弟弟能回答十万个问题"],"q":"刘小雪为什么叫弟弟“十万个为什么”？"}],"scene":"在动物园，王一雪和孩子们边走边聊。","sceneVi":"Ở vườn thú, Vương Nhất Tuyết và các con vừa đi vừa trò chuyện."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"这只大熊猫一会儿爬上去，一会儿跳下来，可爱极了！","pinyin":"Zhè zhī dàxióngmāo yíhuìr pá shàngqù, yíhuìr tiào xiàlái, kě'ài jí le!","speaker":"刘小雪","vi":"Con gấu trúc lớn này lúc thì trèo lên, lúc thì nhảy xuống, đáng yêu cực kỳ!"},{"hanzi":"它好像还没吃饱，站起来张着嘴找吃的呢。","pinyin":"Tā hǎoxiàng hái méi chībǎo, zhàn qǐlái zhāngzhe zuǐ zhǎo chī de ne.","speaker":"王一雪","vi":"Nó hình như vẫn chưa ăn no, đứng dậy há miệng tìm đồ ăn kìa."},{"hanzi":"它身边那只熊猫半天没动，是不是在睡觉呢？","pinyin":"Tā shēnbiān nà zhī xióngmāo bàntiān méi dòng, shì bu shì zài shuìjiào ne?","speaker":"刘小雪","vi":"Con gấu trúc bên cạnh nó mãi không nhúc nhích, có phải đang ngủ không ạ?"},{"hanzi":"我看不见它的脸，可能是吧。一般来说，熊猫每天要睡很多次觉。","pinyin":"Wǒ kàn bú jiàn tā de liǎn, kěnéng shì ba. Yìbān lái shuō, xióngmāo měitiān yào shuì hěn duō cì jiào.","speaker":"王一雪","vi":"Mẹ không nhìn thấy mặt nó, chắc là vậy đấy. Nói chung, gấu trúc mỗi ngày phải ngủ rất nhiều lần."},{"hanzi":"对，除了睡觉以外，很多时间都在吃东西。","pinyin":"Duì, chúle shuìjiào yǐwài, hěn duō shíjiān dōu zài chī dōngxi.","speaker":"刘小雪","vi":"Đúng rồi, ngoài ngủ ra, rất nhiều thời gian đều đang ăn uống."},{"hanzi":"大熊猫的生活真舒服啊！","pinyin":"Dàxióngmāo de shēnghuó zhēn shūfu a!","speaker":"刘小明","vi":"Cuộc sống của gấu trúc lớn thật thoải mái quá đi!"},{"hanzi":"妈妈，您帮我和这两只大熊猫照一张照片吧。","pinyin":"Māma, nín bāng wǒ hé zhè liǎng zhī dàxióngmāo zhào yì zhāng zhàopiàn ba.","speaker":"刘小雪","vi":"Mẹ ơi, mẹ chụp giúp con một tấm ảnh với hai con gấu trúc lớn này đi ạ."}],"readingQuiz":[{"answerIdx":3,"explanation":"Trong bài, Vương Nhất Tuyết nói \"它好像还没吃饱，站起来张着嘴找吃的呢。\" (Hình như nó vẫn chưa ăn no, đang đứng dậy há miệng tìm đồ ăn kìa.), nên đáp án đúng là vì nó đứng dậy há miệng tìm thức ăn.","options":["因为它一直在睡觉","因为它的脸看起来很不高兴","因为它一直跳下来找妈妈","因为它站起来张着嘴找吃的"],"q":"王一雪为什么觉得那只动来动去的大熊猫还没吃饱？"},{"answerIdx":0,"explanation":"Trong bài có câu \"一般来说，熊猫每天要睡很多次觉。\" và \"对，除了睡觉以外，很多时间都在吃东西。\" (Thông thường gấu trúc mỗi ngày phải ngủ rất nhiều lần. / Đúng vậy, ngoài ngủ ra thì phần lớn thời gian đều đang ăn.), nên đáp án đúng là ngoài ngủ ra thì phần lớn thời gian đều ăn uống.","options":["除了睡觉以外，很多时间都在吃东西","每天只睡一次觉，然后一直爬树","跟游客一起照相和做游戏","站起来张着嘴看别的动物"],"q":"按照她们的聊天，大熊猫每天大部分时间都在做什么？"}],"scene":"在熊猫馆，王一雪和孩子们在看大熊猫。","sceneVi":"Ở khu nuôi gấu trúc, Vương Nhất Tuyết và các con đang xem gấu trúc lớn."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"今天我带小雪和小明去动物园玩了。","pinyin":"Jīntiān wǒ dài Xiǎoxuě hé Xiǎomíng qù dòngwùyuán wán le.","speaker":"Đoạn văn","vi":"Hôm nay tôi đưa Tiểu Tuyết và Tiểu Minh đi vườn thú chơi."},{"hanzi":"北京动物园是中国很有名的动物园，里面有非常多的动物，当然，大人和孩子最喜爱的还是大熊猫。","pinyin":"Běijīng Dòngwùyuán shì Zhōngguó hěn yǒumíng de dòngwùyuán, lǐmiàn yǒu fēicháng duō de dòngwù, dāngrán, dàren hé háizi zuì xǐ'ài de háishi dàxióngmāo.","speaker":"Đoạn văn","vi":"Vườn thú Bắc Kinh là vườn thú rất nổi tiếng của Trung Quốc, bên trong có rất nhiều loài động vật, tất nhiên, loài được người lớn và trẻ em yêu thích nhất vẫn là gấu trúc lớn."},{"hanzi":"每天有很多游客去熊猫馆，他们带着相机去给可爱的大熊猫拍照。","pinyin":"Měitiān yǒu hěn duō yóukè qù Xióngmāoguǎn, tāmen dàizhe xiàngjī qù gěi kě'ài de dàxióngmāo pāizhào.","speaker":"Đoạn văn","vi":"Mỗi ngày có rất nhiều du khách đến khu nuôi gấu trúc, họ mang theo máy ảnh đến chụp ảnh cho những chú gấu trúc lớn đáng yêu."},{"hanzi":"动物园早上七点半开门，晚上七点关门，冬天比夏天游客少，所以也比平时早关门一个小时。","pinyin":"Dòngwùyuán zǎoshang qī diǎn bàn kāimén, wǎnshang qī diǎn guānmén, dōngtiān bǐ xiàtiān yóukè shǎo, suǒyǐ yě bǐ píngshí zǎo guānmén yí gè xiǎoshí.","speaker":"Đoạn văn","vi":"Vườn thú mở cửa lúc 7 giờ 30 sáng, đóng cửa lúc 7 giờ tối, mùa đông ít khách hơn mùa hè nên cũng đóng cửa sớm hơn bình thường một tiếng."},{"hanzi":"如果第一次来北京旅游，跟家人一起去北京动物园是个不错的选择。","pinyin":"Rúguǒ dì-yī cì lái Běijīng lǚyóu, gēn jiārén yìqǐ qù Běijīng Dòngwùyuán shì gè búcuò de xuǎnzé.","speaker":"Đoạn văn","vi":"Nếu lần đầu tiên đến Bắc Kinh du lịch, cùng gia đình đi Vườn thú Bắc Kinh là một lựa chọn không tồi."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài nhật ký có câu \"每天有很多游客去熊猫馆，他们带着相机去给可爱的大熊猫拍照。\" (Mỗi ngày có rất nhiều du khách đến khu gấu trúc, họ mang theo máy ảnh để chụp ảnh cho những chú gấu trúc đáng yêu.), nên đáp án đúng là nhiều du khách mang máy ảnh đến chụp ảnh gấu trúc.","options":["只有小孩子喜欢看大熊猫","冬天的游客比夏天多","很多游客带着相机去给大熊猫拍照","游客晚上八点还可以进动物园"],"q":"根据这篇日记，关于北京动物园的游客，哪句话是对的？"},{"answerIdx":0,"explanation":"Trong bài viết \"动物园早上七点半开门，晚上七点关门，冬天比夏天游客少，所以也比平时早关门一个小时。\" (Vườn thú mở cửa lúc 7 giờ 30 sáng, đóng cửa lúc 7 giờ tối; mùa đông ít khách hơn mùa hè nên đóng cửa sớm hơn bình thường một tiếng.), nên vào mùa đông vườn thú đóng cửa lúc 6 giờ tối (六点).","options":["六点","七点","七点半","八点"],"q":"冬天的时候，北京动物园晚上几点关门？"}],"scene":"在家里，王一雪在写日记。","sceneVi":"Ở nhà, Vương Nhất Tuyết đang viết nhật ký."}],"hsk3-17":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"别再向前走了，李老师的办公室已经到了。","pinyin":"Bié zài xiàng qián zǒu le, Lǐ lǎoshī de bàngōngshì yǐjīng dào le.","speaker":"刘小雪","vi":"Đừng đi về phía trước nữa, đến văn phòng thầy Lý rồi."},{"hanzi":"你进去吧，我在楼梯那儿等你。我害怕见李老师。","pinyin":"Nǐ jìnqù ba, wǒ zài lóutī nàr děng nǐ. Wǒ hàipà jiàn Lǐ lǎoshī.","speaker":"同学","vi":"Cậu vào đi, tớ đợi cậu ở chỗ cầu thang. Tớ sợ gặp thầy Lý."},{"hanzi":"怎么回事？","pinyin":"Zěnme huíshì?","speaker":"刘小雪","vi":"Có chuyện gì vậy?"},{"hanzi":"最近我做错了好几件事，我怕李老师生气。","pinyin":"Zuìjìn wǒ zuòcuò le hǎojǐ jiàn shì, wǒ pà Lǐ lǎoshī shēngqì.","speaker":"同学","vi":"Gần đây tớ làm sai mấy việc liền, tớ sợ thầy Lý giận."},{"hanzi":"你想多了，做错事情是很常见的。","pinyin":"Nǐ xiǎng duō le, zuòcuò shìqing shì hěn chángjiàn de.","speaker":"刘小雪","vi":"Cậu nghĩ nhiều quá rồi, làm sai việc là chuyện rất thường gặp mà."},{"hanzi":"我把简单的事情做错了，李老师一定觉得我不认真。","pinyin":"Wǒ bǎ jiǎndān de shìqing zuòcuò le, Lǐ lǎoshī yídìng juéde wǒ bú rènzhēn.","speaker":"同学","vi":"Tớ làm sai những việc đơn giản, thầy Lý nhất định sẽ nghĩ tớ không cẩn thận."},{"hanzi":"有的人虽然很聪明，但是会在简单的事情中出错，因为他们认为事情简单，就不会认真去做了。","pinyin":"Yǒude rén suīrán hěn cōngmíng, dànshì huì zài jiǎndān de shìqing zhōng chūcuò, yīnwèi tāmen rènwéi shìqing jiǎndān, jiù bú huì rènzhēn qù zuò le.","speaker":"刘小雪","vi":"Có người tuy rất thông minh, nhưng lại hay mắc lỗi ở những việc đơn giản, vì họ cho rằng việc đơn giản nên không nghiêm túc làm nữa."},{"hanzi":"你说的就是我，以后我要多向认真的人学习。","pinyin":"Nǐ shuō de jiù shì wǒ, yǐhòu wǒ yào duō xiàng rènzhēn de rén xuéxí.","speaker":"同学","vi":"Cậu nói đúng là tớ đấy, sau này tớ phải học hỏi nhiều hơn từ những người cẩn thận."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, người bạn học nói \"我害怕见李老师。... 最近我做错了好几件事，我怕李老师生气。\" (Mình sợ gặp thầy Lý... Gần đây mình làm sai mấy việc liền, mình sợ thầy Lý giận.), nên đáp án đúng là vì gần đây bạn ấy làm sai mấy việc nên sợ thầy giận.","options":["因为他迷路了，找不到楼梯","因为最近他做错了好几件事，怕老师生气","因为李老师现在不在办公室里","因为他觉得李老师太严格，不聪明"],"q":"同学为什么不想进李老师的办公室？"},{"answerIdx":3,"explanation":"Trong bài, Lưu Tiểu Tuyết nói \"有的人虽然很聪明，但是会在简单的事情中出错，因为他们认为事情简单，就不会认真去做了。\" (Có người tuy rất thông minh nhưng lại mắc lỗi ở những việc đơn giản, bởi vì họ cho rằng việc đơn giản nên sẽ không nghiêm túc làm.), nên đáp án đúng là vì họ nghĩ việc đơn giản nên không làm một cách nghiêm túc.","options":["因为他们太害怕老师了","因为简单的事情其实很难","因为他们没有向别人学习","因为他们觉得事情简单，就不认真去做"],"q":"在刘小雪看来，聪明人为什么有时会在简单的事情上出错？"}],"scene":"在教学楼里，刘小雪和同学边走边聊。","sceneVi":"Trong tòa nhà giảng đường, Lưu Tiểu Tuyết và bạn học vừa đi vừa trò chuyện."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"太阳从西边出来了？这几天怎么总是在图书馆看见你？","pinyin":"Tàiyáng cóng xībiān chūlái le? Zhè jǐ tiān zěnme zǒngshì zài túshūguǎn kànjiàn nǐ?","speaker":"白家月","vi":"Mặt trời mọc đằng tây à? Mấy hôm nay sao lúc nào cũng thấy cậu ở thư viện thế?"},{"hanzi":"这有什么奇怪的？我是来学习的。","pinyin":"Zhè yǒu shénme qíguài de? Wǒ shì lái xuéxí de.","speaker":"陈天中","vi":"Chuyện này có gì lạ đâu? Tớ đến để học mà."},{"hanzi":"你怎么还来图书馆学习？同学们都在到处找工作呢。","pinyin":"Nǐ zěnme hái lái túshūguǎn xuéxí? Tóngxuémen dōu zài dàochù zhǎo gōngzuò ne.","speaker":"白家月","vi":"Sao cậu vẫn còn đến thư viện học? Các bạn đều đang đi khắp nơi tìm việc làm đấy."},{"hanzi":"我不想现在就工作，还想继续学习，我爸妈也同意。可我还没想好学什么，所以来图书馆看看。","pinyin":"Wǒ bù xiǎng xiànzài jiù gōngzuò, hái xiǎng jìxù xuéxí, wǒ bàmā yě tóngyì. Kě wǒ hái méi xiǎnghǎo xué shénme, suǒyǐ lái túshūguǎn kànkan.","speaker":"陈天中","vi":"Tớ chưa muốn đi làm ngay bây giờ, vẫn muốn học tiếp, bố mẹ tớ cũng đồng ý. Nhưng tớ vẫn chưa nghĩ kỹ xem nên học gì, nên đến thư viện xem thử."},{"hanzi":"你不是喜欢玩电脑吗？你可以去看看跟电脑有关系的书。","pinyin":"Nǐ bú shì xǐhuan wán diànnǎo ma? Nǐ kěyǐ qù kànkan gēn diànnǎo yǒu guānxì de shū.","speaker":"白家月","vi":"Không phải cậu thích dùng máy tính sao? Cậu có thể đi xem mấy quyển sách liên quan đến máy tính."},{"hanzi":"你说得对，我记得那个屋子里有些跟电脑有关的书，我去找找。","pinyin":"Nǐ shuō de duì, wǒ jìde nàge wūzi lǐ yǒuxiē gēn diànnǎo yǒuguān de shū, wǒ qù zhǎozhao.","speaker":"陈天中","vi":"Cậu nói đúng đấy, tớ nhớ trong căn phòng kia có một ít sách liên quan đến máy tính, tớ đi tìm thử xem."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài, Trần Thiên Trung nói \"我不想现在就工作，还想继续学习，我爸妈也同意。可我还没想好学什么，所以来图书馆看看。\" (Mình không muốn đi làm ngay bây giờ, vẫn muốn học tiếp, bố mẹ mình cũng đồng ý. Nhưng mình chưa nghĩ ra học gì nên đến thư viện xem thử.), nên đáp án đúng là vì muốn học tiếp nhưng chưa chọn được ngành học nên đến thư viện xem thử.","options":["因为他想找一份跟电脑有关的工作","因为他想在图书馆等白家月","因为他想继续学习，但还没想好学什么，来这里看看","因为他爸妈不同意他现在去工作"],"q":"陈天中这几天为什么总来图书馆？"},{"answerIdx":0,"explanation":"Trong bài, Bạch Gia Nguyệt gợi ý \"你不是喜欢玩电脑吗？你可以去看看跟电脑有关系的书。\" (Chẳng phải cậu thích dùng máy tính sao? Cậu có thể đi xem những cuốn sách liên quan đến máy tính.), nên đáp án đúng là đi xem sách liên quan đến máy tính.","options":["看看跟电脑有关的书","跟同学们一起到处找工作","先问问爸爸妈妈的意见","去阅览室外面玩电脑"],"q":"白家月建议陈天中去做什么？"}],"scene":"在阅览室门口，白家月碰到了陈天中。","sceneVi":"Ở cửa phòng đọc sách, Bạch Gia Nguyệt tình cờ gặp Trần Thiên Trung."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"天中，你的手机怎么关机了？","pinyin":"Tiānzhōng, nǐ de shǒujī zěnme guānjī le?","speaker":"李文","vi":"Thiên Trung, sao điện thoại của cậu lại tắt máy rồi?"},{"hanzi":"我的手机没电了。你找我有事吗？","pinyin":"Wǒ de shǒujī méi diàn le. Nǐ zhǎo wǒ yǒu shì ma?","speaker":"陈天中","vi":"Điện thoại tớ hết pin rồi. Cậu tìm tớ có việc gì à?"},{"hanzi":"前天我看见家月了，她告诉我你打算继续留学？","pinyin":"Qiántiān wǒ kànjiàn Jiāyuè le, tā gàosu wǒ nǐ dǎsuàn jìxù liúxué?","speaker":"李文","vi":"Hôm kia tớ gặp Gia Nguyệt, cậu ấy nói với tớ là cậu định tiếp tục đi du học à?"},{"hanzi":"是，可是我还没想好学什么，更没想好去哪个国家。","pinyin":"Shì, kěshì wǒ hái méi xiǎnghǎo xué shénme, gèng méi xiǎnghǎo qù nǎge guójiā.","speaker":"陈天中","vi":"Ừ, nhưng tớ vẫn chưa nghĩ kỹ xem học ngành gì, lại càng chưa nghĩ ra sẽ đi nước nào."},{"hanzi":"你可以去中国学中文啊。比如可以去北京、上海这样的大城市，那里有很多好大学，也有很多留学生。","pinyin":"Nǐ kěyǐ qù Zhōngguó xué Zhōngwén a. Bǐrú kěyǐ qù Běijīng, Shànghǎi zhèyàng de dà chéngshì, nàlǐ yǒu hěn duō hǎo dàxué, yě yǒu hěn duō liúxuéshēng.","speaker":"李文","vi":"Cậu có thể sang Trung Quốc học tiếng Trung đấy. Ví dụ có thể đến những thành phố lớn như Bắc Kinh, Thượng Hải, ở đó có rất nhiều trường đại học tốt, cũng có rất nhiều du học sinh."},{"hanzi":"好，那我上网查一查。","pinyin":"Hǎo, nà wǒ shàngwǎng chá yi chá.","speaker":"陈天中","vi":"Được, vậy để tớ lên mạng tra thử xem."},{"hanzi":"我给你介绍几个有用的网站。","pinyin":"Wǒ gěi nǐ jièshào jǐ gè yǒuyòng de wǎngzhàn.","speaker":"李文","vi":"Để tớ giới thiệu cho cậu vài trang web hữu ích."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Trần Thiên Trung nói \"是，可是我还没想好学什么，更没想好去哪个国家。\" (Đúng vậy, nhưng mình vẫn chưa nghĩ xong học gì, càng chưa nghĩ ra đi nước nào.), nên đáp án đúng là chưa nghĩ ra học gì và cũng chưa quyết định đi nước nào.","options":["已经决定去北京学中文了","还没想好学什么，也没想好去哪个国家","已经上网找好了合适的大学","不打算出国留学，只想用手机查资料"],"q":"关于留学的打算，陈天中现在的情况是什么？"},{"answerIdx":3,"explanation":"Trong bài, Lý Văn khuyên \"你可以去中国学中文啊。比如可以去北京、上海这样的大城市...\" (Cậu có thể đến Trung Quốc học tiếng Trung đấy. Ví dụ có thể đến những thành phố lớn như Bắc Kinh, Thượng Hải...) và nói thêm \"我给你介绍几个有用的网站。\" (Mình giới thiệu cho cậu vài trang web hữu ích.), nên đáp án đúng là gợi ý đi Trung Quốc học tiếng Trung và giới thiệu các trang web hữu ích.","options":["借给陈天中一个有电的手机","帮陈天中问了家月的意见","带陈天中去北京和上海参观大学","建议他去中国学中文，并给他介绍有用的网站"],"q":"李文是怎么帮助陈天中的？"}],"scene":"在校园里，李文和陈天中在聊天儿。","sceneVi":"Trong khuôn viên trường, Lý Văn và Trần Thiên Trung đang trò chuyện."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"大学生活马上就要结束了，我最近经常被问到一个问题——“你以后想做什么”，这个问题真不容易回答。","pinyin":"Dàxué shēnghuó mǎshàng jiù yào jiéshù le, wǒ zuìjìn jīngcháng bèi wèn dào yí gè wèntí —— “nǐ yǐhòu xiǎng zuò shénme”, zhège wèntí zhēn bù róngyì huídá.","speaker":"Đoạn văn","vi":"Cuộc sống đại học sắp kết thúc rồi, gần đây tôi thường xuyên bị hỏi một câu hỏi —— “Sau này cậu muốn làm gì?”, câu hỏi này thật sự không dễ trả lời."},{"hanzi":"我也问了几个同学，大家选择的方向都不同。","pinyin":"Wǒ yě wèn le jǐ gè tóngxué, dàjiā xuǎnzé de fāngxiàng dōu bù tóng.","speaker":"Đoạn văn","vi":"Tôi cũng đã hỏi vài bạn học, hướng đi mà mọi người lựa chọn đều khác nhau."},{"hanzi":"有的想继续在学校学习，有的打算出国留学，还有的决定先找工作。","pinyin":"Yǒude xiǎng jìxù zài xuéxiào xuéxí, yǒude dǎsuàn chūguó liúxué, háiyǒude juédìng xiān zhǎo gōngzuò.","speaker":"Đoạn văn","vi":"Có bạn muốn tiếp tục học ở trường, có bạn dự định đi du học nước ngoài, lại có bạn quyết định tìm việc làm trước."},{"hanzi":"我认为只有想清楚自己真正喜欢什么，才能做出最合适的选择。","pinyin":"Wǒ rènwéi zhǐyǒu xiǎng qīngchu zìjǐ zhēnzhèng xǐhuan shénme, cái néng zuòchū zuì héshì de xuǎnzé.","speaker":"Đoạn văn","vi":"Tôi cho rằng chỉ khi nghĩ rõ mình thực sự thích gì thì mới có thể đưa ra lựa chọn phù hợp nhất."},{"hanzi":"对我来说，想清楚“真正喜欢什么”是个难题。","pinyin":"Duì wǒ lái shuō, xiǎng qīngchu “zhēnzhèng xǐhuan shénme” shì gè nántí.","speaker":"Đoạn văn","vi":"Đối với tôi, nghĩ rõ xem “mình thực sự thích gì” là một bài toán khó."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài nhật ký viết \"有的想继续在学校学习，有的打算出国留学，还有的决定先找工作。\" (Có người muốn học tiếp ở trường, có người dự định ra nước ngoài du học, còn có người quyết định đi tìm việc trước.), nên đáp án đúng là có người học tiếp, có người đi du học và có người tìm việc trước.","options":["所有同学都打算先找工作","大家都想出国留学，不想继续在学校学习","有的继续学习，有的出国留学，还有的先找工作","大家都在等老师告诉他们选择什么方向"],"q":"关于大学毕业以后，陈天中的同学们有什么不同的打算？"},{"answerIdx":0,"explanation":"Trong bài có câu \"我认为只有想清楚自己真正喜欢什么，才能做出最合适的选择。\" (Tôi cho rằng chỉ khi nghĩ rõ bản thân thực sự thích gì thì mới có thể đưa ra lựa chọn phù hợp nhất.), nên đáp án đúng là phải nghĩ rõ bản thân thực sự thích gì.","options":["想清楚自己真正喜欢什么","多问几个同学选了什么方向","先随便找一份工作试试","尽快结束大学生活去旅游"],"q":"陈天中认为，怎样才能做出最合适的选择？"}],"scene":"在家里，陈天中在写日记。","sceneVi":"Ở nhà, Trần Thiên Trung đang viết nhật ký."}],"hsk3-18":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"我要在中国过年，真开心。","pinyin":"Wǒ yào zài Zhōngguó guònián, zhēn kāixīn.","speaker":"白家月","vi":"Tớ sắp được đón Tết ở Trung Quốc rồi, vui quá đi."},{"hanzi":"第一次请外国朋友来家里过春节，我也很高兴。","pinyin":"Dì-yī cì qǐng wàiguó péngyou lái jiālǐ guò Chūnjié, wǒ yě hěn gāoxìng.","speaker":"李文","vi":"Lần đầu tiên mời bạn nước ngoài về nhà đón Tết Nguyên đán, tớ cũng rất vui."},{"hanzi":"你们怎样过节？","pinyin":"Nǐmen zěnyàng guòjié?","speaker":"白家月","vi":"Mọi người đón Tết như thế nào?"},{"hanzi":"春节是中国最重要的节日，我们一般会回家，跟家人一起过。","pinyin":"Chūnjié shì Zhōngguó zuì zhòngyào de jiérì, wǒmen yìbān huì huíjiā, gēn jiārén yìqǐ guò.","speaker":"李文","vi":"Tết Nguyên đán là ngày lễ quan trọng nhất ở Trung Quốc, bọn tớ thường sẽ về nhà, đón Tết cùng gia đình."},{"hanzi":"那你跟家人会一起做什么？","pinyin":"Nà nǐ gēn jiārén huì yìqǐ zuò shénme?","speaker":"白家月","vi":"Vậy cậu với gia đình sẽ cùng nhau làm gì?"},{"hanzi":"我们家会一边包饺子，一边看春节联欢晚会，一直到十二点以后才睡觉。","pinyin":"Wǒmen jiā huì yìbiān bāo jiǎozi, yìbiān kàn Chūnjié Liánhuān Wǎnhuì, yìzhí dào shí'èr diǎn yǐhòu cái shuìjiào.","speaker":"李文","vi":"Nhà tớ sẽ vừa gói bánh chẻo, vừa xem Chương trình Đêm hội Mừng Xuân, mãi đến sau 12 giờ mới đi ngủ."},{"hanzi":"听起来很有意思。春节放几天假？","pinyin":"Tīng qǐlái hěn yǒu yìsi. Chūnjié fàng jǐ tiān jià?","speaker":"白家月","vi":"Nghe thú vị quá. Tết Nguyên đán được nghỉ mấy ngày?"},{"hanzi":"大概七八天。","pinyin":"Dàgài qī bā tiān.","speaker":"李文","vi":"Khoảng bảy tám ngày."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài, Lý Văn nói \"第一次请外国朋友来家里过春节，我也很高兴。\" (Lần đầu tiên mời bạn nước ngoài về nhà đón Tết Nguyên đán, mình cũng rất vui.), nên đáp án đúng là vì đây là lần đầu tiên anh ấy mời bạn nước ngoài về nhà đón Tết.","options":["因为这是他第一次请外国朋友来家里过春节","因为他终于坐飞机回到中国了","因为他特别喜欢吃饺子和看晚会","因为春节只放七八天假"],"q":"李文为什么也很高兴？"},{"answerIdx":2,"explanation":"Trong bài, Lý Văn cho biết \"我们家会一边包饺子，一边看春节联欢晚会，一直到十二点以后才睡觉。\" (Nhà mình sẽ vừa gói sủi cảo vừa xem chương trình Gặp nhau cuối năm, mãi đến sau 12 giờ mới đi ngủ.) và \"大概七八天。\" (Khoảng 7-8 ngày.), nên đáp án đúng là vừa gói sủi cảo vừa xem Gala Xuân Vãn và nghỉ khoảng 7-8 ngày.","options":["出去旅游，放十天假","十二点以前睡觉，放五六天假","一边包饺子一边看春节联欢晚会，放七八天假","跟外国朋友在飞机上过节，不放假"],"q":"李文一家过春节时一般做什么，春节大概放几天假？"}],"scene":"在飞机上，白家月和李文在聊天儿。","sceneVi":"Trên máy bay, Bạch Gia Nguyệt và Lý Văn đang trò chuyện."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"张阿姨，李叔叔。过年好！这是我准备的礼物，请收下。","pinyin":"Zhāng āyí, Lǐ shūshu. Guònián hǎo! Zhè shì wǒ zhǔnbèi de lǐwù, qǐng shōuxià.","speaker":"白家月","vi":"Cô Trương, chú Lý. Chúc mừng năm mới ạ! Đây là món quà cháu chuẩn bị, xin cô chú nhận cho ạ."},{"hanzi":"谢谢家月，你太客气了！","pinyin":"Xièxie Jiāyuè, nǐ tài kèqi le!","speaker":"李叔叔","vi":"Cảm ơn Gia Nguyệt, cháu khách sáo quá rồi!"},{"hanzi":"总听小文说起你，今天终于有机会见面了。","pinyin":"Zǒng tīng Xiǎowén shuōqǐ nǐ, jīntiān zhōngyú yǒu jīhuì jiànmiàn le.","speaker":"张阿姨","vi":"Cô vẫn luôn nghe Tiểu Văn nhắc đến cháu, hôm nay cuối cùng cũng có cơ hội gặp mặt rồi."},{"hanzi":"谢谢您和叔叔请我来家里做客。","pinyin":"Xièxie nín hé shūshu qǐng wǒ lái jiālǐ zuòkè.","speaker":"白家月","vi":"Cháu cảm ơn cô và chú đã mời cháu đến nhà chơi ạ."},{"hanzi":"桌子上有饮料，还有矿泉水，你想喝什么就自己拿。","pinyin":"Zhuōzi shàng yǒu yǐnliào, hái yǒu kuàngquánshuǐ, nǐ xiǎng hē shénme jiù zìjǐ ná.","speaker":"李叔叔","vi":"Trên bàn có nước ngọt, còn có nước khoáng, cháu muốn uống gì thì cứ tự lấy nhé."},{"hanzi":"你先坐着看会儿电视，饺子很快就包好了。","pinyin":"Nǐ xiān zuòzhe kànhuìr diànshì, jiǎozi hěn kuài jiù bāohǎo le.","speaker":"张阿姨","vi":"Cháu cứ ngồi xem ti vi một lát đi, bánh chẻo sắp gói xong rồi."},{"hanzi":"我刚刚看视频学会了包饺子，我跟你们一起包吧。","pinyin":"Wǒ gānggāng kàn shìpín xuéhuì le bāo jiǎozi, wǒ gēn nǐmen yìqǐ bāo ba.","speaker":"白家月","vi":"Cháu vừa xem video học được cách gói bánh chẻo rồi, để cháu gói cùng cô chú nhé."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, cô Trương nói \"总听小文说起你，今天终于有机会见面了。\" (Cô luôn nghe Tiểu Văn nhắc đến cháu, hôm nay cuối cùng cũng có cơ hội gặp mặt rồi.), chứng tỏ hôm nay là lần đầu tiên hai người gặp nhau.","options":["她们以前见过好几次面","今天是她们第一次见面","张阿姨从来没听过白家月的名字","张阿姨不喜欢白家月带的礼物"],"q":"关于张阿姨和白家月，下面哪句话是对的？"},{"answerIdx":3,"explanation":"Khi cô Trương bảo ngồi xem tivi một lát, Bạch Gia Nguyệt đáp \"我刚刚看视频学会了包饺子，我跟你们一起包吧。\" (Cháu vừa xem video học được cách gói sủi cảo rồi, cháu gói cùng hai bác nhé.), nên đáp án đúng là muốn cùng bố mẹ Lý Văn gói sủi cảo.","options":["先拿桌子上的矿泉水喝","拿出礼物送给李叔叔","坐着看视频学中文","和李文的父母一起包饺子"],"q":"张阿姨让白家月先坐着看会儿电视，白家月想做什么？"}],"scene":"在李文家，白家月给李文的父母拜年。","sceneVi":"Tại nhà Lý Văn, Bạch Gia Nguyệt chúc Tết bố mẹ của Lý Văn."},{"id":3,"isNarrative":false,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"这张照片是李文出国前照的吗？","pinyin":"Zhè zhāng zhàopiàn shì Lǐ Wén chūguó qián zhào de ma?","speaker":"白家月","vi":"Bức ảnh này là chụp trước khi Lý Văn ra nước ngoài phải không ạ?"},{"hanzi":"对，这是他从北京出发时，我们全家在机场照的。","pinyin":"Duì, zhè shì tā cóng Běijīng chūfā shí, wǒmen quánjiā zài jīchǎng zhào de.","speaker":"张阿姨","vi":"Đúng rồi, đây là lúc nó xuất phát từ Bắc Kinh, cả nhà cô chụp ở sân bay đấy."},{"hanzi":"那是三四年前吧？","pinyin":"Nà shì sān sì nián qián ba?","speaker":"白家月","vi":"Đó là khoảng ba bốn năm trước phải không ạ?"},{"hanzi":"是啊，时间过得真快，好像是不久前发生的一样。","pinyin":"Shì a, shíjiān guò de zhēn kuài, hǎoxiàng shì bùjiǔ qián fāshēng de yíyàng.","speaker":"张阿姨","vi":"Phải đó, thời gian trôi nhanh thật, cứ như chuyện mới xảy ra cách đây không lâu vậy."},{"hanzi":"您一定特别想李文吧？","pinyin":"Nín yídìng tèbié xiǎng Lǐ Wén ba?","speaker":"白家月","vi":"Chắc cô nhớ Lý Văn lắm nhỉ?"},{"hanzi":"他刚离开家时，我很不习惯，只要几天不跟他视频，就很想他。","pinyin":"Tā gāng líkāi jiā shí, wǒ hěn bù xíguàn, zhǐyào jǐ tiān bù gēn tā shìpín, jiù hěn xiǎng tā.","speaker":"张阿姨","vi":"Lúc nó mới xa nhà, cô không quen chút nào, chỉ cần vài ngày không gọi video cho nó là nhớ nó lắm."},{"hanzi":"还有最后一个学期就要毕业了，他很快就会回来了。","pinyin":"Hái yǒu zuìhòu yí gè xuéqī jiù yào bìyè le, tā hěn kuài jiù huì huílái le.","speaker":"白家月","vi":"Còn một học kỳ cuối nữa là tốt nghiệp rồi, cậu ấy sẽ nhanh chóng về thôi ạ."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài, cô Trương nói \"对，这是他从北京出发时，我们全家在机场照的。\" (Đúng vậy, đây là ảnh cả nhà cô chụp ở sân bay khi nó xuất phát từ Bắc Kinh.) và xác nhận \"那是三四年前吧？\" (Đó là 3-4 năm trước phải không?), nên đáp án đúng là chụp ở sân bay khi Lý Văn xuất phát từ Bắc Kinh khoảng 3-4 năm trước.","options":["三四年前李文从北京出发时，全家在机场照的","李文刚毕业回国时在家里照的","今年春节全家人包饺子时照的","李文在外国的大学校园里照的"],"q":"白家月和张阿姨看的那张照片是什么时候、在哪里照的？"},{"answerIdx":2,"explanation":"Trong bài, cô Trương nói \"他刚离开家时，我很不习惯，只要几天不跟他视频，就很想他。\" (Lúc nó mới rời nhà, cô rất không quen, hễ mấy ngày không gọi video cho nó là lại rất nhớ nó.), nên đáp án đúng là lúc Lý Văn mới xa nhà, cô Trương rất nhớ anh ấy và không quen.","options":["李文离开家以后，张阿姨从来不跟李文视频","李文还要两年才能毕业","李文刚离开家时，张阿姨很想他，不习惯","张阿姨觉得这三四年过得很慢"],"q":"根据这段对话，下面哪句话是对的？"}],"scene":"在李文家，李文妈妈和白家月在聊天儿。","sceneVi":"Tại nhà Lý Văn, mẹ Lý Văn và Bạch Gia Nguyệt đang trò chuyện."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"这次来中国，我最高兴的是认识了李文的父母。","pinyin":"Zhè cì lái Zhōngguó, wǒ zuì gāoxìng de shì rènshi le Lǐ Wén de fùmǔ.","speaker":"Đoạn văn","vi":"Lần này đến Trung Quốc, điều khiến tôi vui nhất là được quen biết bố mẹ của Lý Văn."},{"hanzi":"他们给我看了李文出生时的照片，还给我讲了很多他过去的故事。","pinyin":"Tāmen gěi wǒ kàn le Lǐ Wén chūshēng shí de zhàopiàn, hái gěi wǒ jiǎng le hěn duō tā guòqù de gùshi.","speaker":"Đoạn văn","vi":"Bác ấy đã cho tôi xem ảnh lúc Lý Văn mới sinh, còn kể cho tôi nghe rất nhiều câu chuyện trước đây của cậu ấy."},{"hanzi":"李文高中的时候想学医，从那时起就努力学习。","pinyin":"Lǐ Wén gāozhōng de shíhou xiǎng xuéyī, cóng nà shí qǐ jiù nǔlì xuéxí.","speaker":"Đoạn văn","vi":"Hồi cấp ba Lý Văn muốn học ngành y, từ lúc đó cậu ấy đã chăm chỉ học tập."},{"hanzi":"高三的时候，因为成绩特别好，他得到了出国留学的机会。","pinyin":"Gāosān de shíhou, yīnwèi chéngjì tèbié hǎo, tā dédào le chūguó liúxué de jīhuì.","speaker":"Đoạn văn","vi":"Năm lớp 12, nhờ thành tích đặc biệt xuất sắc, cậu ấy đã giành được cơ hội đi du học nước ngoài."},{"hanzi":"在他身上，我懂得了，只要一直坚持，就能完成自己的目标。","pinyin":"Zài tā shēnshàng, wǒ dǒngde le, zhǐyào yìzhí jiānchí, jiù néng wánchéng zìjǐ de mùbiāo.","speaker":"Đoạn văn","vi":"Từ cậu ấy, tôi hiểu ra rằng chỉ cần luôn kiên trì thì sẽ có thể hoàn thành được mục tiêu của mình."},{"hanzi":"我相信，他以后一定会发展得更好。","pinyin":"Wǒ xiāngxìn, tā yǐhòu yídìng huì fāzhǎn de gèng hǎo.","speaker":"Đoạn văn","vi":"Tôi tin rằng sau này cậu ấy nhất định sẽ phát triển tốt hơn nữa."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài nhật ký có câu \"高三的时候，因为成绩特别好，他得到了出国留学的机会。\" (Hồi lớp 12, nhờ thành tích đặc biệt tốt nên cậu ấy đã có được cơ hội ra nước ngoài du học.), nên đáp án đúng là vì thành tích của cậu ấy đặc biệt tốt.","options":["因为他有很多外国朋友","因为他的成绩特别好","因为他爸爸妈妈让他出国","因为他不想在高中继续学习"],"q":"高三的时候，李文为什么得到了出国留学的机会？"},{"answerIdx":3,"explanation":"Trong bài có câu \"在他身上，我懂得了，只要一直坚持，就能完成自己的目标。\" (Từ cậu ấy, tôi hiểu ra rằng chỉ cần luôn kiên trì thì sẽ có thể hoàn thành được mục tiêu của mình.), nên đáp án đúng là chỉ cần luôn kiên trì thì sẽ hoàn thành được mục tiêu.","options":["学医是高中生最好的选择","出国留学一定要在高三准备","认识朋友的父母是一件很高兴的事","只要一直坚持，就能完成自己的目标"],"q":"从李文的故事中，白家月明白了什么道理？"}],"scene":"在家里，白家月在写日记。","sceneVi":"Ở nhà, Bạch Gia Nguyệt đang viết nhật ký."}],"hsk4a-1":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"你们好，欢迎来到中国留学！请把护照、签证和入学通知书给我。","pinyin":"Nǐmen hǎo, huānyíng láidào Zhōngguó liúxué! Qǐng bǎ hùzhào, qiānzhèng hé rùxué tōngzhīshū gěi wǒ.","speaker":"老师","vi":"Chào các em, chào mừng đến Trung Quốc du học! Hãy đưa hộ chiếu, visa và giấy báo nhập học cho cô."},{"hanzi":"好的。这是我们的证件和材料。","pinyin":"Hǎo de. Zhè shì wǒmen de zhèngjiàn hé cáiliào.","speaker":"白家月","vi":"Vâng ạ. Đây là giấy tờ và tài liệu của chúng em."},{"hanzi":"（几分钟后。）","pinyin":"(Jǐ fēnzhōng hòu.)","speaker":"Dẫn chuyện","vi":"(Vài phút sau.)"},{"hanzi":"办好了，这是你们的学生证，下周一开始上课。先试听两周，然后在网上选课。","pinyin":"Bànhǎo le, zhè shì nǐmen de xuéshengzhèng, xià Zhōuyī kāishǐ shàngkè. Xiān shìtīng liǎng zhōu, ránhòu zài wǎngshàng xuǎnkè.","speaker":"老师","vi":"Làm xong rồi, đây là thẻ sinh viên của các em, thứ Hai tuần sau bắt đầu lên lớp. Học thử trước hai tuần, sau đó chọn môn trên mạng."},{"hanzi":"谢谢老师。","pinyin":"Xièxie lǎoshī.","speaker":"白家月、陈天中","vi":"Cảm ơn cô ạ."},{"hanzi":"不客气，你们以后有任何问题都可以来找我。","pinyin":"Bú kèqi, nǐmen yǐhòu yǒu rènhé wèntí dōu kěyǐ lái zhǎo wǒ.","speaker":"老师","vi":"Không có gì, sau này các em có bất kỳ vấn đề gì đều có thể đến tìm cô."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài giáo viên nói \"办好了，这是你们的学生证\" (Làm xong rồi, đây là thẻ sinh viên của các em), còn hộ chiếu, visa và giấy báo nhập học là giấy tờ hai bạn nộp cho giáo viên.","options":["护照","学生证","签证","入学通知书"],"q":"老师为白家月和陈天中办好了什么证件？"},{"answerIdx":2,"explanation":"Trong bài giáo viên dặn \"下周一开始上课。先试听两周，然后在网上选课。\" (Thứ Hai tuần sau bắt đầu lên lớp. Học thử hai tuần trước, sau đó chọn môn học trên mạng).","options":["今天开始上课，在办公室选课","下个月开始上课，先选课再试听","下周一开始上课，先试听两周再在网上选课","下周三开始上课，让老师帮忙选课"],"q":"他们什么时候开始上课，怎么选课？"}],"scene":"在学院办公室，白家月和陈天中在办理入学手续。","sceneVi":"Tại văn phòng học viện, Bạch Gia Nguyệt và Trần Thiên Trung đang làm thủ tục nhập học."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"你看，咱们的校园真大！有图书馆、体育馆、超市，还有好几个食堂。","pinyin":"Nǐ kàn, zánmen de xiàoyuán zhēn dà! Yǒu túshūguǎn, tǐyùguǎn, chāoshì, hái yǒu hǎojǐ gè shítáng.","speaker":"陈天中","vi":"Cậu xem, khuôn viên trường mình rộng thật đấy! Có thư viện, nhà thi đấu thể thao, siêu thị, còn có mấy nhà ăn nữa."},{"hanzi":"是啊，我觉得学校就像一座小城市，什么都有，方便极了。","pinyin":"Shì a, wǒ juéde xuéxiào jiù xiàng yí zuò xiǎo chéngshì, shénme dōu yǒu, fāngbiàn jíle.","speaker":"白家月","vi":"Đúng vậy, mình thấy trường học giống như một thành phố nhỏ vậy, cái gì cũng có, tiện lợi cực kỳ."},{"hanzi":"刚才老师说，咱们可以申请奖学金，你了解过吗？","pinyin":"Gāngcái lǎoshī shuō, zánmen kěyǐ shēnqǐng jiǎngxuéjīn, nǐ liǎojiě guo ma?","speaker":"陈天中","vi":"Lúc nãy cô giáo nói chúng ta có thể xin học bổng, cậu đã tìm hiểu qua chưa?"},{"hanzi":"我听说过一点儿，好像成绩好、表现好的学生都有机会获得奖学金。","pinyin":"Wǒ tīngshuō guo yìdiǎnr, hǎoxiàng chéngjì hǎo, biǎoxiàn hǎo de xuésheng dōu yǒu jīhuì huòdé jiǎngxuéjīn.","speaker":"白家月","vi":"Mình có nghe nói qua một chút, hình như sinh viên có thành tích tốt, biểu hiện tốt đều có cơ hội nhận được học bổng."},{"hanzi":"那太好了，要是申请到奖学金，就能减轻不少经济压力。","pinyin":"Nà tài hǎo le, yàoshi shēnqǐng dào jiǎngxuéjīn, jiù néng jiǎnqīng bùshǎo jīngjì yālì.","speaker":"陈天中","vi":"Thế thì tuyệt quá, nếu xin được học bổng thì có thể giảm bớt không ít áp lực kinh tế."},{"hanzi":"没错，我们一起加油吧！","pinyin":"Méicuò, wǒmen yìqǐ jiāyóu ba!","speaker":"白家月","vi":"Đúng vậy, chúng ta cùng cố gắng nhé!"}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài Bạch Gia Nguyệt nói \"我觉得学校就像一座小城市，什么都有，方便极了。\" (Mình cảm thấy trường học giống như một thành phố nhỏ vậy, cái gì cũng có, vô cùng tiện lợi).","options":["像一座小城市，什么都有，非常方便","虽然很大，但是食堂和超市太少了","环境很安静，不过离市区有点儿远","图书馆和体育馆都太旧了，不太方便"],"q":"白家月觉得他们的校园怎么样？"},{"answerIdx":3,"explanation":"Trong bài Trần Thiên Trung nói \"要是申请到奖学金，就能减轻不少经济压力。\" (Nếu xin được học bổng thì có thể giảm bớt không ít áp lực kinh tế).","options":["因为老师要求每个留学生都必须申请","因为他的成绩一直是全班第一名","因为学校给所有新生都发奖学金","因为申请到奖学金可以减轻不少经济压力"],"q":"陈天中为什么想申请奖学金？"}],"scene":"在大学校园，白家月和陈天中边逛边聊。","sceneVi":"Trong khuôn viên trường đại học, Bạch Gia Nguyệt và Trần Thiên Trung vừa đi dạo vừa trò chuyện."},{"id":3,"isNarrative":true,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"随着中国的发展，越来越多的外国学生来到中国的大学学习。","pinyin":"Suízhe Zhōngguó de fāzhǎn, yuèláiyuè duō de wàiguó xuésheng láidào Zhōngguó de dàxué xuéxí.","speaker":"Đoạn văn","vi":"Cùng với sự phát triển của Trung Quốc, ngày càng có nhiều sinh viên nước ngoài đến học tập tại các trường đại học của Trung Quốc."},{"hanzi":"他们可以先上一年的中文课程，然后根据自己的兴趣和需要选择专业。","pinyin":"Tāmen kěyǐ xiān shàng yì nián de Zhōngwén kèchéng, ránhòu gēnjù zìjǐ de xìngqù hé xūyào xuǎnzé zhuānyè.","speaker":"Đoạn văn","vi":"Họ có thể học một năm khóa tiếng Trung trước, sau đó chọn chuyên ngành dựa theo sở thích và nhu cầu của bản thân."},{"hanzi":"除了读本科课程，他们还可以申请读硕士研究生或者博士研究生。","pinyin":"Chúle dú běnkē kèchéng, tāmen hái kěyǐ shēnqǐng dú shuòshì yánjiūshēng huòzhě bóshì yánjiūshēng.","speaker":"Đoạn văn","vi":"Ngoài học chương trình đại học, họ còn có thể đăng ký học thạc sĩ hoặc tiến sĩ."},{"hanzi":"在大学里，外国学生可以和中国学生一起学习、做研究、参加校园活动。","pinyin":"Zài dàxué lǐ, wàiguó xuésheng kěyǐ hé Zhōngguó xuésheng yìqǐ xuéxí, zuò yánjiū, cānjiā xiàoyuán huódòng.","speaker":"Đoạn văn","vi":"Ở trường đại học, sinh viên nước ngoài có thể cùng sinh viên Trung Quốc học tập, làm nghiên cứu và tham gia các hoạt động trong khuôn viên trường."},{"hanzi":"通过这些交流，外国学生能更快地适应中国的大学生活。","pinyin":"Tōngguò zhèxiē jiāoliú, wàiguó xuésheng néng gèng kuài de shìyìng Zhōngguó de dàxué shēnghuó.","speaker":"Đoạn văn","vi":"Thông qua những sự giao lưu này, sinh viên nước ngoài có thể thích nghi nhanh hơn với cuộc sống đại học ở Trung Quốc."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"他们可以先上一年的中文课程，然后根据自己的兴趣和需要选择专业。\" (Họ có thể học khóa tiếng Trung một năm trước, sau đó chọn chuyên ngành dựa theo sở thích và nhu cầu của bản thân).","options":["完全由学校和老师帮他们决定","根据自己的兴趣和需要来选择","只能选择中文或者中国文化专业","必须和中国学生选择一样的专业"],"q":"上完一年的中文课程后，外国学生怎么选择专业？"},{"answerIdx":0,"explanation":"Trong bài có câu \"在大学里，外国学生可以和中国学生一起学习、做研究、参加校园活动。通过这些交流，外国学生能更快地适应中国的大学生活。\" (Thông qua việc cùng học tập, nghiên cứu và tham gia hoạt động với sinh viên Trung Quốc, sinh viên nước ngoài có thể thích nghi nhanh hơn với cuộc sống đại học ở Trung Quốc).","options":["跟中国学生一起学习、做研究和参加活动","只跟本国留学生住在一起练习口语","每天在宿舍里自己看书和上网课","来中国以前先工作两年攒够生活费"],"q":"外国学生通过什么能更快地适应中国的大学生活？"}],"scene":"外国学生在中国大学的学习和生活","sceneVi":"Việc học tập và cuộc sống của sinh viên nước ngoài tại các trường đại học Trung Quốc"},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"很多外国学生来中国学习以前，就已经想好了自己的发展方向。","pinyin":"Hěnduō wàiguó xuésheng lái Zhōngguó xuéxí yǐqián, jiù yǐjīng xiǎnghǎo le zìjǐ de fāzhǎn fāngxiàng.","speaker":"Đoạn văn","vi":"Nhiều sinh viên nước ngoài trước khi sang Trung Quốc học tập đã suy nghĩ kỹ về định hướng phát triển của bản thân rồi."},{"hanzi":"有人对经济感兴趣，希望将来在国际公司工作；有人喜欢学医，打算回国后当一名医生；还有人对教育有热情，想要成为一名教师。","pinyin":"Yǒurén duì jīngjì gǎn xìngqù, xīwàng jiānglái zài guójì gōngsī gōngzuò; yǒurén xǐhuan xué yī, dǎsuàn huíguó hòu dāng yì míng yīshēng; hái yǒurén duì jiàoyù yǒu rèqíng, xiǎngyào chéngwéi yì míng jiàoshī.","speaker":"Đoạn văn","vi":"Có người hứng thú với kinh tế, hy vọng tương lai làm việc ở công ty quốc tế; có người thích học y, dự định sau khi về nước sẽ làm bác sĩ; cũng có người nhiệt huyết với giáo dục, muốn trở thành giáo viên."},{"hanzi":"陈天中想选择跟经济有关的专业，希望通过学习，了解更多国际贸易方面的知识。","pinyin":"Chén Tiānzhōng xiǎng xuǎnzé gēn jīngjì yǒuguān de zhuānyè, xīwàng tōngguò xuéxí, liǎojiě gèng duō guójì màoyì fāngmiàn de zhīshi.","speaker":"Đoạn văn","vi":"Trần Thiên Trung muốn chọn chuyên ngành liên quan đến kinh tế, hy vọng thông qua việc học sẽ hiểu biết thêm nhiều kiến thức về thương mại quốc tế."},{"hanzi":"安妮以后想做一名中文老师，所以要选择国际中文教育专业。","pinyin":"Ānnī yǐhòu xiǎng zuò yì míng Zhōngwén lǎoshī, suǒyǐ yào xuǎnzé guójì Zhōngwén jiàoyù zhuānyè.","speaker":"Đoạn văn","vi":"An Ni sau này muốn làm giáo viên tiếng Trung, vì vậy bạn ấy muốn chọn chuyên ngành Giáo dục tiếng Trung quốc tế."},{"hanzi":"对他们来说，来到中国留学，一方面是为了学习语言和知识，另一方面也是为将来的工作和生活做准备。","pinyin":"Duì tāmen láishuō, láidào Zhōngguó liúxué, yì fāngmiàn shì wèile xuéxí yǔyán hé zhīshi, lìng yì fāngmiàn yě shì wèi jiānglái de gōngzuò hé shēnghuó zuò zhǔnbèi.","speaker":"Đoạn văn","vi":"Đối với họ, đến Trung Quốc du học một mặt là để học ngôn ngữ và kiến thức, mặt khác cũng là để chuẩn bị cho công việc và cuộc sống tương lai."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu \"陈天中想选择跟经济有关的专业，希望通过学习，了解更多国际贸易方面的知识。\" (Trần Thiên Trung muốn chọn chuyên ngành liên quan đến kinh tế, hy vọng thông qua việc học sẽ hiểu thêm nhiều kiến thức về thương mại quốc tế).","options":["因为他父母希望他以后当一名医生","因为他想做一名国际中文教师","因为他想多了解国际贸易方面的知识","因为这个专业的奖学金金额最高"],"q":"陈天中为什么想选择跟经济有关的专业？"},{"answerIdx":2,"explanation":"Trong bài có câu \"来到中国留学，一方面是为了学习语言和知识，另一方面也是为将来的工作和生活做准备。\" (Sang Trung Quốc du học một mặt là để học ngôn ngữ và kiến thức, mặt khác cũng là để chuẩn bị cho công việc và cuộc sống tương lai).","options":["安妮将来想在国际贸易公司工作","很多外国学生来中国后才开始想发展方向","他们来留学既是为了学习，也是为将来做准备","喜欢学医的学生打算毕业后都留在中国当医生"],"q":"关于这段话，下面哪一项是正确的？"}],"scene":"专业选择与职业发展","sceneVi":"Lựa chọn chuyên ngành và phát triển nghề nghiệp"}],"hsk4a-2":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"请进！我给你们介绍一下，这个房子有两个房间，那个大房间出租，房租每月5500元。现在已经收拾好了，想租的话，今天就可以搬进来。","pinyin":"Qǐng jìn! Wǒ gěi nǐmen jièshào yíxià, zhège fángzi yǒu liǎng gè fángjiān, nàge dà fángjiān chūzū, fángzū měi yuè wǔqiān wǔbǎi yuán. Xiànzài yǐjīng shōushi hǎo le, xiǎng zū de huà, jīntiān jiù kěyǐ bān jìnlái.","speaker":"房东","vi":"Mời vào! Để tôi giới thiệu với hai bạn một chút, căn nhà này có hai phòng, phòng lớn kia cho thuê, tiền thuê nhà mỗi tháng 5500 tệ. Hiện tại đã dọn dẹp xong xuôi rồi, nếu muốn thuê thì hôm nay có thể dọn vào ở ngay."},{"hanzi":"嗯，这个房间真不小，还挺亮。小区离我们学校也不远。","pinyin":"Ǹg, zhège fángjiān zhēn bù xiǎo, hái tǐng liàng. Xiǎoqū lí wǒmen xuéxiào yě bù yuǎn.","speaker":"白家月","vi":"Ừm, căn phòng này đúng là không nhỏ, lại khá sáng sủa. Khu chung cư cách trường chúng tôi cũng không xa."},{"hanzi":"是的，我们小区离地铁站也很近，生活上很方便。如果决定租了，告诉我就是了。","pinyin":"Shì de, wǒmen xiǎoqū lí dìtiězhàn yě hěn jìn, shēnghuó shàng hěn fāngbiàn. Rúguǒ juédìng zū le, gàosu wǒ jiùshì le.","speaker":"房东","vi":"Đúng vậy, khu chung cư chúng tôi cũng rất gần ga tàu điện ngầm, sinh hoạt rất thuận tiện. Nếu quyết định thuê rồi thì cứ nói với tôi là được."},{"hanzi":"好的，我们再去看看外边的环境。","pinyin":"Hǎo de, wǒmen zài qù kànkan wàibian de huánjìng.","speaker":"白家月","vi":"Vâng, chúng tôi ra ngoài xem thêm môi trường xung quanh một chút."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài chủ nhà nói \"这个房子有两个房间，那个大房间出租，房租每月5500元。\" (Căn nhà này có hai phòng, cho thuê phòng lớn kia, tiền thuê mỗi tháng 5500 tệ).","options":["两个房间都出租，每月5500元","那个大房间出租，每月5500元","那个小房间出租，每月5000元","整套房子出租，每月6500元"],"q":"房东要出租哪个房间，房租是多少？"},{"answerIdx":0,"explanation":"Trong bài Bạch Gia Nguyệt nói \"小区离我们学校也不远\" (Khu chung cư cách trường chúng tôi cũng không xa) và chủ nhà nói \"我们小区离地铁站也很近\" (Khu chung cư của chúng tôi cũng rất gần ga tàu điện ngầm).","options":["离学校不远，离地铁站也很近","离学校很近，但附近没有地铁站","离地铁站很近，但离学校非常远","在市中心外面，买东西不太方便"],"q":"关于这个小区的位置，下面哪项符合对话内容？"}],"scene":"白家月想租房，李文陪白家月去看房。","sceneVi":"Bạch Gia Nguyệt muốn thuê nhà, Lý Văn đi cùng Bạch Gia Nguyệt đi xem nhà."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"家月，你看，那边还有个小花园。","pinyin":"Jiāyuè, nǐ kàn, nàbian hái yǒu gè xiǎo huāyuán.","speaker":"李文","vi":"Gia Nguyệt, cậu nhìn kìa, bên kia còn có một vườn hoa nhỏ nữa."},{"hanzi":"嗯，这个小区到处是花，还种了不少树，周围也很安静。","pinyin":"Ǹg, zhège xiǎoqū dàochù shì huā, hái zhòng le bùshǎo shù, zhōuwéi yě hěn ānjìng.","speaker":"白家月","vi":"Ừm, khu chung cư này khắp nơi đều có hoa, còn trồng không ít cây, xung quanh cũng rất yên tĩnh."},{"hanzi":"是啊！这个小区的环境真不错，不过我听说，附近有十几家公司，很多刚毕业的学生都租住在这里。周末他们可能会玩到很晚，恐怕会影响你休息。","pinyin":"Shì a! Zhège xiǎoqū de huánjìng zhēn búcuò, búguò wǒ tīngshuō, fùjìn yǒu shíjǐ jiā gōngsī, hěnduō gāng bìyè de xuésheng dōu zūzhù zài zhèlǐ. Zhōumò tāmen kěnéng huì wán dào hěn wǎn, kǒngpà huì yǐngxiǎng nǐ xiūxi.","speaker":"李文","vi":"Đúng thế! Môi trường khu này thật sự rất ổn, nhưng mình nghe nói gần đây có hơn chục công ty, rất nhiều sinh viên mới tốt nghiệp đều thuê ở đây. Cuối tuần họ có thể sẽ vui chơi đến rất muộn, e là sẽ ảnh hưởng đến việc nghỉ ngơi của cậu."},{"hanzi":"没关系，我还想多认识一些朋友，和他们一起玩呢。","pinyin":"Méi guānxi, wǒ hái xiǎng duō rènshi yìxiē péngyou, hé tāmen yìqǐ wán ne.","speaker":"白家月","vi":"Không sao đâu, mình còn muốn quen thêm một vài người bạn, cùng chơi với họ nữa cơ."},{"hanzi":"是呢，大家可以一起热闹热闹。","pinyin":"Shì ne, dàjiā kěyǐ yìqǐ rènao rènao.","speaker":"李文","vi":"Đúng đấy, mọi người có thể cùng nhau vui vẻ náo nhiệt."},{"hanzi":"这里房租合适，环境很好，而且房东也热情，所以我决定租这个房子了，明天就入住新家。","pinyin":"Zhèlǐ fángzū héshì, huánjìng hěn hǎo, érqiě fángdōng yě rèqíng, suǒyǐ wǒ juédìng zū zhège fángzi le, míngtiān jiù rùzhù xīnjiā.","speaker":"白家月","vi":"Tiền thuê ở đây hợp lý, môi trường rất tốt, hơn nữa chủ nhà cũng nhiệt tình, vì vậy mình quyết định thuê căn nhà này rồi, ngày mai sẽ dọn vào nhà mới."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài Lý Văn nói \"附近有十几家公司，很多刚毕业的学生都租住在这里。周末他们可能会玩到很晚，恐怕会影响你休息。\" (Gần đây có hơn chục công ty, nhiều sinh viên mới tốt nghiệp thuê ở đây. Cuối tuần họ có thể chơi rất khuya, e rằng sẽ ảnh hưởng đến việc nghỉ ngơi của bạn).","options":["因为小花园周末总是有人吵架","因为小区旁边有十几家大商场","因为附近住的刚毕业的学生周末可能玩到很晚","因为房东周末经常在家里请朋友吃饭"],"q":"李文为什么担心周末可能会影响白家月休息？"},{"answerIdx":2,"explanation":"Trong bài Bạch Gia Nguyệt nói \"这里房租合适，环境很好，而且房东也热情，所以我决定租这个房子了，明天就入住新家。\" (Tiền thuê ở đây hợp lý, môi trường rất tốt, hơn nữa chủ nhà cũng nhiệt tình, nên tôi quyết định thuê căn nhà này, ngày mai dọn vào nhà mới luôn).","options":["因为只住两天，今天就搬进去","因为房租便宜、离公司近，下周一搬进去","因为房租合适、环境好、房东热情，明天入住","因为李文也住在这个小区，下个月一起入住"],"q":"白家月为什么决定租这个房子，什么时候搬进去？"}],"scene":"在小区里，白家月和李文继续查看周围环境。","sceneVi":"Trong khu chung cư, Bạch Gia Nguyệt và Lý Văn tiếp tục xem xét môi trường xung quanh."},{"id":3,"isNarrative":true,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"8月25日，晴","pinyin":"Bā yuè èrshíwǔ rì, qíng","speaker":"Đoạn văn","vi":"Ngày 25 tháng 8, trời nắng"},{"hanzi":"昨天我顺利租到了合适的房子，今天李文帮我搬家。","pinyin":"Zuótiān wǒ shùnlì zūdào le héshì de fángzi, jīntiān Lǐ Wén bāng wǒ bānjiā.","speaker":"Đoạn văn","vi":"Hôm qua mình đã thuận lợi thuê được căn nhà phù hợp, hôm nay Lý Văn giúp mình chuyển nhà."},{"hanzi":"搬进去的时候，房东又向我介绍了一下房子里的东西，并告诉我这些东西怎么用。","pinyin":"Bān jìnqù de shíhou, fángdōng yòu xiàng wǒ jièshào le yíxià fángzi lǐ de dōngxi, bìng gàosu wǒ zhèxiē dōngxi zěnme yòng.","speaker":"Đoạn văn","vi":"Lúc dọn vào, chủ nhà lại giới thiệu cho mình một lượt đồ đạc trong nhà, đồng thời chỉ cho mình cách sử dụng những đồ dùng đó."},{"hanzi":"我看了一下，客厅里有椅子、沙发，还有一台大电视；厨房里有冰箱和一些做饭用的东西，不过，我平常主要在学校食堂吃，基本上不做饭。","pinyin":"Wǒ kàn le yíxià, kètīng lǐ yǒu yǐzi, shāfā, hái yǒu yì tái dà diànshì; chúfáng lǐ yǒu bīngxiāng hé yìxiē zuòfàn yòng de dōngxi, búguò, wǒ píngcháng zhǔyào zài xuéxiào shítáng chī, jīběnshàng bú zuòfàn.","speaker":"Đoạn văn","vi":"Mình xem qua một lượt, trong phòng khách có ghế, ghế sofa, còn có một chiếc tivi lớn; trong bếp có tủ lạnh và một số đồ dùng nấu ăn, tuy nhiên bình thường mình chủ yếu ăn ở nhà ăn trường học, hầu như không nấu cơm."},{"hanzi":"我租的房间里，除了一张床以外，还有一台空调、一张书桌和一把椅子。","pinyin":"Wǒ zū de fángjiān lǐ, chúle yì zhāng chuáng yǐwài, hái yǒu yì tái kōngtiáo, yì zhāng shūzhuō hé yì bǎ yǐzi.","speaker":"Đoạn văn","vi":"Trong phòng mình thuê, ngoài một chiếc giường ra, còn có một chiếc điều hòa, một cái bàn học và một chiếc ghế."},{"hanzi":"看完整个房子后，我准备再去买几条毛巾，其他东西还不需要。","pinyin":"Kànwán zhěnggè fángzi hòu, wǒ zhǔnbèi zài qù mǎi jǐ tiáo máojīn, qítā dōngxi hái bù xūyào.","speaker":"Đoạn văn","vi":"Sau khi xem xong toàn bộ căn nhà, mình định đi mua thêm mấy chiếc khăn mặt, những thứ khác thì vẫn chưa cần."}],"readingQuiz":[{"answerIdx":3,"explanation":"Trong nhật ký có câu \"我租的房间里，除了一张床以外，还有一台空调、一张书桌和一把椅子。\" (Trong căn phòng tôi thuê, ngoài một chiếc giường ra, còn có một máy điều hòa, một bàn học và một cái ghế).","options":["客厅里有床、沙发和冰箱","白家月租的房间里有空调、书桌和电视","厨房里什么做饭用的东西都没有","白家月租的房间里有床、空调、书桌和椅子"],"q":"关于房子里的东西，下面哪一项是对的？"},{"answerIdx":1,"explanation":"Trong bài có câu \"我平常主要在学校食堂吃，基本上不做饭\" (Bình thường tôi chủ yếu ăn ở căng tin trường, cơ bản không nấu cơm) và \"我准备再去买几条毛巾，其他东西还不需要\" (Tôi định đi mua thêm mấy chiếc khăn mặt, các đồ khác vẫn chưa cần).","options":["每天自己做饭，打算去买冰箱和椅子","主要在学校食堂吃，打算再去买几条毛巾","主要在外面饭馆吃，打算买一台新电视","经常在李文家吃，什么东西都不需要买"],"q":"白家月平常在哪儿吃饭，搬家后还打算买什么？"}],"scene":"搬进新家后，白家月很开心，写了一篇日记。","sceneVi":"Sau khi dọn vào nhà mới, Bạch Gia Nguyệt rất vui và đã viết một bài nhật ký."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"在李文的帮助下，白家月租到了合适的房子。","pinyin":"Zài Lǐ Wén de bāngzhù xià, Bái Jiāyuè zūdào le héshì de fángzi.","speaker":"Đoạn văn","vi":"Nhờ sự giúp đỡ của Lý Văn, Bạch Gia Nguyệt đã thuê được căn nhà phù hợp."},{"hanzi":"对白家月来说，这次租房并不容易。","pinyin":"Duì Bái Jiāyuè láishuō, zhè cì zūfáng bìng bù róngyì.","speaker":"Đoạn văn","vi":"Đối với Bạch Gia Nguyệt, lần thuê nhà này quả thực không dễ dàng."},{"hanzi":"根据李文的建议，她先在租房网站和App上查看有关信息，查找合适的房子，接着又去看了看房子，同时了解房子周围的环境。","pinyin":"Gēnjù Lǐ Wén de jiànyì, tā xiān zài zūfáng wǎngzhàn hé App shàng chákàn yǒuguān xìnxī, cházhǎo héshì de fángzi, jiēzhe yòu qù kàn le kàn fángzi, tóngshí liǎojiě fángzi zhōuwéi de huánjìng.","speaker":"Đoạn văn","vi":"Theo lời khuyên của Lý Văn, cô ấy trước tiên xem thông tin liên quan trên các trang web và ứng dụng thuê nhà để tìm căn nhà phù hợp, tiếp theo đến xem nhà trực tiếp, đồng thời tìm hiểu môi trường xung quanh căn nhà."},{"hanzi":"她看了好几个房子，才找到一个位置、环境和价格都合适的，最后顺利租到了理想的房子。","pinyin":"Tā kàn le hǎojǐ gè fángzi, cái zhǎodào yí gè wèizhì, huánjìng hé jiàgé dōu héshì de, zuìhòu shùnlì zūdào le lǐxiǎng de fángzi.","speaker":"Đoạn văn","vi":"Cô ấy đã xem khá nhiều căn nhà mới tìm được một căn có vị trí, môi trường và giá cả đều phù hợp, cuối cùng đã thuận lợi thuê được căn nhà lý tưởng."},{"hanzi":"租房的时候，李文告诉白家月，在中国，由于很多刚工作的年轻人工资还不太高，所以他们一开始也不买房，都选择租房。","pinyin":"Zūfáng de shíhou, Lǐ Wén gàosu Bái Jiāyuè, zài Zhōngguó, yóuyú hěnduō gāng gōngzuò de niánqīngrén gōngzī hái bú tài gāo, suǒyǐ tāmen yì kāishǐ yě bù mǎifáng, dōu xuǎnzé zūfáng.","speaker":"Đoạn văn","vi":"Khi thuê nhà, Lý Văn nói với Bạch Gia Nguyệt rằng ở Trung Quốc, do lương của nhiều bạn trẻ mới đi làm chưa cao lắm nên ban đầu họ đều không mua nhà mà chọn thuê nhà."},{"hanzi":"工作几年后，不少人就会买房，因为大家一直觉得，有房才有家，有自己的房子会更有安全感。","pinyin":"Gōngzuò jǐ nián hòu, bùshǎo rén jiù huì mǎifáng, yīnwèi dàjiā yìzhí juéde, yǒu fáng cái yǒu jiā, yǒu zìjǐ de fángzi huì gèng yǒu ānquángǎn.","speaker":"Đoạn văn","vi":"Sau vài năm đi làm, không ít người sẽ mua nhà, bởi vì mọi người luôn cảm thấy có nhà mới có gia đình, có căn nhà của riêng mình sẽ có cảm giác an toàn hơn."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài có câu \"她先在租房网站和App上查看有关信息，查找合适的房子，接着又去看了看房子，同时了解房子周围的环境。\" (Cô ấy trước tiên xem thông tin liên quan trên trang web và ứng dụng thuê nhà, tìm căn phù hợp, tiếp đó lại đi xem nhà, đồng thời tìm hiểu môi trường xung quanh).","options":["先在租房网站和软件上查信息，再去实地看房和了解周围环境","只看了一套房子就立刻决定租下来了","请房东先发照片，没有去现场看周围环境","完全让李文帮她选好房子并签了合同"],"q":"白家月这次是怎么找到理想房子的？"},{"answerIdx":2,"explanation":"Trong bài có câu \"工作几年后，不少人就会买房，因为大家一直觉得，有房才有家，有自己的房子会更有安全感。\" (Sau khi đi làm vài năm, không ít người sẽ mua nhà, vì mọi người luôn cảm thấy có nhà mới có gia đình, có nhà của riêng mình sẽ có cảm giác an toàn hơn).","options":["因为租房比买房的价格贵得多","因为学校要求毕业后必须买房","因为他们觉得有房才有家，更有安全感","因为刚工作时工资很高，已经存够了钱"],"q":"在中国，为什么不少人工作几年后会选择买房？"}],"scene":"怎样租到合适的房子","sceneVi":"Làm thế nào để thuê được căn nhà phù hợp"}],"hsk4a-3":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"请问，花园小区怎么走？","pinyin":"Qǐngwèn, Huāyuán Xiǎoqū zěnme zǒu?","speaker":"陈天中","vi":"Xin hỏi, Khu dân cư Hoa Viên đi thế nào ạ?"},{"hanzi":"你往前走，到十字路口不要过马路，直接右转就到小区门口了。正好我也去那边，一起走吧。","pinyin":"Nǐ wǎng qián zǒu, dào shízì lùkǒu búyào guò mǎlù, zhíjiē yòu zhuǎn jiù dào xiǎoqū ménkǒu le. Zhènghǎo wǒ yě qù nàbiān, yìqǐ zǒu ba.","speaker":"同学","vi":"Bạn đi thẳng về phía trước, đến ngã tư đừng qua đường, rẽ phải luôn là tới cổng khu dân cư rồi. Vừa hay mình cũng đi hướng đó, đi cùng nhé."},{"hanzi":"好的。我刚来中国，不熟悉路。北京真是太大了。","pinyin":"Hǎo de. Wǒ gāng lái Zhōngguó, bù shúxi lù. Běijīng zhēnshi tài dà le.","speaker":"陈天中","vi":"Được ạ. Mình mới đến Trung Quốc, chưa quen đường. Bắc Kinh thật sự rộng quá."},{"hanzi":"北京大是大，不过这边的路基本上都是正南正北、正东正西的，很好找。你也可以用手机地图，很容易就能找到目的地。","pinyin":"Běijīng dà shì dà, búguò zhèbiān de lù jīběnshang dōu shì zhèngnán zhèngběi, zhèngdōng zhèngxī de, hěn hǎo zhǎo. Nǐ yě kěyǐ yòng shǒujī dìtú, hěn róngyì jiù néng zhǎodào mùdìdì.","speaker":"同学","vi":"Bắc Kinh rộng thì rộng thật, nhưng đường ở đây về cơ bản đều theo hướng chính nam chính bắc, chính đông chính tây, rất dễ tìm. Bạn cũng có thể dùng bản đồ trên điện thoại, rất dễ dàng tìm được điểm đến."},{"hanzi":"嗯，不过很多中文地名我还不认识。","pinyin":"Ǹg, búguò hěnduō Zhōngwén dìmíng wǒ hái bú rènshi.","speaker":"陈天中","vi":"Ừ, nhưng mà nhiều tên địa danh tiếng Trung mình vẫn chưa biết mặt chữ."},{"hanzi":"没关系，你很快就会熟悉的。","pinyin":"Méi guānxi, nǐ hěn kuài jiù huì shúxi de.","speaker":"同学","vi":"Không sao đâu, bạn sẽ nhanh chóng quen thôi."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài bạn học chỉ đường \"你往前走，到十字路口不要过马路，直接右转就到小区门口了。\" (Bạn đi thẳng về phía trước, đến ngã tư đừng qua đường, rẽ phải ngay là tới cổng khu dân cư rồi).","options":["往前走，过了十字路口再左转","往前走，到十字路口不过马路直接右转","先往后走，看到小花园再过马路","坐地铁到下一站，出站后左转"],"q":"按照同学的指路，陈天中怎么走到花园小区？"},{"answerIdx":2,"explanation":"Trong bài Trần Thiên Trung nói \"嗯，不过很多中文地名我还不认识。\" (Ừ, nhưng nhiều tên địa danh tiếng Trung mình vẫn chưa biết mặt chữ).","options":["因为他的手机停机了，没有信号","因为北京的路都不是正南正北的","因为很多中文地名他还不认识","因为他的手机里还没有下载地图软件"],"q":"陈天中为什么觉得用手机地图还是不太容易？"}],"scene":"一天，陈天中从学校出来迷路了，就向一位同学问路。","sceneVi":"Một ngày nọ, Trần Thiên Trung từ trường đi ra bị lạc đường nên đã hỏi đường một bạn học."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"前两天和李文喝咖啡时，他帮我下载了微信和支付宝，教我认识里边的汉字，还教我用手机进行支付。","pinyin":"Qián liǎng tiān hé Lǐ Wén hē kāfēi shí, tā bāng wǒ xiàzài le Wēixìn hé Zhīfùbǎo, jiāo wǒ rènshi lǐbiān de Hànzì, hái jiāo wǒ yòng shǒujī jìnxíng zhīfù.","speaker":"陈天中","vi":"Mấy hôm trước lúc uống cà phê với Lý Văn, cậu ấy đã giúp mình tải WeChat và Alipay, dạy mình nhận biết chữ Hán bên trong, còn dạy mình thanh toán bằng điện thoại nữa."},{"hanzi":"他也教了我怎么用这两个软件。","pinyin":"Tā yě jiāo le wǒ zěnme yòng zhè liǎng gè ruǎnjiàn.","speaker":"白家月","vi":"Cậu ấy cũng dạy mình cách dùng hai phần mềm này đấy."},{"hanzi":"现在我不仅会扫码结账，还会用手机在网上购物了。昨天我就在网上订了一台电脑，今天下午一点送到。","pinyin":"Xiànzài wǒ bùjǐn huì sǎomǎ jiézhàng, hái huì yòng shǒujī zài wǎngshàng gòuwù le. Zuótiān wǒ jiù zài wǎngshàng dìng le yì tái diànnǎo, jīntiān xiàwǔ yì diǎn sòngdào.","speaker":"陈天中","vi":"Bây giờ mình không những biết quét mã thanh toán mà còn biết dùng điện thoại mua sắm trực tuyến rồi. Hôm qua mình vừa đặt mua một chiếc máy tính trên mạng, chiều nay một giờ sẽ giao tới."},{"hanzi":"学会了这些，我们在中国生活真是方便了不少。","pinyin":"Xuéhuì le zhèxiē, wǒmen zài Zhōngguó shēnghuó zhēnshi fāngbiàn le bùshǎo.","speaker":"白家月","vi":"Học được những thứ này, cuộc sống của chúng ta ở Trung Quốc thật sự tiện lợi hơn rất nhiều."},{"hanzi":"对。快递员要到了，我得马上回去！家月，明天见！","pinyin":"Duì. Kuàidìyuán yào dào le, wǒ děi mǎshàng huíqu! Jiāyuè, míngtiān jiàn!","speaker":"陈天中","vi":"Đúng vậy. Nhân viên giao hàng sắp tới rồi, mình phải về ngay đây! Gia Nguyệt, mai gặp nhé!"},{"hanzi":"好的，天中，再见。","pinyin":"Hǎo de, Tiānzhōng, zàijiàn.","speaker":"白家月","vi":"Được, Thiên Trung, tạm biệt."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Trần Thiên Trung nói \"他帮我下载了微信和支付宝，教我认识里边的汉字，还教我用手机进行支付。\" (Anh ấy đã giúp mình tải WeChat và Alipay, dạy mình nhận mặt chữ Hán bên trong, còn dạy mình thanh toán bằng điện thoại).","options":["教他怎么在学校食堂点菜和付款","帮他下载微信和支付宝，教他认字和手机支付","帮他在网上修好了一台旧电脑","教他怎么在网站上找房子和签合同"],"q":"前两天和李文喝咖啡时，李文教了陈天中什么？"},{"answerIdx":3,"explanation":"Trong bài Trần Thiên Trung nói \"昨天我就在网上订了一台电脑，今天下午一点送到\" và \"快递员要到了，我得马上回去！\" (Hôm qua mình đặt mua một chiếc máy tính trên mạng, 1 giờ chiều nay giao tới... Nhân viên giao hàng sắp đến rồi, mình phải về ngay!).","options":["因为下午一点他还有一节中文课","因为他约了李文再去喝咖啡","因为他忘了带手机和现金结账","因为他昨天订的电脑快递员要送到了"],"q":"陈天中为什么着急跟白家月说再见、马上回去？"}],"scene":"中午下课后，白家月和陈天中在学校食堂相遇，两人边吃饭边聊天儿。","sceneVi":"Buổi trưa sau khi tan học, Bạch Gia Nguyệt và Trần Thiên Trung gặp nhau ở nhà ăn trường học, hai người vừa ăn cơm vừa trò chuyện."},{"id":3,"isNarrative":true,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"白家月和陈天中刚到北京时就发现，中国人在饭馆或超市结账时，几乎都用手机支付，只有他们用现金结账。","pinyin":"Bái Jiāyuè hé Chén Tiānzhōng gāng dào Běijīng shí jiù fāxiàn, Zhōngguórén zài fànguǎn huò chāoshì jiézhàng shí, jīhū dōu yòng shǒujī zhīfù, zhǐyǒu tāmen yòng xiànjīn jiézhàng.","speaker":"Đoạn văn","vi":"Bạch Gia Nguyệt và Trần Thiên Trung khi mới đến Bắc Kinh liền phát hiện người Trung Quốc khi thanh toán ở nhà hàng hay siêu thị hầu như đều trả bằng điện thoại, chỉ có họ dùng tiền mặt."},{"hanzi":"在李文的帮助下，白家月和陈天中也都学会了用手机支付、网购、寄快递等等。","pinyin":"Zài Lǐ Wén de bāngzhù xià, Bái Jiāyuè hé Chén Tiānzhōng yě dōu xuéhuì le yòng shǒujī zhīfù, wǎnggòu, jì kuàidì děngděng.","speaker":"Đoạn văn","vi":"Dưới sự giúp đỡ của Lý Văn, Bạch Gia Nguyệt và Trần Thiên Trung cũng đều học được cách thanh toán bằng điện thoại, mua sắm trực tuyến, gửi chuyển phát nhanh, v.v."},{"hanzi":"在中国网购，不仅选择多、价格不高，而且送货很快，很多留学生甚至改变了自己的购物习惯。","pinyin":"Zài Zhōngguó wǎnggòu, bùjǐn xuǎnzé duō, jiàgé bù gāo, érqiě sònghuò hěn kuài, hěnduō liúxuéshēng shènzhì gǎibiàn le zìjǐ de gòuwù xíguàn.","speaker":"Đoạn văn","vi":"Mua sắm trực tuyến ở Trung Quốc không chỉ nhiều lựa chọn, giá cả phải chăng mà giao hàng còn rất nhanh, nhiều du học sinh thậm chí đã thay đổi thói quen mua sắm của mình."},{"hanzi":"不过，由于网购太方便了，动动手指就能买到想要的东西，他们也开始担心自己在网购时会乱花钱。","pinyin":"Búguò, yóuyú wǎnggòu tài fāngbiàn le, dòngdong shǒuzhǐ jiù néng mǎidào xiǎng yào de dōngxi, tāmen yě kāishǐ dānxīn zìjǐ zài wǎnggòu shí huì luàn huā qián.","speaker":"Đoạn văn","vi":"Tuy nhiên, vì mua sắm trực tuyến quá tiện lợi, chỉ cần cử động ngón tay là có thể mua được món đồ mình muốn, nên họ cũng bắt đầu lo lắng bản thân sẽ tiêu tiền bừa bãi khi mua hàng online."},{"hanzi":"怎么才能管住自己不乱花钱呢？","pinyin":"Zěnme cái néng guǎnzhù zìjǐ bú luàn huā qián ne?","speaker":"Đoạn văn","vi":"Làm thế nào để kiềm chế bản thân không tiêu tiền bừa bãi đây?"}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"中国人在饭馆或超市结账时，几乎都用手机支付，只有他们用现金结账。\" (Người Trung Quốc khi thanh toán ở nhà hàng hoặc siêu thị hầu như đều dùng điện thoại trả tiền, chỉ có hai bạn ấy dùng tiền mặt).","options":["饭馆和超市都不收手机支付，只收现金","中国人几乎都用手机支付，只有他们用现金","所有留学生都已经习惯用手机寄快递了","中国人在超市买东西时不用排队结账"],"q":"刚到北京时，白家月和陈天中在结账时发现了什么？"},{"answerIdx":2,"explanation":"Trong bài có câu \"由于网购太方便了，动动手指就能买到想要的东西，他们也开始担心自己在网购时会乱花钱。\" (Do mua sắm trực tuyến quá tiện lợi, chỉ cần nhúc nhích ngón tay là mua được thứ mình muốn, nên họ cũng bắt đầu lo lắng mình sẽ tiêu tiền bừa bãi khi mua sắm online).","options":["因为网购的东西价格都比商店贵很多","因为网购时快递费非常高","因为网购太方便，动动手指就能买到想要的东西","因为父母每个月给他们的钱太多了"],"q":"为什么他们开始担心自己在网购时会乱花钱？"}],"scene":"生活新体验","sceneVi":"Trải nghiệm cuộc sống mới"},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"网上购物或者订票时，我们经常需要提供姓名、手机号、身份证号等个人信息。","pinyin":"Wǎngshàng gòuwù huòzhě dìng piào shí, wǒmen jīngcháng xūyào tígōng xìngmíng, shǒujī hào, shēnfènzhèng hào děng gèrén xìnxī.","speaker":"Đoạn văn","vi":"Khi mua sắm trực tuyến hoặc đặt vé, chúng ta thường xuyên cần cung cấp thông tin cá nhân như họ tên, số điện thoại, số căn cước công dân."},{"hanzi":"在提供这些信息时，我们也会担心：我的个人信息能否得到保护？","pinyin":"Zài tígōng zhèxiē xìnxī shí, wǒmen yě huì dānxīn: wǒ de gèrén xìnxī néngfǒu dédào bǎohù?","speaker":"Đoạn văn","vi":"Khi cung cấp những thông tin này, chúng ta cũng sẽ lo lắng: liệu thông tin cá nhân của mình có được bảo vệ hay không?"},{"hanzi":"于是，有人在网上说出了自己的担心，很快就有人给出了一些建议。","pinyin":"Yúshì, yǒurén zài wǎngshàng shuōchū le zìjǐ de dānxīn, hěn kuài jiù yǒurén gěichū le yìxiē jiànyì.","speaker":"Đoạn văn","vi":"Thế là có người đã nói lên nỗi lo của mình trên mạng, rất nhanh sau đó đã có người đưa ra một số lời khuyên."},{"hanzi":"比如，别把密码随便告诉别人，不在网上发自己的车票、机票信息……","pinyin":"Bǐrú, bié bǎ mìmǎ suíbiàn gàosu biérén, bú zài wǎngshàng fā zìjǐ de chēpiào, jīpiào xìnxī……","speaker":"Đoạn văn","vi":"Ví dụ như đừng tùy tiện nói mật khẩu cho người khác, không đăng thông tin vé tàu, vé máy bay của mình lên mạng..."},{"hanzi":"现在，很多国家也通过技术、法律等手段来保证个人信息安全。","pinyin":"Xiànzài, hěnduō guójiā yě tōngguò jìshù, fǎlǜ děng shǒuduàn lái bǎozhèng gèrén xìnxī ānquán.","speaker":"Đoạn văn","vi":"Hiện nay, nhiều quốc gia cũng thông qua các biện pháp như công nghệ, pháp luật để bảo đảm an toàn thông tin cá nhân."},{"hanzi":"比如中国的网络安全法、个人信息保护法等就很好地保护了人们的个人信息。","pinyin":"Bǐrú Zhōngguó de Wǎngluò Ānquán Fǎ, Gèrén Xìnxī Bǎohù Fǎ děng jiù hěn hǎo de bǎohù le rénmen de gèrén xìnxī.","speaker":"Đoạn văn","vi":"Ví dụ như Luật An ninh mạng, Luật Bảo vệ thông tin cá nhân của Trung Quốc đã bảo vệ rất tốt thông tin cá nhân của người dân."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"比如，别把密码随便告诉别人，不在网上发自己的车票、机票信息……\" (Ví dụ như đừng tùy tiện nói mật khẩu cho người khác, không đăng thông tin vé tàu, vé máy bay của mình lên mạng...).","options":["网上买东西时不要写自己的姓名","不要把密码随便告诉别人，不在网上发车票信息","买完机票后要把照片发到网上留作纪念","千万不要用手机在网上订票或购物"],"q":"为了保护个人信息，下面哪项是文中提到的建议？"},{"answerIdx":0,"explanation":"Trong bài có câu \"现在，很多国家也通过技术、法律等手段来保证个人信息安全。\" (Hiện nay, nhiều quốc gia cũng thông qua các biện pháp như kỹ thuật, pháp luật... để bảo đảm an toàn thông tin cá nhân).","options":["技术、法律等手段","只允许用现金购物","禁止大家在网上订车票","让每个人都更换新手机号"],"q":"现在很多国家主要通过什么手段来保证个人信息安全？"}],"scene":"用手机时如何保护个人信息","sceneVi":"Làm thế nào để bảo vệ thông tin cá nhân khi sử dụng điện thoại"}],"hsk4a-4":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"啊，我的手机停机了！怎么办啊？","pinyin":"Ā, wǒ de shǒujī tíngjī le! Zěnme bàn a?","speaker":"陈天中","vi":"Á, điện thoại của mình bị khóa mạng rồi! Làm sao bây giờ?"},{"hanzi":"你好，你看上去很着急，需要帮忙吗？","pinyin":"Nǐ hǎo, nǐ kànshàngqu hěn zháojí, xūyào bāngmáng ma?","speaker":"路人","vi":"Chào bạn, trông bạn rất vội, có cần giúp gì không?"},{"hanzi":"我忘了交电话费，手机停机了。我没带现金，手机没有信号，上不了网，买不了地铁票了。","pinyin":"Wǒ wàng le jiāo diànhuàfèi, shǒujī tíngjī le. Wǒ méi dài xiànjīn, shǒujī méiyǒu xìnhào, shàngbuliǎo wǎng, mǎibuliǎo dìtiěpiào le.","speaker":"陈天中","vi":"Mình quên đóng tiền điện thoại nên bị khóa máy rồi. Mình lại không mang tiền mặt, điện thoại không có sóng, không lên mạng được, không mua được vé tàu điện ngầm nữa rồi."},{"hanzi":"你要去哪儿？我帮你买张票。","pinyin":"Nǐ yào qù nǎr? Wǒ bāng nǐ mǎi zhāng piào.","speaker":"路人","vi":"Bạn muốn đi đâu? Mình mua giúp bạn một tấm vé."},{"hanzi":"太感谢你了，我要去北京大学站。对了，能不能告诉我你的联系方式？我想把钱还给你。","pinyin":"Tài gǎnxiè nǐ le, wǒ yào qù Běijīng Dàxué Zhàn. Duìle, néng bu néng gàosu wǒ nǐ de liánxì fāngshì? Wǒ xiǎng bǎ qián huángěi nǐ.","speaker":"陈天中","vi":"Cảm ơn bạn nhiều lắm, mình muốn đến ga Đại học Bắc Kinh. À đúng rồi, bạn có thể cho mình biết thông tin liên hệ được không? Mình muốn trả lại tiền cho bạn."},{"hanzi":"别客气，很高兴能帮到你。","pinyin":"Bié kèqi, hěn gāoxìng néng bāngdào nǐ.","speaker":"路人","vi":"Đừng khách sáo, rất vui vì đã giúp được bạn."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài Trần Thiên Trung nói \"我忘了交电话费，手机停机了。我没带现金，手机没有信号，上不了网，买不了地铁票了。\" (Mình quên nộp tiền điện thoại nên máy bị khóa chiều. Mình không mang tiền mặt, điện thoại không có sóng, không lên mạng được, không mua được vé tàu điện ngầm nữa).","options":["因为地铁站的自动售票机坏了","因为他忘了交电话费导致手机停机，又没带现金","因为他不知道北京大学站在哪一条线上","因为他的钱包和手机在路上弄丢了"],"q":"陈天中为什么买不了地铁票？"},{"answerIdx":1,"explanation":"Trong bài Trần Thiên Trung nói \"对了，能不能告诉我你的联系方式？我想把钱还给你。\" (À đúng rồi, bạn có thể cho mình biết thông tin liên hệ của bạn không? Mình muốn trả lại tiền cho bạn).","options":["因为他想请路人教他用中文买票","因为他想以后把买票的钱还给路人","因为他想邀请路人一起去北京大学玩","因为他想借路人的手机给李文打电话"],"q":"陈天中为什么想问路人的联系方式？"}],"scene":"在地铁站，陈天中准备买票进站。","sceneVi":"Ở ga tàu điện ngầm, Trần Thiên Trung chuẩn bị mua vé vào ga."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"阿姨，您怎么站在这儿不上楼？","pinyin":"Āyí, nín zěnme zhàn zài zhèr bú shànglóu?","speaker":"白家月","vi":"Cô ơi, sao cô đứng ở đây mà chưa lên lầu ạ?"},{"hanzi":"我开车去超市买了不少东西，刚拿过来了一些。我先休息一会儿，再去车里拿剩下的。","pinyin":"Wǒ kāichē qù chāoshì mǎi le bùshǎo dōngxi, gāng ná guòlái le yìxiē. Wǒ xiān xiūxi yíhuìr, zài qù chē lǐ ná shèngxià de.","speaker":"邻居","vi":"Cô lái xe đi siêu thị mua khá nhiều đồ, vừa mới mang qua một ít. Cô nghỉ một lát rồi ra xe lấy nốt số còn lại."},{"hanzi":"我正好要上楼，我帮您提上去吧。","pinyin":"Wǒ zhènghǎo yào shànglóu, wǒ bāng nín tí shàngqù ba.","speaker":"白家月","vi":"Cháu vừa hay cũng định lên lầu, để cháu xách lên giúp cô nhé."},{"hanzi":"不用不用，这几个袋子太重了，我自己拿吧。","pinyin":"Búyòng búyòng, zhè jǐ gè dàizi tài zhòng le, wǒ zìjǐ ná ba.","speaker":"邻居","vi":"Không cần đâu, mấy túi này nặng lắm, để cô tự mang."},{"hanzi":"没事，我提着这些东西就算锻炼身体了，再说邻居之间就是要互相帮助啊。","pinyin":"Méishì, wǒ tízhe zhèxiē dōngxi jiù suàn duànliàn shēntǐ le, zàishuō línjū zhījiān jiùshì yào hùxiāng bāngzhù a.","speaker":"白家月","vi":"Không sao đâu ạ, cháu xách mấy đồ này coi như rèn luyện sức khỏe luôn, vả lại hàng xóm với nhau vốn dĩ phải giúp đỡ lẫn nhau mà."},{"hanzi":"谢谢家月！那就辛苦你了。","pinyin":"Xièxie Jiāyuè! Nà jiù xīnkǔ nǐ le.","speaker":"邻居","vi":"Cảm ơn Gia Nguyệt nhé! Vậy làm phiền cháu rồi."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài cô hàng xóm nói \"我开车去超市买了不少东西，刚拿过来了一些。我先休息一会儿，再去车里拿剩下的。\" (Cô lái xe đi siêu thị mua khá nhiều đồ, vừa mới mang qua một ít. Cô nghỉ một lát trước rồi mới ra xe lấy số còn lại).","options":["因为她忘了带家里的钥匙","因为她在楼下等白家月一起回去","因为她买了不少东西，刚拿来一部分，想歇会儿再去车里拿剩下的","因为电梯坏了，她一个人提不动袋子"],"q":"邻居阿姨为什么站在楼下没有马上上楼？"},{"answerIdx":0,"explanation":"Trong bài Bạch Gia Nguyệt nói \"我提着这些东西就算锻炼身体了，再说邻居之间就是要互相帮助啊。\" (Cháu xách mấy đồ này coi như tập thể dục luôn, vả lại hàng xóm với nhau thì phải giúp đỡ lẫn nhau chứ ạ).","options":["她说她今天正好想锻炼身体，而且邻居之间应该互相帮助","她说自己家里也有一辆车可以帮忙搬","她说袋子其实一点儿也不重，自己力气很大","她说如果阿姨不让帮忙，她就不上楼了"],"q":"白家月说了什么让阿姨同意她帮忙提东西？"}],"scene":"在楼下，白家月遇到了住在同一层的邻居。","sceneVi":"Ở dưới lầu, Bạch Gia Nguyệt gặp người hàng xóm sống cùng tầng."},{"id":3,"isNarrative":true,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"在城市里，人们出行的方式越来越多。","pinyin":"Zài chéngshì lǐ, rénmen chūxíng de fāngshì yuèláiyuè duō.","speaker":"Đoạn văn","vi":"Ở trong thành phố, phương thức đi lại của mọi người ngày càng đa dạng."},{"hanzi":"短距离出行时，骑自行车往往是人们常见的选择。","pinyin":"Duǎn jùlí chūxíng shí, qí zìxíngchē wǎngwǎng shì rénmen chángjiàn de xuǎnzé.","speaker":"Đoạn văn","vi":"Khi di chuyển quãng đường ngắn, đạp xe đạp thường là lựa chọn phổ biến của mọi người."},{"hanzi":"白家月就很喜欢骑车去学校，她觉得这样既方便，又能锻炼身体，还能保护环境。","pinyin":"Bái Jiāyuè jiù hěn xǐhuan qíchē qù xuéxiào, tā juéde zhèyàng jì fāngbiàn, yòu néng duànliàn shēntǐ, hái néng bǎohù huánjìng.","speaker":"Đoạn văn","vi":"Bạch Gia Nguyệt rất thích đạp xe đi học, cô ấy thấy cách này vừa tiện lợi, vừa rèn luyện sức khỏe, lại còn bảo vệ môi trường."},{"hanzi":"除了骑自行车，人们还会选择骑电动车。","pinyin":"Chúle qí zìxíngchē, rénmen hái huì xuǎnzé qí diàndòngchē.","speaker":"Đoạn văn","vi":"Ngoài đạp xe đạp, mọi người còn chọn đi xe máy điện."},{"hanzi":"电动车速度快，价格不高，充电也很方便，所以越来越流行。","pinyin":"Diàndòngchē sùdù kuài, jiàgé bù gāo, chōngdiàn yě hěn fāngbiàn, suǒyǐ yuèláiyuè liúxíng.","speaker":"Đoạn văn","vi":"Xe máy điện tốc độ nhanh, giá cả không cao, sạc điện cũng rất tiện, vì vậy ngày càng phổ biến."},{"hanzi":"陈天中平时也骑自行车，不过为了省力气，他最近打算买一辆电动车。","pinyin":"Chén Tiānzhōng píngshí yě qí zìxíngchē, búguò wèile shěng lìqi, tā zuìjìn dǎsuàn mǎi yí liàng diàndòngchē.","speaker":"Đoạn văn","vi":"Trần Thiên Trung bình thường cũng đạp xe đạp, nhưng để đỡ tốn sức, gần đây cậu ấy dự định mua một chiếc xe máy điện."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"白家月就很喜欢骑车去学校，她觉得这样既方便，又能锻炼身体，还能保护环境。\" (Bạch Gia Nguyệt rất thích đạp xe đi học, bạn ấy thấy như vậy vừa tiện lợi, vừa rèn luyện sức khỏe, lại vừa bảo vệ môi trường).","options":["因为骑自行车速度最快，而且不用花钱","因为既方便，又能锻炼身体，还能保护环境","因为学校门口没有公交车站和地铁站","因为骑自行车比骑电动车更省力气"],"q":"白家月为什么喜欢骑自行车去学校？"},{"answerIdx":2,"explanation":"Trong bài có câu \"陈天中平时也骑自行车，不过为了省力气，他最近打算买一辆电动车。\" (Trần Thiên Trung bình thường cũng đạp xe, nhưng để đỡ tốn sức, gần đây cậu ấy dự định mua một chiếc xe điện).","options":["因为他的自行车刚刚坏了","因为骑电动车能帮他锻炼身体","因为骑电动车可以省力气","因为学校规定留学生不能骑自行车"],"q":"陈天中最近为什么打算买一辆电动车？"}],"scene":"短距离出行的新选择","sceneVi":"Lựa chọn mới cho việc di chuyển quãng đường ngắn"},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"在中国，乘客可以在不少地铁站里直接扫码购买食物和饮料，有的地铁站还提供免费借雨伞、发雨衣等服务。","pinyin":"Zài Zhōngguó, chéngkè kěyǐ zài bùshǎo dìtiězhàn lǐ zhíjiē sǎomǎ gòumǎi shíwù hé yǐnliào, yǒude dìtiězhàn hái tígōng miǎnfèi jiè yǔsǎn, fā yǔyī děng fúwù.","speaker":"Đoạn văn","vi":"Ở Trung Quốc, hành khách có thể trực tiếp quét mã mua đồ ăn và thức uống ngay tại nhiều ga tàu điện ngầm, một số ga còn cung cấp dịch vụ mượn ô miễn phí, phát áo mưa, v.v."},{"hanzi":"有些地铁站附近公司比较多，工作日站里还有早餐车，没来得及吃早饭的人在这里就能买到热包子和牛奶等，省了不少时间。","pinyin":"Yǒuxiē dìtiězhàn fùjìn gōngsī bǐjiào duō, gōngzuòrì zhàn lǐ hái yǒu zǎocānchē, méi láidejí chī zǎofàn de rén zài zhèlǐ jiù néng mǎidào rè bāozi hé niúnǎi děng, shěng le bùshǎo shíjiān.","speaker":"Đoạn văn","vi":"Một số ga tàu điện ngầm có khá nhiều công ty ở gần, vào ngày làm việc trong ga còn có xe bán đồ ăn sáng, những người chưa kịp ăn sáng có thể mua bánh bao nóng và sữa ở đây, tiết kiệm được rất nhiều thời gian."},{"hanzi":"有的地铁站里甚至还有鲜花店，乘客下班时可以顺便买花送给家人。","pinyin":"Yǒude dìtiězhàn lǐ shènzhì hái yǒu xiānhuādiàn, chéngkè xiàbān shí kěyǐ shùnbiàn mǎi huā sònggěi jiārén.","speaker":"Đoạn văn","vi":"Có ga tàu điện ngầm thậm chí còn có cả tiệm hoa tươi, hành khách khi tan làm có thể tiện đường mua hoa tặng cho người thân."},{"hanzi":"这些小小的服务，不仅方便了人们的出行，也让大家的心情变得更加愉快。","pinyin":"Zhèxiē xiǎoxiǎo de fúwù, bùjǐn fāngbiàn le rénmen de chūxíng, yě ràng dàjiā de xīnqíng biàndé gèngjiā yúkuài.","speaker":"Đoạn văn","vi":"Những dịch vụ nho nhỏ này không chỉ giúp việc đi lại của mọi người thêm thuận tiện mà còn khiến tâm trạng của mọi người trở nên vui vẻ hơn."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"有些地铁站附近公司比较多，工作日站里还有早餐车\" (Một số ga tàu điện ngầm có khá nhiều công ty ở gần đó, vào ngày làm việc trong ga còn có xe bán đồ ăn sáng).","options":["离大学校园很近的地铁站","附近公司比较多的地铁站","站里有鲜花店的地铁站","只有周末才开放的地铁站"],"q":"什么样的地铁站在工作日通常会有早餐车？"},{"answerIdx":3,"explanation":"Trong bài có nhắc đến quét mã mua đồ ăn thức uống (\"扫码购买食物和饮料\"), mượn ô/phát áo mưa miễn phí (\"免费借雨伞、发雨衣\") và tiệm hoa tươi (\"鲜花店\"), hoàn toàn không nhắc đến dịch vụ sửa xe đạp miễn phí.","options":["扫码购买食物和饮料","免费借雨伞或者发雨衣","下班时在鲜花店买花送家人","免费帮乘客修理自行车"],"q":"关于中国地铁站里的服务，下面哪一项文中没有提到？"}],"scene":"地铁站里的贴心服务","sceneVi":"Dịch vụ chu đáo trong ga tàu điện ngầm"}],"hsk4a-5":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"家月，你来中国至少两个月了，习惯吃中餐了吗？","pinyin":"Jiāyuè, nǐ lái Zhōngguó zhìshǎo liǎng gè yuè le, xíguàn chī Zhōngcān le ma?","speaker":"刘明","vi":"Gia Nguyệt, cậu đến Trung Quốc ít nhất hai tháng rồi, đã quen ăn món Trung chưa?"},{"hanzi":"习惯了，而且我很喜欢吃中国菜。","pinyin":"Xíguàn le, érqiě wǒ hěn xǐhuan chī Zhōngguó cài.","speaker":"白家月","vi":"Quen rồi, hơn nữa mình rất thích ăn món Trung Quốc."},{"hanzi":"你还没吃过水煮鱼吧？这是我专门为你做的。","pinyin":"Nǐ hái méi chīguo shuǐzhǔyú ba? Zhè shì wǒ zhuānmén wèi nǐ zuò de.","speaker":"王一雪","vi":"Cậu vẫn chưa ăn cá luộc cay Tứ Xuyên bao giờ đúng không? Món này mình làm riêng cho cậu đấy."},{"hanzi":"看起来不像水煮鱼，更像“油煮鱼”。","pinyin":"Kàn qǐlái bú xiàng shuǐzhǔyú, gèng xiàng “yóuzhǔyú”.","speaker":"白家月","vi":"Nhìn không giống 'cá luộc nước', mà giống 'cá luộc dầu' hơn."},{"hanzi":"这道菜是先用水把鱼煮熟，最后再倒上辣椒油，其实只有最上面那一层是油。你尝尝，对你来说辣不辣？","pinyin":"Zhè dào cài shì xiān yòng shuǐ bǎ yú zhǔshú, zuìhòu zài dàoshàng làjiāoyóu, qíshí zhǐyǒu zuì shàngmiàn nà yì céng shì yóu. Nǐ chángchang, duì nǐ láishuō là bu là?","speaker":"王一雪","vi":"Món này là luộc chín cá bằng nước trước, cuối cùng mới rưới dầu ớt lên, thực ra chỉ có lớp trên cùng là dầu thôi. Cậu nếm thử xem, đối với cậu có cay không?"},{"hanzi":"辣是辣，但是非常好吃！","pinyin":"Là shì là, dànshì fēicháng hǎochī!","speaker":"白家月","vi":"Cay thì có cay, nhưng mà rất ngon!"},{"hanzi":"那你多吃点儿，不要客气。","pinyin":"Nà nǐ duō chī diǎnr, búyào kèqi.","speaker":"王一雪","vi":"Vậy cậu ăn nhiều một chút, đừng khách sáo."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Lưu Minh nói \"家月，你来中国至少两个月了\" (Gia Nguyệt, bạn đến Trung Quốc ít nhất hai tháng rồi), nên đáp án đúng là ít nhất hai tháng.","options":["最多一个月","至少两个月","不到两个星期","差不多一年了"],"q":"白家月来中国多长时间了？"},{"answerIdx":0,"explanation":"Trong bài, Bạch Gia Nguyệt nhận xét về món cá luộc cay: \"辣是辣，但是非常好吃！\" (Cay thì có cay, nhưng rất ngon!), nên đáp án đúng là tuy cay nhưng rất ngon.","options":["虽然辣，但是非常好吃","一点儿也不辣，味道很一般","油太多了，所以她不想吃","鱼还没煮熟，吃起来不太好"],"q":"白家月觉得水煮鱼怎么样？"}],"scene":"在刘明和王一雪家，夫妻两人请白家月和李文吃饭。","sceneVi":"Tại nhà Lưu Minh và Vương Nhất Tuyết, hai vợ chồng mời Bạch Gia Nguyệt và Lý Văn ăn cơm."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"我听李文说，你现在也爱吃辣了？","pinyin":"Wǒ tīng Lǐ Wén shuō, nǐ xiànzài yě ài chī là le?","speaker":"王一雪","vi":"Mình nghe Lý Văn nói, bây giờ cậu cũng thích ăn cay rồi à?"},{"hanzi":"是的，来中国以后，我越来越喜欢吃辣了。","pinyin":"Shì de, lái Zhōngguó yǐhòu, wǒ yuèláiyuè xǐhuan chī là le.","speaker":"白家月","vi":"Đúng vậy, sau khi đến Trung Quốc, mình càng ngày càng thích ăn cay."},{"hanzi":"我们以前不太敢吃辣，吃完可能会肚子不舒服，不过现在也慢慢适应了。","pinyin":"Wǒmen yǐqián bú tài gǎn chī là, chīwán kěnéng huì dùzi bù shūfu, búguò xiànzài yě mànmàn shìyìng le.","speaker":"王一雪","vi":"Trước đây bọn mình không dám ăn cay lắm, ăn xong có thể sẽ bị khó chịu ở bụng, nhưng bây giờ cũng dần dần quen rồi."},{"hanzi":"对，我们现在都不怕辣了。家月，你是“不怕辣”还是“怕不辣”？","pinyin":"Duì, wǒmen xiànzài dōu bú pà là le. Jiāyuè, nǐ shì “bú pà là” háishi “pà bú là”?","speaker":"刘明","vi":"Đúng thế, bây giờ bọn mình đều không sợ cay nữa rồi. Gia Nguyệt, cậu thuộc kiểu 'không sợ cay' hay 'sợ không cay'?"},{"hanzi":"中文真有意思，相同的字，顺序一换，意思就变了。","pinyin":"Zhōngwén zhēn yǒuyìsi, xiāngtóng de zì, shùnxù yí huàn, yìsi jiù biàn le.","speaker":"白家月","vi":"Tiếng Trung thật thú vị, những chữ giống nhau, chỉ cần đổi thứ tự một chút là ý nghĩa đã thay đổi rồi."},{"hanzi":"你的中文水平够高的，这都听懂了！你说得对，“不怕辣”是说不怕吃辣的菜，“怕不辣”是担心菜还不够辣呢。","pinyin":"Nǐ de Zhōngwén shuǐpíng gòu gāo de, zhè dōu tīngdǒng le! Nǐ shuō de duì, “bú pà là” shì shuō bú pà chī là de cài, “pà bú là” shì dānxīn cài hái búgòu là ne.","speaker":"李文","vi":"Trình độ tiếng Trung của cậu cao thật đấy, câu này cũng nghe hiểu được! Cậu nói đúng rồi, 'không sợ cay' là nói không sợ ăn món cay, còn 'sợ không cay' là lo món ăn vẫn chưa đủ cay đấy."},{"hanzi":"我还达不到“怕不辣”的水平，甚至也不能算“不怕辣”，只是喜欢吃辣。","pinyin":"Wǒ hái dábudào “pà bú là” de shuǐpíng, shènzhì yě bù néng suàn “bú pà là”, zhǐshì xǐhuan chī là.","speaker":"白家月","vi":"Mình vẫn chưa đạt đến trình độ 'sợ không cay', thậm chí cũng chưa thể tính là 'không sợ cay', chỉ là thích ăn cay thôi."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài, Vương Nhất Tuyết nói \"我们以前不太敢吃辣，吃完可能会肚子不舒服\" (Trước đây chúng tôi không dám ăn cay lắm, ăn xong có thể bị khó chịu ở bụng), nên đáp án đúng là vì ăn xong có thể bị khó chịu ở bụng.","options":["因为吃完以后可能会肚子不舒服","因为他们更喜欢吃甜的菜","因为辣的菜在家里很难做","因为医生不让他们吃辣的东西"],"q":"以前王一雪和刘明为什么不太敢吃辣？"},{"answerIdx":1,"explanation":"Trong bài, Lý Văn giải thích \"‘怕不辣’是担心菜还不够辣呢\" (“怕不辣” là lo món ăn vẫn chưa đủ cay đấy), nên đáp án đúng là lo món ăn vẫn chưa đủ cay.","options":["一点儿辣的菜都不敢吃","担心菜还不够辣","吃了辣的菜以后会生病","觉得只有四川菜才算辣"],"q":"根据李文的解释，“怕不辣”是什么意思？"}],"scene":"在刘明和王一雪家，夫妻两人和白家月、李文边吃边聊。","sceneVi":"Tại nhà Lưu Minh và Vương Nhất Tuyết, hai vợ chồng vừa ăn vừa trò chuyện cùng Bạch Gia Nguyệt và Lý Văn."},{"id":3,"isNarrative":true,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"周末，白家月、陈天中、李文和安妮聚在一起吃午餐。","pinyin":"Zhōumò, Bái Jiāyuè, Chén Tiānzhōng, Lǐ Wén hé Ānnī jù zài yìqǐ chī wǔcān.","speaker":"Đoạn văn","vi":"Cuối tuần, Bạch Gia Nguyệt, Trần Thiên Trung, Lý Văn và An Ni tụ tập cùng nhau ăn bữa trưa."},{"hanzi":"白家月想吃辣的，要了辣子鸡；陈天中爱吃甜的，想尝尝松鼠鳜鱼；李文更喜欢吃咸的，选了红烧羊肉和一道凉菜；安妮听说贵州酸汤很有名，点了酸汤米线。","pinyin":"Bái Jiāyuè xiǎng chī là de, yào le làzǐjī; Chén Tiānzhōng ài chī tián de, xiǎng chángchang sōngshǔ guìyú; Lǐ Wén gèng xǐhuan chī xián de, xuǎn le hóngshāo yángròu hé yí dào liángcài; Ānnī tīngshuō Guìzhōu suāntāng hěn yǒumíng, diǎn le suāntāng mǐxiàn.","speaker":"Đoạn văn","vi":"Bạch Gia Nguyệt muốn ăn đồ cay nên gọi gà xào ớt; Trần Thiên Trung thích ăn đồ ngọt nên muốn nếm thử cá quế hình sóc; Lý Văn thích ăn đồ mặn hơn nên chọn thịt dê kho tàu và một món nộm nguội; An Ni nghe nói canh chua Quý Châu rất nổi tiếng nên gọi bún canh chua."},{"hanzi":"他们边吃边聊，非常愉快。","pinyin":"Tāmen biān chī biān liáo, fēicháng yúkuài.","speaker":"Đoạn văn","vi":"Họ vừa ăn vừa trò chuyện, vô cùng vui vẻ."},{"hanzi":"结账时，李文想请客，但大家觉得还是各付各的更合适。","pinyin":"Jiézhàng shí, Lǐ Wén xiǎng qǐngkè, dàn dàjiā juéde háishi gè fù gè de gèng héshì.","speaker":"Đoạn văn","vi":"Khi thanh toán, Lý Văn muốn mời khách, nhưng mọi người cảm thấy vẫn nên ai trả phần nấy thì phù hợp hơn."},{"hanzi":"于是，李文付完钱后，大家把钱转给了他，还笑着说下次再一起聚餐。","pinyin":"Yúshì, Lǐ Wén fùwán qián hòu, dàjiā bǎ qián zhuǎngěi le tā, hái xiàozhe shuō xià cì zài yìqǐ jùcān.","speaker":"Đoạn văn","vi":"Thế là, sau khi Lý Văn trả tiền xong, mọi người chuyển tiền lại cho anh ấy, còn cười nói lần sau sẽ lại cùng nhau đi ăn nữa."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu \"白家月想吃辣的，要了辣子鸡\" (Bạch Gia Nguyệt muốn ăn cay nên đã gọi món gà xào ớt), nên người gọi món này là Bạch Gia Nguyệt.","options":["陈天中","李文","白家月","安妮"],"q":"谁点了辣子鸡？"},{"answerIdx":2,"explanation":"Trong bài có câu \"于是，李文付完钱后，大家把钱转给了他\" (Thế là sau khi Lý Văn trả tiền xong, mọi người đã chuyển tiền lại cho anh ấy), nên đáp án đúng là Lý Văn trả tiền trước rồi mọi người chuyển tiền cho anh ấy.","options":["李文请大家吃饭，别人没给钱","安妮先付了钱，大家下次再还她","李文先付了钱，之后大家把钱转给了他","陈天中用手机请大家吃了这顿饭"],"q":"吃完饭结账时，他们是怎么付钱的？"}],"scene":"在餐厅里，白家月、陈天中、李文和安妮聚餐。","sceneVi":"Tại nhà hàng, Bạch Gia Nguyệt, Trần Thiên Trung, Lý Văn và An Ni ăn uống tụ tập cùng nhau."},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"今天吃饭的时候，大家坐得比较随意。","pinyin":"Jīntiān chīfàn de shíhou, dàjiā zuò de bǐjiào suíyì.","speaker":"Đoạn văn","vi":"Lúc ăn cơm hôm nay, mọi người ngồi khá thoải mái tùy ý."},{"hanzi":"李文告诉白家月，在中国，正式聚餐和普通聚餐不同，正式聚餐时人们比较重视座位的安排，比如可以按照年龄大小来安排，年龄比较大的客人往往会坐在中间或者面对门口的座位。","pinyin":"Lǐ Wén gàosu Bái Jiāyuè, zài Zhōngguó, zhèngshì jùcān hé pǔtōng jùcān bù tóng, zhèngshì jùcān shí rénmen bǐjiào zhòngshì zuòwèi de ānpái, bǐrú kěyǐ ànzhào niánlíng dàxiǎo lái ānpái, niánlíng bǐjiào dà de kèrén wǎngwǎng huì zuò zài zhōngjiān huòzhě miànduì ménkǒu de zuòwèi.","speaker":"Đoạn văn","vi":"Lý Văn nói với Bạch Gia Nguyệt rằng ở Trung Quốc, tiệc tụ họp trang trọng và bữa ăn bình thường không giống nhau; khi dự tiệc trang trọng, mọi người khá coi trọng việc sắp xếp chỗ ngồi, ví dụ có thể sắp xếp theo độ tuổi, những vị khách lớn tuổi thường sẽ ngồi ở giữa hoặc ở vị trí đối diện cửa ra vào."},{"hanzi":"大家坐下时，主人会请客人先坐。","pinyin":"Dàjiā zuòxià shí, zhǔrén huì qǐng kèrén xiān zuò.","speaker":"Đoạn văn","vi":"Khi mọi người ngồi xuống, chủ nhà sẽ mời khách ngồi trước."},{"hanzi":"如果聚餐时有老人，年轻人要等老人坐下后再坐。","pinyin":"Rúguǒ jùcān shí yǒu lǎorén, niánqīngrén yào děng lǎorén zuòxià hòu zài zuò.","speaker":"Đoạn văn","vi":"Nếu khi ăn tiệc có người lớn tuổi, người trẻ phải đợi người lớn tuổi ngồi xuống rồi mới ngồi."},{"hanzi":"白家月听后觉得很有意思，她认为这么做是照顾客人、尊重老人的表现。","pinyin":"Bái Jiāyuè tīnghòu juéde hěn yǒuyìsi, tā rènwéi zhème zuò shì zhàogù kèrén, zūnzhòng lǎorén de biǎoxiàn.","speaker":"Đoạn văn","vi":"Bạch Gia Nguyệt nghe xong cảm thấy rất thú vị, cô ấy cho rằng làm như vậy là biểu hiện của sự quan tâm khách và tôn trọng người lớn tuổi."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"年龄比较大的客人往往会坐在中间或者面对门口的座位\" (Những vị khách lớn tuổi hơn thường sẽ ngồi ở giữa hoặc ở chỗ đối diện cửa ra vào), nên đáp án đúng là chỗ ở giữa hoặc đối diện cửa ra vào.","options":["靠近厨房或者角落的座位","中间或者面对门口的座位","背对门口或者最边上的座位","离主人最远的那个座位"],"q":"在中国正式聚餐时，年龄比较大的客人往往坐在哪里？"},{"answerIdx":3,"explanation":"Trong bài có câu \"如果聚餐时有老人，年轻人要等老人坐下后再坐\" (Nếu khi tụ họp ăn uống có người lớn tuổi, người trẻ phải đợi người lớn tuổi ngồi xuống rồi mới ngồi), nên đáp án đúng là đợi người lớn tuổi ngồi xuống rồi mới ngồi.","options":["一进餐厅就马上找座位坐下","在主人还没有到的时候先坐下","等所有客人都点完菜以后再坐","等老人坐下以后再坐下"],"q":"如果聚餐时有老人，年轻人应该什么时候坐下？"}],"scene":"中国餐桌上的座位安排","sceneVi":"Sắp xếp chỗ ngồi trên bàn ăn Trung Quốc"}],"hsk4a-6":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"喂，李文，我身体不舒服。","pinyin":"Wèi, Lǐ Wén, wǒ shēntǐ bù shūfu.","speaker":"白家月","vi":"Alo, Lý Văn, mình thấy trong người không khỏe."},{"hanzi":"你怎么了？听你的声音，好像感冒了。","pinyin":"Nǐ zěnme le? Tīng nǐ de shēngyīn, hǎoxiàng gǎnmào le.","speaker":"李文","vi":"Cậu bị sao thế? Nghe giọng cậu hình như bị cảm rồi."},{"hanzi":"对，我还发烧，一直咳嗽，咳得很厉害。","pinyin":"Duì, wǒ hái fāshāo, yìzhí késou, ké de hěn lìhai.","speaker":"白家月","vi":"Đúng vậy, mình còn bị sốt, ho liên tục, ho rất dữ dội."},{"hanzi":"那挺严重的，最好赶快去医院检查一下。","pinyin":"Nà tǐng yánzhòng de, zuìhǎo gǎnkuài qù yīyuàn jiǎnchá yíxià.","speaker":"李文","vi":"Vậy thì khá nghiêm trọng đấy, tốt nhất mau đi bệnh viện kiểm tra một chút đi."},{"hanzi":"我也这么想，不过我来中国后还没去过医院，不知道怎么在中国的医院看病。","pinyin":"Wǒ yě zhème xiǎng, búguò wǒ lái Zhōngguó hòu hái méi qùguo yīyuàn, bù zhīdào zěnme zài Zhōngguó de yīyuàn kànbìng.","speaker":"白家月","vi":"Mình cũng nghĩ vậy, nhưng từ khi đến Trung Quốc mình vẫn chưa đi bệnh viện bao giờ, không biết cách khám bệnh ở bệnh viện Trung Quốc."},{"hanzi":"没关系，我陪你一起去，还能帮你翻译。你在家等一下，我现在就去接你。","pinyin":"Méi guānxi, wǒ péi nǐ yìqǐ qù, hái néng bāng nǐ fānyì. Nǐ zài jiā děng yíxià, wǒ xiànzài jiù qù jiē nǐ.","speaker":"李文","vi":"Không sao đâu, mình đi cùng với cậu, còn có thể giúp cậu phiên dịch. Cậu ở nhà đợi một chút, bây giờ mình sang đón cậu ngay."},{"hanzi":"太好了！有你陪着，我就放心多了。","pinyin":"Tài hǎo le! Yǒu nǐ péizhe, wǒ jiù fàngxīn duō le.","speaker":"白家月","vi":"Tuyệt quá! Có cậu đi cùng, mình yên tâm hơn nhiều rồi."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Lý Văn đoán \"好像感冒了\" (hình như bị cảm rồi) và Bạch Gia Nguyệt nói thêm \"对，我还发烧，一直咳嗽，咳得很厉害\" (Đúng vậy, mình còn bị sốt, ho liên tục, ho rất dữ dội), nên cô ấy bị cảm, sốt và ho liên tục.","options":["肚子疼，而且有点儿拉肚子","感冒、发烧，还一直咳嗽","眼睛很疼，晚上睡不着觉","腿受伤了，没办法自己走路"],"q":"白家月现在身体怎么了？"},{"answerIdx":2,"explanation":"Trong bài, Bạch Gia Nguyệt nói \"不过我来中国后还没去过医院，不知道怎么在中国的医院看病\" (nhưng từ khi đến Trung Quốc mình chưa từng đi bệnh viện, không biết khám bệnh ở bệnh viện Trung Quốc như thế nào), nên cô ấy lo lắng vì chưa từng đến bệnh viện Trung Quốc và không biết cách khám.","options":["她担心去医院看病要花很多钱","她害怕一个人打针会特别疼","她没去过中国的医院，不知道怎么看病","她家里离医院太远，没有车去"],"q":"关于去医院看病，白家月一开始担心什么？"}],"scene":"在家里，白家月躺在床上给李文打电话。","sceneVi":"Ở nhà, Bạch Gia Nguyệt nằm trên giường gọi điện thoại cho Lý Văn."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"护士，您好，我的这位外国朋友生病了，第一次来这里看病，需要怎么做？","pinyin":"Hùshi, nín hǎo, wǒ de zhè wèi wàiguó péngyou shēngbìng le, dì-yī cì lái zhèlǐ kànbìng, xūyào zěnme zuò?","speaker":"李文","vi":"Chào y tá, bạn người nước ngoài này của tôi bị ốm, lần đầu tiên đến đây khám bệnh, cần phải làm như thế nào ạ?"},{"hanzi":"请在这张表上写上病人的姓名、性别、国籍、年龄、电话号码和家庭地址。","pinyin":"Qǐng zài zhè zhāng biǎo shang xiěshàng bìngrén de xìngmíng, xìngbié, guójí, niánlíng, diànhuà hàomǎ hé jiātíng dìzhǐ.","speaker":"护士","vi":"Xin hãy điền họ tên, giới tính, quốc tịch, tuổi, số điện thoại và địa chỉ nhà của bệnh nhân vào tờ đơn này."},{"hanzi":"我写好了，您看看，这样可以吗？","pinyin":"Wǒ xiěhǎo le, nín kànkan, zhèyàng kěyǐ ma?","speaker":"李文","vi":"Tôi viết xong rồi, cô xem thử xem, như vậy được chưa ạ?"},{"hanzi":"没问题，您拿着病人的护照去挂号吧。","pinyin":"Méi wèntí, nín názhe bìngrén de hùzhào qù guàhào ba.","speaker":"护士","vi":"Không vấn đề gì, anh cầm hộ chiếu của bệnh nhân đi đăng ký khám đi ạ."},{"hanzi":"家月，我去排队挂号，你先在大厅休息，别着急。","pinyin":"Jiāyuè, wǒ qù páiduì guàhào, nǐ xiān zài dàtīng xiūxi, bié zháojí.","speaker":"李文","vi":"Gia Nguyệt, mình đi xếp hàng lấy số khám đây, cậu cứ ở sảnh nghỉ ngơi trước đi, đừng sốt ruột nhé."},{"hanzi":"好的，真是太谢谢你了！","pinyin":"Hǎo de, zhēn shì tài xièxie nǐ le!","speaker":"白家月","vi":"Được rồi, thật sự cảm ơn cậu nhiều lắm!"},{"hanzi":"你跟我有什么好客气的。","pinyin":"Nǐ gēn wǒ yǒu shénme hǎo kèqi de.","speaker":"李文","vi":"Cậu với mình thì có gì mà phải khách sáo chứ."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài, y tá bảo Lý Văn \"没问题，您拿着病人的护照去挂号吧\" (Không vấn đề gì, anh cầm hộ chiếu của bệnh nhân đi đăng ký khám nhé), nên đáp án đúng là cầm hộ chiếu của bệnh nhân đi đăng ký khám.","options":["带着白家月直接进医生办公室","先去药店买一些感冒药","拿着病人的护照去挂号","在大厅里再填另外一张表"],"q":"填好表以后，护士让李文接着做什么？"},{"answerIdx":0,"explanation":"Trong bài, Lý Văn dặn Bạch Gia Nguyệt \"我去排队挂号，你先在大厅休息，别着急\" (Mình đi xếp hàng đăng ký khám, bạn cứ ở đại sảnh nghỉ ngơi trước, đừng lo lắng), nên Bạch Gia Nguyệt nghỉ ngơi ở đại sảnh.","options":["在大厅里休息","在门口等出租车","在房间里做检查","自己去拿药"],"q":"李文去排队挂号的时候，白家月在哪里做什么？"}],"scene":"在医院大厅，李文帮白家月办理看病手续。","sceneVi":"Tại sảnh lớn bệnh viện, Lý Văn giúp Bạch Gia Nguyệt làm thủ tục khám bệnh."},{"id":3,"isNarrative":true,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"下午白家月去看病了，她告诉医生，自己平时身体不错，偶尔才会生一次病。","pinyin":"Xiàwǔ Bái Jiāyuè qù kànbìng le, tā gàosu yīshēng, zìjǐ píngshí shēntǐ búcuò, ǒu'ěr cái huì shēng yí cì bìng.","speaker":"Đoạn văn","vi":"Buổi chiều Bạch Gia Nguyệt đi khám bệnh, cô ấy nói với bác sĩ rằng bình thường sức khỏe mình khá tốt, thỉnh thoảng mới bị ốm một lần."},{"hanzi":"这次她病得很厉害，头也一直疼，身上一点儿力气都没有。","pinyin":"Zhè cì tā bìng de hěn lìhai, tóu yě yìzhí téng, shēnshang yìdiǎnr lìqi dōu méiyǒu.","speaker":"Đoạn văn","vi":"Lần này cô ấy ốm rất nặng, đầu cũng đau liên tục, trên người không còn chút sức lực nào."},{"hanzi":"医生给她做了检查，检查结果出来后，发现她得了比较严重的流行性感冒。","pinyin":"Yīshēng gěi tā zuò le jiǎnchá, jiǎnchá jiéguǒ chūlái hòu, fāxiàn tā dé le bǐjiào yánzhòng de liúxíngxìng gǎnmào.","speaker":"Đoạn văn","vi":"Bác sĩ kiểm tra cho cô ấy, sau khi có kết quả kiểm tra thì phát hiện cô ấy bị cúm khá nặng."},{"hanzi":"医生告诉她，现在需要把体温降下来，光吃药恐怕不够，打针会更有效。","pinyin":"Yīshēng gàosu tā, xiànzài xūyào bǎ tǐwēn jiàng xiàlái, guāng chīyào kǒngpà búgòu, dǎzhēn huì gèng yǒuxiào.","speaker":"Đoạn văn","vi":"Bác sĩ bảo cô ấy rằng hiện tại cần phải hạ thân nhiệt xuống, chỉ uống thuốc e rằng không đủ, tiêm sẽ có hiệu quả hơn."},{"hanzi":"医生还让她回家以后按时吃药，多喝水，多休息。","pinyin":"Yīshēng hái ràng tā huíjiā yǐhòu ànshí chīyào, duō hē shuǐ, duō xiūxi.","speaker":"Đoạn văn","vi":"Bác sĩ còn dặn cô ấy sau khi về nhà phải uống thuốc đúng giờ, uống nhiều nước và nghỉ ngơi nhiều."},{"hanzi":"晚上，白家月睡觉时出了一身汗。","pinyin":"Wǎnshang, Bái Jiāyuè shuìjiào shí chū le yì shēn hàn.","speaker":"Đoạn văn","vi":"Buổi tối, khi Bạch Gia Nguyệt ngủ đã toát mồ hôi đầy người."},{"hanzi":"第二天醒来时，她感觉头不那么疼了，体温也低了一些，身体不那么难受了。","pinyin":"Dì-èr tiān xǐnglái shí, tā gǎnjué tóu bú nàme téng le, tǐwēn yě dī le yìxiē, shēntǐ bú nàme nánshòu le.","speaker":"Đoạn văn","vi":"Ngày hôm sau lúc tỉnh dậy, cô ấy cảm thấy đầu không còn đau như thế nữa, nhiệt độ cơ thể cũng giảm đi một chút, trong người không còn khó chịu như vậy nữa."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"检查结果出来后，发现她得了比较严重的流行性感冒\" (Sau khi có kết quả kiểm tra, phát hiện cô ấy bị cúm mùa khá nặng), nên đáp án đúng là bị cúm mùa khá nặng.","options":["普通的胃病","比较严重的流行性感冒","一点儿小问题，不用吃药","吃坏东西引起的肚子疼"],"q":"检查结果出来后，医生发现白家月得了什么病？"},{"answerIdx":2,"explanation":"Trong bài có câu \"医生告诉她，现在需要把体温降下来，光吃药恐怕不够，打针会更有效\" (Bác sĩ bảo cô ấy hiện cần hạ thân nhiệt xuống, chỉ uống thuốc e rằng không đủ, tiêm sẽ hiệu quả hơn), nên đáp án đúng là cần hạ sốt và chỉ uống thuốc có thể chưa đủ, tiêm hiệu quả hơn.","options":["因为她害怕吃药，不想吃药","因为医院那天刚好没有感冒药了","因为需要把体温降下来，只吃药可能不够，打针更有效","因为医生觉得打针以后就不用回家休息了"],"q":"为什么医生建议白家月打针？"}],"scene":"一次看病的经历","sceneVi":"Một lần đi khám bệnh"},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"外国人第一次在中国看病，可能会担心语言不通，或者觉得看病的过程和自己的国家不同。","pinyin":"Wàiguórén dì-yī cì zài Zhōngguó kànbìng, kěnéng huì dānxīn yǔyán bù tōng, huòzhě juéde kànbìng de guòchéng hé zìjǐ de guójiā bù tóng.","speaker":"Đoạn văn","vi":"Người nước ngoài lần đầu tiên đi khám bệnh ở Trung Quốc có thể sẽ lo lắng bất đồng ngôn ngữ, hoặc cảm thấy quy trình khám bệnh khác với đất nước của mình."},{"hanzi":"其实，这些问题都有办法解决。","pinyin":"Qíshí, zhèxiē wèntí dōu yǒu bànfǎ jiějué.","speaker":"Đoạn văn","vi":"Thực ra, những vấn đề này đều có cách giải quyết."},{"hanzi":"有的医院有国际部，那里的医生一般会说英文，交流比较方便，但是国际部的收费比较高。","pinyin":"Yǒude yīyuàn yǒu guójìbù, nàlǐ de yīshēng yìbān huì shuō Yīngwén, jiāoliú bǐjiào fāngbiàn, dànshì guójìbù de shōufèi bǐjiào gāo.","speaker":"Đoạn văn","vi":"Có những bệnh viện có khoa Quốc tế, bác sĩ ở đó thường biết nói tiếng Anh, giao tiếp khá thuận tiện, nhưng chi phí ở khoa Quốc tế tương đối cao."},{"hanzi":"如果没有特别需要，可以选择普通部，用简单的中文和医生交流。","pinyin":"Rúguǒ méiyǒu tèbié xūyào, kěyǐ xuǎnzé pǔtōngbù, yòng jiǎndān de Zhōngwén hé yīshēng jiāoliú.","speaker":"Đoạn văn","vi":"Nếu không có nhu cầu đặc biệt, có thể chọn khoa thông thường, dùng tiếng Trung đơn giản để trao đổi với bác sĩ."},{"hanzi":"在中国看病要先挂号，然后再去找医生。","pinyin":"Zài Zhōngguó kànbìng yào xiān guàhào, ránhòu zài qù zhǎo yīshēng.","speaker":"Đoạn văn","vi":"Đi khám bệnh ở Trung Quốc phải đăng ký lấy số trước, sau đó mới đi gặp bác sĩ."},{"hanzi":"医生会问病人的情况，有时还会做一些检查，好给出合适的治疗方法。","pinyin":"Yīshēng huì wèn bìngrén de qíngkuàng, yǒushí hái huì zuò yìxiē jiǎnchá, hǎo gěichū héshì de zhìliáo fāngfǎ.","speaker":"Đoạn văn","vi":"Bác sĩ sẽ hỏi tình hình của bệnh nhân, đôi khi còn làm một số xét nghiệm kiểm tra để đưa ra phương pháp điều trị phù hợp."},{"hanzi":"只要按照医生说的一步一步来，一般都可以顺利得到治疗。","pinyin":"Zhǐyào ànzhào yīshēng shuō de yíbù yíbù lái, yìbān dōu kěyǐ shùnlì dédào zhìliáo.","speaker":"Đoạn văn","vi":"Chỉ cần làm từng bước một theo lời bác sĩ dặn, nhìn chung đều có thể được điều trị thuận lợi."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"有的医院有国际部，那里的医生一般会说英文，交流比较方便，但是国际部的收费比较高\" (Có bệnh viện có khoa Quốc tế, bác sĩ ở đó thường biết nói tiếng Anh, giao tiếp khá thuận tiện, nhưng chi phí ở khoa Quốc tế khá cao), nên nhược điểm là mức phí khám chữa bệnh khá cao.","options":["那里的医生一般不会说英文","看病的收费比较高","病人不能在那里做检查","挂号的过程特别慢"],"q":"根据课文，医院的国际部有什么缺点？"},{"answerIdx":2,"explanation":"Trong bài có câu \"在中国看病要先挂号，然后再去找医生\" (Khám bệnh ở Trung Quốc phải đăng ký khám trước, rồi mới đi gặp bác sĩ), nên đáp án đúng là đăng ký khám trước rồi mới gặp bác sĩ.","options":["先做检查，再挂号找医生","先找医生开药，再填写表格","先挂号，然后再去找医生","先交钱治疗，再问医生情况"],"q":"在中国看病，一般应该先做什么，再做什么？"}],"scene":"怎么在中国看病","sceneVi":"Cách đi khám bệnh ở Trung Quốc"}],"hsk4a-7":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"经理，打扰您一下。市场调查的计划书我昨天发到您邮箱了。在内容方面，您觉得有需要改的吗？","pinyin":"Jīnglǐ, dǎrǎo nín yíxià. Shìchǎng diàochá de jìhuàshū wǒ zuótiān fā dào nín yóuxiāng le. Zài nèiróng fāngmiàn, nín juéde yǒu xūyào gǎi de ma?","speaker":"同事","vi":"Giám đốc, xin phép làm phiền chị một chút. Bản kế hoạch khảo sát thị trường tôi đã gửi vào hộp thư của chị hôm qua rồi. Về mặt nội dung, chị thấy có chỗ nào cần sửa không ạ?"},{"hanzi":"我看过了，写得不错，就是调查的地点只有超市，不太够。","pinyin":"Wǒ kànguo le, xiě de búcuò, jiùshì diàochá de dìdiǎn zhǐ yǒu chāoshì, bú tài gòu.","speaker":"王一雪","vi":"Tôi xem rồi, viết khá tốt, chỉ là địa điểm khảo sát chỉ có siêu thị thì hơi ít."},{"hanzi":"好的，那我再加一些网店。","pinyin":"Hǎo de, nà wǒ zài jiā yìxiē wǎngdiàn.","speaker":"同事","vi":"Vâng, vậy tôi sẽ thêm một số cửa hàng trực tuyến nữa ạ."},{"hanzi":"行。做调查的时候要细心，注意了解客户真正的想法。","pinyin":"Xíng. Zuò diàochá de shíhou yào xìxīn, zhùyì liǎojiě kèhù zhēnzhèng de xiǎngfǎ.","speaker":"王一雪","vi":"Được. Khi làm khảo sát phải cẩn thận, chú ý tìm hiểu suy nghĩ thực sự của khách hàng."},{"hanzi":"明白了，我会认真准备，按时完成任务。","pinyin":"Míngbai le, wǒ huì rènzhēn zhǔnbèi, ànshí wánchéng rènwù.","speaker":"同事","vi":"Tôi hiểu rồi ạ, tôi sẽ chuẩn bị nghiêm túc và hoàn thành nhiệm vụ đúng hạn."},{"hanzi":"嗯，如果遇到什么问题，及时跟我联系。","pinyin":"Ǹg, rúguǒ yùdào shénme wèntí, jíshí gēn wǒ liánxì.","speaker":"王一雪","vi":"Ừ, nếu gặp vấn đề gì thì liên hệ kịp thời với tôi nhé."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài, Vương Nhất Tuyết nhận xét \"我看过了，写得不错，就是调查的地点只有超市，不太够\" (Tôi xem rồi, viết khá tốt, chỉ là địa điểm khảo sát chỉ có siêu thị thì chưa đủ lắm), nên đáp án đúng là viết khá tốt nhưng địa điểm khảo sát quá ít, chỉ có siêu thị.","options":["整体写得不错，但调查地点太少，只有超市","内容写得不好，需要全部重写一遍","调查地点太多了，应该去掉网店","她还没有时间看同事发来的邮件"],"q":"王一雪觉得同事写的市场调查计划书怎么样？"},{"answerIdx":2,"explanation":"Trong bài, Vương Nhất Tuyết dặn \"做调查的时候要细心，注意了解客户真正的想法\" (Khi làm khảo sát phải tỉ mỉ, chú ý tìm hiểu suy nghĩ thực sự của khách hàng), nên đáp án đúng là cần tỉ mỉ, chú ý tìm hiểu suy nghĩ thực sự của khách hàng.","options":["尽量少花时间，早点儿结束调查","只在超市里问买东西的人","要细心，注意了解客户真正的想法","不用和经理联系，自己决定就行"],"q":"王一雪提醒同事做调查时要注意什么？"}],"scene":"在王一雪办公室，同事向她汇报工作。","sceneVi":"Tại văn phòng của Vương Nhất Tuyết, đồng nghiệp đang báo cáo công việc với cô ấy."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"杨哥，经理让我下周去上海出差，做市场调查，你有这方面的经验吗？","pinyin":"Yáng gē, jīnglǐ ràng wǒ xià zhōu qù Shànghǎi chūchāi, zuò shìchǎng diàochá, nǐ yǒu zhè fāngmiàn de jīngyàn ma?","speaker":"同事","vi":"Anh Dương ơi, giám đốc bảo tôi tuần sau đi Thượng Hải công tác để làm khảo sát thị trường, anh có kinh nghiệm về mặt này không?"},{"hanzi":"你要去几天？主要调查什么内容？","pinyin":"Nǐ yào qù jǐ tiān? Zhǔyào diàochá shénme nèiróng?","speaker":"杨同乐","vi":"Em đi mấy ngày? Chủ yếu khảo sát những nội dung gì?"},{"hanzi":"去四天，打算采访一些客户，了解他们对新产品的看法。","pinyin":"Qù sì tiān, dǎsuàn cǎifǎng yìxiē kèhù, liǎojiě tāmen duì xīn chǎnpǐn de kànfǎ.","speaker":"同事","vi":"Đi bốn ngày ạ, em dự định phỏng vấn một số khách hàng để tìm hiểu quan điểm của họ về sản phẩm mới."},{"hanzi":"那你要提前准备好问题，便于和客户交流。","pinyin":"Nà nǐ yào tíqián zhǔnbèi hǎo wèntí, biànyú hé kèhù jiāoliú.","speaker":"杨同乐","vi":"Vậy em phải chuẩn bị sẵn câu hỏi trước, để tiện trao đổi với khách hàng."},{"hanzi":"好的，我已经准备了一些问题。","pinyin":"Hǎo de, wǒ yǐjīng zhǔnbèi le yìxiē wèntí.","speaker":"同事","vi":"Vâng, em cũng đã chuẩn bị sẵn một số câu hỏi rồi ạ."},{"hanzi":"很好。既然出差时间不长，就要安排好时间，多获得有用的信息。","pinyin":"Hěn hǎo. Jìrán chūchāi shíjiān bù cháng, jiù yào ānpái hǎo shíjiān, duō huòdé yǒuyòng de xìnxī.","speaker":"杨同乐","vi":"Tốt lắm. Đã đi công tác thời gian không dài thì phải sắp xếp thời gian hợp lý, thu thập thật nhiều thông tin hữu ích."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài, người đồng nghiệp nói \"去四天，打算采访一些客户，了解他们对新产品的看法\" (Đi bốn ngày, dự định phỏng vấn một số khách hàng để tìm hiểu nhận xét của họ về sản phẩm mới), nên mục đích chính là phỏng vấn khách hàng về sản phẩm mới.","options":["参加一个重要的公司会议","拜访以前的老朋友","采访客户，了解他们对新产品的看法","去上海的分公司学习管理方法"],"q":"同事下周去上海出差四天，主要打算做什么？"},{"answerIdx":1,"explanation":"Trong bài, Dương Đồng Lạc đưa ra hai lời khuyên: \"那你要提前准备好问题，便于和客户交流\" (Vậy cậu phải chuẩn bị sẵn câu hỏi trước để tiện trao đổi với khách hàng) và \"就要安排好时间，多获得有用的信息\" (nên sắp xếp thời gian hợp lý, thu thập nhiều thông tin hữu ích), nên đáp án đúng là chuẩn bị trước câu hỏi và sắp xếp thời gian hợp lý để thu thập nhiều thông tin hữu ích.","options":["延长出差时间，并多带几个同事一起去","提前准备好问题，同时安排好时间以多获得有用信息","不要提前准备问题，到了上海再慢慢想","先去了解一下上海的超市，不用见客户"],"q":"杨同乐给了同事什么建议？"}],"scene":"在公司，同事向杨同乐征求建议。","sceneVi":"Tại công ty, đồng nghiệp xin lời khuyên của Dương Đồng Lạc."},{"id":3,"isNarrative":true,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"前段时间，杨同乐的同事谈成了一笔不错的生意。","pinyin":"Qián duàn shíjiān, Yáng Tónglè de tóngshì tánchéng le yì bǐ búcuò de shēngyi.","speaker":"Đoạn văn","vi":"Thời gian trước, đồng nghiệp của Dương Đồng Lạc đã đàm phán thành công một thương vụ khá tốt."},{"hanzi":"刚开始，这位同事也遇到了一些困难。","pinyin":"Gāng kāishǐ, zhè wèi tóngshì yě yùdào le yìxiē kùnnan.","speaker":"Đoạn văn","vi":"Lúc mới bắt đầu, người đồng nghiệp này cũng gặp phải một số khó khăn."},{"hanzi":"拿和客户交流来说，虽然她能把产品的优缺点说得很清楚，但实际效果并不理想。","pinyin":"Ná hé kèhù jiāoliú lái shuō, suīrán tā néng bǎ chǎnpǐn de yōuquēdiǎn shuō de hěn qīngchu, dàn shíjì xiàoguǒ bìng bù lǐxiǎng.","speaker":"Đoạn văn","vi":"Nói riêng về việc giao tiếp với khách hàng, mặc dù cô ấy có thể nói rất rõ ưu nhược điểm của sản phẩm, nhưng hiệu quả thực tế lại không được như ý."},{"hanzi":"杨同乐告诉她，这是因为她介绍的方式都一样。","pinyin":"Yáng Tónglè gàosu tā, zhè shì yīnwèi tā jièshào de fāngshì dōu yíyàng.","speaker":"Đoạn văn","vi":"Dương Đồng Lạc nói với cô ấy rằng đó là vì cách giới thiệu của cô ấy đều giống nhau."},{"hanzi":"其实，不同年龄、不同性别的客户对产品的关注点是不一样的。","pinyin":"Qíshí, bùtóng niánlíng, bùtóng xìngbié de kèhù duì chǎnpǐn de guānzhùdiǎn shì bù yíyàng de.","speaker":"Đoạn văn","vi":"Thực ra, khách hàng ở các độ tuổi và giới tính khác nhau sẽ có những điểm quan tâm khác nhau đối với sản phẩm."},{"hanzi":"于是，这位同事又认真地进行了几次市场调查，了解不同客户的想法。","pinyin":"Yúshì, zhè wèi tóngshì yòu rènzhēn de jìnxíng le jǐ cì shìchǎng diàochá, liǎojiě bùtóng kèhù de xiǎngfǎ.","speaker":"Đoạn văn","vi":"Thế là người đồng nghiệp này lại nghiêm túc tiến hành thêm vài lần khảo sát thị trường để tìm hiểu suy nghĩ của các khách hàng khác nhau."},{"hanzi":"后来她在面对不同客户时，能根据他们的情况介绍产品，效果一下就好了很多。","pinyin":"Hòulái tā zài miànduì bùtóng kèhù shí, néng gēnjù tāmen de qíngkuàng jièshào chǎnpǐn, xiàoguǒ yíxià jiù hǎo le hěn duō.","speaker":"Đoạn văn","vi":"Sau này khi đối diện với những khách hàng khác nhau, cô ấy đã có thể giới thiệu sản phẩm dựa theo tình hình của họ, hiệu quả lập tức tốt hơn rất nhiều."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"杨同乐告诉她，这是因为她介绍的方式都一样\" (Dương Đồng Lạc nói với cô ấy, đó là vì cách giới thiệu của cô ấy đều giống nhau), nên nguyên nhân là vì cô ấy giới thiệu sản phẩm theo cùng một cách với mọi khách hàng.","options":["因为她自己也不清楚产品的优缺点","因为她对所有客户都用一样的方式介绍产品","因为公司的产品质量不太好，价格太高","因为她说话太快，客户听不明白"],"q":"刚开始，为什么这位同事和客户交流时实际效果不理想？"},{"answerIdx":2,"explanation":"Trong bài có câu \"于是，这位同事又认真地进行了几次市场调查，了解不同客户的想法。后来她在面对不同客户时，能根据他们的情况介绍产品，效果一下就好了很多\" (Vì thế, người đồng nghiệp này lại nghiêm túc làm vài cuộc khảo sát thị trường... Sau đó khi gặp các khách hàng khác nhau, cô ấy có thể giới thiệu sản phẩm tùy theo tình hình của họ, hiệu quả lập tức tốt hơn nhiều), nên đáp án đúng là cô ấy làm lại khảo sát thị trường và giới thiệu sản phẩm phù hợp theo từng đối tượng khách hàng.","options":["她换了一家新公司，去卖别的产品","她请杨同乐帮她去和客户谈生意","她重新做了市场调查，并根据不同客户的情况来介绍产品","她决定只和年龄相同的客户交流"],"q":"为了提高效果，这位同事后来是怎么做的？"}],"scene":"不同客户，不同方法","sceneVi":"Khách hàng khác nhau, phương pháp khác nhau"},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"有的年轻人经常换工作，总觉得下一份工作会更好。","pinyin":"Yǒude niánqīngrén jīngcháng huàn gōngzuò, zǒng juéde xià yí fèn gōngzuò huì gèng hǎo.","speaker":"Đoạn văn","vi":"Một số người trẻ thường xuyên đổi việc, luôn cảm thấy công việc tiếp theo sẽ tốt hơn."},{"hanzi":"但是，适应新工作往往需要比较长的时间。","pinyin":"Dànshì, shìyìng xīn gōngzuò wǎngwǎng xūyào bǐjiào cháng de shíjiān.","speaker":"Đoạn văn","vi":"Tuy nhiên, việc thích nghi với công việc mới thường cần một khoảng thời gian khá dài."},{"hanzi":"如果总是换工作，不但很难积累经验，还可能会使自己的发展受到影响。","pinyin":"Rúguǒ zǒngshì huàn gōngzuò, búdàn hěn nán jīlěi jīngyàn, hái kěnéng huì shǐ zìjǐ de fāzhǎn shòudào yǐngxiǎng.","speaker":"Đoạn văn","vi":"Nếu cứ liên tục đổi việc, không những rất khó tích lũy kinh nghiệm mà còn có thể khiến sự phát triển của bản thân bị ảnh hưởng."},{"hanzi":"我认为，年轻人刚进入社会时，不能只关心工资的高低，更要重视学习。","pinyin":"Wǒ rènwéi, niánqīngrén gāng jìnrù shèhuì shí, bù néng zhǐ guānxīn gōngzī de gāodī, gèng yào zhòngshì xuéxí.","speaker":"Đoạn văn","vi":"Tôi cho rằng, khi người trẻ mới bước chân vào xã hội, không thể chỉ quan tâm đến mức lương cao hay thấp, mà càng phải coi trọng việc học hỏi."},{"hanzi":"比如，学习课本中没有的专业知识，了解公司的管理方式，学会和同事有效交流，等等。","pinyin":"Bǐrú, xuéxí kèběn zhōng méiyǒu de zhuānyè zhīshi, liǎojiě gōngsī de guǎnlǐ fāngshì, xuéhuì hé tóngshì yǒuxiào jiāoliú, děngděng.","speaker":"Đoạn văn","vi":"Ví dụ như học những kiến thức chuyên môn không có trong sách giáo khoa, tìm hiểu cách thức quản lý của công ty, học cách giao tiếp hiệu quả với đồng nghiệp, v.v."},{"hanzi":"只有把这些基础打好，提高工作能力，今后才会有更好的发展机会。","pinyin":"Zhǐyǒu bǎ zhèxiē jīchǔ dǎ hǎo, tígāo gōngzuò nénglì, jīnhòu cái huì yǒu gèng hǎo de fāzhǎn jīhuì.","speaker":"Đoạn văn","vi":"Chỉ khi xây dựng vững chắc những nền tảng này và nâng cao năng lực làm việc, sau này mới có những cơ hội phát triển tốt hơn."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"如果总是换工作，不但很难积累经验，还可能会使自己的发展受到影响\" (Nếu cứ luôn đổi việc, không những khó tích lũy kinh nghiệm mà còn có thể khiến sự phát triển của bản thân bị ảnh hưởng), nên đáp án đúng là khó tích lũy kinh nghiệm và có thể ảnh hưởng đến sự phát triển bản thân.","options":["会变得越来越不喜欢学习新知识","很难积累经验，还可能影响自己的发展","没有时间去认识新公司的同事","工资一定会比以前低很多"],"q":"根据课文，年轻人如果经常换工作，可能会有什么坏处？"},{"answerIdx":2,"explanation":"Trong bài có câu \"年轻人刚进入社会时，不能只关心工资的高低，更要重视学习。比如，学习课本中没有的专业知识，了解公司的管理方式，学会和同事有效交流，等等。只有把这些基础打好...\" (Người trẻ mới bước vào xã hội không thể chỉ quan tâm lương cao thấp mà càng phải coi trọng việc học, ví dụ học kiến thức chuyên môn không có trong sách vở, tìm hiểu cách quản lý của công ty, học cách giao tiếp hiệu quả với đồng nghiệp... Chỉ khi xây dựng tốt nền tảng này...), nên đáp án đúng là coi trọng việc học kiến thức chuyên môn, cách quản lý và giao tiếp với đồng nghiệp để xây dựng nền tảng.","options":["尽量找一份工资最高、最轻松的工作","在一年内多换几份工作，看看自己喜欢什么","重视学习专业知识、管理方式和与同事交流，打好基础","只学好学校课本里的知识就足够了"],"q":"作者认为年轻人刚进入社会时，最应该重视什么？"}],"scene":"工作的选择与发展","sceneVi":"Lựa chọn và phát triển công việc"}],"hsk4a-8":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"家月，最近学习太紧张了，咱们明天出去放松放松吧。","pinyin":"Jiāyuè, zuìjìn xuéxí tài jǐnzhāng le, zánmen míngtiān chūqù fàngsōng fàngsōng ba.","speaker":"安妮","vi":"Gia Nguyệt à, dạo này học hành căng thẳng quá, ngày mai chúng mình ra ngoài thư giãn một chút đi."},{"hanzi":"呀，正好我也想出去呢。咱们去哪儿好呢？","pinyin":"Yā, zhènghǎo wǒ yě xiǎng chūqù ne. Zánmen qù nǎr hǎo ne?","speaker":"白家月","vi":"Ôi, đúng lúc mình cũng muốn ra ngoài đây. Chúng mình đi đâu thì hay nhỉ?"},{"hanzi":"不管去哪儿，能放松的地方都行。","pinyin":"Bùguǎn qù nǎr, néng fàngsōng de dìfang dōu xíng.","speaker":"安妮","vi":"Bất kể đi đâu, chỗ nào thư giãn được đều ổn cả."},{"hanzi":"郊区怎么样？","pinyin":"Jiāoqū zěnmeyàng?","speaker":"白家月","vi":"Vùng ngoại ô thì sao?"},{"hanzi":"天中说，下周王老师要带咱们去郊区游玩呢。","pinyin":"Tiānzhōng shuō, xià zhōu Wáng lǎoshī yào dài zánmen qù jiāoqū yóuwán ne.","speaker":"安妮","vi":"Thiên Trung bảo tuần sau thầy Vương sẽ dẫn chúng mình đi ngoại ô tham quan đấy."},{"hanzi":"是吗？那咱们明天去爬长城吧，不是说“不到长城非好汉”吗？","pinyin":"Shì ma? Nà zánmen míngtiān qù pá Chángchéng ba, bú shì shuō “bú dào Chángchéng fēi hǎohàn” ma?","speaker":"白家月","vi":"Thế à? Vậy ngày mai chúng mình đi leo Vạn Lý Trường Thành đi, chẳng phải có câu 'Bất đáo Trường Thành phi hảo hán' sao?"},{"hanzi":"好主意！不过明天是个大晴天，外出记得戴帽子。","pinyin":"Hǎo zhǔyi! Búguò míngtiān shì ge dà qíngtiān, wàichū jìde dài màozi.","speaker":"安妮","vi":"Ý hay đấy! Nhưng ngày mai trời nắng to, ra ngoài nhớ đội mũ nhé."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, khi Bạch Gia Nguyệt gợi ý đi ngoại ô, Anny nói \"天中说，下周王老师要带咱们去郊区游玩呢\" (Thiên Trung nói tuần sau thầy Vương sẽ dẫn chúng mình đi chơi ở ngoại ô đấy), nên hai người không đi ngoại ô vào ngày mai.","options":["因为郊区太远，明天来不及回来","因为下周王老师要带她们去郊区游玩","因为明天要下雨，不适合去郊区","因为她们以前已经去过好几次郊区了"],"q":"为什么安妮和白家月明天不去郊区玩？"},{"answerIdx":2,"explanation":"Trong bài, Bạch Gia Nguyệt đề nghị \"那咱们明天去爬长城吧\" (Vậy ngày mai chúng mình đi leo Trường Thành đi) và Anny đồng ý rồi nhắc \"不过明天是个大晴天，外出记得戴帽子\" (Nhưng ngày mai trời nắng to đấy, ra ngoài nhớ đội mũ nhé), nên đáp án đúng là đi leo Trường Thành và nhớ đội mũ.","options":["去公园散步，安妮提醒她多带点儿水","在宿舍休息，安妮提醒她早点儿睡觉","去爬长城，安妮提醒她明天是大晴天，记得戴帽子","去郊区爬山，安妮提醒她穿舒服的鞋"],"q":"两人最后决定明天去做什么？安妮还提醒白家月什么？"}],"scene":"周五晚上，安妮给白家月打电话。","sceneVi":"Tối thứ Sáu, Anny gọi điện thoại cho Bạch Gia Nguyệt."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"同乐哥，你们平时工作忙吗？","pinyin":"Tónglè gē, nǐmen píngshí gōngzuò máng ma?","speaker":"李文","vi":"Anh Đồng Lạc, bình thường công việc của mọi người có bận không?"},{"hanzi":"挺忙的。以前我总觉得年轻时要多学多干，所以参加了公司里的很多项目，经常加班、熬夜，身体也亮起了红灯。","pinyin":"Tǐng máng de. Yǐqián wǒ zǒng juéde niánqīng shí yào duō xué duō gàn, suǒyǐ cānjiā le gōngsī lǐ de hěn duō xiàngmù, jīngcháng jiābān, áoyè, shēntǐ yě liàngqǐ le hóngdēng.","speaker":"杨同乐","vi":"Khá bận đấy. Trước đây anh luôn nghĩ khi còn trẻ thì phải học nhiều làm nhiều, nên đã tham gia rất nhiều dự án trong công ty, thường xuyên tăng ca, thức khuya, cơ thể cũng bật đèn đỏ (báo động sức khỏe) luôn."},{"hanzi":"还是别给自己太大压力，否则，失去健康就不值得了。","pinyin":"Háishi bié gěi zìjǐ tài dà yālì, fǒuzé, shīqù jiànkāng jiù bù zhídé le.","speaker":"李文","vi":"Tốt nhất đừng tự tạo áp lực quá lớn cho bản thân, nếu không, đánh mất sức khỏe thì thật không đáng chút nào."},{"hanzi":"是啊，后来我就不接那么多项目了。我发现暂停下来、好好休息之后，我能把工作做得更快更好。","pinyin":"Shì a, hòulái wǒ jiù bù jiē nàme duō xiàngmù le. Wǒ fāxiàn zàntíng xiàlái, hǎohāo xiūxi zhīhòu, wǒ néng bǎ gōngzuò zuò de gèng kuài gèng hǎo.","speaker":"杨同乐","vi":"Đúng vậy, sau này anh không nhận nhiều dự án như thế nữa. Anh nhận ra sau khi tạm dừng lại và nghỉ ngơi đầy đủ, anh có thể làm việc nhanh hơn và tốt hơn."},{"hanzi":"对，该工作时就工作，该放松时就要放松。","pinyin":"Duì, gāi gōngzuò shí jiù gōngzuò, gāi fàngsōng shí jiù yào fàngsōng.","speaker":"李文","vi":"Đúng thế, lúc cần làm việc thì làm việc, lúc cần thư giãn thì phải thư giãn."},{"hanzi":"是的，现在我周末常来郊区，在好山好水好风景中放松自己。","pinyin":"Shì de, xiànzài wǒ zhōumò cháng lái jiāoqū, zài hǎo shān hǎo shuǐ hǎo fēngjǐng zhōng fàngsōng zìjǐ.","speaker":"杨同乐","vi":"Phải đấy, bây giờ cuối tuần anh thường đến ngoại ô, thư giãn bản thân giữa núi non, sông nước và phong cảnh tươi đẹp."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Dương Đồng Lạc nói \"所以参加了公司里的很多项目，经常加班、熬夜，身体也亮起了红灯\" (nên tôi đã tham gia rất nhiều dự án trong công ty, thường xuyên tăng ca, thức khuya, sức khỏe cũng bật đèn đỏ), nên nguyên nhân là do anh tham gia nhiều dự án, thường xuyên tăng ca và thức khuya.","options":["因为他平时工作太轻松，很少运动","因为他参加了很多项目，经常加班、熬夜","因为他周末经常去郊区，太累了","因为他在公司里和同事相处得不好"],"q":"以前杨同乐的身体为什么亮起了红灯？"},{"answerIdx":0,"explanation":"Trong bài, Dương Đồng Lạc chia sẻ \"我发现暂停下来、好好休息之后，我能把工作做得更快更好\" (Tôi phát hiện ra sau khi tạm dừng lại và nghỉ ngơi đàng hoàng, tôi có thể làm việc nhanh hơn và tốt hơn), nên đáp án đúng là anh ấy có thể làm việc nhanh hơn và tốt hơn.","options":["他能把工作做得更快更好","他的工作变得比以前更慢了","他再也不用去公司上班了","公司给他安排了更多的项目"],"q":"后来不再接那么多项目并好好休息以后，杨同乐的工作有什么变化？"}],"scene":"周末，李文、杨同乐等人去郊区游玩。","sceneVi":"Cuối tuần, Lý Văn, Dương Đồng Lạc và mọi người đi ngoại ô dạo chơi."},{"id":3,"isNarrative":true,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"以前杨同乐总觉得自己年轻，就应该多学多干、积累经验。","pinyin":"Yǐqián Yáng Tónglè zǒng juéde zìjǐ niánqīng, jiù yīnggāi duō xué duō gàn, jīlěi jīngyàn.","speaker":"Đoạn văn","vi":"Trước đây Dương Đồng Lạc luôn nghĩ mình còn trẻ thì nên học nhiều làm nhiều, tích lũy kinh nghiệm."},{"hanzi":"很多年轻人和他想法一样。","pinyin":"Hěn duō niánqīngrén hé tā xiǎngfǎ yíyàng.","speaker":"Đoạn văn","vi":"Rất nhiều người trẻ cũng có suy nghĩ giống như anh ấy."},{"hanzi":"但是，由于工作紧张，他们经常加班、熬夜，休息不够，结果工作效率下降，健康也受到了影响。","pinyin":"Dànshì, yóuyú gōngzuò jǐnzhāng, tāmen jīngcháng jiābān, áoyè, xiūxi bú gòu, jiéguǒ gōngzuò xiàolǜ xiàjiàng, jiànkāng yě shòudào le yǐngxiǎng.","speaker":"Đoạn văn","vi":"Thế nhưng, do công việc căng thẳng, họ thường xuyên tăng ca, thức khuya, nghỉ ngơi không đủ, kết quả là hiệu suất công việc giảm sút và sức khỏe cũng bị ảnh hưởng."},{"hanzi":"现在越来越多的人认识到，跟一直加班相比，休息好了再工作，效率更高。","pinyin":"Xiànzài yuèláiyuè duō de rén rènshì dào, gēn yìzhí jiābān xiāngbǐ, xiūxi hǎo le zài gōngzuò, xiàolǜ gèng gāo.","speaker":"Đoạn văn","vi":"Hiện nay ngày càng có nhiều người nhận ra rằng, so với việc liên tục tăng ca thì nghỉ ngơi đầy đủ rồi mới làm việc sẽ đạt hiệu suất cao hơn."},{"hanzi":"因此，很多人开始做出改变，提醒自己减轻压力、多多放松。","pinyin":"Yīncǐ, hěn duō rén kāishǐ zuòchū gǎibiàn, tíxǐng zìjǐ jiǎnqīng yālì, duōduō fàngsōng.","speaker":"Đoạn văn","vi":"Vì vậy, nhiều người bắt đầu thay đổi, tự nhắc nhở bản thân giảm bớt áp lực và thư giãn nhiều hơn."},{"hanzi":"比如，杨同乐周末时或者与朋友们去郊区游玩，在大自然美丽的景色中好好放松自己；或者就在家里安安静静地看看书。","pinyin":"Bǐrú, Yáng Tónglè zhōumò shí huòzhě yǔ péngyoumen qù jiāoqū yóuwán, zài dàzìrán měilì de jǐngsè zhōng hǎohāo fàngsōng zìjǐ; huòzhě jiù zài jiālǐ ān'ānjìngjìng de kànkan shū.","speaker":"Đoạn văn","vi":"Ví dụ, vào cuối tuần Dương Đồng Lạc hoặc là cùng bạn bè đi ngoại ô dạo chơi, thư giãn thật tốt giữa khung cảnh thiên nhiên tươi đẹp; hoặc là ở nhà đọc sách một cách yên tĩnh."},{"hanzi":"休息好了，再回去上班时，心情愉快，工作效率也更高。","pinyin":"Xiūxi hǎo le, zài huíqù shàngbān shí, xīnqíng yúkuài, gōngzuò xiàolǜ yě gèng gāo.","speaker":"Đoạn văn","vi":"Nghỉ ngơi đầy đủ rồi, khi quay lại đi làm, tâm trạng vui vẻ mà hiệu suất công việc cũng cao hơn."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"但是，由于工作紧张，他们经常加班、熬夜，休息不够，结果工作效率下降，健康也受到了影响\" (Nhưng do công việc căng thẳng, họ thường xuyên tăng ca, thức khuya, nghỉ ngơi không đủ, kết quả là hiệu suất công việc giảm sút, sức khỏe cũng bị ảnh hưởng), nên hậu quả là hiệu suất công việc giảm và sức khỏe bị ảnh hưởng.","options":["经验很快增加，心情越来越好","工作效率下降，健康也受到影响","每个人都能更快地完成所有工作","周末会有更多时间和朋友去郊区"],"q":"根据课文，年轻人经常加班、熬夜、休息不够会带来什么结果？"},{"answerIdx":1,"explanation":"Trong bài có câu \"比如，杨同乐周末时或者与朋友们去郊区游玩，在大自然美丽的景色中好好放松自己；或者就在家里安安静静地看看书\" (Ví dụ, cuối tuần Dương Đồng Lạc hoặc đi chơi ngoại ô với bạn bè để thư giãn giữa cảnh đẹp thiên nhiên; hoặc ở nhà yên tĩnh đọc sách), nên đáp án đúng là đi chơi ngoại ô cùng bạn bè hoặc yên tĩnh đọc sách ở nhà.","options":["继续在公司加班，或者准备下周的项目","和朋友去郊区游玩，或者在家里安安静静地看书","每天都在家里睡觉，哪里都不去","一个人坐飞机去其他城市旅游"],"q":"杨同乐周末通常怎样放松自己？"}],"scene":"学会放松","sceneVi":"Học cách thư giãn"},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"一到周末，很多人都喜欢外出游玩。","pinyin":"Yí dào zhōumò, hěn duō rén dōu xǐhuan wàichū yóuwán.","speaker":"Đoạn văn","vi":"Cứ đến cuối tuần, rất nhiều người đều thích ra ngoài đi chơi."},{"hanzi":"你一般去哪里呢？","pinyin":"Nǐ yìbān qù nǎlǐ ne?","speaker":"Đoạn văn","vi":"Bạn thường đi đâu thế?"},{"hanzi":"我生活在中国的首都——北京。","pinyin":"Wǒ shēnghuó zài Zhōngguó de shǒudū——Běijīng.","speaker":"Đoạn văn","vi":"Tôi sống ở Bắc Kinh — thủ đô của Trung Quốc."},{"hanzi":"在北京，周末的时候，有人会在市区公园走走，看看眼前的美景；有人喜欢去参观长城、故宫等有名的景点，放松心情的同时，也能了解历史文化。","pinyin":"Zài Běijīng, zhōumò de shíhou, yǒurén huì zài shìqū gōngyuán zǒuzou, kànkan yǎnqián de měijǐng; yǒurén xǐhuan qù cānguān Chángchéng, Gùgōng děng yǒumíng de jǐngdiǎn, fàngsōng xīnqíng de tóngshí, yě néng liǎojiě lìshǐ wénhuà.","speaker":"Đoạn văn","vi":"Ở Bắc Kinh, vào cuối tuần, có người sẽ đi dạo trong công viên nội thành, ngắm nhìn cảnh đẹp trước mắt; có người thích đi tham quan các danh lam thắng cảnh nổi tiếng như Vạn Lý Trường Thành, Cố Cung, vừa thư giãn tâm trạng lại vừa có thể tìm hiểu văn hóa lịch sử."},{"hanzi":"北京交通很方便，所以我和家人更爱乘坐公交车去郊区，偶尔也会自己开车。","pinyin":"Běijīng jiāotōng hěn fāngbiàn, suǒyǐ wǒ hé jiārén gèng ài chéngzuò gōngjiāochē qù jiāoqū, ǒu'ěr yě huì zìjǐ kāichē.","speaker":"Đoạn văn","vi":"Giao thông ở Bắc Kinh rất thuận tiện, vì vậy tôi và gia đình thích đi xe buýt ra vùng ngoại ô hơn, thỉnh thoảng cũng tự lái xe."},{"hanzi":"郊区有山有水，还有很多农家乐，吃、玩、住都十分方便。","pinyin":"Jiāoqū yǒu shān yǒu shuǐ, hái yǒu hěn duō nóngjiālè, chī, wán, zhù dōu shífēn fāngbiàn.","speaker":"Đoạn văn","vi":"Vùng ngoại ô có núi có sông, còn có rất nhiều khu du lịch nhà nông (nông gia lạc), ăn uống, vui chơi, nghỉ ngơi đều vô cùng tiện lợi."},{"hanzi":"在我看来，不管去哪里玩，实际上都是为了放松。","pinyin":"Zài wǒ kànlái, bùguǎn qù nǎlǐ wán, shíjìshang dōu shì wèile fàngsōng.","speaker":"Đoạn văn","vi":"Theo tôi thấy, bất kể đi chơi ở đâu, thực chất đều là để thư giãn."},{"hanzi":"也可以说，只要能放松，去哪儿都合适。","pinyin":"Yě kěyǐ shuō, zhǐyào néng fàngsōng, qù nǎr dōu héshì.","speaker":"Đoạn văn","vi":"Cũng có thể nói rằng, chỉ cần có thể thư giãn được thì đi đâu cũng đều thích hợp cả."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài có câu \"有人喜欢去参观长城、故宫等有名的景点，放松心情的同时，也能了解历史文化\" (Có người thích đi tham quan các danh thắng nổi tiếng như Trường Thành, Cố Cung, vừa thư giãn tâm trạng vừa có thể tìm hiểu lịch sử văn hóa), nên lợi ích là vừa thư giãn vừa tìm hiểu được lịch sử văn hóa.","options":["既可以放松心情，又能了解历史文化","可以住进郊区的农家乐里吃住","不用买票，而且比市区公园更近","自己开车直接在景点里面逛"],"q":"在北京，人们周末去参观长城、故宫等景点有什么好处？"},{"answerIdx":2,"explanation":"Trong bài, tác giả kết luận \"在我看来，不管去哪里玩，实际上都是为了放松。也可以说，只要能放松，去哪儿都合适\" (Theo tôi, bất kể đi chơi ở đâu, thực ra đều là để thư giãn. Cũng có thể nói, chỉ cần có thể thư giãn thì đi đâu cũng hợp), nên đáp án đúng là chỉ cần giúp bản thân thư giãn thì đi đâu cũng phù hợp.","options":["必须去有山有水的郊区农家乐","一定要去北京最有名的历史景点","只要能让自己放松，去哪儿都合适","最好是不用坐公交车就能到的地方"],"q":"在作者看来，去哪里游玩才是最合适的？"}],"scene":"去哪儿放松好","sceneVi":"Đi đâu thư giãn thì tốt"}],"hsk4a-9":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"家月，给你的，祝你生日快乐！","pinyin":"Jiāyuè, gěi nǐ de, zhù nǐ shēngrì kuàilè!","speaker":"李文","vi":"Gia Nguyệt, tặng em này, chúc em sinh nhật vui vẻ!"},{"hanzi":"啊，好漂亮的花！还有巧克力！你怎么知道我喜欢这个巧克力？","pinyin":"A, hǎo piàoliang de huā! Hái yǒu qiǎokèlì! Nǐ zěnme zhīdào wǒ xǐhuan zhège qiǎokèlì?","speaker":"白家月","vi":"Ồ, hoa đẹp quá! Còn có cả sô-cô-la nữa! Sao anh biết em thích loại sô-cô-la này vậy?"},{"hanzi":"上次咱们去超市，看你拿起来看了看又放下了，我就记住了。","pinyin":"Shàngcì zánmen qù chāoshì, kàn nǐ ná qǐlái kàn le kàn yòu fàng xià le, wǒ jiù jìzhù le.","speaker":"李文","vi":"Lần trước chúng ta đi siêu thị, thấy em cầm lên xem rồi lại đặt xuống, anh liền nhớ kỹ luôn."},{"hanzi":"好感动！我不说你也懂我在想什么，你真是细心又浪漫。其实刚认识不久，你的幽默与耐心就很吸引我，不过我当时也只把你当普通朋友。如果你没有一直找我聊天儿，我们可能就错过了。","pinyin":"Hǎo gǎndòng! Wǒ bù shuō nǐ yě dǒng wǒ zài xiǎng shénme, nǐ zhēn shì xìxīn yòu làngmàn. Qíshí gāng rènshi bùjiǔ, nǐ de yōumò yǔ nàixīn jiù hěn xīyǐn wǒ, búguò wǒ dāngshí yě zhǐ bǎ nǐ dāng pǔtōng péngyou. Rúguǒ nǐ méiyǒu yìzhí zhǎo wǒ liáotiānr, wǒmen kěnéng jiù cuòguò le.","speaker":"白家月","vi":"Cảm động quá! Em không nói anh cũng hiểu em đang nghĩ gì, anh đúng là vừa chu đáo lại vừa lãng mạn. Thật ra hồi mới quen chưa lâu, sự hài hước và kiên nhẫn của anh đã rất thu hút em rồi, nhưng lúc đó em cũng chỉ coi anh là bạn bình thường. Nếu anh không luôn chủ động tìm em trò chuyện, có lẽ chúng ta đã bỏ lỡ nhau rồi."},{"hanzi":"我终于遇见了对的人，哪能错过呢？","pinyin":"Wǒ zhōngyú yùjiàn le duì de rén, nǎ néng cuòguò ne?","speaker":"李文","vi":"Anh cuối cùng cũng gặp được đúng người rồi, sao có thể bỏ lỡ được chứ?"},{"hanzi":"遇见你，我也觉得很幸运。","pinyin":"Yùjiàn nǐ, wǒ yě juéde hěn xìngyùn.","speaker":"白家月","vi":"Gặp được anh, em cũng cảm thấy rất may mắn."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, khi nhận quà, Bạch Gia Nguyệt đã thốt lên \"啊，好漂亮的花！还有巧克力！\" (Ôi, hoa đẹp quá! Lại còn có sô-cô-la nữa!), nên đáp án đúng là hoa và sô-cô-la (花和巧克力).","options":["衣服和帽子","花和巧克力","蛋糕和水果","书和咖啡"],"q":"白家月过生日时，李文送了她什么礼物？"},{"answerIdx":2,"explanation":"Trong bài, Lý Văn giải thích \"上次咱们去超市，看你拿起来看了看又放下了，我就记住了。\" (Lần trước hai ta đi siêu thị, thấy em cầm lên xem rồi lại đặt xuống, nên anh đã nhớ kỹ.), nên đáp án đúng là anh ấy đã để ý thấy trong lần đi siêu thị trước.","options":["白家月的朋友告诉他的","白家月发微信跟他说过","他上次去超市时注意到的","服务员向他推荐的"],"q":"李文是怎么知道白家月喜欢那种巧克力的？"}],"scene":"在餐馆里，李文给白家月过生日。","sceneVi":"Ở trong nhà hàng, Lý Văn tổ chức sinh nhật cho Bạch Gia Nguyệt."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"看到一飞和同乐结婚后这么幸福，我这个介绍人也特别开心。","pinyin":"Kàndào Yīfēi hé Tónglè jiéhūn hòu zhème xìngfú, wǒ zhège jièshàorén yě tèbié kāixīn.","speaker":"王一雪","vi":"Thấy Nhất Phi và Đồng Lạc sau khi kết hôn hạnh phúc như vậy, người làm mối như em cũng thấy đặc biệt vui mừng."},{"hanzi":"是啊，同乐是你的好朋友，一飞是你妹妹，你都很了解。","pinyin":"Shì a, Tónglè shì nǐ de hǎo péngyou, Yīfēi shì nǐ mèimei, nǐ dōu hěn liǎojiě.","speaker":"刘明","vi":"Đúng vậy, Đồng Lạc là bạn tốt của em, Nhất Phi là em gái em, em đều rất hiểu cả hai."},{"hanzi":"嗯，他们尽管性格不同，但是有很多共同爱好。特别是同乐人好，性格也好，很有责任感。","pinyin":"Ng, tāmen jǐnguǎn xìnggé bùtóng, dànshì yǒu hěn duō gòngtóng àihào. Tèbié shì Tónglè rén hǎo, xìnggé yě hǎo, hěn yǒu zérèngǎn.","speaker":"王一雪","vi":"Ừ, tuy tính cách họ khác nhau, nhưng lại có rất nhiều sở thích chung. Đặc biệt là Đồng Lạc người tốt, tính tình cũng tốt, lại rất có tinh thần trách nhiệm."},{"hanzi":"是的，一飞也算在对的时间遇到了对的人。后边的路还很长，希望他们能一直相互理解、相互支持。","pinyin":"Shì de, Yīfēi yě suàn zài duì de shíjiān yùdào le duì de rén. Hòubian de lù hái hěn cháng, xīwàng tāmen néng yìzhí xiānghù lǐjiě, xiānghù zhīchí.","speaker":"刘明","vi":"Phải đấy, Nhất Phi cũng coi như đã gặp được đúng người vào đúng thời điểm. Chặng đường phía sau còn rất dài, hy vọng họ có thể luôn thấu hiểu và ủng hộ lẫn nhau."},{"hanzi":"我了解同乐，更了解一飞，相信他们会一直走下去的。","pinyin":"Wǒ liǎojiě Tónglè, gèng liǎojiě Yīfēi, xiāngxìn tāmen huì yìzhí zǒu xiàqù de.","speaker":"王一雪","vi":"Em hiểu Đồng Lạc, càng hiểu Nhất Phi hơn, tin rằng họ sẽ đi cùng nhau đến suốt đời."},{"hanzi":"祝他们越来越幸福。","pinyin":"Zhù tāmen yuèláiyuè xìngfú.","speaker":"刘明","vi":"Chúc họ ngày càng hạnh phúc."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài, Vương Nhất Tuyết nói \"他们尽管性格不同，但是有很多共同爱好。特别是同乐人好，性格也好，很有责任感。\" (Tuy tính cách của họ khác nhau, nhưng có rất nhiều sở thích chung. Đặc biệt là Đồng Lạc người tốt, tính tình cũng tốt, rất có tinh thần trách nhiệm.), nên đáp án đúng là họ có nhiều sở thích chung và Đồng Lạc là người tốt, có trách nhiệm.","options":["他们性格完全一样，而且住得很近","他们有很多共同爱好，而且同乐人好、有责任感","他们从小一起长大，非常了解彼此","他们在同一家公司工作，天天见面"],"q":"在王一雪看来，一飞和同乐为什么很合适？"},{"answerIdx":3,"explanation":"Trong bài, Lưu Minh nói \"后边的路还很长，希望他们能一直相互理解、相互支持。\" (Chặng đường phía trước còn rất dài, hy vọng họ có thể luôn thấu hiểu và ủng hộ lẫn nhau.), nên đáp án đúng là hy vọng họ luôn thấu hiểu và ủng hộ lẫn nhau.","options":["希望他们以后能经常出去旅游","希望他们早点儿买一套大房子","希望他们能一起换一份更好的工作","希望他们一直相互理解、相互支持"],"q":"对于一飞和同乐以后的婚姻生活，刘明有什么希望？"}],"scene":"在家里，王一雪和刘明谈论王一飞和杨同乐的婚姻。","sceneVi":"Ở nhà, Vương Nhất Tuyết và Lưu Minh bàn luận về cuộc hôn nhân của Vương Nhất Phi và Dương Đồng Lạc."},{"id":3,"isNarrative":true,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"王一雪比杨同乐更早进入公司。","pinyin":"Wáng Yīxuě bǐ Yáng Tónglè gèng zǎo jìnrù gōngsī.","speaker":"Đoạn văn","vi":"Vương Nhất Tuyết vào công ty sớm hơn Dương Đồng Lạc."},{"hanzi":"杨同乐刚来不久，王一雪对他印象就非常好：人很实在，性格阳光，工作负责，表现积极……","pinyin":"Yáng Tónglè gāng lái bùjiǔ, Wáng Yīxuě duì tā yìnxiàng jiù fēicháng hǎo: rén hěn shízài, xìnggé yángguāng, gōngzuò fùzé, biǎoxiàn jījí……","speaker":"Đoạn văn","vi":"Dương Đồng Lạc mới đến chưa lâu, Vương Nhất Tuyết đã có ấn tượng rất tốt về anh ấy: con người chân thật, tính cách cởi mở tươi sáng, làm việc có trách nhiệm, biểu hiện tích cực..."},{"hanzi":"后来他们一起出了次差，此次出差，让两人熟悉了起来，从此成了好朋友。","pinyin":"Hòulái tāmen yìqǐ chū le cì chāi, cǐcì chūchāi, ràng liǎng rén shúxī le qǐlái, cóngcǐ chéng le hǎo péngyou.","speaker":"Đoạn văn","vi":"Sau đó họ cùng nhau đi công tác một chuyến, chuyến công tác này đã giúp hai người thân thiết hơn, từ đó trở thành bạn tốt."},{"hanzi":"一次聊天儿时，王一雪了解到杨同乐还没女朋友，正好自己的妹妹王一飞也没有男朋友，于是王一雪就把王一飞介绍给了他。","pinyin":"Yícì liáotiānr shí, Wáng Yīxuě liǎojiě dào Yáng Tónglè hái méi nǚpéngyou, zhènghǎo zìjǐ de mèimei Wáng Yīfēi yě méiyǒu nánpéngyou, yúshì Wáng Yīxuě jiù bǎ Wáng Yīfēi jièshào gěi le tā.","speaker":"Đoạn văn","vi":"Một lần trò chuyện, Vương Nhất Tuyết biết được Dương Đồng Lạc vẫn chưa có bạn gái, trùng hợp em gái mình là Vương Nhất Phi cũng chưa có bạn trai, thế là Vương Nhất Tuyết bèn giới thiệu Vương Nhất Phi cho anh ấy."},{"hanzi":"杨同乐和王一飞认识后，很聊得来，两人之间慢慢产生了爱情，最后成了夫妻。","pinyin":"Yáng Tónglè hé Wáng Yīfēi rènshi hòu, hěn liáodelái, liǎng rén zhījiān mànmàn chǎnshēng le àiqíng, zuìhòu chéng le fūqī.","speaker":"Đoạn văn","vi":"Sau khi quen nhau, Dương Đồng Lạc và Vương Nhất Phi nói chuyện rất hợp, giữa hai người dần nảy sinh tình yêu, cuối cùng trở thành vợ chồng."},{"hanzi":"杨同乐说自己很幸运，和王一雪这份同事间的友情，给他带来了美好的爱情。","pinyin":"Yáng Tónglè shuō zìjǐ hěn xìngyùn, hé Wáng Yīxuě zhè fèn tóngshì jiān de yǒuqíng, gěi tā dàilái le měihǎo de àiqíng.","speaker":"Đoạn văn","vi":"Dương Đồng Lạc nói mình rất may mắn, tình bạn đồng nghiệp với Vương Nhất Tuyết đã mang lại cho anh ấy một tình yêu đẹp."}],"readingQuiz":[{"answerIdx":1,"explanation":"Trong bài có câu \"后来他们一起出了次差，此次出差，让两人熟悉了起来，从此成了好朋友。\" (Sau này họ cùng đi công tác một chuyến, chuyến công tác này đã giúp hai người trở nên thân thiết và từ đó thành bạn tốt.), nên đáp án đúng là sau khi họ cùng đi công tác.","options":["他们一起参加大学同学聚会的时候","他们一起出差以后","王一飞介绍他们认识以后","杨同乐刚搬家到王一雪家附近时"],"q":"王一雪和杨同乐是在什么情况下熟悉起来的？"},{"answerIdx":2,"explanation":"Trong bài có câu \"杨同乐说自己很幸运，和王一雪这份同事间的友情，给他带来了美好的爱情。\" (Dương Đồng Lạc nói mình rất may mắn, tình bạn đồng nghiệp với Vương Nhất Tuyết đã mang lại cho anh ấy một tình yêu đẹp.), nên đáp án đúng là tình bạn với Vương Nhất Tuyết đã mang lại cho anh ấy tình yêu đẹp.","options":["因为他刚进公司就得到了很高的工资","因为他经常能去不同的城市出差","因为和王一雪的友情给他带来了美好的爱情","因为他不用找工作就认识了王一雪"],"q":"杨同乐为什么觉得自己很幸运？"}],"scene":"杨同乐的双份幸运","sceneVi":"Niềm may mắn nhân đôi của Dương Đồng Lạc"},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"李文在校园里遇见白家月，从此，他们的人生变得更加精彩；王一飞和杨同乐通过王一雪介绍认识后，感情越来越深，最后两人幸福地走到了一起。","pinyin":"Lǐ Wén zài xiàoyuán lǐ yùjiàn Bái Jiāyuè, cóngcǐ, tāmen de rénshēng biànde gèngjiā jīngcǎi; Wáng Yīfēi hé Yáng Tónglè tōngguò Wáng Yīxuě jièshào rènshi hòu, gǎnqíng yuèláiyuè shēn, zuìhòu liǎng rén xìngfú de zǒudào le yìqǐ.","speaker":"Đoạn văn","vi":"Lý Văn gặp Bạch Gia Nguyệt trong khuôn viên trường, từ đó cuộc đời họ trở nên rực rỡ hơn; Vương Nhất Phi và Dương Đồng Lạc sau khi quen nhau qua sự giới thiệu của Vương Nhất Tuyết, tình cảm ngày càng sâu đậm, cuối cùng hai người đã hạnh phúc đến với nhau."},{"hanzi":"在我看来，遇见爱情的方式并不重要，重要的是在合适的时间遇到了合适的人。","pinyin":"Zài wǒ kànlái, yùjiàn àiqíng de fāngshì bìng bú zhòngyào, zhòngyào de shì zài héshì de shíjiān yùdào le héshì de rén.","speaker":"Đoạn văn","vi":"Theo tôi, cách thức gặp được tình yêu không hề quan trọng, điều quan trọng là gặp được đúng người vào đúng thời điểm."},{"hanzi":"遇见你，刚刚好。","pinyin":"Yùjiàn nǐ, gānggānghǎo.","speaker":"Đoạn văn","vi":"Gặp được bạn, vừa vặn đúng lúc."},{"hanzi":"不过美好的遇见只是爱的开始，爱更需要经营。","pinyin":"Búguò měihǎo de yùjiàn zhǐ shì ài de kāishǐ, ài gèng xūyào jīngyíng.","speaker":"Đoạn văn","vi":"Tuy nhiên, cuộc gặp gỡ tốt đẹp chỉ là khởi đầu của tình yêu, tình yêu càng cần phải được vun đắp."},{"hanzi":"在一段感情中，两个人要多关注对方的感受，尤其是结婚后，更要共同经营好家庭，日子才能越过越好。","pinyin":"Zài yí duàn gǎnqíng zhōng, liǎng gè rén yào duō guānzhù duìfāng de gǎnshòu, yóuqí shì jiéhūn hòu, gèng yào gòngtóng jīngyíng hǎo jiātíng, rìzi cái néng yuè guò yuè hǎo.","speaker":"Đoạn văn","vi":"Trong một mối quan hệ tình cảm, hai người cần quan tâm nhiều hơn đến cảm nhận của đối phương, đặc biệt là sau khi kết hôn, càng phải cùng nhau vun vén gia đình thật tốt thì cuộc sống mới ngày càng tốt đẹp hơn được."},{"hanzi":"爱，从来都是相互尊重、理解与支持，不是吗？","pinyin":"Ài, cónglái dōu shì xiānghù zūnzhòng, lǐjiě yǔ zhīchí, búshì ma?","speaker":"Đoạn văn","vi":"Tình yêu từ trước đến nay vẫn luôn là sự tôn trọng, thấu hiểu và ủng hộ lẫn nhau, phải không nào?"}],"readingQuiz":[{"answerIdx":3,"explanation":"Trong bài có câu \"在我看来，遇见爱情的方式并不重要，重要的是在合适的时间遇到了合适的人。\" (Theo tôi thấy, cách gặp được tình yêu không quan trọng, điều quan trọng là gặp đúng người vào đúng thời điểm.), nên đáp án đúng là gặp đúng người vào đúng thời điểm.","options":["遇见爱情的方式一定要很浪漫","必须是在校园里认识的","一定要通过好朋友的介绍","在合适的时间遇到合适的人"],"q":"在作者看来，遇见爱情时最重要的是什么？"},{"answerIdx":0,"explanation":"Trong bài có câu \"两个人要多关注对方的感受，尤其是结婚后，更要共同经营好家庭，日子才能越过越好。\" (Hai người cần quan tâm nhiều hơn đến cảm nhận của đối phương, đặc biệt là sau khi kết hôn càng phải cùng nhau vun đắp gia đình, cuộc sống mới ngày càng tốt đẹp hơn.), nên đáp án đúng là quan tâm nhiều hơn đến cảm nhận của nhau và cùng nhau vun đắp gia đình.","options":["多关注对方感受，共同经营好家庭","每天都给对方买很贵的礼物","遇到问题时不要告诉对方","尽量减少见面，各自忙自己的事"],"q":"为了让感情和婚姻生活越来越好，两个人应该怎么做？"}],"scene":"爱更需要经营","sceneVi":"Tình yêu càng cần sự vun đắp"}],"hsk4a-10":[{"id":1,"isNarrative":false,"label":"Bài khóa 1 (课文 1)","lines":[{"hanzi":"你看，这个小伙子从广州去哈尔滨出差，没想到哈尔滨的气温降到了零下二十几度，把他冻坏了。","pinyin":"Nǐ kàn, zhège xiǎohuǒzi cóng Guǎngzhōu qù Hā'ěrbīn chūchāi, méi xiǎngdào Hā'ěrbīn de qìwēn jiàngdào le língxià èrshí jǐ dù, bǎ tā dòng huài le.","speaker":"刘明","vi":"Em xem này, chàng trai này đi công tác từ Quảng Châu đến Cáp Nhĩ Tân, không ngờ nhiệt độ ở Cáp Nhĩ Tân giảm xuống âm hơn hai mươi độ, làm anh ấy lạnh cóng luôn."},{"hanzi":"他一定后悔自己穿少了吧？","pinyin":"Tā yídìng hòuhuǐ zìjǐ chuān shǎo le ba?","speaker":"王一雪","vi":"Chắc chắn anh ấy hối hận vì mình mặc ít quá rồi nhỉ?"},{"hanzi":"是啊，这就叫南方不懂北方的冷。","pinyin":"Shì a, zhè jiù jiào nánfāng bù dǒng běifāng de lěng.","speaker":"刘明","vi":"Đúng vậy, thế này gọi là miền Nam không hiểu cái lạnh của miền Bắc."},{"hanzi":"就是呢，冬天北方和南方的温度差别还是很大的。","pinyin":"Jiùshì ne, dōngtiān běifāng hé nánfāng de wēndù chābié háishì hěn dà de.","speaker":"王一雪","vi":"Đúng thế đấy, mùa đông sự chênh lệch nhiệt độ giữa miền Bắc và miền Nam vẫn rất lớn."},{"hanzi":"所以冬天来北方，尤其是东北，一定要提前查好目的地的天气，看看下不下雪，气温怎么样。","pinyin":"Suǒyǐ dōngtiān lái běifāng, yóuqí shì Dōngběi, yídìng yào tíqián chá hǎo mùdìdì de tiānqì, kànkan xià bu xiàxuě, qìwēn zěnmeyàng.","speaker":"刘明","vi":"Vì vậy mùa đông đến miền Bắc, đặc biệt là vùng Đông Bắc, nhất định phải tra trước thời tiết nơi đến, xem có tuyết rơi không, nhiệt độ thế nào."},{"hanzi":"对。更重要的是，说什么也得穿上厚一点儿的衣服。","pinyin":"Duì. Gèng zhòngyào de shì, shuō shénme yě děi chuān shang hòu yìdiǎnr de yīfu.","speaker":"王一雪","vi":"Đúng rồi. Quan trọng hơn là, dù thế nào cũng phải mặc quần áo dày một chút."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài, Lưu Minh nói \"没想到哈尔滨的气温降到了零下二十几度，把他冻坏了。\" (Không ngờ nhiệt độ ở Cáp Nhĩ Tân giảm xuống hơn âm hai mươi độ, làm cậu ấy lạnh cóng.), nên đáp án đúng là hơn âm hai mươi độ (零下二十几度).","options":["零上二十几度","零下十几度","零下二十几度","零度左右"],"q":"那个小伙子去哈尔滨出差时，那里的气温降到了多少度？"},{"answerIdx":1,"explanation":"Trong bài, Lưu Minh khuyên \"一定要提前查好目的地的天气\" (Nhất định phải xem trước thời tiết nơi đến) và Vương Nhất Tuyết bổ sung \"更重要的是，说什么也得穿上厚一点儿的衣服。\" (Quan trọng hơn là thế nào cũng phải mặc quần áo dày một chút.), nên đáp án đúng là kiểm tra thời tiết trước và mặc quần áo dày hơn.","options":["不用看天气预报，带一把伞就行","提前查好天气，一定要穿厚一点儿的衣服","尽量坐火车去，不要坐飞机","到了北方以后再去买薄衣服"],"q":"对于冬天去北方的人，刘明和王一雪提出了什么建议？"}],"scene":"在家里，刘明和王一雪说他在网上看到的一条信息。","sceneVi":"Ở nhà, Lưu Minh kể với Vương Nhất Tuyết về một mẩu tin anh ấy đọc được trên mạng."},{"id":2,"isNarrative":false,"label":"Bài khóa 2 (课文 2)","lines":[{"hanzi":"寒假你们打算做什么呢？","pinyin":"Hánjià nǐmen dǎsuàn zuò shénme ne?","speaker":"王一飞","vi":"Kỳ nghỉ đông các cậu định làm gì thế?"},{"hanzi":"我们刚刚还说呢，家月春节时要去广州，我计划去哈尔滨。","pinyin":"Wǒmen gānggāng hái shuō ne, Jiāyuè Chūnjié shí yào qù Guǎngzhōu, wǒ jìhuà qù Hā'ěrbīn.","speaker":"陈天中","vi":"Bọn mình vừa mới nói xong đấy, dịp Tết Gia Nguyệt sẽ đi Quảng Châu, còn mình dự định đi Cáp Nhĩ Tân."},{"hanzi":"那时候广州暖和，但哈尔滨特别冷，气温一般都低于零下十摄氏度甚至零下二十摄氏度，这么低的温度你受不了吧？","pinyin":"Nà shíhou Guǎngzhōu nuǎnhuo, dàn Hā'ěrbīn tèbié lěng, qìwēn yìbān dōu dīyú língxià shí shèshìdù shènzhì língxià èrshí shèshìdù, zhème dī de wēndù nǐ shòubuliǎo ba?","speaker":"王一飞","vi":"Lúc đó Quảng Châu ấm áp, nhưng Cáp Nhĩ Tân đặc biệt lạnh, nhiệt độ thường dưới âm mười độ C thậm chí âm hai mươi độ C, nhiệt độ thấp như vậy cậu chịu không nổi đâu nhỉ?"},{"hanzi":"没问题，受得了，我有的是厚衣服。我去哈尔滨主要是想看雪，听说春节时那里会举办很多活动。","pinyin":"Méi wèntí, shòudeliǎo, wǒ yǒudeshì hòu yīfu. Wǒ qù Hā'ěrbīn zhǔyào shì xiǎng kàn xuě, tīngshuō Chūnjié shí nàlǐ huì jǔbàn hěn duō huódòng.","speaker":"陈天中","vi":"Không sao đâu, chịu được mà, mình có khối quần áo dày. Mình đi Cáp Nhĩ Tân chủ yếu là muốn ngắm tuyết, nghe nói dịp Tết ở đó sẽ tổ chức rất nhiều hoạt động."},{"hanzi":"我想在广州过年，那里冬天比较暖和。而且我喜欢看花，听说广州的鲜花市场很有名，里面有各种植物。","pinyin":"Wǒ xiǎng zài Guǎngzhōu guònián, nàlǐ dōngtiān bǐjiào nuǎnhuo. Érqiě wǒ xǐhuan kàn huā, tīngshuō Guǎngzhōu de xiānhuā shìchǎng hěn yǒumíng, lǐmiàn yǒu gèzhǒng zhíwù.","speaker":"白家月","vi":"Mình muốn đón Tết ở Quảng Châu, mùa đông ở đó khá ấm áp. Hơn nữa mình thích ngắm hoa, nghe nói chợ hoa tươi ở Quảng Châu rất nổi tiếng, bên trong có đủ các loại thực vật."},{"hanzi":"真不错！听你们这么一说，我也想外出旅游了。","pinyin":"Zhēn búcuò! Tīng nǐmen zhème yì shuō, wǒ yě xiǎng wàichū lǚyóu le.","speaker":"王一飞","vi":"Tuyệt thật đấy! Nghe các cậu nói thế, mình cũng muốn ra ngoài đi du lịch rồi."}],"readingQuiz":[{"answerIdx":0,"explanation":"Trong bài, Trần Thiên Trung nói \"我去哈尔滨主要是想看雪，听说春节时那里会举办很多活动。\" (Tôi đi Cáp Nhĩ Tân chủ yếu là muốn ngắm tuyết, nghe nói dịp Tết ở đó sẽ tổ chức nhiều hoạt động.), nên đáp án đúng là đến đó ngắm tuyết và tham gia hoạt động.","options":["去那里看雪和参加活动","去那里买很多厚衣服","去那里逛有名的鲜花市场","因为那里冬天比广州更暖和"],"q":"陈天中计划春节去哈尔滨主要是为了什么？"},{"answerIdx":1,"explanation":"Trong bài, Bạch Gia Nguyệt nói \"我想在广州过年，那里冬天比较暖和。而且我喜欢看花，听说广州的鲜花市场很有名，里面有各种植物。\" (Tôi muốn đón Tết ở Quảng Châu, mùa đông ở đó khá ấm áp. Hơn nữa tôi thích ngắm hoa, nghe nói chợ hoa tươi ở Quảng Châu rất nổi tiếng...), nên đáp án đúng là vì mùa đông ở đó ấm áp và cô ấy thích ngắm hoa.","options":["因为她想去广州出差工作","因为那里冬天较暖和，而且她喜欢看花","因为广州的冬天经常下大雪","因为她的好朋友住在哈尔滨"],"q":"白家月为什么想在广州过年？"}],"scene":"在校园里，王一飞下课后遇到陈天中和白家月。","sceneVi":"Trong khuôn viên trường, Vương Nhất Phi sau giờ tan học gặp Trần Thiên Trung và Bạch Gia Nguyệt."},{"id":3,"isNarrative":true,"label":"Bài khóa 3 (课文 3)","lines":[{"hanzi":"广州和哈尔滨，一个在南方，一个在北方，两个城市之间的距离有三千多公里，气候也大不相同。","pinyin":"Guǎngzhōu hé Hā'ěrbīn, yígè zài nánfāng, yígè zài běifāng, liǎng gè chéngshì zhījiān de jùlí yǒu sānqiān duō gōnglǐ, qìhòu yě dà bù xiāngtóng.","speaker":"Đoạn văn","vi":"Quảng Châu và Cáp Nhĩ Tân, một thành phố ở miền Nam, một thành phố ở miền Bắc, khoảng cách giữa hai thành phố hơn ba nghìn ki-lô-mét, khí hậu cũng khác nhau rất nhiều."},{"hanzi":"广州基本上没有冬天，而哈尔滨的冬天一般会从十月开始，到第二年的三四月才结束。","pinyin":"Guǎngzhōu jīběnshang méiyǒu dōngtiān, ér Hā'ěrbīn de dōngtiān yìbān huì cóng shíyuè kāishǐ, dào dì-èr nián de sān sì yuè cái jiéshù.","speaker":"Đoạn văn","vi":"Quảng Châu về cơ bản không có mùa đông, còn mùa đông ở Cáp Nhĩ Tân thường bắt đầu từ tháng mười, đến tháng ba hoặc tháng tư năm sau mới kết thúc."},{"hanzi":"广州四季开满鲜花，所以又叫“花城”；哈尔滨冬天冰雪多，所以也叫“冰城”。","pinyin":"Guǎngzhōu sìjì kāi mǎn xiānhuā, suǒyǐ yòu jiào “Huāchéng”; Hā'ěrbīn dōngtiān bīngxuě duō, suǒyǐ yě jiào “Bīngchéng”.","speaker":"Đoạn văn","vi":"Quảng Châu bốn mùa nở đầy hoa tươi nên còn được gọi là “Hoa Thành”; Cáp Nhĩ Tân mùa đông nhiều băng tuyết nên cũng được gọi là “Băng Thành”."},{"hanzi":"此外，两地的方言也不一样。","pinyin":"Cǐwài, liǎng dì de fāngyán yě bù yíyàng.","speaker":"Đoạn văn","vi":"Ngoài ra, phương ngữ của hai nơi cũng không giống nhau."},{"hanzi":"哈尔滨方言和普通话听起来比较像，而广州方言和普通话差别较大。","pinyin":"Hā'ěrbīn fāngyán hé pǔtōnghuà tīng qǐlái bǐjiào xiàng, ér Guǎngzhōu fāngyán hé pǔtōnghuà chābié jiào dà.","speaker":"Đoạn văn","vi":"Phương ngữ Cáp Nhĩ Tân và tiếng phổ thông nghe khá giống nhau, còn phương ngữ Quảng Châu và tiếng phổ thông có sự khác biệt khá lớn."},{"hanzi":"如果广州人和哈尔滨人都只使用自己的方言，那么交流就很困难，甚至还可能引起误会。","pinyin":"Rúguǒ Guǎngzhōurén hé Hā'ěrbīnrén dōu zhǐ shǐyòng zìjǐ de fāngyán, nàme jiāoliú jiù hěn kùnnan, shènzhì hái kěnéng yǐnqǐ wùhuì.","speaker":"Đoạn văn","vi":"Nếu người Quảng Châu và người Cáp Nhĩ Tân đều chỉ sử dụng phương ngữ của mình, thì việc giao tiếp sẽ rất khó khăn, thậm chí còn có thể gây ra hiểu lầm."},{"hanzi":"其实，中国很多地方都有自己的方言，所以，为了顺利交流，中国人从小都要学习普通话。","pinyin":"Qíshí, Zhōngguó hěn duō dìfang dōu yǒu zìjǐ de fāngyán, suǒyǐ, wèile shùnlì jiāoliú, Zhōngguó rén cóngxiǎo dōu yào xuéxí pǔtōnghuà.","speaker":"Đoạn văn","vi":"Thực ra, rất nhiều nơi ở Trung Quốc đều có phương ngữ riêng, vì vậy, để giao tiếp thuận lợi, người Trung Quốc từ nhỏ đều phải học tiếng phổ thông."}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu \"广州基本上没有冬天，而哈尔滨的冬天一般会从十月开始，到第二年的三四月才结束。\" (Quảng Châu về cơ bản không có mùa đông, còn mùa đông ở Cáp Nhĩ Tân thường bắt đầu từ tháng mười và đến tháng ba, tháng tư năm sau mới kết thúc.), nên đáp án đúng là Quảng Châu cơ bản không có mùa đông, còn mùa đông ở Cáp Nhĩ Tân rất dài.","options":["广州的冬天从十月开始，非常冷","哈尔滨四季开满鲜花，基本没有冬天","广州基本没有冬天，哈尔滨的冬天很长","两个城市的冬天一样长，冰雪都很多"],"q":"关于广州和哈尔滨的气候，下面哪一项是对的？"},{"answerIdx":0,"explanation":"Trong bài có câu \"其实，中国很多地方都有自己的方言，所以，为了顺利交流，中国人从小都要学习普通话。\" (Thực ra, nhiều nơi ở Trung Quốc đều có phương ngữ riêng, vì vậy để giao tiếp thuận lợi, người Trung Quốc từ nhỏ đều phải học tiếng phổ thông.), nên đáp án đúng là vì nhiều nơi có phương ngữ khác nhau, học tiếng phổ thông là để giao tiếp thuận lợi.","options":["因为中国很多地方方言不同，学普通话是为了顺利交流","因为所有地方的方言和普通话都完全一样","因为广州方言和哈尔滨方言都听不懂","因为只有学会普通话才能去北方旅游"],"q":"中国人为什么从小都要学习普通话？"}],"scene":"广州与哈尔滨的不同","sceneVi":"Sự khác biệt giữa Quảng Châu và Cáp Nhĩ Tân"},{"id":4,"isNarrative":true,"label":"Bài khóa 4 (课文 4)","lines":[{"hanzi":"亲爱的同学们：","pinyin":"Qīn'ài de tóngxuémen:","speaker":"Đoạn văn","vi":"Các bạn học sinh thân mến:"},{"hanzi":"今年的“世界环境日”，我们再次开展“绿色生活”活动，希望同学们做到：","pinyin":"Jīnnián de “Shìjiè Huánjìng Rì”, wǒmen zàicì kāizhǎn “Lǜsè Shēnghuó” huódòng, xīwàng tóngxuémen zuòdào:","speaker":"Đoạn văn","vi":"Nhân “Ngày Môi trường Thế giới” năm nay, chúng ta một lần nữa phát động hoạt động “Cuộc sống xanh”, mong các bạn học sinh thực hiện được:"},{"hanzi":"一、绿色出行","pinyin":"Yī, lǜsè chūxíng","speaker":"Đoạn văn","vi":"Một, đi lại xanh"},{"hanzi":"绿色一小步，环保一大步。","pinyin":"Lǜsè yì xiǎo bù, huánbǎo yí dà bù.","speaker":"Đoạn văn","vi":"Một bước nhỏ sống xanh, một bước lớn bảo vệ môi trường."},{"hanzi":"根据距离选择绿色交通方式。","pinyin":"Gēnjù jùlí xuǎnzé lǜsè jiāotōng fāngshì.","speaker":"Đoạn văn","vi":"Lựa chọn phương tiện giao thông xanh tùy theo khoảng cách."},{"hanzi":"距离短时可以走路或者骑自行车，距离长时多乘坐公交车或者地铁。","pinyin":"Jùlí duǎn shí kěyǐ zǒulù huòzhě qí zìxíngchē, jùlí cháng shí duō chéngzuò gōngjiāochē huòzhě dìtiě.","speaker":"Đoạn văn","vi":"Khi quãng đường ngắn có thể đi bộ hoặc đạp xe đạp, khi quãng đường dài nên đi xe buýt hoặc tàu điện ngầm nhiều hơn."},{"hanzi":"二、拒绝浪费","pinyin":"Èr, jùjué làngfèi","speaker":"Đoạn văn","vi":"Hai, từ chối lãng phí"},{"hanzi":"节约资源，坚持一水多用、人走灯关、餐餐都“光盘”。","pinyin":"Jiéyuē zīyuán, jiānchí yì shuǐ duō yòng, rén zǒu dēng guān, cāncān dōu “guāngpán”.","speaker":"Đoạn văn","vi":"Tiết kiệm tài nguyên, kiên trì dùng nước nhiều lần, người đi tắt đèn, bữa nào cũng ăn sạch đĩa (“đĩa sạch”)."},{"hanzi":"三、垃圾分类","pinyin":"Sān, lājī fēnlèi","speaker":"Đoạn văn","vi":"Ba, phân loại rác thải"},{"hanzi":"积极参加校园、小区环保活动，学习垃圾分类知识，从小事做起，做好垃圾分类。","pinyin":"Jījí cānjiā xiàoyuán, xiǎoqū huánbǎo huódòng, xuéxí lājī fēnlèi zhīshi, cóng xiǎoshì zuòqǐ, zuòhǎo lājī fēnlèi.","speaker":"Đoạn văn","vi":"Tích cực tham gia các hoạt động bảo vệ môi trường ở trường học và khu dân cư, học kiến thức phân loại rác, bắt đầu từ những việc nhỏ để làm tốt việc phân loại rác."},{"hanzi":"保护环境是每一个人的责任。","pinyin":"Bǎohù huánjìng shì měi yígè rén de zérèn.","speaker":"Đoạn văn","vi":"Bảo vệ môi trường là trách nhiệm của mỗi người."},{"hanzi":"同学们，让我们共同努力，让绿色生活成为我们的日常习惯！","pinyin":"Tóngxuémen, ràng wǒmen gòngtóng nǔlì, ràng lǜsè shēnghuó chéngwéi wǒmen de rìcháng xíguàn!","speaker":"Đoạn văn","vi":"Các bạn học sinh ơi, hãy cùng nhau nỗ lực để lối sống xanh trở thành thói quen hằng ngày của chúng ta!"},{"hanzi":"校学生会 2026年6月5日","pinyin":"Xiào xuéshēnghuì 2026 nián 6 yuè 5 rì","speaker":"Đoạn văn","vi":"Hội học sinh trường, ngày 5 tháng 6 năm 2026"}],"readingQuiz":[{"answerIdx":2,"explanation":"Trong bài có câu \"根据距离选择绿色交通方式。距离短时可以走路或者骑自行车，距离长时多乘坐公交车或者地铁。\" (Chọn phương tiện giao thông xanh theo khoảng cách. Khi khoảng cách ngắn có thể đi bộ hoặc đi xe đạp, khi khoảng cách dài nên đi xe buýt hoặc tàu điện ngầm.), nên đáp án đúng là tùy khoảng cách mà chọn đi bộ, đi xe đạp hoặc đi xe buýt, tàu điện ngầm.","options":["每天都只走路，不要坐任何车","不管去哪里都尽量自己开车","根据距离选择走路、骑自行车，或乘坐公交车、地铁","距离长的时候也一定要骑自行车"],"q":"为了做到“绿色出行”，发起书建议同学们怎么做？"},{"answerIdx":3,"explanation":"Trong mục \"二、拒绝浪费\" (Từ chối lãng phí), văn bản chỉ nhắc đến \"坚持一水多用、人走灯关、餐餐都“光盘”\" (kiên trì dùng một nước nhiều việc, người đi tắt đèn, bữa nào cũng ăn sạch đĩa), không hề nhắc đến việc ít mua quần áo mới (\"少买新衣服\").","options":["一水多用","人走灯关","餐餐都“光盘”","少买新衣服"],"q":"下面哪一项在“拒绝浪费”部分没有提到？"}],"scene":"“世界环境日”那天，刘小雪学校学生会发布了一份活动发起书。","sceneVi":"Vào “Ngày Môi trường Thế giới”, Hội học sinh trường của Lưu Tiểu Tuyết đã phát hành một bản phát động hoạt động."}]};
